-- Generated by scripts/seed/seed_health_missions.js. Apply after api/kidlearn_patch_math_grade5.sql.
-- Hides the six original health games (rows, questions and scores are kept) and adds the grade-5
-- health and PE mission games. Rerunning replaces only missions no teacher has created or edited.
-- Each mission is one questions row: question_text is the title, question_img holds the mission JSON.
BEGIN;

UPDATE games SET is_active = FALSE WHERE subject_id = 6 AND game_code IS NULL;

INSERT INTO games (subject_id, game_code, is_active, name, game_type, level, icon, time_limit, question_count)
VALUES
    (6, 'health_detective', TRUE, 'นักสืบสุขภาพ พิชิตภารกิจร่างกาย', 'mcq', 'medium', '🕵️', 1800, NULL),
    (6, 'health_meal_chef', TRUE, 'เชฟน้อยจัดจานสุขภาพ', 'mcq', 'medium', '🍱', 1800, NULL),
    (6, 'health_routine', TRUE, 'นักวางแผนชีวิตสุขภาพดี', 'mcq', 'medium', '⏰', 1800, NULL),
    (6, 'health_sports', TRUE, 'สนามกีฬาอัจฉริยะ', 'mcq', 'medium', '⚽', 1800, NULL),
    (6, 'health_safety', TRUE, 'ฮีโร่พิทักษ์ความปลอดภัย', 'mcq', 'medium', '🦸', 1800, NULL),
    (6, 'health_teamwork', TRUE, 'ภารกิจทีมเวิร์ก พิชิตปัญหา', 'mcq', 'medium', '🤝', 1800, NULL)
ON CONFLICT (game_code) DO UPDATE SET
    is_active = TRUE,
    name = EXCLUDED.name,
    icon = EXCLUDED.icon,
    question_count = NULL;

DELETE FROM questions
WHERE game_id IN (SELECT game_id FROM games WHERE game_code IN ('health_detective', 'health_meal_chef', 'health_routine', 'health_sports', 'health_safety', 'health_teamwork'))
  AND created_by IS NULL AND updated_by IS NULL;

