('health_detective', 'หลังเตะบอลเหงื่อท่วม', '{"icon":"🚿","story":["ต้นน้ำชอบเตะบอลตอนเย็นจนเหงื่อท่วมตัว","วันต่อมาเพื่อนบอกว่าต้นน้ำมีกลิ่นตัว และต้นน้ำเองก็รู้สึกคันผิว"],"tip":"อาบน้ำฟอกสบู่และเปลี่ยนเสื้อผ้าหลังเหงื่อออกมาก","context":[{"type":"table","title":"เมื่อวานของต้นน้ำ","head":["เวลา","พฤติกรรม"],"rows":[["16:00","เตะบอลกับเพื่อน เหงื่อออกมาก"],["17:00","กลับบ้าน นั่งดูทีวีโดยไม่อาบน้ำ"],["18:00","กินข้าวเย็น"],["21:00","เข้านอนทั้งชุดพละที่ใส่มาทั้งวัน"]]}],"steps":[{"kind":"multi","prompt":"พฤติกรรมใดทำให้ต้นน้ำมีกลิ่นตัวและคันผิว (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["เหงื่อที่ค้างอยู่บนผิวและเสื้อผ้าทำให้เกิดอะไร"],"options":[{"text":"ไม่อาบน้ำหลังเหงื่อออกมาก","ok":true},{"text":"ใส่ชุดที่มีเหงื่อเข้านอน","ok":true},{"text":"เตะบอลตอนเย็น","ok":false,"why":"การออกกำลังกายดีต่อร่างกาย แค่ต้องดูแลความสะอาดหลังเล่น"},{"text":"กินข้าวเย็น","ok":false,"why":"การกินข้าวเย็นไม่เกี่ยวกับกลิ่นตัว"}],"solution":["เหงื่อและสิ่งสกปรกที่ค้างบนผิวและเสื้อผ้าทำให้เกิดกลิ่นและคันได้","ควรอาบน้ำฟอกสบู่และเปลี่ยนชุดสะอาดหลังเล่นกีฬา"]},{"kind":"choice","prompt":"ข้อใดเป็นการดูแลร่างกายที่ดีที่สุดหลังเล่นกีฬา","skill":"decision","points":10,"hints":["ต้องทำให้ทั้งร่างกายและเสื้อผ้าสะอาด"],"options":[{"text":"อาบน้ำฟอกสบู่ แล้วเปลี่ยนเป็นเสื้อผ้าที่สะอาด","ok":true},{"text":"ฉีดน้ำหอมกลบกลิ่น","ok":false,"why":"น้ำหอมกลบกลิ่นได้ชั่วคราว แต่เหงื่อและสิ่งสกปรกยังอยู่"},{"text":"เปิดพัดลมให้เหงื่อแห้งแล้วใส่ชุดเดิมต่อ","ok":false,"why":"เหงื่อแห้งแต่ความสกปรกยังติดอยู่ที่ผิวและเสื้อ"},{"text":"ล้างหน้าอย่างเดียวก็พอ","ok":false,"why":"เหงื่อออกทั่วร่างกาย ต้องทำความสะอาดทั้งตัว"}],"solution":["การอาบน้ำฟอกสบู่ช่วยขจัดเหงื่อและสิ่งสกปรก","เสื้อผ้าที่เปียกเหงื่อควรนำไปซักทุกครั้ง"],"answer":0}]}', 'easy', 5),
('health_detective', 'นอนกี่ชั่วโมงดี', '{"icon":"😴","story":["ภูมิง่วงนอนในห้องเรียนตอนบ่ายเกือบทุกวัน","นักสืบขอดูเวลาเข้านอนและเวลาตื่นของภูมิ"],"tip":"เด็กวัย 6–12 ปี ควรนอนหลับคืนละ 9–12 ชั่วโมง","context":[{"type":"table","title":"การนอนของภูมิ (วันจันทร์–ศุกร์)","head":["รายการ","เวลา"],"rows":[["เข้านอน","23:00"],["ตื่นนอน","06:00"]]},{"type":"note","text":"ภูมิพูดว่า \"ผมนอนทุกคืนนะ แต่ทำไมยังง่วงอยู่\""}],"steps":[{"kind":"choice","prompt":"ภูมินอนหลับคืนละประมาณกี่ชั่วโมง และเพียงพอหรือไม่","skill":"analysis","points":10,"hints":["นับตั้งแต่ 23:00 ไปจนถึง 06:00"],"options":[{"text":"7 ชั่วโมง น้อยกว่าที่เด็กวัยนี้ควรได้","ok":true},{"text":"7 ชั่วโมง เพียงพอแล้ว","ok":false,"why":"เด็กวัย 6–12 ปี ควรนอน 9–12 ชั่วโมง"},{"text":"8 ชั่วโมง เพียงพอแล้ว","ok":false,"why":"ลองนับใหม่ 23:00 ถึง 06:00 คือ 7 ชั่วโมง"},{"text":"9 ชั่วโมง เพียงพอแล้ว","ok":false,"why":"ลองนับใหม่ 23:00 ถึง 06:00 คือ 7 ชั่วโมง"}],"solution":["23:00 ถึง 06:00 คือ 7 ชั่วโมง","เด็กวัย 6–12 ปี ควรนอน 9–12 ชั่วโมง ภูมิจึงนอนไม่พอและง่วงในห้องเรียน"],"answer":0},{"kind":"choice","prompt":"ถ้าภูมิต้องตื่น 06:00 เหมือนเดิม ควรเข้านอนช้าที่สุดกี่โมง จึงจะนอนได้อย่างน้อย 9 ชั่วโมง","skill":"planning","points":10,"hints":["นับย้อนจาก 06:00 ไป 9 ชั่วโมง"],"options":[{"text":"21:00","ok":true},{"text":"22:00","ok":false,"why":"22:00 ถึง 06:00 ได้เพียง 8 ชั่วโมง"},{"text":"22:30","ok":false,"why":"22:30 ถึง 06:00 ได้เพียง 7 ชั่วโมงครึ่ง"},{"text":"23:00","ok":false,"why":"เป็นเวลาเดิมที่ทำให้นอนไม่พอ"}],"solution":["06:00 ย้อนไป 9 ชั่วโมงคือ 21:00","การเข้านอนเวลาเดิมทุกคืนช่วยให้หลับง่ายและตื่นสดชื่น"],"answer":0}]}', 'easy', 6),
('health_detective', 'น้ำหวานแทนน้ำเปล่า', '{"icon":"🥤","story":["มะลิชอบดื่มเครื่องดื่มรสหวาน","ช่วงนี้มะลิฟันผุ คุณครูจึงให้นักสืบช่วยดูว่ามะลิดื่มอะไรบ้าง"],"tip":"น้ำเปล่าเป็นเครื่องดื่มที่ดีที่สุดสำหรับร่างกาย","context":[{"type":"table","title":"เครื่องดื่มของมะลิในหนึ่งวัน","head":["ช่วงเวลา","เครื่องดื่ม"],"rows":[["เช้า","นมจืด 1 กล่อง"],["สาย","ชานมเย็นใส่น้ำตาล 1 แก้ว"],["กลางวัน","น้ำอัดลม 1 กระป๋อง"],["บ่าย","น้ำหวานสีแดง 1 แก้ว"],["เย็น","น้ำเปล่า 1 แก้ว"]]}],"steps":[{"kind":"multi","prompt":"เครื่องดื่มใดที่มะลิควรลดลง (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["เครื่องดื่มไหนมีน้ำตาลมาก"],"options":[{"text":"ชานมเย็นใส่น้ำตาล","ok":true},{"text":"น้ำอัดลม","ok":true},{"text":"น้ำหวานสีแดง","ok":true},{"text":"นมจืด","ok":false,"why":"นมจืดมีโปรตีนและแคลเซียม ไม่ใส่น้ำตาล เหมาะกับเด็ก"},{"text":"น้ำเปล่า","ok":false,"why":"น้ำเปล่าไม่มีน้ำตาล มะลิควรดื่มเพิ่มขึ้น"}],"solution":["ชานม น้ำอัดลม และน้ำหวานมีน้ำตาลมาก ทำให้ฟันผุและเสี่ยงน้ำหนักเกิน","ควรดื่มน้ำเปล่าเป็นหลักและดื่มนมจืด"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่มะลิควรดื่มน้ำเปล่าแทนน้ำหวาน","skill":"reason","points":10,"hints":["เทียบสิ่งที่ร่างกายได้รับจากน้ำเปล่ากับน้ำหวาน"],"options":[{"text":"น้ำเปล่าช่วยให้ร่างกายได้น้ำโดยไม่มีน้ำตาลที่ทำให้ฟันผุ","ok":true},{"text":"น้ำเปล่าราคาถูกกว่าเสมอ","ok":false,"why":"ราคาไม่ใช่เหตุผลด้านสุขภาพ"},{"text":"น้ำหวานทำให้ร่างกายขาดน้ำทันที","ok":false,"why":"ข้อนี้เกินจริง ปัญหาของน้ำหวานคือมีน้ำตาลมาก"},{"text":"น้ำเปล่าทำให้ฟันขาวขึ้นทันที","ok":false,"why":"น้ำเปล่าไม่ได้ทำให้ฟันขาวทันที"}],"solution":["ร่างกายต้องการน้ำทุกวัน และน้ำเปล่าไม่มีน้ำตาล","การลดเครื่องดื่มหวานช่วยลดโอกาสฟันผุ"],"answer":0}]}', 'easy', 7),
('health_detective', 'ขั้นตอนล้างมือของแพรวา', '{"icon":"🫧","story":["แพรวาเพิ่งเล่นกับแมวที่บ้าน","แม่ชวนแพรวามาช่วยทำกับข้าว แพรวาจึงต้องล้างมือให้สะอาดก่อน"],"tip":"ถูมือด้วยสบู่ให้ทั่วประมาณ 20 วินาที","context":[{"type":"note","text":"แพรวาพูดว่า \"หนูเช็ดมือกับผ้าขี้ริ้วในครัวได้ไหม ผืนนั้นอยู่ใกล้ดี\""}],"steps":[{"kind":"order","prompt":"เรียงขั้นตอนการล้างมือให้ถูกต้อง","skill":"rules","points":10,"hints":["สบู่จะเกิดฟองได้ต้องมีน้ำก่อน","ขั้นสุดท้ายคือทำให้มือแห้ง"],"items":["เปิดน้ำให้มือเปียก","ถูสบู่ให้ทั่วมือ","ถูฝ่ามือ หลังมือ ซอกนิ้ว และปลายเล็บ ประมาณ 20 วินาที","ล้างฟองสบู่ออกด้วยน้ำสะอาด","เช็ดมือให้แห้งด้วยผ้าสะอาด"],"solution":["ทำให้มือเปียก ถูสบู่ ถูให้ทั่วทุกส่วน ล้างออก แล้วเช็ดให้แห้ง","การถูนานพอและทั่วถึงช่วยให้เชื้อโรคหลุดออกได้ดี"]},{"kind":"choice","prompt":"แพรวาควรเช็ดมือด้วยอะไร","skill":"decision","points":10,"hints":["ถ้าเช็ดมือกับผ้าที่สกปรก มือจะยังสะอาดอยู่ไหม"],"options":[{"text":"ผ้าเช็ดมือที่สะอาดและแห้ง","ok":true},{"text":"ผ้าขี้ริ้วในครัวเพราะอยู่ใกล้","ok":false,"why":"ผ้าขี้ริ้วใช้เช็ดคราบสกปรก อาจมีเชื้อโรค"},{"text":"เสื้อของตัวเองที่ใส่เล่นกับแมว","ok":false,"why":"เสื้ออาจมีขนและสิ่งสกปรกจากแมว"},{"text":"สะบัดมือแล้วจับอาหารต่อเลย","ok":false,"why":"มือที่เปียกไม่สะอาดเท่ามือที่เช็ดแห้งด้วยผ้าสะอาด"}],"solution":["เมื่อล้างมือสะอาดแล้ว ต้องเช็ดด้วยผ้าสะอาด เชื้อโรคจะไม่กลับมาติดมืออีก"],"answer":0}]}', 'easy', 8),
('health_detective', 'วันหยุดหน้าจอ', '{"icon":"🎮","story":["วันเสาร์ต้นข้าวเล่นเกมและดูการ์ตูนเกือบทั้งวัน","ตอนเย็นเขาปวดตาและไม่อยากขยับตัวเลย"],"tip":"เด็กควรเคลื่อนไหวร่างกายอย่างน้อย 60 นาทีต่อวัน และดูจอเพื่อความบันเทิงไม่เกิน 2 ชั่วโมง","context":[{"type":"table","title":"วันเสาร์ของต้นข้าว","head":["กิจกรรม","เวลารวม"],"rows":[["เล่นเกมในแท็บเล็ต","4 ชั่วโมง"],["ดูการ์ตูนในโทรศัพท์","2 ชั่วโมง"],["วิ่งเล่น เล่นกีฬา","0 นาที"]]}],"steps":[{"kind":"plan","prompt":"ช่วยต้นข้าววางแผนวันหยุดใหม่ เลือกให้เหมาะสมทุกหัวข้อ","skill":"planning","points":10,"hints":["เทียบเวลาของต้นข้าวกับคำแนะนำในเคล็ดลับ"],"fields":[{"id":"screen","label":"เวลาดูจอเพื่อความบันเทิง","options":[{"text":"ไม่เกิน 2 ชั่วโมงต่อวัน","ok":true},{"text":"4 ชั่วโมงเหมือนเดิม","ok":false,"why":"ยังเกินคำแนะนำไม่เกิน 2 ชั่วโมงต่อวัน"},{"text":"ได้ทั้งวันเพราะเป็นวันหยุด","ok":false,"why":"วันหยุดก็ควรจำกัดเวลาดูจอ"}],"answer":0},{"id":"move","label":"การเคลื่อนไหวร่างกาย","options":[{"text":"ปั่นจักรยานหรือเล่นกีฬารวมอย่างน้อย 60 นาที","ok":true},{"text":"เดินไปหยิบขนม 10 นาที","ok":false,"why":"ยังน้อยกว่า 60 นาทีต่อวันมาก"},{"text":"ไม่ต้องขยับ เพราะเหนื่อยจากการเรียนมาทั้งสัปดาห์","ok":false,"why":"การเคลื่อนไหวช่วยให้ร่างกายแข็งแรงและสดชื่น"}],"answer":0},{"id":"eyes","label":"การดูแลสายตา","options":[{"text":"พักสายตาเป็นระยะ มองไปไกล ๆ","ok":true},{"text":"ถือจอใกล้ตาเพื่อเห็นชัด","ok":false,"why":"จอที่ใกล้ตาเกินไปทำให้ตาล้า"},{"text":"ปิดไฟให้มืดจะได้ไม่แสบตา","ok":false,"why":"ดูจอในที่มืดทำให้ตาทำงานหนัก"}],"answer":0}],"solution":["ลดเวลาดูจอให้ไม่เกิน 2 ชั่วโมง และเคลื่อนไหวร่างกายอย่างน้อย 60 นาทีต่อวัน","พักสายตาเป็นระยะช่วยลดอาการปวดตา"]}]}', 'easy', 9),
('health_detective', 'ของใช้ส่วนตัวในค่าย', '{"icon":"🪥","story":["ใบบัวไปค่ายลูกเสือ 2 วัน แต่ลืมนำของใช้บางอย่างมา","เพื่อน ๆ ใจดีเสนอให้ยืมของหลายอย่าง"],"tip":"ของใช้ที่สัมผัสร่างกายโดยตรงไม่ควรใช้ร่วมกับผู้อื่น","context":[{"type":"note","text":"เพื่อนเสนอให้ใบบัวยืม: แปรงสีฟัน ผ้าเช็ดตัว หวี ลูกบอล และหนังสือนิทาน"}],"steps":[{"kind":"multi","prompt":"ของใช้ใดที่ใบบัวไม่ควรยืมใช้ร่วมกับเพื่อน (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["ของชิ้นไหนสัมผัสปาก ผิว หรือเส้นผมโดยตรง"],"options":[{"text":"แปรงสีฟัน","ok":true},{"text":"ผ้าเช็ดตัว","ok":true},{"text":"หวี","ok":true},{"text":"ลูกบอล","ok":false,"why":"ลูกบอลเล่นร่วมกันได้ แค่ล้างมือหลังเล่น"},{"text":"หนังสือนิทาน","ok":false,"why":"หนังสือแบ่งกันอ่านได้"}],"solution":["แปรงสีฟัน ผ้าเช็ดตัว และหวีสัมผัสปาก ผิว และเส้นผมโดยตรง","การใช้ร่วมกันทำให้เชื้อโรคหรือเหาติดต่อกันได้"]},{"kind":"choice","prompt":"ถ้าใบบัวลืมแปรงสีฟัน ควรทำอย่างไรดีที่สุด","skill":"decision","points":10,"hints":["ใครในค่ายช่วยเหลือเด็ก ๆ ได้"],"options":[{"text":"บอกครูผู้ดูแลค่ายเพื่อขอแปรงสีฟันใหม่","ok":true},{"text":"ยืมแปรงของเพื่อนแล้วล้างน้ำก่อนใช้","ok":false,"why":"ล้างน้ำแล้วก็ยังเป็นแปรงที่เพื่อนใช้ เชื้อโรคติดต่อกันได้"},{"text":"ไม่แปรงฟันเลยตลอด 2 วัน","ok":false,"why":"ควรแปรงฟันทุกวัน วันละ 2 ครั้ง"},{"text":"ใช้นิ้วถูฟันกับยาสีฟันของเพื่อน","ok":false,"why":"ทำความสะอาดได้ไม่ดีเท่าแปรงสีฟัน ควรขอความช่วยเหลือ"}],"solution":["เมื่อขาดของใช้ส่วนตัว ควรบอกผู้ใหญ่เพื่อขอของใหม่ ไม่ใช้ของคนอื่น"],"answer":0}]}', 'easy', 10),
('health_detective', 'คดีง่วงในห้องเรียน', '{"icon":"🥱","story":["ต้นกล้าหาวทั้งคาบแรก และตอบคำถามครูไม่ได้","คุณครูส่งแฟ้มคดีมาให้นักสืบช่วยหาว่าต้นกล้าควรปรับอะไร"],"tip":"ปัญหาหนึ่งอาจเป็นต้นเหตุของปัญหาอื่น ๆ ตามมา","context":[{"type":"table","title":"แฟ้มคดีของต้นกล้า","head":["เวลา","พฤติกรรม"],"rows":[["22:30","ดูคลิปในโทรศัพท์บนเตียง"],["23:30","หลับ"],["06:30","ตื่นสาย รีบแต่งตัว"],["07:00","ออกจากบ้านโดยไม่กินอาหารเช้า"],["09:00","ง่วง ไม่มีสมาธิ ตอบคำถามครูไม่ได้"],["10:00","ดื่มน้ำหวานแก้ง่วงแก้หิว"]]},{"type":"note","text":"ต้นกล้าพูดว่า \"ผมดื่มน้ำหวานตอนสายก็หายหิวแล้ว ไม่ต้องกินข้าวเช้าก็ได้\""}],"steps":[{"kind":"multi","prompt":"พฤติกรรมใดที่ต้นกล้าควรปรับ (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["นับชั่วโมงนอนของต้นกล้า","น้ำหวานทดแทนอาหารเช้าได้จริงไหม"],"options":[{"text":"ดูคลิปในโทรศัพท์บนเตียงจนดึก","ok":true},{"text":"นอนหลับเพียงประมาณ 7 ชั่วโมง","ok":true},{"text":"ไม่กินอาหารเช้า","ok":true},{"text":"ใช้น้ำหวานแทนอาหารเช้า","ok":true},{"text":"ไปโรงเรียนทุกวัน","ok":false,"why":"การไปโรงเรียนเป็นเรื่องดี ไม่ใช่ปัญหา"}],"solution":["ต้นกล้านอน 23:30–06:30 ได้เพียง 7 ชั่วโมง น้อยกว่า 9–12 ชั่วโมงที่ควรได้","น้ำหวานมีแต่น้ำตาล ไม่ใช่อาหารเช้าที่มีสารอาหารครบ"]},{"kind":"choice","prompt":"ปัญหาใดเป็นต้นเหตุที่ทำให้เกิดปัญหาอื่นตามมามากที่สุด","skill":"analysis","points":10,"hints":["ลองเรียงเหตุการณ์ตามเวลา อะไรเกิดก่อนแล้วทำให้เกิดเรื่องต่อไป"],"options":[{"text":"นอนดึกเพราะดูคลิปบนเตียง","ok":true},{"text":"ไม่กินอาหารเช้า","ok":false,"why":"เป็นผลจากการตื่นสายจนไม่มีเวลากิน"},{"text":"ง่วงในห้องเรียน","ok":false,"why":"เป็นผลที่เกิดจากการนอนไม่พอและไม่กินอาหารเช้า"},{"text":"ดื่มน้ำหวานตอนสาย","ok":false,"why":"เกิดขึ้นหลังจากง่วงและหิวแล้ว"}],"solution":["นอนดึก ทำให้ตื่นสาย ทำให้ไม่มีเวลากินอาหารเช้า แล้วจึงง่วงและหิวในห้องเรียน","แก้ที่ต้นเหตุจะช่วยลดปัญหาที่ตามมาทั้งหมด"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้นกล้าควรงดดูจอบนเตียงก่อนนอน","skill":"reason","points":10,"hints":["คิดว่าการดูคลิปส่งผลต่อเวลาที่หลับอย่างไร"],"options":[{"text":"คลิปที่สนุกและแสงจอทำให้หลับยาก นอนดึก และนอนไม่พอ","ok":true},{"text":"เพราะโทรศัพท์จะแบตหมดตอนเช้า","ok":false,"why":"เป็นเรื่องของโทรศัพท์ ไม่ใช่เรื่องสุขภาพ"},{"text":"เพราะกลัวพ่อแม่ดุ","ok":false,"why":"ควรทำเพราะเข้าใจผลต่อร่างกาย ไม่ใช่เพราะกลัว"},{"text":"เพราะดูจอครั้งเดียวสายตาจะเสียทันที","ok":false,"why":"ข้อนี้เกินจริง ปัญหาหลักคือทำให้นอนดึก"}],"solution":["การดูจอก่อนนอนทำให้สมองตื่นตัวและหลับช้า","ควรวางโทรศัพท์ไว้นอกห้องนอนเพื่อให้นอนได้ 9–12 ชั่วโมง"],"answer":0}]}', 'medium', 11),
