('health_detective', 'คดีหวัดระบาดในห้อง', '{"icon":"🤧","story":["สัปดาห์นี้ต้นข้าวเป็นหวัด ไอและจามบ่อย","ผ่านไปไม่กี่วัน เพื่อนข้างโต๊ะเริ่มไอตามกัน"],"tip":"ปิดปากและจมูกเวลาไอจาม แล้วล้างมือด้วยสบู่","context":[{"type":"table","title":"บันทึกของต้นข้าว","head":["วัน","อาการ","พฤติกรรม"],"rows":[["จันทร์","ไอ จาม","ไอใส่มือแล้วจับลูกบิดประตูห้อง"],["อังคาร","มีน้ำมูก","ใช้แก้วน้ำใบเดียวกับเพื่อน"],["พุธ","ยังไอ","ไม่สวมหน้ากากอนามัย ไอใส่เพื่อนข้าง ๆ"],["พฤหัสบดี","ยังไอ","บอกครูว่าไม่สบาย"]]},{"type":"note","text":"วันพฤหัสบดี เพื่อนข้างโต๊ะ 2 คนเริ่มไอ"}],"steps":[{"kind":"multi","prompt":"พฤติกรรมใดที่ทำให้หวัดแพร่ไปสู่เพื่อน (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["เชื้อหวัดออกมากับละอองไอจามและน้ำมูก แล้วไปติดที่ไหนได้บ้าง"],"options":[{"text":"ไอใส่มือแล้วไปจับลูกบิดประตู","ok":true},{"text":"ใช้แก้วน้ำร่วมกับเพื่อน","ok":true},{"text":"ไม่ปิดปากจมูกและไอใส่เพื่อน","ok":true},{"text":"บอกครูว่าไม่สบาย","ok":false,"why":"เป็นสิ่งที่ถูกต้อง ครูจะได้ช่วยดูแล"}],"solution":["เชื้อหวัดติดต่อทางละอองไอจาม มือ และของใช้ร่วมกัน","การบอกครูเป็นการขอความช่วยเหลือที่ถูกต้อง"]},{"kind":"order","prompt":"เรียงขั้นตอนเมื่อต้นข้าวจะไอหรือจามในห้องเรียน","skill":"rules","points":10,"hints":["ต้องกันละอองก่อน แล้วจึงจัดการสิ่งที่ปนเปื้อน"],"items":["ใช้กระดาษทิชชูปิดปากและจมูกเวลาไอหรือจาม","ทิ้งทิชชูที่ใช้แล้วลงถังขยะที่มีฝาปิด","ล้างมือด้วยสบู่ให้สะอาด"],"solution":["ปิดปากจมูกเพื่อกันละออง ทิ้งทิชชูให้ถูกที่ แล้วล้างมือ","ถ้าไม่มีทิชชู ให้ไอใส่ข้อพับแขนแทนมือ"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ควรไอใส่ทิชชูหรือข้อพับแขนแทนการไอใส่มือ","skill":"reason","points":10,"hints":["ดูเบาะแสวันจันทร์ มือไปจับอะไรต่อ"],"options":[{"text":"มือจะไปจับสิ่งของที่คนอื่นจับต่อ ทำให้เชื้อโรคแพร่ได้ง่าย","ok":true},{"text":"เพราะไอใส่ทิชชูเสียงเบากว่า","ok":false,"why":"เรื่องเสียงไม่ใช่เหตุผลด้านสุขภาพ"},{"text":"เพราะไอใส่ทิชชูแล้วหายป่วยเร็วขึ้น","ok":false,"why":"ช่วยป้องกันการแพร่เชื้อ ไม่ได้ทำให้หายเร็วขึ้น"},{"text":"เพราะครูไม่ชอบเห็นคนไอ","ok":false,"why":"ควรทำเพราะช่วยป้องกันโรค ไม่ใช่เพื่อให้ครูพอใจ"}],"solution":["มือสัมผัสลูกบิดประตู โต๊ะ และของใช้ต่าง ๆ เชื้อโรคจึงแพร่ต่อไปได้","ทิชชูทิ้งได้ ข้อพับแขนไม่ค่อยไปจับของ จึงแพร่เชื้อน้อยกว่า"],"answer":0}]}', 'medium', 19),
('health_detective', 'เมื่อร่างกายเริ่มเปลี่ยนแปลง', '{"icon":"🌱","story":["ฟ้าใสเรียนชั้น ป.5 ช่วงนี้หน้ามันและมีสิวขึ้น","เหงื่อของฟ้าใสมีกลิ่นแรงกว่าเดิม คุณครูบอกว่าเป็นการเปลี่ยนแปลงตามวัย"],"tip":"เมื่อเข้าสู่วัยรุ่น ร่างกายต้องการการดูแลความสะอาดมากขึ้น","context":[{"type":"table","title":"กิจวัตรของฟ้าใส","head":["ช่วง","พฤติกรรม"],"rows":[["เช้า","รีบไปโรงเรียน ไม่ได้ล้างหน้า"],["กลางวัน","ใช้มือที่ยังไม่ได้ล้างบีบสิว"],["บ่าย","ซ้อมกีฬา เหงื่อออกมาก"],["เย็น","อาบน้ำฟอกสบู่"],["ถุงเท้า","ใส่คู่เดิมติดกัน 3 วัน"]]}],"steps":[{"kind":"multi","prompt":"พฤติกรรมใดที่ฟ้าใสควรปรับ (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["ข้อไหนทำให้สิวอักเสบ และข้อไหนทำให้เกิดกลิ่น"],"options":[{"text":"ไม่ล้างหน้าตอนเช้า","ok":true},{"text":"ใช้มือที่ไม่สะอาดบีบสิว","ok":true},{"text":"ใส่ถุงเท้าคู่เดิมหลายวัน","ok":true},{"text":"อาบน้ำฟอกสบู่ตอนเย็น","ok":false,"why":"เป็นนิสัยที่ดี ควรทำต่อไป"},{"text":"ซ้อมกีฬาตอนบ่าย","ok":false,"why":"การออกกำลังกายดีต่อร่างกาย แค่ต้องทำความสะอาดหลังซ้อม"}],"solution":["ล้างหน้าเช้าเย็นช่วยลดความมันบนใบหน้า","การบีบสิวด้วยมือสกปรกทำให้สิวอักเสบ","ถุงเท้าที่มีเหงื่อควรซักทุกวัน"]},{"kind":"choice","prompt":"เหตุผลใดอธิบายได้ดีที่สุดว่าทำไมเหงื่อของฟ้าใสมีกลิ่นแรงกว่าเดิม","skill":"reason","points":10,"hints":["ดูสิ่งที่คุณครูบอกในเรื่องราว"],"options":[{"text":"เมื่อเข้าสู่วัยรุ่น ต่อมเหงื่อทำงานมากขึ้น จึงต้องดูแลความสะอาดมากขึ้น","ok":true},{"text":"เพราะฟ้าใสเล่นกีฬา จึงควรเลิกเล่นกีฬา","ok":false,"why":"การออกกำลังกายมีประโยชน์ ควรอาบน้ำหลังเล่นแทนการเลิกเล่น"},{"text":"เพราะฟ้าใสป่วยหนัก","ok":false,"why":"ครูบอกแล้วว่าเป็นการเปลี่ยนแปลงตามวัย ไม่ใช่การป่วย"},{"text":"เพราะอากาศร้อนเท่านั้น ไม่เกี่ยวกับวัย","ok":false,"why":"อากาศมีผล แต่ข้อมูลบอกว่าเปลี่ยนไปตามวัยด้วย"}],"solution":["การเปลี่ยนแปลงตามวัยทำให้มีเหงื่อและความมันมากขึ้น เป็นเรื่องปกติ","การอาบน้ำ ล้างหน้า และเปลี่ยนเสื้อผ้าสะอาดช่วยได้"],"answer":0},{"kind":"choice","prompt":"ถ้าสิวของฟ้าใสอักเสบและเจ็บมาก ควรทำอย่างไร","skill":"decision","points":10,"hints":["ใครช่วยดูแลได้อย่างปลอดภัย"],"options":[{"text":"ไม่บีบสิว และบอกผู้ปกครองเพื่อพาไปปรึกษาแพทย์","ok":true},{"text":"บีบให้แรงขึ้นจะได้หายเร็ว","ok":false,"why":"การบีบทำให้อักเสบมากขึ้นและอาจเป็นแผลเป็น"},{"text":"ยืมครีมของเพื่อนมาทา","ok":false,"why":"ไม่ควรใช้ยาหรือครีมของคนอื่นเอง"},{"text":"ไม่ล้างหน้าเลยเพราะกลัวเจ็บ","ok":false,"why":"ควรล้างหน้าเบา ๆ ให้สะอาด"}],"solution":["สิวที่อักเสบมากควรให้ผู้ใหญ่ช่วยดูแล","ไม่บีบสิวเองและไม่ใช้ยาของผู้อื่น"],"answer":0}]}', 'medium', 20),
('health_detective', 'คดีนักเรียนหมดแรงตอนเช้า', '{"icon":"🕵️","story":["ภูผาง่วงและไม่มีสมาธิในคาบแรกเกือบทุกวัน","ภูผาคิดว่าเป็นเพราะวิชาแรกน่าเบื่อ นักสืบจึงรวบรวมหลักฐาน 3 วันมาเทียบกัน"],"tip":"หลักฐานที่ดีคือข้อมูลที่เทียบกันได้ ไม่ใช่ความรู้สึก","context":[{"type":"table","title":"แฟ้มคดีของภูผา","head":["วัน","เข้านอน–ตื่น","อาหารเช้า","อาการในคาบแรก"],"rows":[["จันทร์","23:00–06:00 (ดูคลิปก่อนนอน)","ไม่ได้กิน","ง่วง หาวตลอด"],["อังคาร","23:30–06:30 (ดูคลิปก่อนนอน)","ขนมกรุบกรอบในรถ","ปวดหัว หิว สมาธิสั้น"],["พุธ","21:00–06:00 (แม่เก็บโทรศัพท์)","ข้าวต้มไข่","สดชื่น ตั้งใจเรียน"]]},{"type":"note","text":"คาบแรกทั้ง 3 วันเป็นวิชาคณิตศาสตร์กับครูคนเดิม ภูผาพูดว่า \"ผมง่วงเพราะวิชาแรกน่าเบื่อ\""}],"steps":[{"kind":"multi","prompt":"ข้อมูลใดเป็นหลักฐานว่าการนอนและอาหารเช้าทำให้ภูผาง่วงและไม่มีสมาธิ (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["วันพุธต่างจากวันอื่นอย่างไร","ถ้าวิชาเหมือนกันทุกวัน วิชาเป็นสาเหตุได้ไหม"],"options":[{"text":"วันจันทร์และอังคารที่นอนดึกและไม่ได้กินอาหารเช้าที่มีประโยชน์ ภูผาง่วงและไม่มีสมาธิ","ok":true},{"text":"วันพุธที่นอน 21:00 และกินข้าวต้มไข่ ภูผาสดชื่นและตั้งใจเรียน","ok":true},{"text":"คืนที่ดูคลิปก่อนนอน ภูผาเข้านอนดึก","ok":true},{"text":"ภูผาบอกว่าวิชาแรกน่าเบื่อ","ok":false,"why":"เป็นความรู้สึก และวิชาเหมือนกันทั้ง 3 วัน แต่ผลต่างกัน"},{"text":"คาบแรกเป็นวิชาคณิตศาสตร์ทุกวัน","ok":false,"why":"สิ่งที่เหมือนกันทุกวันอธิบายไม่ได้ว่าทำไมผลแต่ละวันต่างกัน"}],"solution":["สิ่งที่เปลี่ยนไปในวันพุธคือนอนเร็วและกินอาหารเช้า แล้วอาการก็ดีขึ้น","วิชาเหมือนกันทุกวัน จึงไม่ใช่สาเหตุ"]},{"kind":"choice","prompt":"คืนวันจันทร์และคืนวันพุธ ภูผานอนหลับได้กี่ชั่วโมงตามลำดับ","skill":"analysis","points":10,"hints":["นับจากเวลาเข้านอนถึงเวลาตื่นของแต่ละวัน"],"options":[{"text":"จันทร์ 7 ชั่วโมง พุธ 9 ชั่วโมง","ok":true},{"text":"จันทร์ 6 ชั่วโมง พุธ 9 ชั่วโมง","ok":false,"why":"23:00 ถึง 06:00 คือ 7 ชั่วโมง"},{"text":"จันทร์ 7 ชั่วโมง พุธ 8 ชั่วโมง","ok":false,"why":"21:00 ถึง 06:00 คือ 9 ชั่วโมง"},{"text":"ทั้งสองวัน 9 ชั่วโมงเท่ากัน","ok":false,"why":"วันจันทร์เข้านอน 23:00 จึงนอนน้อยกว่า"}],"solution":["จันทร์ 23:00–06:00 = 7 ชั่วโมง น้อยกว่าที่ควร","พุธ 21:00–06:00 = 9 ชั่วโมง อยู่ในช่วง 9–12 ชั่วโมงที่เด็กวัยนี้ควรได้"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดสนับสนุนได้ดีที่สุดว่าภูผาควรแก้เรื่องเวลานอนเป็นอันดับแรก","skill":"reason","points":10,"hints":["การนอนเร็วส่งผลต่อเรื่องอื่นในตอนเช้าอย่างไร"],"options":[{"text":"เมื่อนอนเร็วจะนอนพอ ตื่นทันเวลา และมีเวลากินอาหารเช้า ข้อมูลวันพุธยืนยันผลนี้","ok":true},{"text":"เพราะการนอนสำคัญกว่าอาหารเสมอ ไม่ต้องกินอาหารเช้าก็ได้","ok":false,"why":"อาหารเช้าก็สำคัญ การนอนเร็วช่วยให้มีเวลากินอาหารเช้าด้วย"},{"text":"เพราะแม่จะได้ไม่ต้องเก็บโทรศัพท์","ok":false,"why":"ไม่ใช่เหตุผลด้านสุขภาพ"},{"text":"เพราะนอนเร็วแล้วจะชอบวิชาคณิตศาสตร์ทันที","ok":false,"why":"ไม่มีข้อมูลเรื่องความชอบวิชา"}],"solution":["การนอนดึกเป็นต้นเหตุที่ทำให้ตื่นยาก ไม่มีเวลากินอาหารเช้า และง่วง","วันพุธแสดงให้เห็นว่าเมื่อแก้เรื่องนี้ ปัญหาอื่นดีขึ้นด้วย"],"answer":0},{"kind":"order","prompt":"เรียงแผนดูแลตัวเองของภูผาตั้งแต่ตอนค่ำจนถึงก่อนไปโรงเรียน","skill":"planning","points":10,"hints":["ดูเวลาในแต่ละขั้น และคิดว่าอะไรต้องเกิดก่อน"],"items":["20:30 วางโทรศัพท์ไว้นอกห้องนอน","20:45 แปรงฟันแล้วขึ้นเตียง","21:00 ปิดไฟนอนหลับ","06:00 ตื่นนอน","06:30 กินอาหารเช้าก่อนออกจากบ้าน"],"solution":["วางโทรศัพท์ก่อนนอนเพื่อไม่ให้มีสิ่งล่อใจ นอน 21:00 ได้ 9 ชั่วโมง","ตื่นตรงเวลาแล้วจึงมีเวลากินอาหารเช้า"]}]}', 'hard', 21),
('health_detective', 'คดีปวดท้องหลังทัศนศึกษา', '{"icon":"🚌","story":["หลังกลับจากทัศนศึกษา มีนักเรียน 2 คนปวดท้อง","คุณครูให้นักสืบเทียบข้อมูลของเพื่อน 4 คนเพื่อหาเบาะแสร่วม"],"tip":"เบาะแสร่วมคือสิ่งที่คนมีอาการทำเหมือนกัน แต่คนไม่มีอาการไม่ได้ทำ","context":[{"type":"table","title":"ข้อมูลของเพื่อน 4 คน","head":["ชื่อ","อาหารที่กิน","ล้างมือก่อนกิน","อาการ"],"rows":[["มะปราง","ข้าวมันไก่ร้านริมทาง และน้ำแข็งไส","ไม่ได้ล้าง","ปวดท้อง"],["ใบเฟิร์น","ข้าวมันไก่ร้านริมทาง","ล้างด้วยสบู่","ปกติ"],["ต้นกล้า","แซนด์วิชจากบ้าน และน้ำแข็งไส","ไม่ได้ล้าง","ปวดท้อง"],["ภูผา","แซนด์วิชจากบ้าน","ล้างด้วยสบู่","ปกติ"]]},{"type":"note","text":"นักสืบสังเกตว่ารถเข็นน้ำแข็งไสตักน้ำแข็งจากถังที่ไม่มีฝาปิด"}],"steps":[{"kind":"multi","prompt":"ข้อมูลใดเป็นเบาะแสร่วมของคนที่ปวดท้อง (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["ดูเฉพาะมะปรางกับต้นกล้า ทั้งคู่มีอะไรเหมือนกัน","แล้วคนที่ปกติทำสิ่งนั้นด้วยไหม"],"options":[{"text":"กินน้ำแข็งไสจากถังที่ไม่มีฝาปิด","ok":true},{"text":"ไม่ได้ล้างมือก่อนกิน","ok":true},{"text":"กินข้าวมันไก่ร้านริมทาง","ok":false,"why":"ต้นกล้าไม่ได้กินข้าวมันไก่แต่ก็ปวดท้อง จึงไม่ใช่เบาะแสร่วม"},{"text":"กินแซนด์วิชจากบ้าน","ok":false,"why":"มะปรางไม่ได้กินแซนด์วิชแต่ก็ปวดท้อง"}],"solution":["คนที่ปวดท้องทั้งสองคนกินน้ำแข็งไสและไม่ได้ล้างมือ","คนที่ปกติทั้งสองคนล้างมือด้วยสบู่และไม่ได้กินน้ำแข็งไส"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่บอกว่าการล้างมือเกี่ยวข้องกับอาการปวดท้องในคดีนี้","skill":"reason","points":10,"hints":["เทียบคอลัมน์ล้างมือก่อนกินกับคอลัมน์อาการ"],"options":[{"text":"คนที่ล้างมือด้วยสบู่ไม่มีอาการ ส่วนคนที่ไม่ล้างมือมีอาการ เพราะเชื้อโรคบนมือเข้าปากพร้อมอาหารได้","ok":true},{"text":"เพราะทุกคนที่กินแซนด์วิชไม่ปวดท้อง","ok":false,"why":"ต้นกล้ากินแซนด์วิชแล้วปวดท้อง ข้อนี้จึงขัดกับข้อมูล"},{"text":"เพราะสบู่มีกลิ่นหอม ทำให้อาหารอร่อยขึ้น","ok":false,"why":"กลิ่นสบู่ไม่เกี่ยวกับการป้องกันโรค"},{"text":"เพราะคนที่ล้างมือกินอาหารน้อยกว่า","ok":false,"why":"ไม่มีข้อมูลเรื่องปริมาณอาหาร"}],"solution":["ข้อมูลทั้ง 4 คน