('health_detective', 'คดีเวียนหัวกลางสนาม', '{"icon":"☀️","story":["ต้นน้ำซ้อมฟุตบอลกลางแดดเพื่อเตรียมแข่ง","ซ้อมไปได้ชั่วโมงกว่า เขาเริ่มปวดหัว เวียนหัว และหน้าแดง"],"tip":"เมื่อร่างกายผิดปกติขณะออกกำลังกาย ให้หยุดและบอกผู้ใหญ่ทันที","context":[{"type":"table","title":"บันทึกการซ้อมของต้นน้ำ","head":["เวลา","พฤติกรรม","อาการ"],"rows":[["13:00","เริ่มซ้อมฟุตบอลกลางแดดจัด","ปกติ"],["13:45","ยังไม่ได้ดื่มน้ำเลย","เหงื่อออกมาก กระหายน้ำ"],["14:15","ซ้อมต่อโดยไม่พัก","ปวดหัว เวียนหัว หน้าแดง"]]},{"type":"note","text":"ขวดน้ำของต้นน้ำลืมไว้ในห้องเรียน ต้นน้ำพูดว่า \"ผมไม่อยากพัก กลัวโค้ชว่า\""}],"steps":[{"kind":"multi","prompt":"ข้อมูลใดเป็นสาเหตุที่ทำให้ต้นน้ำมีอาการเวียนหัว (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["ร่างกายเสียน้ำไปทางไหน และได้น้ำกลับคืนหรือไม่"],"options":[{"text":"ไม่ได้ดื่มน้ำระหว่างซ้อม","ok":true},{"text":"ซ้อมกลางแดดจัดเป็นเวลานาน","ok":true},{"text":"เหงื่อออกมากแต่ไม่ได้พัก","ok":true},{"text":"เล่นฟุตบอล","ok":false,"why":"ฟุตบอลเป็นกีฬาที่ดี ปัญหาอยู่ที่แดดจัดและขาดน้ำ"}],"solution":["เหงื่อที่ออกมากทำให้ร่างกายเสียน้ำ เมื่อไม่ได้ดื่มน้ำและอยู่กลางแดดนาน ร่างกายจึงผิดปกติ"]},{"kind":"choice","prompt":"ตอนนี้ต้นน้ำเวียนหัว ควรทำอย่างไรเป็นอย่างแรก","skill":"decision","points":10,"hints":["ความปลอดภัยต้องมาก่อนการซ้อม"],"options":[{"text":"หยุดซ้อม แล้วบอกโค้ชหรือครูทันที","ok":true},{"text":"ซ้อมต่อให้จบก่อน แล้วค่อยพัก","ok":false,"why":"อาการอาจรุนแรงขึ้น ต้องหยุดทันที"},{"text":"แอบไปนอนพักคนเดียวโดยไม่บอกใคร","ok":false,"why":"ถ้าอาการแย่ลงจะไม่มีใครช่วย ต้องบอกผู้ใหญ่"},{"text":"ดื่มน้ำอัดลมเย็น ๆ แล้วกลับไปซ้อมต่อ","ok":false,"why":"ยังไม่ได้หยุดพักและไม่ได้บอกผู้ใหญ่"}],"solution":["เมื่อร่างกายผิดปกติ ให้หยุดกิจกรรมและบอกผู้ใหญ่ทันที","ผู้ใหญ่จะช่วยพาไปพักในที่ร่มและดูแลต่อ"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้นน้ำควรบอกโค้ชแม้จะกลัวโค้ชว่า","skill":"reason","points":10,"hints":["เทียบผลเสียของการโดนว่ากับผลเสียของการฝืนซ้อม"],"options":[{"text":"ความปลอดภัยของร่างกายสำคัญกว่าการซ้อม และโค้