('health_detective', 'นักสืบประจำห้อง', '{"icon":"📋","story":["คุณครูมอบแฟ้มคดีของเพื่อน 4 คนให้นักสืบ","แต่ละคนมีปัญหาสุขภาพต่างกัน นักสืบต้องให้คำแนะนำที่ตรงกับสาเหตุของแต่ละคน"],"tip":"คำแนะนำที่ดีต้องแก้ที่สาเหตุของคนนั้น","context":[{"type":"table","title":"แฟ้มคดีเพื่อน 4 คน","head":["ชื่อ","พฤติกรรม","อาการ"],"rows":[["ภูผา","แปรงฟันวันละครั้ง กินลูกอมบ่อย","ปวดฟันกราม"],["มะปราง","กินขนมโดยไม่ล้างมือ","ปวดท้องบ่อย"],["ต้นกล้า","เล่นเกมจนถึงเที่ยงคืน ตื่น 06:00","ง่วงในห้องเรียน"],["ใบเฟิร์น","นั่งดูจอทั้งวันหลังเลิกเรียน ไม่ได้ออกไปวิ่งเล่น","เหนื่อยง่ายตอนเรียนพละ"]]}],"steps":[{"kind":"choice","prompt":"ใครควรบอกผู้ปกครองให้พาไปพบทันตแพทย์","skill":"analysis","points":10,"hints":["ดูช่องอาการ ใครมีปัญหาเกี่ยวกับฟัน"],"options":[{"text":"ภูผา","ok":true},{"text":"มะปราง","ok":false,"why":"มะปรางมีอาการปวดท้อง ไม่ใช่ปัญหาเรื่องฟัน"},{"text":"ต้นกล้า","ok":false,"why":"ต้นกล้ามีปัญหาเรื่องการนอน"},{"text":"ใบเฟิร์น","ok":false,"why":"ใบเฟิร์นมีปัญหาเรื่องการเคลื่อนไหวร่างกาย"}],"solution":["ภูผาปวดฟันกราม และมีพฤติกรรมเสี่ยงฟันผุ","อาการปวดฟันควรให้ทันตแพทย์ตรวจ"],"answer":0},{"kind":"plan","prompt":"เลือกคำแนะนำที่ตรงกับสาเหตุของเพื่อนแต่ละคน","skill":"planning","points":10,"hints":["จับคู่พฤติกรรมของแต่ละคนกับคำแนะนำที่แก้พฤติกรรมนั้น"],"fields":[{"id":"phupha","label":"ภูผา","options":[{"text":"แปรงฟันเช้าและก่อนนอน ครั้งละ 2 นาที และลดลูกอม","ok":true},{"text":"ล้างมือด้วยสบู่ก่อนกินขนม","ok":false,"why":"ไม่ได้แก้ปัญหาฟันของภูผา"},{"text":"เข้านอนให้เร็วขึ้น","ok":false,"why":"ภูผาไม่ได้มีปัญหาเรื่องการนอน"}],"answer":0},{"id":"maprang","label":"มะปราง","options":[{"text":"ล้างมือด้วยสบู่ก่อนกินอาหารและขนมทุกครั้ง","ok":true},{"text":"ออกไปวิ่งเล่นวันละ 60 นาที","ok":false,"why":"ไม่ได้แก้สาเหตุที่มะปรางปวดท้อง"},{"text":"แปรงฟันให้นานขึ้น","ok":false,"why":"มะปรางไม่ได้มีปัญหาเรื่องฟัน"}],"answer":0},{"id":"tonkla","label":"ต้นกล้า","options":[{"text":"เลิกเล่นเกมก่อน 20:30 และเข้านอน 21:00","ok":true},{"text":"เล่นเกมต่อแต่ตื่นสายขึ้น","ok":false,"why":"ต้องไปโรงเรียนตรงเวลา และการเล่นเกมดึกยังเป็นต้นเหตุ"},{"text":"ลดลูกอม","ok":false,"why":"ไม่ได้แก้ปัญหาการนอนของต้นกล้า"}],"answer":0},{"id":"baifern","label":"ใบเฟิร์น","options":[{"text":"ลดเวลาดูจอ และออกไปวิ่งเล่นหรือเล่นกีฬาอย่างน้อย 60 นาทีต่อวัน","ok":true},{"text":"นั่งพักให้มากขึ้นจะได้ไม่เหนื่อย","ok":false,"why":"ร่างกายจะยิ่งไม่แข็งแรง ต้องเคลื่อนไหวสม่ำเสมอ"},{"text":"ล้างมือบ่อย ๆ","ok":false,"why":"เป็นนิสัยที่ดี แต่ไม่ได้แก้ปัญหาเหนื่อยง่าย"}],"answer":0}],"solution":["ภูผาแก้เรื่องแปรงฟันและลูกอม มะปรางแก้เรื่องล้างมือ ต้นกล้าแก้เรื่องเวลานอน ใบเฟิร์นแก้เรื่องการเคลื่อนไหว"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่นักสืบไม่ให้คำแนะนำเดียวกันกับทุกคน","skill":"reason","points":10,"hints":["ช่องพฤติกรรมของแต่ละคนเหมือนกันไหม"],"options":[{"text":"แต่ละคนมีพฤติกรรมที่เป็นต้นเหตุต่างกัน ต้องแก้ที่ต้นเหตุของแต่ละคน","ok":true},{"text":"เพราะครูสั่งให้เขียนคำแนะนำให้ยาว","ok":false,"why":"ไม่ใช่เหตุผลด้านสุขภาพ"},{"text":"เพราะคำแนะนำเดียวกันจะทำให้ทุกคนป่วย","ok":false,"why":"ข้อนี้เกินจริง คำแนะนำที่ดีไม่ได้ทำให้ป่วย แค่อาจไม่ตรงปัญหา"},{"text":"เพราะเพื่อนแต่ละคนไม่ชอบกันจึงต้องแยก","ok":false,"why":"ไม่เกี่ยวกับปัญหาสุขภาพ"}],"solution":["อาการคล้ายกันอาจมีสาเหตุต่างกัน และสาเหตุต่างกันต้องแก้ต่างกัน","นักสืบจึงต้องอ่านทั้งพฤติกรรมและอาการก่อนให้คำแนะนำ"],"answer":0}]}', 'hard', 27),
('health_detective', 'คดีฟันของน้องมะปิ่น', '{"icon":"👧","story":["มะปรางสังเกตว่าน้องมะปิ่นวัย 6 ขวบ มีจุดสีดำที่ฟันกราม","มะปรางอยากสอนน้องดูแลฟันให้ถูกวิธี จึงจดสิ่งที่น้องทำทั้งวัน"],"tip":"แปรงให้ทั่วทุกซี่ทุกด้าน นานประมาณ 2 นาที วันละ 2 ครั้ง","context":[{"type":"table","title":"สิ่งที่น้องมะปิ่นทำ","head":["เวลา","พฤติกรรม"],"rows":[["07:00","แปรงเฉพาะฟันหน้า ประมาณ 30 วินาที"],["07:05","หยิบแปรงสีฟันของพี่มาใช้เพราะของตัวเองขนบานแล้ว"],["15:00","กินลูกอมระหว่างดูการ์ตูน"],["20:00","ดื่มนมรสหวานแล้วหลับไปเลย ไม่ได้แปรงฟัน"]]},{"type":"note","text":"มะปรางพูดว่า \"แปรงของน้องขนบานจนแปรงไม่เข้าซอกฟันแล้ว\""}],"steps":[{"kind":"multi","prompt":"พฤติกรรมใดของน้องมะปิ่นที่ต้องแก้ไข (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["ดูทั้งวิธีแปรง เวลาแปรง แปรงที่ใช้ และสิ่งที่กินก่อนนอน"],"options":[{"text":"แปรงเฉพาะฟันหน้า","ok":true},{"text":"แปรงเพียง 30 วินาที","ok":true},{"text":"ใช้แปรงสีฟันของพี่","ok":true},{"text":"ดื่มนมรสหวานแล้วนอนโดยไม่แปรงฟัน","ok":true},{"text":"แปรงฟันตอนเช้า","ok":false,"why":"การแปรงฟันตอนเช้าเป็นสิ่งที่ดี แต่ต้องแปรงให้ถูกวิธี"}],"solution":["ฟันกรามที่ไม่ได้แปรงมีเศษอาหารค้าง จึงผุได้ง่าย","น้ำตาลที่ค้างในปากตอนนอนทำให้ฟันผุ","แปรงสีฟันเป็นของใช้ส่วนตัว"]},{"kind":"order","prompt":"เรียงขั้นตอนการแปรงฟันที่มะปรางจะสอนน้อง","skill":"rules","points":10,"hints":["เริ่มจากเตรียมแปรง จบด้วยการเก็บแปรง"],"items":["บีบยาสีฟันลงบนแปรงสีฟันอันใหม่ของตัวเอง","แปรงให้ทั่วทุกซี่ ทั้งด้านนอก ด้านใน และด้านบดเคี้ยว นานประมาณ 2 นาที","บ้วนยาสีฟันออก","ล้างแปรงให้สะอาดแล้วเก็บไว้ในที่โปร่งให้แห้ง"],"solution":["เตรียมแปรงของตัวเอง แปรงให้ทั่วทุกด้าน บ้วนออก แล้วล้างและเก็บแปรง","ฟันกรามด้านบดเคี้ยวมีร่องลึก ต้องแปรงให้ถึง"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่น้องควรเปลี่ยนแปรงสีฟันที่ขนบานแล้ว","skill":"reason","points":10,"hints":["ดูคำพูดของมะปราง"],"options":[{"text":"แปรงที่ขนบานทำความสะอาดซอกฟันได้ไม่ดี เศษอาหารจึงค้างอยู่","ok":true},{"text":"เพราะแปรงใหม่มีสีสวยกว่า","ok":false,"why":"สีของแปรงไม่ใช่เหตุผลด้านสุขภาพ"},{"text":"เพราะใช้แปรงของพี่สะดวกกว่า","ok":false,"why":"แปรงสีฟันเป็นของใช้ส่วนตัว ไม่ควรใช้ร่วมกัน"},{"text":"เพราะแปรงใหม่ทำให้ไม่ต้องแปรงก่อนนอน","ok":false,"why":"ยังต้องแปรงวันละ 2 ครั้งเสมอ"}],"solution":["ขนแปรงที่บานไม่สามารถเข้าซอกฟันได้","แปรงใหม่ของตัวเองช่วยให้ทำความสะอาดได้ดีและไม่ติดเชื้อจากผู้อื่น"],"answer":0},{"kind":"choice","prompt":"จุดสีดำที่ฟันกรามของน้อง ควรจัดการอย่างไร","skill":"decision","points":10,"hints":["ใครเป็นผู้ตรวจและรักษาฟันผุได้"],"options":[{"text":"บอกพ่อแม่ให้พาน้องไปพบทันตแพทย์","ok":true},{"text":"ใช้ไม้จิ้มฟันขูดจุดดำออกเอง","ok":false,"why":"อาจทำให้ฟันและเหงือกบาดเจ็บ และไม่ได้รักษาฟันผุ"},{"text":"รอให้ฟันหลุดเองเพราะเป็นฟันน้ำนม","ok":false,"why":"ฟันน้ำนมผุก็ควรรักษา และฟันกรามแท้ซี่แรกขึ้นตอนประมาณ 6 ขวบ"},{"text":"แปรงจุดนั้นแรง ๆ ทุกวัน","ok":false,"why":"การแปรงแรงไม่ได้รักษาฟันที่ผุแล้ว และทำร้ายเหงือก"}],"solution":["จุดดำอาจเป็นฟันผุ ทันตแพทย์จะตรวจและรักษาได้","ควรพบทันตแพทย์ทุก 6 เดือนเพื่อตรวจฟัน"],"answer":0}]}', 'hard', 28),
('health_detective', 'คดีในครัวของยาย', '{"icon":"🍲","story":["ต้นกล้าอาสาช่วยยายทำกับข้าวมื้อเย็น","ครั้งก่อนที่ต้นกล้าช่วยทำ คนในบ้านปวดท้องกันหลายคน นักสืบจึงเฝ้าดูในครัว"],"tip":"อาหารสะอาดเริ่มจากมือสะอาด วัตถุดิบสะอาด และอุปกรณ์สะอาด","context":[{"type":"table","title":"สิ่งที่ต้นกล้าทำในครัว","head":["เวลา","พฤติกรรม"],"rows":[["16:00","ขุดดินปลูกต้นไม้ในสวน"],["16:30","เดินเข้าครัวทันที เล็บยาวและมีดินติดอยู่"],["16:35","หยิบผักกาดมาหั่นโดยไม่ล้างผัก"],["16:40","ใช้เขียงเดียวกันหั่นหมูดิบ แล้วหั่นแตงกวาสำหรับกินสด"],["17:00","ยายผัดหมูจนสุกดี"]]},{"type":"note","text":"ยายพูดว่า \"ครั้งก่อนกินแตงกวาที่ต้นกล้าหั่นแล้ว ทุกคนปวดท้องเลย\""}],"steps":[{"kind":"multi","prompt":"พฤติกรรมใดที่ทำให้อาหารไม่สะอาด (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["ใช้ข้อมูลจากคำพูดของยายด้วย อาหารชนิดไหนที่ไม่ได้ผ่านความร้อน"],"options":[{"text":"เข้าครัวโดยไม่ล้างมือหลังขุดดิน","ok":true},{"text":"เล็บยาวและมีดินติด","ok":true},{"text":"ไม่ล้างผักก่อนหั่น","ok":true},{"text":"ใช้เขียงเดียวกันหั่นหมูดิบแล้วหั่นแตงกวาที่กินสด","ok":true},{"text":"ผัดหมูจนสุกดี","ok":false,"why":"การทำให้สุกช่วยทำลายเชื้อโรค เป็นสิ่งที่ถูกต้อง"}],"solution":["ดินและเชื้อโรคจากมือ เล็บ ผักที่ไม่ล้าง และเขียงที่หั่นหมูดิบ ติดไปกับอาหารได้","แตงกวาที่กินสดไม่ได้ผ่านความร้อน เชื้อโรคจึงยังอยู่"]},{"kind":"choice","prompt":"ก่อนเข้าครัว ต้นกล้าควรทำอะไรกับมือและเล็บ","skill":"decision","points":10,"hints":["ดินซ่อนอยู่ตรงไหนบ้าง"],"options":[{"text":"ตัดเล็บให้สั้น แล้วล้างมือด้วยสบู่ให้สะอาดทั้งซอกนิ้วและปลายเล็บ","ok":true},{"text":"เช็ดมือกับผ้ากันเปื้อนก็พอ","ok":false,"why":"ดินและเชื้อโรคยังติดอยู่ที่มือและใต้เล็บ"},{"text":"ใส่ถุงมือทับมือที่มีดินโดยไม่ล้าง","ok":false,"why":"ต้องล้างมือให้สะอาดก่อนเสมอ"},{"text":"ล้างมือด้วยน้ำเปล่าแป๊บเดียว","ok":false,"why":"น้ำเปล่าแป๊บเดียวล้างดินใต้เล็บไม่ออก"}],"solution":["เล็บสั้นเก็บสิ่งสกปรกน้อยลง","การล้างมือด้วยสบู่ให้ถึงซอกนิ้วและปลายเล็บช่วยกำจัดดินและเชื้อโรค"],"answer":0},{"kind":"order","prompt":"เรียงขั้นตอนการช่วยยายทำกับข้าวอย่างสะอาด","skill":"planning","points":10,"hints":["อะไรต้องสะอาดก่อนจะเริ่มจับวัตถุดิบ"],"items":["ล้างมือด้วยสบู่ก่อนเข้าครัว","ล้างผักด้วยน้ำสะอาดหลาย ๆ ครั้ง","หั่นผักที่ล้างแล้ว และปรุงอาหารให้สุก","ตักอาหารใส่จานสะอาดแล้วปิดฝา","ล้างจานและเก็บอุปกรณ์หลังกินเสร็จ"],"solution":["มือสะอาด วัตถุดิบสะอาด ปรุงให้สุก ปิดฝากันแมลง แล้วล้างอุปกรณ์","ทุกขั้นช่วยไม่ให้เชื้อโรคปนเปื้อนอาหาร"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ไม่ควรใช้เขียงเดียวกันหั่นเนื้อดิบและผักที่กินสด","skill":"reason","points":10,"hints":["หมูถูกทำให้สุก แต่แตงกวาล่ะ"],"options":[{"text":"เชื้อโรคจากเนื้อดิบติดไปที่ผัก และผักที่กินสดไม่ได้ผ่านความร้อนที่จะทำลายเชื้อโรค","ok":true},{"text":"เพราะแตงกวาจะมีกลิ่นหมู","ok":false,"why":"กลิ่นไม่ใช่เหตุผลหลักด้านสุขภาพ"},{"text":"เพราะเขียงจะทื่อเร็ว","ok":false,"why":"เป็นเรื่องอุปกรณ์ ไม่ใช่สุขภาพ"},{"text":"เพราะหมูดิบจะสุกไม่ทั่ว","ok":false,"why":"การใช้เขียงไม่เกี่ยวกับความสุกของหมู"}],"solution":["เนื้อดิบอาจมีเชื้อโรค ซึ่งถูกทำลายเมื่อปรุงสุก","แต่ผักที่กินสดไม่ได้ผ่านความร้อน จึงควรแยกเขียงหรือล้างเขียงให้สะอาดก่อน"],"answer":0}]}', 'hard', 29),
('health_detective', 'คดีสัปดาห์ขยับร่างกาย', '{"icon":"📅","story":["ใบเตยจดบันทึกการเคลื่อนไหวร่างกายและเวลาดูจอตลอด 1 สัปดาห์","ใบเตยมั่นใจว่าตัวเองออกกำลังกายเพียงพอแล้ว นักสืบจึงช่วยตรวจข้อมูล"],"tip":"เด็กควรเคลื่อนไหวร่างกายอย่างน้อย 60 นาทีทุกวัน และดูจอเพื่อความบันเทิงไม่เกิน 2 ชั่วโมงต่อวัน","context":[{"type":"table","title":"บันทึก 1 สัปดาห์ของใบเตย","head":["วัน","กิจกรรมที่ขยับร่างกาย","เวลาเคลื่อนไหว (นาที)","ดูจอเพื่อความบันเทิง (ชั่วโมง)"],"rows":[["จันทร์","เรียนพละและวิ่งเล่นช่วงพัก","70","1"],["อังคาร","เดินไปโรงเรียน","20","2"],["พุธ","ปั่นจักรยานกับพ่อ","60","1"],["พฤหัสบดี","ไม่ได้ออกไปไหน","0","4"],["ศุกร์","เตะฟุตบอล","45","2"],["เสาร์","ว่ายน้ำ","90","1"],["อาทิตย์","เดินเล่นในบ้าน","10","5"]]},{"type":"note","text":"ใบเตยพูดว่า \"สัปดาห์นี้หนูออกกำลังกายเยอะแล้ว เพราะวันเสาร์ว่ายน้ำตั้ง 90 นาที\""}],"steps":[{"kind":"multi","prompt":"วันใดที่ใบเตยเคลื่อนไหวร่างกายไม่ถึง 60 นาที (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["ดูคอลัมน์เวลาเคลื่อนไหว แล้วเทียบกับ 60 ทีละวัน"],"options":[{"text":"อังคาร","ok":true},{"text":"พฤหัสบดี","ok":true},{"text":"ศุกร์","ok":true},{"text":"อาทิตย์","ok":true},{"text":"จันทร์","ok":false,"why":"วันจันทร์เคลื่อนไหว 70 นาที ถึงเกณฑ์แล้ว"},{"text":"พุธ","ok":false,"why":"วันพุธเคลื่อนไหว 60 นาที ถึงเกณฑ์พอดี"},{"text":"เสาร์","ok":false,"why":"วันเสาร์เคลื่อนไหว 90 นาที ถึงเกณฑ์แล้ว"}],"solution":["มี 4 วันที่ไม่ถึง 60 นาที คืออังคาร พฤหัสบดี ศุกร์ และอาทิตย์"]},{"kind":"choice","prompt":"คำพูดของใบเตยที่ว่า \"ออกกำลังกายเยอะแล้ว\" ถูกต้องหรือไม่ เพราะอะไร","skill":"reason","points":10,"hints":["ลองนับจำนวนวันที่ถึงเกณฑ์ และดูวันที่ดูจอมากด้วย"],"options":[{"text":"ยังไม่ถูก เพราะมีถึง 4 วันที่เคลื่อนไหวไม่ถึง 60 นาที และวันพฤหัสบดีกับวันอาทิตย์ยังดูจอเกิน 2 ชั่วโมง","ok":true},{"text":"ถูกแล้ว เพราะวันเสาร์ว่ายน้ำ 90 นาที ซึ่งมากที่สุดในสัปดาห์","ok":false,"why":"วันเดียวที่มากไม่ได้ทำให้อีก 4 วันที่น้อยหายไป"},{"text":"ถูกแล้ว เพราะเคลื่อนไหวทุกวันอย่างน้อย 1 นาที","ok":false,"why":"วันพฤหัสบดีเคลื่อนไหว 0 นาที และเกณฑ์คือ 60 นาทีต่อวัน"},{"text":"ยังไม่ถูก เพราะว่ายน้ำไม่นับเป็นการออกกำลังกาย","ok":false,"why":"ว่ายน้ำเป็นการออกกำลังกายที่ดี"}],"solution":["ทั้งสัปดาห์เคลื่อนไหวรวม 295 นาที เฉลี่ยประมาณ 42 นาทีต่อวัน ยังน้อยกว่า 60 นาที","วันที่ดูจอมากคือวันที่เคลื่อนไหวน้อยที่สุด"],"answer":0},{"kind":"plan","prompt":"วางแผนแก้วันที่มีปัญหามากที่สุดของใบเตย เลือกหนึ่งข้อในแต่ละวัน","skill":"planning","points":10,"hints":["วันที่มีปัญหามากที่สุดมีทั้งการเคลื่อนไหวน้อยและดูจอเกิน","แผนต้องแก้ทั้งสองเรื่อง"],"fields":[{"id":"thu","label":"วันพฤหัสบดี","options":[{"text":"ดูจอไม่เกิน 2 ชั่วโมง แล้วไปเล่นแบดมินตันกับเพื่อน 60 นาที","ok":true},{"text":"ดูจอ 4 ชั่วโมงเหมือนเดิม แต่เดินไปห้องน้ำบ่อยขึ้น","ok":false,"why":"ยังดูจอเกิน 2 ชั่วโมง และเคลื่อนไหวไม่ถึง 60 นาที"},{"text":"ไม่ดูจอเลย แต่นอนอ่านหนังสือทั้งวัน","ok":false,"why":"ลดจอได้ดี แต่ยังไม่ได้เคลื่อนไหวร่างกาย"}],"answer":0},{"id":"sun","label":"วันอาทิตย์","options":[{"text":"ช่วยแม่ล้างรถ แล้วไปปั่นจักรยานรวม 60 นาที และดูจอไม่เกิน 2 ชั่วโมง","ok":true},{"text":"ว่ายน้ำ 3 ชั่วโมงเพื่อชดเชยทั้งสัปดาห์","ok":false,"why":"ควรเคลื่อนไหวพอดีทุกวัน และยังไม่ได้แก้เรื่องดูจอ"},{"text":"ดูจอ 5 ชั่วโมงเหมือนเดิม เพราะเป็นวันหยุด","ok":false,"why":"วันหยุดก็ควรดูจอไม่เกิน 2 ชั่วโมง"}],"answer":0}],"solution":["วันพฤหัสบดีและวันอาทิตย์มีทั้งเคลื่อนไหวน้อยและดูจอเกิน 2 ชั่วโมง","แผนที่ดีต้องลดเวลาดูจอและเพิ่มการเคลื่อนไหวให้ได้อย่างน้อย 60 นาที"]}]}', 'hard', 30),
('health_meal_chef', 'มื้อเช้าครบหมู่ของมะปราง', '{"icon":"🍳","story":["เช้าวันจันทร์ มะปรางต้องไปโรงเรียน แม่วางอาหารไว้บนโต๊ะให้เลือกเอง","มะปรางอยากได้มื้อเช้าที่มีทั้งโปรตีน ข้าวแป้ง และผลไม้ ส่วนน้ำอัดลมเก็บไว้ก่อน"],"tip":"ดูป้ายหมู่อาหารใต้เมนู แล้วเลือกให้ครบตามเงื่อนไข","steps":[{"kind":"meal","prompt":"จัดจานมื้อเช้าให้มะปราง 2–4 อย่าง ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["มื้อเช้าต้องมีครบ 3 หมู่ ลองหาอาหารที่มีป้ายโปรตีน คาร์โบไฮเดรต และผลไม้","น้ำอัดลมเป็นเครื่องดื่มรสหวาน ไม่ควรอยู่ในจาน"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อเช้า: ขนมปังโฮลวีต + ไข่ต้ม + กล้วยน้ำว้า + นมจืด","✓ มื้อเช้ามีโปรตีน คาร์โบไฮเดรต และผลไม้","✓ ไม่มี\"เครื่องดื่มรสหวาน\"","มื้อเช้าให้พลังงานสำหรับเรียนช่วงเช้า ถ้ามีหลายหมู่ร่างกายจะได้สารอาหารครบกว่า","นมจืดหรือน้ำเปล่าดีกว่าน้ำอัดลม เพราะไม่มีน้ำตาลมาก"],"showGroups":true,"foods":[{"name":"ข้าวสวย","icon":"🍚","groups":[2],"price":10,"tags":[]},{"name":"ขนมปังโฮลวีต","icon":"🍞","groups":[2],"price":15,"tags":[]},{"name":"ไข่ต้ม","icon":"🥚","groups":[1],"price":8,"tags":[]},{"name":"ไส้กรอกทอด","icon":"🌭","groups":[1,5],"price":15,"tags":["fried","oily"]},{"name":"กล้วยน้ำว้า","icon":"🍌","groups":[4],"price":5,"tags":[]},{"name":"ส้มเขียวหวาน","icon":"🍊","groups":[4],"price":10,"tags":[]},{"name":"นมจืด","icon":"🥛","groups":[1],"price":12,"tags":["cow_milk"]},{"name":"น้ำอัดลม","icon":"🥤","groups":[2],"price":15,"tags":["sugary_drink"]},{"name":"โดนัท","icon":"🍩","groups":[2,5],"price":20,"tags":["sweet","fried","oily"]}],"meals":[{"label":"มื้อเช้า","min":2,"max":4}],"rules":[{"type":"groups","groups":[1,2,4],"scope":0,"label":"มื้อเช้ามีโปรตีน คาร์โบไฮเดรต และผลไม้"},{"type":"maxTag","tag":"sugary_drink","tagLabel":"เครื่องดื่มรสหวาน","max":0,"scope":0}],"example":[[1,2,4,6]],"notes":["มื้อเช้าให้พลังงานสำหรับเรียนช่วงเช้า ถ้ามีหลายหมู่ร่างกายจะได้สารอาหารครบกว่า","นมจืดหรือน้ำเปล่าดีกว่าน้ำอัดลม เพราะไม่มีน้ำตาลมาก"]}],"context":[]}', 'easy', 1),
('health_meal_chef', 'กล่องข้าวกลางวันของภูผา', '{"icon":"🍱","story":["ภูผาเตรียมกล่องข้าวไปกินที่โรงเรียนเอง","เขาชอบของทอดมาก แต่ครูประจำชั้นบอกว่ากล่องข้าวที่ดีควรมีผักด้วย"],"steps":[{"kind":"meal","prompt":"จัดกล่องข้าวกลางวันให้ภูผา 3–4 อย่าง ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["ตรวจว่ามีผักอย่างน้อย 1 อย่างหรือยัง","นับของทอดในกล่อง ถ้าเกิน 1 อย่างให้เปลี่ยนเป็นเมนูย่างหรือต้ม"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: กล่องข้าวกลางวัน: ข้าวสวย + อกไก่ย่าง + ผัดผักรวม + ส้มเขียวหวาน","✓ กล่องข้าวมีโปรตีน คาร์โบไฮเดรต และผัก","✓ \"ของทอด\" ไม่เกิน 1 อย่าง","ของทอดมีไขมันมาก กินได้บ้างแต่ไม่ควรหลายอย่างในมื้อเดียว","ผักช่วยให้ได้เกลือแร่และใยอาหาร ช่วยให้ขับถ่ายดี"],"showGroups":true,"foods":[{"name":"ข้าวสวย","icon":"🍚","groups":[2],"price":10,"tags":[]},{"name":"ข้าวกล้อง","icon":"🍚","groups":[2],"price":12,"tags":[]},{"name":"ไก่ทอด","icon":"🍗","groups":[1,5],"price":25,"tags":["fried","oily"]},{"name":"หมูทอดกระเทียม","icon":"🥓","groups":[1,5],"price":25,"tags":["fried","oily"]},{"name":"อกไก่ย่าง","icon":"🍗","groups":[1],"price":25,"tags":[]},{"name":"ผัดผักรวม","icon":"🥦","groups":[3,5],"price":20,"tags":[]},{"name":"ผักลวกจิ้มน้ำพริก","icon":"🥕","groups":[3],"price":15,"tags":[]},{"name":"มันฝรั่งทอดกรอบ","icon":"🍟","groups":[2,5],"price":20,"tags":["fried","oily"]},{"name":"ส้มเขียวหวาน","icon":"🍊","groups":[4],"price":10,"tags":[]}],"meals":[{"label":"กล่องข้าวกลางวัน","min":3,"max":4}],"rules":[{"type":"groups","groups":[1,2,3],"scope":0,"label":"กล่องข้าวมีโปรตีน คาร์โบไฮเดรต และผัก"},{"type":"maxTag","tag":"fried","tagLabel":"ของทอด","max":1,"scope":0}],"example":[[0,4,5,8]],"notes":["ของทอดมีไขมันมาก กินได้บ้างแต่ไม่ควรหลายอย่างในมื้อเดียว","ผักช่วยให้ได้เกลือแร่และใยอาหาร ช่วยให้ขับถ่ายดี"]}],"context":[]}', 'easy', 2),
('health_meal_chef', 'ต้นกล้าไม่ชอบผัก', '{"icon":"🥦","story":["ต้นกล้าเขี่ยผักออกจากจานทุกครั้ง","แม่อยากให้ต้นกล้าได้กินผักโดยไม่ฝืนใจมากนัก จึงชวนต้นกล้ามาช่วยเลือกเมนูกลางวันวันเสาร์"],"steps":[{"kind":"choice","prompt":"วิธีใดช่วยให้ต้นกล้ากินผักได้ดีที่สุด","skill":"decision","points":10,"hints":["วิธีไหนทำให้ต้นกล้ายังได้กินผัก และไม่รู้สึกถูกบังคับ"],"solution":["การผสมผักในเมนูที่ชอบช่วยให้เด็กค่อย ๆ คุ้นกับผัก","ผัก (หมู่ 3) ให้เกลือแร่ ผลไม้ (หมู่ 4) ให้วิตามิน ควรกินทั้งสองหมู่"],"options":[{"text":"เลือกเมนูโปรดที่มีผักผสมอยู่ เช่น ข้าวผัดใส่ผักหั่นชิ้นเล็ก","ok":true},{"text":"ไม่ต้องกินผักเลย กินผลไม้อย่างเดียวแทนได้ทุกมื้อ","ok":false,"why":"ผักและผลไม้อยู่คนละหมู่ ให้สารอาหารไม่เหมือนกันทั้งหมด จึงควรกินทั้งสองอย่าง"},{"text":"บังคับให้กินผักจานใหญ่ให้หมดก่อนจึงจะกินอย่างอื่นได้","ok":false,"why":"การบังคับมักทำให้เด็กยิ่งไม่อยากกินผัก ค่อย ๆ เริ่มจากเมนูที่ชอบได้ผลดีกว่า"},{"text":"ให้กินขนมแทนข้าวมื้อนั้น","ok":false,"why":"ขนมไม่มีผัก และมักมีน้ำตาลหรือไขมันมาก"}],"answer":0},{"kind":"meal","prompt":"จัดมื้อกลางวันให้ต้นกล้า 2–3 อย่าง ให้มีครบ 4 หมู่ตามเงื่อนไข","skill":"planning","points":10,"hints":["ดูป้ายหมู่อาหาร เมนูไหนมีผักซ่อนอยู่บ้าง","อย่าลืมผลไม้ตบท้าย"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อกลางวัน: ข้าวผัดไก่ใส่ผัก + แตงโม","✓ มื้อกลางวันมีโปรตีน คาร์โบไฮเดรต ผัก และผลไม้","ข้าวผัดใส่ผักหรือก๋วยเตี๋ยวใส่ผัก ช่วยให้คนไม่ชอบผักได้กินผักง่ายขึ้น"],"showGroups":true,"foods":[{"name":"ข้าวสวย","icon":"🍚","groups":[2],"price":10,"tags":[]},{"name":"ข้าวผัดไก่ใส่ผัก","icon":"🍛","groups":[1,2,3,5],"price":35,"tags":[]},{"name":"ไข่เจียว","icon":"🍳","groups":[1,5],"price":12,"tags":["fried","oily"]},{"name":"ไก่ทอด","icon":"🍗","groups":[1,5],"price":25,"tags":["fried","oily"]},{"name":"ก๋วยเตี๋ยวน้ำใสหมูใส่ผัก","icon":"🍜","groups":[1,2,3],"price":35,"tags":[]},{"name":"แตงกวาหั่น","icon":"🥒","groups":[3],"price":5,"tags":[]},{"name":"แตงโม","icon":"🍉","groups":[4],"price":15,"tags":[]},{"name":"น้ำอัดลม","icon":"🥤","groups":[2],"price"