('health_meal_chef', 'เพื่อนแพ้นมวัว', '{"icon":"🥛","story":["ข้าวหอมแพ้นมวัว หมอบอกให้งดนมวัวและอาหารที่ทำจากนมวัว","วันนี้ข้าวหอมมาค้างบ้านใบเฟิร์น ใบเฟิร์นจึงช่วยจัดมื้อเช้าให้เพื่อน"],"steps":[{"kind":"meal","prompt":"จัดมื้อเช้าให้ข้าวหอม 3–4 อย่าง ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["อาหารไหนทำจากนมวัวบ้าง นม โยเกิร์ต และเค้กครีมล้วนมีนมวัว","ยังหาโปรตีนจากอย่างอื่นได้ เช่น ไข่ หรือนมถั่วเหลือง"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อเช้า: ขนมปังโฮลวีต + ไข่ต้ม + นมถั่วเหลืองสูตรหวานน้อย + กล้วยน้ำว้า","✓ มื้อเช้ามีโปรตีน คาร์โบไฮเดรต และผลไม้","✓ ไม่มี\"มีนมวัว\"","คนที่แพ้อาหารต้องงดอาหารนั้นตามที่หมอบอก และหาอาหารหมู่เดียวกันมาแทน","นมถั่วเหลืองและไข่ให้โปรตีนแทนนมวัวได้"],"showGroups":true,"foods":[{"name":"ขนมปังโฮลวีต","icon":"🍞","groups":[2],"price":15,"tags":[]},{"name":"ไข่ต้ม","icon":"🥚","groups":[1],"price":8,"tags":[]},{"name":"นมจืด","icon":"🥛","groups":[1],"price":12,"tags":["cow_milk"]},{"name":"นมถั่วเหลืองสูตรหวานน้อย","icon":"🥛","groups":[1],"price":12,"tags":[]},{"name":"โยเกิร์ตรสธรรมชาติ","icon":"🥣","groups":[1],"price":15,"tags":["cow_milk"]},{"name":"เค้กครีม","icon":"🍰","groups":[2,5],"price":30,"tags":["sweet","cow_milk"]},{"name":"กล้วยน้ำว้า","icon":"🍌","groups":[4],"price":5,"tags":[]},{"name":"ส้มเขียวหวาน","icon":"🍊","groups":[4],"price":10,"tags":[]}],"meals":[{"label":"มื้อเช้า","min":3,"max":4}],"rules":[{"type":"groups","groups":[1,2,4],"scope":0,"label":"มื้อเช้ามีโปรตีน คาร์โบไฮเดรต และผลไม้"},{"type":"maxTag","tag":"cow_milk","tagLabel":"มีนมวัว","max":0,"scope":0}],"example":[[0,1,3,6]],"notes":["คนที่แพ้อาหารต้องงดอาหารนั้นตามที่หมอบอก และหาอาหารหมู่เดียวกันมาแทน","นมถั่วเหลืองและไข่ให้โปรตีนแทนนมวัวได้"]}],"context":[]}', 'easy', 8),
('health_meal_chef', 'จานข้าวของเพื่อนร่วมโต๊ะ', '{"icon":"🍽️","story":["ตอนพักกลางวัน ต้นกล้านั่งกินข้าวกับเพื่อน 5 คน","ครูอนามัยให้ต้นกล้าสำรวจว่าจานของใครยังไม่มีผักเลย"],"context":[{"type":"table","title":"จานกลางวันของเพื่อนร่วมโต๊ะ","head":["ชื่อ","อาหารในจาน"],"rows":[["มะปราง","ข้าวสวย + แกงจืดผักกาดขาวเต้าหู้ + ไข่ต้ม"],["ภูผา","ข้าวมันไก่ + น้ำอัดลม"],["ใบเฟิร์น","ผัดไทยกุ้ง + ส้มเขียวหวาน"],["ข้าวหอม","ข้าวเหนียว + หมูปิ้ง + ไส้กรอกทอด"],["ปลื้ม","ข้าวสวย + ไข่เจียว + แตงโม"]]}],"steps":[{"kind":"multi","prompt":"จานของใครบ้างที่ยังไม่มีผักเลย เลือกให้ครบ","skill":"analysis","points":10,"hints":["ดูทีละจานว่ามีผักอยู่ในเมนูไหนบ้าง","แตงโมเป็นผลไม้ ไม่ใช่ผัก"],"solution":["ผักอาจซ่อนอยู่ในแกงหรือผัด จึงต้องดูส่วนผสมของเมนู","ผลไม้อยู่หมู่ 4 ส่วนผักอยู่หมู่ 3 จานของปลื้มจึงยังขาดผัก"],"options":[{"text":"ภูผา","ok":true},{"text":"ข้าวหอม","ok":true},{"text":"ปลื้ม","ok":true},{"text":"มะปราง","ok":false,"why":"แกงจืดผักกาดขาวมีผักอยู่แล้ว"},{"text":"ใบเฟิร์น","ok":false,"why":"ผัดไทยมีถั่วงอกและกุยช่ายซึ่งเป็นผัก"}]}]}', 'easy', 9),
('health_meal_chef', 'มื้อเช้าหน้าโรงเรียนงบ 40 บาท', '{"icon":"🍢","story":["ข้าวหอมตื่นสาย ไม่ทันกินมื้อเช้าที่บ้าน แม่ให้เงิน 40 บาทไปซื้อหน้าโรงเรียน","หน้าโรงเรียนมีทั้งหมูปิ้ง ข้าวเหนียว ผลไม้ และชานมไข่มุกร้านใหม่"],"steps":[{"kind":"meal","prompt":"เลือกมื้อเช้าให้ข้าวหอม 2–4 อย่าง ใช้เงินไม่เกิน 40 บาท","skill":"planning","points":10,"hints":["ชานมไข่มุกแก้วเดียวใช้เงินไปเกือบหมดแล้ว","ให้มีทั้งข้าวแป้งและโปรตีน แล้วรวมราคาอีกครั้ง"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อเช้า: ข้าวเหนียว + หมูปิ้ง + นมจืด + กล้วยน้ำว้า","✓ มื้อเช้ามีโปรตีนและคาร์โบไฮเดรต","✓ ใช้เงินรวมไม่เกิน 40 บาท","✓ ไม่มี\"เครื่องดื่มรสหวาน\"","ข้าวเหนียว หมูปิ้ง นม และกล้วย ได้หลายหมู่ในราคา 37 บาท","ชานมไข่มุกกับโดนัทใช้เงิน 55 บาท เกินงบ และมีน้ำตาลมาก"],"showGroups":true,"foods":[{"name":"ข้าวเหนียว","icon":"🍙","groups":[2],"price":10,"tags":[]},{"name":"หมูปิ้ง","icon":"🍢","groups":[1,5],"price":10,"tags":[]},{"name":"ไข่ต้ม","icon":"🥚","groups":[1],"price":8,"tags":[]},{"name":"นมจืด","icon":"🥛","groups":[1],"price":12,"tags":["cow_milk"]},{"name":"กล้วยน้ำว้า","icon":"🍌","groups":[4],"price":5,"tags":[]},{"name":"ชานมไข่มุก","icon":"🧋","groups":[2,5],"price":35,"tags":["sugary_drink"]},{"name":"ไส้กรอกทอด","icon":"🌭","groups":[1,5],"price":15,"tags":["fried","oily"]},{"name":"โดนัท","icon":"🍩","groups":[2,5],"price":20,"tags":["sweet","fried","oily"]}],"meals":[{"label":"มื้อเช้า","min":2,"max":4}],"rules":[{"type":"groups","groups":[1,2],"scope":0,"label":"มื้อเช้ามีโปรตีนและคาร์โบไฮเดรต"},{"type":"budget","max":40,"scope":0},{"type":"maxTag","tag":"sugary_drink","tagLabel":"เครื่องดื่มรสหวาน","max":0,"scope":0}],"example":[[0,1,3,4]],"notes":["ข้าวเหนียว หมูปิ้ง นม และกล้วย ได้หลายหมู่ในราคา 37 บาท","ชานมไข่มุกกับโดนัทใช้เงิน 55 บาท เกินงบ และมีน้ำตาลมาก"]}],"context":[]}', 'easy', 10),
