('health_meal_chef', 'วันกีฬาสีของภูผา', '{"icon":"🏅","story":["วันนี้มีกีฬาสี ภูผาต้องวิ่งผลัดตอนบ่ายโมงครึ่ง","ครูพละบอกว่ามื้อกลางวันก่อนแข่งไม่ควรมีอาหารมันมาก และหลังแข่งต้องดื่มน้ำเปล่าชดเชยเหงื่อ"],"context":[{"type":"table","title":"กำหนดการวันกีฬาสี","head":["เวลา","กิจกรรม"],"rows":[["07:00","กินมื้อเช้า"],["11:00","กินมื้อกลางวัน"],["13:30","วิ่งผลัด"],["15:00","พักกินของว่าง"],["18:00","กินมื้อเย็นที่บ้าน"]]}],"steps":[{"kind":"meal","prompt":"วางแผนอาหารทั้งวันให้ภูผา ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["มื้อไหนอยู่ใกล้เวลาแข่งที่สุด มื้อนั้นต้องเลี่ยงอาหารมันมาก","ของว่างหลังแข่งต้องมีน้ำเปล่า"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อเช้า: โจ๊กหมูใส่ไข่ + ส้มเขียวหวาน · มื้อกลางวัน: ก๋วยเตี๋ยวน้ำใสหมูใส่ผัก + กล้วยน้ำว้า · ของว่างหลังแข่ง: น้ำเปล่า + นมจืด · มื้อเย็น: ข้าวสวย + อกไก่ย่าง + ผัดผักรวม","✓ ทั้งวันมีอาหาร โปรตีน คาร์โบไฮเดรต ผัก ผลไม้ ไขมัน","✓ ไม่เลือกเมนูเดิมซ้ำ","✓ มื้อกลางวันก่อนแข่งไม่มีอาหารมันมาก ย่อยช้า","✓ ของว่างหลังแข่งมีน้ำเปล่า","ก๋วยเตี๋ยวน้ำใสย่อยง่ายกว่าข้าวกะเพราไข่ดาวหรือของทอด","หลังออกกำลังกายเสียเหงื่อมาก ควรดื่มน้ำเปล่าชดเชย"],"foods":[{"name":"โจ๊กหมูใส่ไข่","icon":"🥣","groups":[1,2],"price":30,"tags":[]},{"name":"ไข่ต้ม","icon":"🥚","groups":[1],"price":8,"tags":[]},{"name":"ข้าวสวย","icon":"🍚","groups":[2],"price":10,"tags":[]},{"name":"ก๋วยเตี๋ยวน้ำใสหมูใส่ผัก","icon":"🍜","groups":[1,2,3],"price":35,"tags":[]},{"name":"ข้าวกะเพราไก่ไข่ดาว","icon":"🍛","groups":[1,2,3,5],"price":45,"tags":["fried","oily"]},{"name":"ไก่ทอด","icon":"🍗","groups":[1,5],"price":25,"tags":["fried","oily"]},{"name":"ข้าวมันไก่","icon":"🍗","groups":[1,2,5],"price":40,"tags":["oily"]},{"name":"อกไก่ย่าง","icon":"🍗","groups":[1],"price":25,"tags":[]},{"name":"ผัดผักรวม","icon":"🥦","groups":[3,5],"price":20,"tags":[]},{"name":"กล้วยน้ำว้า","icon":"🍌","groups":[4],"price":5,"tags":[]},{"name":"ส้มเขียวหวาน","icon":"🍊","groups":[4],"price":10,"tags":[]},{"name":"น้ำเปล่า","icon":"💧","groups":[],"price":7,"tags":["water"]},{"name":"น้ำอัดลม","icon":"🥤","groups":[2],"price":15,"tags":["sugary_drink"]},{"name":"นมจืด","icon":"🥛","groups":[1],"price":12,"tags":["cow_milk"]}],"meals":[{"label":"มื้อเช้า","min":1,"max":3},{"label":"มื้อกลางวัน","min":1,"max":3},{"label":"ของว่างหลังแข่ง","min":1,"max":2},{"label":"มื้อเย็น","min":1,"max":3}],"rules":[{"type":"groups","groups":[1,2,3,4,5],"scope":"all"},{"type":"noRepeat"},{"type":"maxTag","tag":"oily","tagLabel":"อาหารมันมาก ย่อยช้า","max":0,"scope":1,"label":"มื้อกลางวันก่อนแข่งไม่มีอาหารมันมาก ย่อยช้า"},{"type":"minTag","tag":"water","tagLabel":"น้ำเปล่า","min":1,"scope":2,"label":"ของว่างหลังแข่งมีน้ำเปล่า"}],"example":[[0,10],[3,9],[11,13],[2,7,8]],"notes":["ก๋วยเตี๋ยวน้ำใสย่อยง่ายกว่าข้าวกะเพราไข่ดาวหรือของทอด","หลังออกกำลังกายเสียเหงื่อมาก ควรดื่มน้ำเปล่าชดเชย"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่มื้อกลางวันของภูผาควรเป็นอาหารย่อยง่าย","skill":"reason","points":10,"hints":["ดูเวลาในตาราง มื้อกลางวันห่างจากเวลาวิ่งกี่ชั่วโมง"],"solution":["มื้อกลางวัน 11:00 ห่างจากการวิ่ง 2 ชั่วโมงครึ่ง ถ้าอาหารยังย่อยไม่หมดอาจจุกได้"],"options":[{"text":"เพราะอีกไม่กี่ชั่วโมงต้องวิ่ง อาหารมันย่อยช้าอาจทำให้จุกเสียดขณะวิ่ง","ok":true},{"text":"เพราะอาหารย่อยง่ายทำให้วิ่งเร็วขึ้นทันที","ok":false,"why":"อาหารไม่ได้ทำให้วิ่งเร็วขึ้นทันที แต่ช่วยไม่ให้อึดอัดท้องขณะวิ่ง"},{"text":"เพราะนักกีฬาควรอดอาหารกลางวันก่อนแข่ง","ok":false,"why":"การอดอาหารทำให้ขาดพลังงาน ควรกินอาหารย่อยง่ายในปริมาณพอดี"},{"text":"เพราะอาหารมันมากไม่มีพลังงาน","ok":false,"why":"อาหารมันมากมีพลังงานสูง แต่ย่อยช้า"}],"answer":0}]}', 'medium', 12),
