เลือกของที่ชอบเพียงบางอย่าง และสลับวันกิน ช่วยให้ได้ทั้งความอร่อยและสุขภาพ"],"options":[{"text":"เลือกกินเพียงอย่างเดียววันนี้ อีกอย่างเก็บไว้วันอื่น และกินคู่กับผัก","ok":true},{"text":"กินทั้งสองอย่างแต่ดื่มน้ำอัดลมช่วยย่อย","ok":false,"why":"น้ำอัดลมไม่ได้ช่วยย่อย และเพิ่มน้ำตาลอีก"},{"text":"กินทั้งสองอย่างแล้วงดมื้อเย็น","ok":false,"why":"การงดมื้ออาหารทำให้ขาดสารอาหาร และยังได้ของทอด 2 อย่างอยู่ดี"},{"text":"กินทั้งสองอย่างโดยไม่ต้องกินผัก เพราะวันนี้กินผักไปแล้ว","ok":false,"why":"เงื่อนไขคือต้องมีผักทั้งมื้อกลางวันและมื้อเย็น"}],"answer":0}]}', 'hard', 24),
('health_meal_chef', 'มะปรางแพ้นมวัว งบ 125 บาท', '{"icon":"🥛","story":["มะปรางแพ้นมวัว หมอสั่งให้งดนมวัวและอาหารที่ทำจากนมวัวทุกชนิด","วันนี้มะปรางไปเข้าค่ายวิทยาศาสตร์ทั้งวัน ต้องเลือกอาหารเองจากร้านในค่าย งบ 125 บาท"],"context":[{"type":"table","title":"ฉลากส่วนผสมที่ร้านในค่ายติดไว้","head":["อาหาร","ส่วนผสมหลัก"],"rows":[["นมจืด","นมวัว"],["โยเกิร์ตรสธรรมชาติ","นมวัวหมัก"],["เค้กครีม","แป้ง ไข่ เนย ครีมจากนมวัว"],["นมถั่วเหลืองสูตรหวานน้อย","ถั่วเหลือง น้ำ น้ำตาลเล็กน้อย"],["ไข่ต้ม","ไข่ไก่"]]},{"type":"note","text":"มะปรางต้องได้โปรตีนจากแหล่งอื่นแทนนมวัว และทั้งวันต้องครบ 5 หมู่ มีน้ำเปล่า ไม่ซ้ำเมนู"}],"steps":[{"kind":"multi","prompt":"จากฉลาก อาหารใดบ้างที่มะปรางต้องงด เลือกให้ครบ","skill":"analysis","points":10,"hints":["อ่านช่องส่วนผสมหลัก หาคำว่านมวัว เนย หรือครีม"],"solution":["เนยและครีมทำจากนมวัว อาหารที่ดูไม่เหมือนนมจึงอาจมีนมวัวได้ ต้องอ่านฉลากเสมอ"],"options":[{"text":"นมจืด","ok":true},{"text":"โยเกิร์ตรสธรรมชาติ","ok":true},{"text":"เค้กครีม","ok":true},{"text":"นมถั่วเหลืองสูตรหวานน้อย","ok":false,"why":"ทำจากถั่วเหลือง ไม่มีนมวัว"},{"text":"ไข่ต้ม","ok":false,"why":"ไข่ไก่ไม่ใช่นมวัว"}]},{"kind":"meal","prompt":"วางแผนอาหารทั้งวันให้มะปราง ใช้งบไม่เกิน 125 บาท และผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["โปรตีนแทนนมวัวมีทั้งไข่ หมูปิ้ง ปลา และนมถั่วเหลือง","รวมราคาทีละมื้อ ถ้าเกินงบให้ลองตัดอาหารที่ให้หมู่ซ้ำกับเมนูอื่น"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อเช้า: ข้าวเหนียว + หมูปิ้ง + นมถั่วเหลืองสูตรหวานน้อย · มื้อกลางวัน: ก๋วยเตี๋ยวน้ำใสหมูใส่ผัก + น้ำเปล่า · ของว่าง: กล้วยน้ำว้า · มื้อเย็น: ข้าวสวย + ปลาทูนึ่ง + ผัดผักรวม","✓ ใช้เงินรวมไม่เกิน 125 บาท","✓ ทั้งวันมีอาหาร โปรตีน คาร์โบไฮเดรต ผัก ผลไม้ ไขมัน","✓ ไม่เลือกเมนูเดิมซ้ำ","✓ ไม่มี\"มีนมวัว\"","✓ มี\"น้ำเปล่า\" อย่างน้อย 1 อย่าง","ตัวอย่างนี้ใช้เงิน 124 บาท และไม่มีนมวัวเลย","นมถั่วเหลืองและหมูปิ้งให้โปรตีนแทนนมวัวได้"],"foods":[{"name":"ข้าวเหนียว","icon":"🍙","groups":[2],"price":10,"tags":[]},{"name":"หมูปิ้ง","icon":"🍢","groups":[1,5],"price":10,"tags":[]