('health_meal_chef', 'วันสอบปลายภาคงบ 115 บาท', '{"icon":"📚","story":["ใบเฟิร์นสอบปลายภาคทั้งวัน มีพักสั้น ๆ ระหว่างวิชา","แม่ให้งบ 115 บาทสำหรับซื้ออาหารทั้งวันจากร้านหน้าบ้านและโรงอาหาร"],"context":[{"type":"table","title":"ตารางสอบ","head":["เวลา","วิชา"],"rows":[["08:30–10:00","คณิตศาสตร์"],["10:15–11:30","ภาษาไทย"],["13:00–14:30","วิทยาศาสตร์"],["14:30–14:45","พักกินของว่าง"],["14:45–15:45","สังคมศึกษา"]]},{"type":"note","text":"มื้อเช้าต้องมีโปรตีน ข้าวแป้ง และผลไม้ ทั้งวันครบ 5 หมู่ ไม่ซ้ำเมนู งดเครื่องดื่มหวาน มีน้ำเปล่า และของทอดไม่เกิน 1 อย่าง"}],"steps":[{"kind":"choice","prompt":"จากตารางสอบ ถ้าใบเฟิร์นข้ามมื้อใด จะกระทบการสอบมากที่สุด","skill":"analysis","points":10,"hints":["ช่วงไหนในตารางที่สอบนานที่สุดโดยไม่มีมื้ออาหารคั่น"],"solution":["มื้อเช้าให้พลังงานสำหรับการสอบช่วงเช้าทั้งหมด"],"options":[{"text":"มื้อเช้า เพราะต้องสอบ 2 วิชาติดกันตั้งแต่ 08:30 ถึง 11:30","ok":true},{"text":"มื้อเย็น เพราะเป็นมื้อสุดท้าย","ok":false,"why":"มื้อเย็นอยู่หลังสอบเสร็จแล้ว"},{"text":"ของว่าง เพราะพักแค่ 15 นาที","ok":false,"why":"ของว่างช่วยได้ แต่ช่วงสอบที่ยาวที่สุดคือช่วงเช้า"},{"text":"ไม่มีมื้อไหนกระทบ","ok":false,"why":"ถ้าท้องว่าง ร่างกายจะขาดพลังงานและไม่มีสมาธิ"}],"answer":0},{"kind":"meal","prompt":"วางแผนอาหารทั้งวันให้ใบเฟิร์น ใช้งบไม่เกิน 115 บาท และผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["มื้อเช้าต้องครบ 3 หมู่ อาหารชิ้นเล็กราคาถูกหลายอย่างรวมกันอาจคุ้มกว่าเมนูจานเดียว","ของว่างช่วงพักสั้น ๆ เลือกของที่กินเร็วและไม่หวาน"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อเช้า: ขนมปังโฮลวีต + ไข่ต้ม + กล้วยน้ำว้า · มื้อกลางวัน: ข้าวผัดไก่ใส่ผัก + น้ำเปล่า · ของว่างช่วงพักสอบ: ส้มเขียวหวาน · มื้อเย็น: ข้าวสวย + แกงจืดผักกาดขาวเต้าหู้","✓ ใช้เงินรวมไม่เกิน 115 บาท","✓ ทั้งวันมีอาหาร โปรตีน คาร์โบไฮเดรต ผัก ผลไม้ ไขมัน","✓ ไม่เลือกเมนูเดิมซ้ำ","✓ มื้อเช้ามีโปรตีน คาร์โบไฮเดรต และผลไม้","✓ ไม่มี\"เครื่องดื่มรสหวาน\"","✓ มี\"น้ำเปล่า\" อย่างน้อย 1 อย่าง","✓ \"ของทอด\" ไม่เกิน 1 อย่าง","ตัวอย่างนี้ใช้เงิน 115 บาทพอดี และมื้อเช้าครบ 3 หมู่","โดนัทกับน้ำอัดลมให้พลังงานเร็วแต่หมดเร็ว และขาดโปรตีนกับผลไม้"],"foods":[{"name":"ขนมปังโฮลวีต","icon":"🍞","groups":[2],"price":15,"tags":[]},{"name":"ไข่ต้ม","icon":"🥚","groups":[1],"price":8,"tags":[]},{"name":"โจ๊กหมูใส่ไข่","icon":"🥣","groups":[1,2],"price":30,"tags":[]},{"name":"โดนัท","icon":"🍩","groups":[2,5],"price":20,"tags":["sweet","fried","oily"]},{"name":"นมจืด","icon":"🥛","groups":[1],"price":12,"tags":["cow_milk"]},{"name":"กล้วยน้ำว้า","icon":"🍌","groups":[4],"price":5,"tags":[]},{"name":"ส้มเขียวหวาน","icon":"🍊","groups":[4],"price":10,"tags":[]},{"name":"ข้าวผัดไก่ใส่ผัก","icon":"🍛","groups":[1,2,3,5],"price":35,"tags":[]},{"name":"ข้าวกะเพราไก่ไข่ดาว","icon":"🍛","groups":[1,2,3,5],"price":45,"tags":["fried","oily"]},{"name":"ข้าวสวย","icon":"🍚","groups":[2],"price":10,"tags":[]},{"name":"แกงจืดผักกาดขาวเต้าหู้","icon":"🍲","groups":[1,3],"price":25,"tags":[]},{"name":"ผัดผักบุ้ง","icon":"🥬","groups":[3,5],"price":20,"tags":[]},{"name":"น้ำเปล่า","icon":"💧","groups":[],"price":7,"tags":["water"]},{"name":"น้ำอัดลม","icon":"🥤","groups":[2],"price":15,"tags":["sugary_drink"]}],"meals":[{"label":"มื้อเช้า","min":1,"max":3},{"label":"มื้อกลางวัน","min":1,"max":3},{"label":"ของว่างช่วงพักสอบ","min":1,"max":2},{"label":"มื้อเย็น","min":1,"max":3}],"rules":[{"type":"budget","max":115,"scope":"all"},{"type":"groups","groups":[1,2,3,4,5],"scope":"all"},{"type":"noRepeat"},{"type":"groups","groups":[1,2,4],"scope":0,"label":"มื้อเช้ามีโปรตีน คาร์โบไฮเดรต และผลไม้"},{"type":"maxTag","tag":"sugary_drink","tagLabel":"เครื่องดื่มรสหวาน","max":0,"scope":"all"},{"type":"minTag","tag":"water","tagLabel":"น้ำเปล่า","min":1,"scope":"all"},{"type":"maxTag","tag":"fried","tagLabel":"ของทอด","max":1,"scope":"all"}],"example":[[0,1,5],[7,12],[6],[9,10]],"notes":["ตัวอย่างนี้ใช้เงิน 115 บาทพอดี และมื้อเช้าครบ 3 หมู่","โดนัทกับน้ำอัดลมให้พลังงานเร็วแต่หมดเร็ว และขาดโปรตีนกับผลไม้"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ของว่างช่วงพักสอบควรเป็นผลไม้หรือนมจืด มากกว่าโดนัทก