('health_meal_chef', 'ตลาดนัดวันหยุดงบ 100 บาท', '{"icon":"🛍️","story":["ข้าวหอมไปเดินตลาดนัดกับพี่สาวตั้งแต่เช้าจนบ่าย ต้องซื้อมื้อเช้า มื้อกลางวัน และของว่างที่ตลาด ส่วนมื้อเย็นกลับไปกินที่บ้าน","ข้าวหอมมีเงิน 100 บาท และอยากกินไอศกรีมมาก"],"context":[{"type":"table","title":"แผนเดินตลาด","head":["เวลา","กิจกรรม"],"rows":[["08:00","ซื้อมื้อเช้า"],["12:00","กินมื้อกลางวัน"],["14:00","ของว่างก่อนกลับบ้าน"],["18:00","มื้อเย็นที่บ้าน (ไม่ต้องใช้เงิน)"]]},{"type":"note","text":"พี่สาวตั้งกติกา: สามมื้อที่ตลาดต้องครบ 5 หมู่ ไม่ซ้ำเมนู ขนมหวานได้ 1 อย่าง ของทอดได้ 1 อย่าง งดเครื่องดื่มหวาน และต้องมีน้ำเปล่า"}],"steps":[{"kind":"meal","prompt":"วางแผนอาหารที่ตลาดนัดให้ข้าวหอม ใช้งบไม่เกิน 100 บาท และผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["ไอศกรีมกินได้ 1 อย่าง แต่ต้องดูว่าเงินที่เหลือพอซื้อผลไม้หรือไม่","ผัดไทยมีหลายหมู่ในจานเดียว แต่ราคา 45 บาท ลองรวมราคาทั้งสามมื้อ"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อเช้า: ข้าวเหนียว + หมูปิ้ง + นมจืด · มื้อกลางวัน: ผัดไทยกุ้ง · ของว่าง: แตงโม + น้ำเปล่า","✓ ใช้เงินรวมไม่เกิน 100 บาท","✓ ทั้งวันมีอาหาร โปรตีน คาร์โบไฮเดรต ผัก ผลไม้ ไขมัน","✓ ไม่เลือกเมนูเดิมซ้ำ","✓ \"ขนมหวาน\" ไม่เกิน 1 อย่าง","✓ \"ของทอด\" ไม่เกิน 1 อย่าง","✓ ไม่มี\"เครื่องดื่มรสหวาน\"","✓ มี\"น้ำเปล่า\" อย่างน้อย 1 อย่าง","ตัวอย่างนี้ใช้เงิน 99 บาท ได้ครบ 5 หมู่","ไอศกรีมกินได้ 1 อย่างตามกติกา แต่ต้องลดอย่างอื่นให้อยู่ในงบ และยังต้องมีผลไม้"],"foods":[{"name":"โจ๊กหมูใส่ไข่","icon":"🥣","groups":[1,2],"price":30,"tags":[]},{"name":"ผัดไทยกุ้ง","icon":"🍝","groups":[1,2,3,5],"price":45,"tags":["oily"]},{"name":"ข้าวกะเพราไก่ไข่ดาว","icon":"🍛","groups":[1,2,3,5],"price":45,"tags":["fried","oily"]},{"name":"ไส้กรอกทอด","icon":"🌭","groups":[1,5],"price":15,"tags":["fried","oily"]},{"name":"มันฝรั่งทอดกรอบ","icon":"🍟","groups":[2,5],"price":20,"tags":["fried","oily"]},{"name":"หมูปิ้ง","icon":"🍢","groups":[1,5],"price":10,"tags":[]},{"name":"ข้าวเหนียว","icon":"🍙","groups":[2],"price":10,"tags":[]},{"name":"ไอศกรีม","icon":"🍦","groups":[2,5],"pri