('health_meal_chef', 'เรียนว่ายน้ำหลังเลิกเรียน งบ 135 บาท', '{"icon":"🏊","story":["มะปรางเรียนว่ายน้ำตอน 4 โมงครึ่งเย็น หลังเลิกเรียน","ครูสอนว่ายน้ำบอกว่า ของว่างก่อนว่ายน้ำควรเบา ไม่มันมาก และต้องดื่มน้ำเปล่า แม่ให้งบทั้งวัน 135 บาท"],"context":[{"type":"table","title":"ตารางวันพฤหัสบดี","head":["เวลา","กิจกรรม"],"rows":[["07:00","มื้อเช้า"],["12:00","มื้อกลางวันที่โรงเรียน"],["15:30","ของว่างก่อนว่ายน้ำ"],["16:30–17:30","เรียนว่ายน้ำ"],["18:30","มื้อเย็น"]]},{"type":"note","text":"ทั้งวันต้องครบ 5 หมู่ ไม่ซ้ำเมนู ของทอดไม่เกิน 1 อย่าง งดเครื่องดื่มหวาน ของว่างก่อนว่ายน้ำต้องไม่มีอาหารมันมาก และต้องมีน้ำเปล่า"}],"steps":[{"kind":"multi","prompt":"ของว่างใดบ้างที่ไม่เหมาะกินก่อนว่ายน้ำ เลือกให้ครบ","skill":"analysis","points":10,"hints":["ดูว่าอาหารไหนมันมาก ย่อยช้า"],"solution":["อาหารมันมากย่อยช้า ถ้าว่ายน้ำหลังกินไม่นานอาจจุกหรืออึดอัด"],"options":[{"text":"มันฝรั่งทอดกรอบ","ok":true},{"text":"โดนัท","ok":true},{"text":"ข้าวมันไก่","ok":true},{"text":"กล้วยน้ำว้า","ok":false,"why":"กล้วยย่อยง่ายและให้พลังงาน เหมาะก่อนว่ายน้ำ"},{"text":"น้ำเปล่า","ok":false,"why":"ควรดื่มน้ำเปล่าก่อนออกกำลังกาย"}]},{"kind":"meal","prompt":"วางแผนอาหารทั้งวันให้มะปราง ใช้งบไม่เกิน 135 บาท และผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["ของว่างก่อนว่ายน้ำต้องย่อยง่ายและมีน้ำเปล่า อาหารไหนไม่มีป้ายมันมาก","ข้าวมันไก่มันมาก แต่กินมื้อกลางวันได้ เพราะห่างจากเวลาว่ายน้ำหลายชั่วโมง"],"solution":["ตัวอย่างที่ผ่านทุกเงื่อนไข: มื้อเช้า: ข้าวเหนียว + หมูปิ้ง + นมจืด · มื้อกลางวัน: ก๋วยเตี๋ยวน้ำใสหมูใส่ผัก · ของว่างก่อนว่ายน้ำ: กล้วยน้ำว้า + น้ำเปล่า · มื้อเย็น: ข้าวสวย + แกงจืดผักกาดขาวเต้าหู้ + ผัดผักบุ้ง","✓ ใช้เงินรวมไม่เกิน 135 บาท","✓ ทั้งวันมีอาหาร โปรตีน คาร์โบไฮเดรต ผัก ผลไม้ ไขมัน","✓ ไม่เลือกเมนูเดิมซ้ำ","✓ ของว่างก่อนว่ายน้ำไม่มีอาหารมันมาก","✓ ของว่างก่อนว่ายน้ำมีน้ำเปล่า","✓ \"ของทอด\" ไม่เกิน 1 อย่าง","✓ ไม่มี\"เครื่องดื่มรสหวาน\"","ตัวอย่างนี้ใช้เงิน 134 บาท","กล้วยกับน้ำเปล่าย่อยง่าย ให้พลังงานและไม่ทำให้ร่างกายขาดน้ำก่อนว่ายน้ำ"],"foods":[{"name":"ข้าวเหนียว",