ints":["คิดทั้งเรื่องแรงที่ต้องใช้ และความรู้สึกในท้องขณะว่ายน้ำ"],"solution":["ของว่างเบา ๆ ก่อนออกกำลังกายช่วยให้มีแรง โดยไม่ทำให้จุกเสียด"],"options":[{"text":"ร่างกายได้พลังงานไว้ใช้ว่ายน้ำ และอาหารเบาย่อยทันจึงไม่อึดอัดท้อง","ok":true},{"text":"ควรว่ายน้ำทั้งที่ท้องว่างจะได้ตัวเบา","ok":false,"why":"ท้องว่างนานทำให้ไม่มีแรงและอาจหน้ามืด ควรกินของว่างเบา ๆ"},{"text":"กินอะไรก็ได้มาก ๆ จะได้มีแรงเยอะ","ok":false,"why":"กินมากหรือมันมากก่อนว่ายน้ำทำให้อึดอัดและจุกได้"},{"text":"เพราะว่ายน้ำแล้วไม่ต้องดื่มน้ำ","ok":false,"why":"แม้อยู่ในน้ำ ร่างกายก็เสียเหงื่อ ยังต้องดื่มน้ำเปล่า"}],"answer":0}]}', 'hard', 30),
('health_routine', 'หลังเลิกเรียนของภูผา', '{"icon":"⚽","story":["ภูผากลับถึงบ้านตอน 16:00 และมีเวลาถึงประมาณ 21:00 ก่อนเข้านอน","เขาอยากเตะฟุตบอล ดูการ์ตูน และต้องทำการบ้านให้เสร็จด้วย"],"tip":"ทำสิ่งที่ต้องทำก่อน แล้วค่อยทำสิ่งที่อยากทำ","steps":[{"kind":"schedule","prompt":"จัดตารางตั้งแต่ 16:00 ให้ภูผา ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["ดูจอได้รวมไม่เกิน 1 ชั่วโมง การ์ดเล่นเกมมือถือใช้ 2 ชั่วโมง จึงใส่ไม่ได้","วางฟุตบอลไว้ก่อนกินข้าวเย็น และให้แปรงฟันเป็นการ์ดใบสุดท้าย"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 16:00 เตะฟุตบอลกับเพื่อน → 17:00 อาบน้ำ → 17:30 กินข้าวเย็น → 18:00 ทำการบ้าน → 19:00 ดูการ์ตูน → 20:00 แปรงฟันเตรียมเข้านอน","✓ ต้องมี: ทำการบ้าน","✓ ต้องมี: กินข้าวเย็น","✓ ต้องมี: อาบน้ำ","✓ เวลารวมไม่เกิน 5 ชม.","✓ ออกกำลังกายอย่างน้อย 1 ชม.","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม.","✓ ทำการบ้านเสร็จก่อนดูการ์ตูน","✓ ไม่เตะฟุตบอลทันทีหลังกินข้าวอิ่ม","✓ จบด้วยการแปรงฟันเตรียมเข้านอน","เด็กวัยเรียนควรเคลื่อนไหวร่างกายอย่างน้อยวันละ 60 นาที","ออกแรงมากทันทีหลังกินอิ่มอาจทำให้จุกเสียด ควรพักก่อน"],"start":"16:00","cards":[{"label":"ทำการบ้าน","icon":"📝","minutes":60,"cat":"study"},{"label":"เตะฟุตบอลกับเพื่อน","icon":"⚽","minutes":60,"cat":"exercise"},{"label":"อาบน้ำ","icon":"🚿","minutes":30,"cat":"hygiene"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"ดูการ์ตูน","icon":"📺","minutes":60,"cat":"screen"},{"label":"เล่นเกมมือถือ","icon":"📱","minutes":120,"cat":"screen"},{"label":"แปรงฟันเตรียมเข้านอน","icon":"🪥","minutes":15,"cat":"hygiene"}],"rules":[{"type":"include","card":0,"label":"ต้องมี: ทำการบ้าน"},{"type":"include","card":3,"label":"ต้องมี: กินข้าวเย็น"},{"type":"include","card":2,"label":"ต้องมี: อาบน้ำ"},{"type":"total","max":300},{"type":"catMin","cat":"exercise","min":60},{"type":"catMax","cat":"screen","max":60},{"type":"before","a":0,"b":4,"label":"ทำการบ้านเสร็จก่อนดูการ์ตูน"},{"type":"notAfter","a":3,"b":1,"label":"ไม่เตะฟุตบอลทันทีหลังกินข้าวอิ่ม"},{"type":"last","card":6,"label":"จบด้วยการแปรงฟันเตรียมเข้านอน"}],"example":[1,2,3,0,4,6],"notes":["เด็กวัยเรียนควรเคลื่อนไหวร่างกายอย่างน้อยวันละ 60 นาที","ออกแรงมากทันทีหลังกินอิ่มอาจทำให้จุกเสียด ควรพักก่อน"]},{"kind":"choice","prompt":"ทำไมภูผาจึงควรทำการบ้านก่อนดูการ์ตูน","skill":"reason","points":10,"hints":["ถ้าดูการ์ตูนก่อน แล้วเพลินจนดึก การบ้านจะเป็นอย่างไร"],"solution":["ทำงานที่จำเป็นให้เสร็จก่อน จะได้พักผ่อนสบายใจและเข้านอนตรงเวลา"],"options":[{"text":"การบ้านเสร็จแน่นอน แล้วดูการ์ตูนได้สบายใจ ไม่ต้องรีบทำตอนดึก","ok":true},{"text":"เพราะการ์ตูนสนุกน้อยกว่าการบ้าน","ok":false,"why":"เหตุผลนี้ไม่เกี่ยวกับการจัดเวลา และไม่จริงสำหรับทุกคน"},{"text":"เพราะดูการ์ตูนตอนกลางวันไม่ได้","ok":false,"why":"ดูได้ แต่ควรจัดหลังจากทำงานที่จำเป็นเสร็จ"},{"text":"เพื่อให้ไม่ต้องแปรงฟันก่อนนอน","ok":false,"why":"การแปรงฟันก่อนนอนต้องทำทุกวัน ไม่เกี่ยวกับการบ้าน"}],"answer":0}],"context":[]}', 'easy', 1),
('health_routine', 'เช้าวันเรียนของมะปราง', '{"icon":"🌅","story":["มะปรางตื่นนอนตอน 06:00 และต้องออกเดินไปโรงเรียนกับแม่ไม่เกิน 07:10","เช้านี้มะปรางอยากดูคลิปในมือถือด้วย"],"tip":"ช่วงเช้ามีเวลาจำกัด ให้เลือกสิ่งที่จำเป็นก่อน","steps":[{"kind":"schedule","prompt":"จัดตารางตอนเช้าของมะปรางตั้งแต่ 06:00 ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["บวกเวลาของการ์ดที่จำเป็นดูก่อน ว่าเหลือเวลาพอดูคลิปหรือไม่","แปรงฟันหลังกินข้าวเช้า แล้วจึงออกเดินทาง"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 06:00 เก็บที่นอน → 06:10 อาบน้ำแต่งตัว → 06:30 กินข้าวเช้า → 06:50 แปรงฟัน → 06:55 เดินไปโรงเรียนกับแม่","✓ ต้องมี: อาบน้ำแต่งตัว","✓ ต้องมี: แปรงฟัน","✓ เวลารวมไม่เกิน 1 ชม. 30 นาที","✓ ตื่นแล้วเก็บที่นอนเป็นอย่างแรก","✓ ต้องมีมื้อเช้า","✓ แปรงฟันหลังกินข้าวเช้า","✓ ออกเดินไปโรงเรียนเป็นกิจกรรมสุดท้าย","✓ ออกเดินทางไม่เกิน 07:10","อาหารเช้าให้พลังงานสำหรับการเรียนช่วงเช้า","ถ้าเพิ่มดูคลิป 30 นาที จะออกจากบ้านช้ากว่าเวลาที่กำหนด"],"start":"06:00","cards":[{"label":"เก็บที่นอน","icon":"🛏️","minutes":10,"cat":"chore"},{"label":"อาบน้ำแต่งตัว","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"กินข้าวเช้า","icon":"🍳","minutes":20,"cat":"meal"},{"label":"แปรงฟัน","icon":"🪥","minutes":5,"cat":"hygiene"},{"label":"ดูคลิปในมือถือ","icon":"📱","minutes":30,"cat":"screen"},{"label":"เดินไปโรงเรียนกับแม่","icon":"🚶","minutes":20,"cat":"travel"}],"rules":[{"type":"include","card":1,"label":"ต้องมี: อาบน้ำแต่งตัว"},{"type":"include","card":3,"label":"ต้องมี: แปรงฟัน"},{"type":"total","max":90},{"type":"first","card":0,"label":"ตื่นแล้วเก็บที่นอนเป็นอย่างแรก"},{"type":"include","card":2,"label":"ต้องมีมื้อเช้า"},{"type":"before","a":2,"b":3,"label":"แปรงฟันหลังกินข้าวเช้า"},{"type":"last","card":5,"label":"ออกเดินไปโรงเรียนเป็นกิจกรรมสุดท้าย"},{"type":"startBy","card":5,"time":"07:10","label":"ออกเดินทางไม่เกิน 07:10"}],"example":[0,1,2,3,5],"notes":["อาหารเช้าให้พลังงานสำหรับการเรียนช่วงเช้า","ถ้าเพิ่มดูคลิป 30 นาที จะออกจากบ้านช้ากว่าเวลาที่กำหนด"]},{"kind":"multi","prompt":"ข้อใดช่วยให้ตอนเช้าของมะปรางไม่รีบร้อน (เลือกได้หลายข้อ)","skill":"analysis","points":10,"hints":["คิดถึงสิ่งที่เตรียมไว้ได้ตั้งแต่คืนก่อน"],"solution":["เข้านอนเร็วและเตรียมของตั้งแต่คืนก่อน ทำให้ตื่นตรงเวลาและมีเวลากินข้าวเช้า"],"options":[{"text":"เข้านอนเร็วในคืนก่อน","ok":true},{"text":"จัดกระเป๋านักเรียนตั้งแต่คืนก่อน","ok":true},{"text":"ดูคลิปบนเตียงก่อนลุก","ok":false,"why":"ทำให้เสียเวลาตอนเช้า"},{"text":"ข้ามมื้อเช้าเพื่อให้ทันเวลา","ok":false,"why":"ร่างกายต้องการอาหารเช้าเพื่อเป็นพลังงานในการเรียน"}]}],"context":[]}', 'easy', 2),
('health_routine', 'คืนวันศุกร์ของต้นกล้า', '{"icon":"🌙","story":["ต้นกล้ามีเวลาตั้งแต่ 18:00 และพรุ่งนี้ต้องตื่นแต่เช้าไปช่วยตาที่สวน","เขาอยากเล่นเกมออนไลน์ 90 นาที แต่บ้านตกลงกันว่าวันนี้ดูจอไม่เกิน 1 ชั่วโมง"],"tip":"เด็กวัย ป.5 ควรนอนหลับอย่างน้อย 9 ชั่วโมงต่อคืน","steps":[{"kind":"schedule","prompt":"จัดตารางตั้งแต่ 18:00 จนถึงเวลานอนของต้นกล้า ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["การ์ดเล่นเกมออนไลน์ใช้เวลาเกิน 1 ชั่วโมง จึงใส่ไม่ได้","ปั่นจักรยานก่อนกินข้าว และให้การ์ดนอนหลับอยู่ท้ายสุด"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 18:00 ปั่นจักรยานรอบหมู่บ้าน → 18:45 อาบน้ำ → 19:05 กินข้าวเย็น → 19:35 ทำการบ้าน → 20:20 อ่านนิทานกับน้อง → 20:40 นอนหลับ","✓ ต้องมี: ทำการบ้าน","✓ ต้องมี: กินข้าวเย็น","✓ ต้องมี: อาบน้ำ","✓ ออกกำลังกายอย่างน้อย 30 นาที","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม.","✓ ไม่ปั่นจักรยานทันทีหลังกินข้าว","✓ นอนหลับอย่างน้อย 9 ชม.","✓ จบวันด้วยการนอนหลับ","✓ เข้านอนไม่เกิน 21:00","การนอนหลับเพียงพอช่วยให้ร่างกายเจริญเติบโตและสดชื่นในวันรุ่งขึ้น"],"start":"18:00","cards":[{"label":"ปั่นจักรยานรอบหมู่บ้าน","icon":"🚲","minutes":45,"cat":"exercise"},{"label":"อาบน้ำ","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"ทำการบ้าน","icon":"📝","minutes":45,"cat":"study"},{"label":"อ่านนิทานกับน้อง","icon":"📖","minutes":20,"cat":"free"},{"label":"เล่นเกมออนไลน์","icon":"🎮","minutes":90,"cat":"screen"},{"label":"นอนหลับ","icon":"😴","minutes":600,"cat":"sleep"}],"rules":[{"type":"include","card":3,"label":"ต้องมี: ทำการบ้าน"},{"type":"include","card":2,"label":"ต้องมี: กินข้าวเย็น"},{"type":"include","card":1,"label":"ต้องมี: อาบน้ำ"},{"type":"catMin","cat":"exercise","min":30},{"type":"catMax","cat":"screen","max":60},{"type":"notAfter","a":2,"b":0,"label":"ไม่ปั่นจักรยานทันทีหลังกินข้าว"},{"type":"catMin","cat":"sleep","min":540},{"type":"last","card":6,"label":"จบวันด้วยการนอนหลับ"},{"type":"startBy","card":6,"time":"21:00","label":"เข้านอนไม่เกิน 21:00"}],"example":[0,1,2,3,4,6],"notes":["การนอนหลับเพียงพอช่วยให้ร่างกายเจริญเติบโตและสดชื่นในวันรุ่งขึ้น"]},{"kind":"choice","prompt":"ทำไมต้นกล้าไม่ควรเล่นเกมออนไลน์ 90 นาทีในคืนนี้","skill":"reason","points":10,"hints":["ดูเงื่อนไขเรื่องเวลาดูจอและเวลาเข้านอน"],"solution":["เล่นเกม 90 นาทีเกินข้อตกลงดูจอ 1 ชั่วโมง และทำให้เข้านอนช้า ได้นอนไม่พอ"],"options":[{"text":"เกินเวลาดูจอที่ตกลงไว้ และทำให้เข้านอนช้าจนนอนไม่พอ","ok":true},{"text":"เพราะเกมออนไลน์ไม่สนุก","ok":false,"why":"ความสนุกไม่ใช่เหตุผลเรื่องสุขภาพ"},{"text":"เพราะเด็กห้ามดูจอเลย","ok":false,"why":"ดูจอได้ แต่ควรจำกัดเวลา"},{"text":"เพราะต้องออกไปปั่นจักรยานตอนดึก","ok":false,"why":"ไม่ควรออกไปปั่นจักรยานตอนดึก และไม่เกี่ยวกับเหตุผลนี้"}],"answer":0}],"context":[]}', 'easy', 3),
('health_routine', 'เช้าวันเสาร์ของใบบัว', '{"icon":"🏊","story":["วันเสาร์ ใบบัวมีเวลาตั้งแต่ 08:00 ถึง 12:00 ก่อนกินข้าวกลางวันพร้อมครอบครัว","แม่ขอให้ช่วยงานบ้าน ส่วนพ่อชวนไปว่ายน้ำ"],"tip":"วันหยุดก็ควรมีทั้งช่วยงานบ้าน ออกกำลังกาย และทบทวนบทเรียน","steps":[{"kind":"schedule","prompt":"จัดตารางตั้งแต่ 08:00 ให้ใบบัว ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["เวลารวมต้องไม่เกิน 4 ชั่วโมง ลองเลือกการ์ดดูจอแค่ใบเดียว","การ์ดกินข้าวกลางวันต้องอยู่ท้ายสุด"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 08:00 กวาดบ้าน → 08:30 รดน้ำต้นไม้ → 08:45 ว่ายน้ำกับพ่อ → 09:45 ทบทวนบทเรียน → 10:30 ดูการ์ตูน → 11:30 กินข้าวกลางวัน","✓ ต้องมี: ทบทวนบทเรียน","✓ เวลารวมไม่เกิน 4 ชม.","✓ ช่วยงานบ้านอย่างน้อย 30 นาที","✓ ออกกำลังกายอย่างน้อย 1 ชม.","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม.","✓ ปิดท้ายด้วยข้าวกลางวัน","ช่วยงานบ้านก็เป็นการเคลื่อนไหวร่างกายและฝึกความรับผิดชอบ"],"start":"08:00","cards":[{"label":"กวาดบ้าน","icon":"🧹","minutes":30,"cat":"chore"},{"label":"รดน้ำต้นไม้","icon":"🪴","minutes":15,"cat":"chore"},{"label":"ว่ายน้ำกับพ่อ","icon":"🏊","minutes":60,"cat":"exercise"},{"label":"ทบทวนบทเรียน","icon":"📚","minutes":45,"cat":"study"},{"label":"ดูการ์ตูน","icon":"📺","minutes":60,"cat":"screen"},{"label":"เล่นเกม","icon":"🎮","minutes":90,"cat":"screen"},{"label":"กินข้าวกลางวัน","icon":"🍱","minutes":30,"cat":"meal"}],"rules":[{"type":"include","card":3,"label":"ต้องมี: ทบทวนบทเรียน"},{"type":"total","max":240},{"type":"catMin","cat":"chore","min":30},{"type":"catMin","cat":"exercise","min":60},{"type":"catMax","cat":"screen","max":60},{"type":"last","card":6,"label":"ปิดท้ายด้วยข้าวกลางวัน"}],"example":[0,1,2,3,4,6],"notes":["ช่วยงานบ้านก็เป็นการเคลื่อนไหวร่างกายและฝึกความรับผิดชอบ"]},{"kind":"sort","prompt":"จัดกิจกรรมของใบบัวเข้ากลุ่มให้ถูกต้อง","skill":"analysis","points":10,"hints":["ถามตัวเองว่า ทำกิจกรรมนี้แล้วร่างกายได้ขยับมากหรือนั่งอยู่กับที่"],"solution":["กวาดบ้าน รดน้ำต้นไม้ และว่ายน้ำได้ขยับร่างกาย ส่วนดูการ์ตูน ทบทวนบทเรียน และเล่นเกมนั่งอยู่กับที่เป็นส่วนใหญ่"],"bins":["ได้เคลื่อนไหวร่างกาย","นั่งอยู่กับที่เป็นส่วนใหญ่"],"items":[{"text":"กวาดบ้าน","bin":0},{"text":"ว่ายน้ำ","bin":0},{"text":"รดน้ำต้นไม้","bin":0},{"text":"ดูการ์ตูน","bin":1},{"text":"ทบทวนบทเรียน","bin":1},{"text":"เล่นเกม","bin":1}]}],"context":[]}', 'easy', 4),
('health_routine', 'ก่อนนอนของใบเฟิร์น', '{"icon":"🛌","story":["ใบเฟิร์นมีเวลาตั้งแต่ 19:00 ก่อนเข้านอน","ช่วงนี้เธอชอบเล่นมือถือบนเตียงจนเผลอนอนดึก แล้วตื่นมาง่วงทุกเช้า"],"tip":"ควรเลิกดูจอก่อนนอนสักพัก เพื่อให้หลับง่ายขึ้น","steps":[{"kind":"schedule","prompt":"จัดตารางก่อนนอนตั้งแต่ 19:00 ให้ใบเฟิร์น ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["ห้ามใส่การ์ดเล่นมือถือบนเตียง","ดูทีวีเสร็จแล้วให้ทำกิจกรรมอื่นก่อน อย่าเข้านอนต่อทันที"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 19:00 ทำการบ้าน → 19:45 ดูทีวีกับครอบครัว → 20:15 จัดกระเป๋านักเรียน → 20:25 อาบน้ำ → 20:45 แปรงฟัน → 20:50 นอนหลับ","✓ ต้องมี: ทำการบ้าน","✓ ต้องมี: จัดกระเป๋านักเรียน","✓ ต้องมี: อาบน้ำ","✓ ไม่เล่นมือถือบนเตียง","✓ แปรงฟันก่อนนอน","✓ ไม่ดูทีวีแล้วเข้านอนทันที","✓ จบวันด้วยการนอนหลับ","✓ เข้านอนไม่เกิน 21:00","แสงและความตื่นเต้นจากหน้าจอทำให้หลับยากขึ้น"],"start":"19:00","cards":[{"label":"ทำการบ้าน","icon":"📝","minutes":45,"cat":"study"},{"label":"ดูทีวีกับครอบครัว","icon":"📺","minutes":30,"cat":"screen"},{"label":"จัดกระเป๋านักเรียน","icon":"🎒","minutes":10,"cat":"chore"},{"label":"อาบน้ำ","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"แปรงฟัน","icon":"🪥","minutes":5,"cat":"hygiene"},{"label":"เล่นมือถือบนเตียง","icon":"📱","minutes":60,"cat":"screen"},{"label":"นอนหลับ","icon":"😴","minutes":600,"cat":"sleep"}],"rules":[{"type":"include","card":0,"label":"ต้องมี: ทำการบ้าน"},{"type":"include","card":2,"label":"ต้องมี: จัดกระเป๋านักเรียน"},{"type":"include","card":3,"label":"ต้องมี: อาบน้ำ"},{"type":"exclude","card":5,"label":"ไม่เล่นมือถือบนเตียง"},{"type":"include","card":4,"label":"แปรงฟันก่อนนอน"},{"type":"notAfter","a":1,"b":6,"label":"ไม่ดูทีวีแล้วเข้านอนทันที"},{"type":"last","card":6,"label":"จบวันด้วยการนอนหลับ"},{"type":"startBy","card":6,"time":"21:00","label":"เข้านอนไม่เกิน 21:00"}],"example":[0,1,2,3,4,6],"notes":["แสงและความตื่นเต้นจากหน้าจอทำให้หลับยากขึ้น"]},{"kind":"choice","prompt":"การเล่นมือถือบนเตียงก่อนนอนส่งผลอย่างไร","skill":"reason","points":10,"hints":["ใบเฟิร์นรู้สึกอย่างไรตอนเช้า"],"solution":["เล่นมือถือก่อนนอนทำให้หลับยากและนอนดึก ตื่นมาจึงง่วงและไม่มีสมาธิ"],"options":[{"text":"หลับยากและนอนดึก ทำให้ตื่นมาง่วงและไม่มีสมาธิเรียน","ok":true},{"text":"ช่วยให้หลับลึกขึ้น","ok":false,"why":"หน้าจอทำให้สมองตื่นตัว หลับยากขึ้น"},{"text":"ไม่มีผลอะไรถ้าเปิดเสียงเบา","ok":false,"why":"แม้เสียงเบา แสงจากจอก็ยังรบกวนการนอน"},{"text":"ทำให้ฟันแข็งแรง","ok":false,"why":"ไม่เกี่ยวกัน การแปรงฟันต่างหากที่ดูแลฟัน"}],"answer":0}],"context":[]}', 'easy', 5),
('health_routine', 'พักกลางวันที่โรงเรียน', '{"icon":"🍱","story":["พักกลางวันของน้องต้นข้าวเริ่ม 12:00 และต้องกลับเข้าห้องเรียนตอน 13:00","เพื่อน ๆ ชวนไปกระโดดเชือกทันทีที่กินข้าวเสร็จ"],"tip":"กินอิ่มแล้วควรพักก่อนออกแรงมาก","steps":[{"kind":"schedule","prompt":"จัดเวลาพักกลางวันตั้งแต่ 12:00 ให้ต้นข้าว ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["ล้างมือเป็นอย่างแรก แล้วจึงกินข้าว","คั่นระหว่างกินข้าวกับกระโดดเชือกด้วยกิจกรรมเบา ๆ"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 12:00 ล้างมือด้วยสบู่ → 12:05 กินข้าวกลางวัน → 12:30 แปรงฟัน → 12:35 อ่านหนังสือในห้องสมุด → 12:45 กระโดดเชือกกับเพื่อน","✓ ต้องมี: กินข้าวกลางวัน","✓ ต้องมี: แปรงฟัน","✓ เวลารวมไม่เกิน 1 ชม.","✓ ล้างมือก่อนกินข้าวเป็นอย่างแรก","✓ แปรงฟันหลังกินข้าว","✓ ไม่กระโดดเชือกทันทีหลังกินข้าว","✓ ออกกำลังกายอย่างน้อย 15 นาที","ล้างมือก่อนกินอาหารช่วยลดเชื้อโรคที่จะเข้าปาก"],"start":"12:00","cards":[{"label":"ล้างมือด้วยสบู่","icon":"🧼","minutes":5,"cat":"hygiene"},{"label":"กินข้าวกลางวัน","icon":"🍱","minutes":25,"cat":"meal"},{"label":"แปรงฟัน","icon":"🪥","minutes":5,"cat":"hygiene"},{"label":"อ่านหนังสือในห้องสมุด","icon":"📖","minutes":10,"cat":"free"},{"label":"กระโดดเชือกกับเพื่อน","icon":"🪢","minutes":15,"cat":"exercise"},{"label":"เล่นเกมมือถือใต้อาคาร","icon":"📱","minutes":30,"cat":"screen"}],"rules":[{"type":"include","card":1,"label":"ต้องมี: กินข้าวกลางวัน"},{"type":"include","card":2,"label":"ต้องมี: แปรงฟัน"},{"type":"total","max":60},{"type":"first","card":0,"label":"ล้างมือก่อนกินข้าวเป็นอย่างแรก"},{"type":"before","a":1,"b":2,"label":"แปรงฟันหลังกินข้าว"},{"type":"notAfter","a":1,"b":4,"label":"ไม่กระโดดเชือกทันทีหลังกินข้าว"},{"type":"catMin","cat":"exercise","min":15}],"example":[0,1,2,3,4],"notes":["ล้างมือก่อนกินอาหารช่วยลดเชื้อโรคที่จะเข้าปาก"]},{"kind":"choice","prompt":"ทำไมไม่ควรกระโดดเชือกหรือวิ่งทันทีหลังกินข้าวอิ่ม","skill":"reason","points":10,"hints":["ตอนนั้นร่างกายกำลังทำอะไรกับอาหาร"],"solution":["หลังกินอิ่มร่างกายกำลังย่อยอาหาร ถ้าออกแรงมากทันทีอาจจุก