('health_routine', 'การบ้านมาก่อนเกม', '{"icon":"🎮","story":["ภูผากลับถึงบ้าน 15:30 มีการบ้านคณิตและภาษาไทย","พ่อตกลงว่าวันนี้เล่นเกมได้ 30 นาที ถ้าทำการบ้านเสร็จก่อน"],"tip":"ตกลงเวลาเล่นเกมกับผู้ปกครอง แล้วทำตามข้อตกลง","steps":[{"kind":"schedule","prompt":"จัดตารางตั้งแต่ 15:30 ให้ภูผา ให้ผ่านทุกเงื่อนไข","skill":"rules","points":10,"hints":["ใส่การบ้านทั้ง 2 วิชาก่อนการ์ดเล่นเกม","การ์ดดูคลิปต่อทำให้ดูจอเกิน 30 นาที"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 15:30 กินนมกับผลไม้เป็นของว่าง → 15:45 ทำการบ้านคณิต → 16:25 ทำการบ้านภาษาไทย → 16:55 เล่นแบดมินตัน → 17:40 เล่นเกม → 18:10 ช่วยแม่ล้างจาน","✓ เวลารวมไม่เกิน 3 ชม.","✓ ทำการบ้านให้ครบทั้ง 2 วิชา","✓ ทำการบ้านคณิตเสร็จก่อนเล่นเกม","✓ ทำการบ้านภาษาไทยเสร็จก่อนเล่นเกม","✓ ออกกำลังกายอย่างน้อย 45 นาที","✓ ดูจอ/เล่นเกมไม่เกิน 30 นาที","ทำตามข้อตกลงเรื่องเวลาเล่นเกมช่วยฝึกการควบคุมตนเอง"],"start":"15:30","cards":[{"label":"กินนมกับผลไม้เป็นของว่าง","icon":"🍌","minutes":15,"cat":"meal"},{"label":"ทำการบ้านคณิต","icon":"➗","minutes":40,"cat":"study"},{"label":"ทำการบ้านภาษาไทย","icon":"📝","minutes":30,"cat":"study"},{"label":"เล่นแบดมินตัน","icon":"🏸","minutes":45,"cat":"exercise"},{"label":"เล่นเกม","icon":"🎮","minutes":30,"cat":"screen"},{"label":"ช่วยแม่ล้างจาน","icon":"🍽️","minutes":15,"cat":"chore"},{"label":"ดูคลิปต่อ","icon":"📱","minutes":60,"cat":"screen"}],"rules":[{"type":"total","max":180},{"type":"catMin","cat":"study","min":70,"label":"ทำการบ้านให้ครบทั้ง 2 วิชา"},{"type":"before","a":1,"b":4,"label":"ทำการบ้านคณิตเสร็จก่อนเล่นเกม"},{"type":"before","a":2,"b":4,"label":"ทำการบ้านภาษาไทยเสร็จก่อนเล่นเกม"},{"type":"catMin","cat":"exercise","min":45},{"type":"catMax","cat":"screen","max":30}],"example":[0,1,2,3,4,5],"notes":["ทำตามข้อตกลงเรื่องเวลาเล่นเกมช่วยฝึกการควบคุมตนเอง"]},{"kind":"multi","prompt":"การทำการบ้านก่อนเล่นเกมมีข้อดีอย่างไร (เลือกได้หลายข้อ)","skill":"reason","points":10,"hints":["คิดถึงเรื่องเวลา ความสบายใจ และการเข้านอน"],"solution":["ทำการบ้านก่อนช่วยให้งานเสร็จทันเวลา เล่นได้อย่างสบายใจ และไม่ต้องนอนดึก"],"options":[{"text":"การบ้านเสร็จแน่นอนและไม่ต้องรีบทำตอนดึก","ok":true},{"text":"เล่นเกมได้อย่างสบายใจ","ok":true},{"text":"ได้เล่นเกมนานขึ้นโดยไม่มีใครว่า","ok":false,"why":"ยังต้องทำตามเวลาที่ตกลงไว้ 30 นาที"},{"text":"ไม่ต้องออกกำลังกายวันนี้","ok":false,"why":"ยังต้องเคลื่อนไหวร่างกายทุกวัน"}]}],"context":[]}', 'easy', 7),
('health_routine', 'วันฝนตกก็ขยับได้', '{"icon":"🌧️","story":["วันนี้ฝนตกหนักและมีฟ้าร้อง มะปรางกลับถึงบ้าน 16:00","น้องชวนออกไปวิ่งเล่นกลางสายฝน"],"tip":"วันฝนตกยังออกกำลังกายในบ้านได้","steps":[{"kind":"schedule","prompt":"จัดตารางตั้งแต่ 16:00 ให้มะปราง ให้ผ่านทุกเงื่อนไข","skill":"decision","points":10,"hints":["หากิจกรรมออกกำลังกายที่ทำในบ้านได้","ทำการบ้านก่อนดูการ์ตูน และตรวจเวลารวม"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 16:00 เต้นแอโรบิกตามคลิปในบ้าน → 16:30 อาบน้ำ → 16:50 ทำการบ้าน → 17:35 ช่วยพับผ้า → 17:50 กินข้าวเย็น","✓ ต้องมี: ทำการบ้าน","✓ ต้องมี: กินข้าวเย็น","✓ ต้องมี: อาบน้ำ","✓ เวลารวมไม่เกิน 3 ชม.","✓ ไม่ออกไปเล่นกลางสายฝนตอนฟ้าร้อง","✓ ออกกำลังกายอย่างน้อย 30 นาที","✓ ทำการบ้านก่อนดูการ์ตูน","✓ ไม่เต้นแอโรบิกทันทีหลังกินข้าว","ฟ้าร้องฟ้าผ่าเป็นอันตราย ควรอยู่ในอาคาร","ออกกำลังกายในบ้านก็ช่วยให้ได้เคลื่อนไหวครบ"],"start":"16:00","cards":[{"label":"เต้นแอโรบิกตามคลิปในบ้าน","icon":"💃","minutes":30,"cat":"exercise"},{"label":"วิ่งเล่นกลางสายฝนตอนฟ้าร้อง","icon":"⛈️","minutes":30,"cat":"exercise"},{"label":"ทำการบ้าน","icon":"📝","minutes":45,"cat":"study"},{"label":"อาบน้ำ","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"ช่วยพับผ้า","icon":"👕","minutes":15,"cat":"chore"},{"label":"ดูการ์ตูน","icon":"📺","minutes":60,"cat":"screen"}],"rules":[{"type":"include","card":2,"label":"ต้องมี: ทำการบ้าน"},{"type":"include","card":4,"label":"ต้องมี: กินข้าวเย็น"},{"type":"include","card":3,"label":"ต้องมี: อาบน้ำ"},{"type":"total","max":180},{"type":"exclude","card":1,"label":"ไม่ออกไปเล่นกลางสายฝนตอนฟ้าร้อง"},{"type":"catMin","cat":"exercise","min":30},{"type":"before","a":2,"b":6,"label":"ทำการบ้านก่อนดูการ์ตูน"},{"type":"notAfter","a":4,"b":0,"label":"ไม่เต้นแอโรบิกทันทีหลังกินข้าว"}],"example":[0,3,2,5,4],"notes":["ฟ้าร้องฟ้าผ่าเป็นอันตราย ควรอยู่ในอาคาร","ออกกำลังกายในบ้านก็ช่วยให้ได้เคลื่อนไหวครบ"]},{"kind":"choice","prompt":"ทำไมไม่ควรออกไปวิ่งเล่นกลางสายฝนตอนฟ้าร้อง","skill":"reason","points":10,"hints":["คิดถึงฟ้าผ่าและพื้นที่เปียก"],"solution":["ฟ้าร้องเป็นสัญญาณว่าอาจมีฟ้าผ่า และพื้นเปียกลื่นทำให้หกล้มได้ง่าย"],"options":[{"text":"อาจถูกฟ้าผ่า และพื้นเปียกลื่นทำให้หกล้ม","ok":true},{"text":"เพราะน้ำฝนทำให้วิ่งช้า","ok":false,"why":"ปัญหาสำคัญคือความปลอดภัย ไม่ใช่ความเร็ว"},{"text":"เพราะฝนตกแล้วห้ามออกกำลังกายทุกชนิด","ok":false,"why":"ยังออกกำลังกายในบ้านได้"},{"text":"เพราะเสื้อจะเปื้อน","ok":false,"why":"เสื้อเปื้อนไม่ใช่เหตุผลหลัก อันตรายจากฟ้าผ่าสำคัญกว่า"}],"answer":0}],"context":[]}', 'easy', 8),
('health_routine', 'สามมื้อตรงเวลา', '{"icon":"🏫","story":["ใบบัวตื่น 06:30 นั่งรถไปโรงเรียน 30 นาที และต้องเริ่มเรียนไม่เกิน 08:00","บางวันเธอรีบจนซื้อขนมกรุบกรอบกินแทนข้าวเช้า"],"tip":"กินอาหารให้ครบ 3 มื้อ และตรงเวลา","steps":[{"kind":"schedule","prompt":"จัดตารางวันเรียนของใบบัวตั้งแต่ 06:30 ให้ผ่านทุกเงื่อนไข","skill":"planning","points":10,"hints":["กินข้าวเช้าก่อนออกเดินทาง","เรียงเรียนช่วงเช้า กินข้าวกลางวัน แล้วเรียนช่วงบ่าย"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 06:30 อาบน้ำแต่งตัว → 07:00 กินข้าวเช้า → 07:20 นั่งรถไปโรงเรียน → 07:50 เรียนช่วงเช้า → 11:50 กินข้าวกลางวัน → 12:20 เรียนช่วงบ่าย","✓ ทำครบทุกช่วงจนเลิกเรียน 15:20 พอดี","✓ มีมื้อเช้าที่เป็นอาหารจริง","✓ ไม่กินขนมแทนข้าวเช้า","✓ กินข้าวเช้าไม่เกิน 07:30","✓ เริ่มเรียนไม่เกิน 08:00","✓ กินข้าวกลางวันหลังเรียนช่วงเช้า","✓ เรียนช่วงบ่ายหลังกินข้าวกลางวัน","ขนมกรุบกรอบมีเกลือหรือไขมันมาก และไม่ได้ให้สารอาหารครบเหมือนข้าวเช้า"],"start":"06:30","cards":[{"label":"อาบน้ำแต่งตัว","icon":"🚿","minutes":30,"cat":"hygiene"},{"label":"กินข้าวเช้า","icon":"🍳","minutes":20,"cat":"meal"},{"label":"นั่งรถไปโรงเรียน","icon":"🚌","minutes":30,"cat":"travel"},{"label":"เรียนช่วงเช้า","icon":"🏫","minutes":240,"cat":"school"},{"label":"กินข้าวกลางวัน","icon":"🍱","minutes":30,"cat":"meal"},{"label":"เรียนช่วงบ่าย","icon":"📚","minutes":180,"cat":"school"},{"label":"ซื้อขนมกรุบกรอบกินแทนข้าวเช้า","icon":"🍟","minutes":10,"cat":"meal"}],"rules":[{"type":"total","min":530,"max":530,"label":"ทำครบทุกช่วงจนเลิกเรียน 15:20 พอดี"},{"type":"include","card":1,"label":"มีมื้อเช้าที่เป็นอาหารจริง"},{"type":"exclude","card":6,"label":"ไม่กินขนมแทนข้าวเช้า"},{"type":"startBy","card":1,"time":"07:30","label":"กินข้าวเช้าไม่เกิน 07:30"},{"type":"startBy","card":3,"time":"08:00","label":"เริ่มเรียนไม่เกิน 08:00"},{"type":"before","a":3,"b":4,"label":"กินข้าวกลางวันหลังเรียนช่วงเช้า"},{"type":"before","a":4,"b":5,"label":"เรียนช่วงบ่ายหลังกินข้าวกลางวัน"}],"example":[0,1,2,3,4,5],"notes":["ขนมกรุบกรอบมีเกลือหรือไขมันมาก และไม่ได้