('health_routine', 'คืนก่อนไปทัศนศึกษา', '{"icon":"🚍","story":["พรุ่งนี้ใบเฟิร์นไปทัศนศึกษา ต้องตื่น 05:30","เย็นนี้เธอมีเวลาตั้งแต่ 17:00 ตื่นเต้นจนอยากดูหนังรอบดึกให้หายตื่นเต้น"],"tip":"นับย้อนจากเวลาตื่น เพื่อหาเวลาเข้านอนที่ทำให้นอนได้ 9 ชั่วโมง","steps":[{"kind":"schedule","prompt":"จัดตารางตั้งแต่ 17:00 จนถึงเวลาตื่น 05:30 ของใบเฟิร์น","skill":"planning","points":15,"hints":["ตารางต้องจบตอน 05:30 พอดี คือรวม 12 ชั่วโมง 30 นาที","นอนหลับ 9 ชั่วโมงต้องเริ่ม 20:30 ไม่ใส่การ์ดเกมหรือหนังรอบดึก"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 17:00 เดินเล่นกับพ่อ → 17:30 กินข้าวเย็น → 18:00 ทำการบ้าน → 18:45 จัดกระเป๋าเตรียมของไปทัศนศึกษา → 19:00 ดูทีวีกับครอบครัว → 19:40 อาบน้ำ → 20:00 อ่านหนังสือการ์ตูน → 20:30 นอนหลับ","✓ ตารางจบตอน 05:30 พอดี (รวม 12 ชม. 30 นาที)","✓ นอนหลับอย่างน้อย 9 ชม.","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม.","✓ จัดกระเป๋าให้พร้อมตั้งแต่คืนนี้","✓ ไม่ดูทีวีแล้วเข้านอนทันที","✓ จบวันด้วยการนอนหลับ","ตื่น 05:30 และต้องนอน 9 ชั่วโมง จึงควรหลับไม่เกิน 20:30"],"start":"17:00","cards":[{"label":"เดินเล่นกับพ่อ","icon":"🚶","minutes":30,"cat":"exercise"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"ทำการบ้าน","icon":"📝","minutes":45,"cat":"study"},{"label":"จัดกระเป๋าเตรียมของไปทัศนศึกษา","icon":"🎒","minutes":15,"cat":"chore"},{"label":"ดูทีวีกับครอบครัว","icon":"📺","minutes":40,"cat":"screen"},{"label":"อาบน้ำ","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"อ่านหนังสือการ์ตูน","icon":"📖","minutes":30,"cat":"free"},{"label":"ดูหนังรอบดึก","icon":"🎬","minutes":120,"cat":"screen"},{"label":"นอนหลับ","icon":"😴","minutes":540,"cat":"sleep"}],"rules":[{"type":"total","min":750,"max":750,"label":"ตารางจบตอน 05:30 พอดี (รวม 12 ชม. 30 นาที)"},{"type":"catMin","cat":"sleep","min":540},{"type":"catMax","cat":"screen","max":60},{"type":"include","card":3,"label":"จัดกระเป๋าให้พร้อมตั้งแต่คืนนี้"},{"type":"notAfter","a":4,"b":8,"label":"ไม่ดูทีวีแล้วเข้านอนทันที"},{"type":"last","card":8,"label":"จบวันด้วยการนอนหลับ"}],"example":[0,1,2,3,4,5,6,8],"notes":["ตื่น 05:30 และต้องนอน 9 ชั่วโมง จึงควรหลับไม่เกิน 20:30"]},{"kind":"choice","prompt":"ใบเฟิร์นตื่นเต้นจนนอนไม่หลับ ควรทำอย่างไรเหมาะที่สุด","skill":"decision","points":10,"hints":["เลือกวิธีที่ทำให้ร่างกายสงบลง ไม่ใช่ตื่นตัวขึ้น"],"solution":["ทำกิจกรรมเงียบ ๆ เช่น อ่านหนังสือ หายใจช้า ๆ ช่วยให้ใจสงบและหลับง่ายขึ้น"],"options":[{"text":"อ่านหนังสือเบา ๆ ปิดไฟ แล้วหายใจเข้าออกช้า ๆ","ok":true},{"text":"ดูหนังรอบดึกจนง่วงเอง","ok":false,"why":"หน้าจอทำให้ตื่นตัวและนอนดึก"},{"text":"ดื่มน้ำอัดลมแก้ตื่นเต้น","ok":false,"why":"น้ำอัดลมมีน้ำตาล บางชนิดมีคาเฟอีนทำให้หลับยาก"},{"text":"ลุกไปวิ่งรอบบ้านตอนดึก","ok":false,"why":"ออกแรงมากก่อนนอนทำให้ร่างกายตื่นตัว"}],"answer":0}],"context":[]}', 'medium', 14),
('health_routine', 'นักว่ายน้ำตัวน้อย', '{"icon":"🏊","story":["ภูผาซ้อมว่ายน้ำหลังเลิกเรียน เริ่มจัดเวลาได้ตั้งแต่ 16:00","เพื่อนชวนไปกินบุฟเฟต์ให้อิ่มก่อนลงสระ"],"tip":"อบอุ่นร่างกายก่อนลงสระ และไม่ลงสระตอนกินอิ่มมาก","steps":[{"kind":"schedule","prompt":"จัดตารางตั้งแต่ 16:00 ให้นักว่ายน้ำตัวน้อย ให้ผ่านทุกเงื่อนไข","skill":"planning","points":15,"hints":["ของว่างเบา ๆ ได้ แต่ห้ามใส่บุฟเฟต์","อบอุ่นร่างกาย ซ้อมว่ายน้ำ แล้วค่อยกินข้าวเย็น"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 16:00 ของว่างเบา ๆ (นมกับกล้วย) → 16:15 อบอุ่นร่างกายข้างสระ → 16:25 ซ้อมว่ายน้ำ → 17:55 อาบน้ำสระผม → 18:15 กินข้าวเย็น → 18:45 ทำการบ้าน → 19:45 ดูคลิปเทคนิคว่ายน้ำ → 20:15 นอนหลับ","✓ อบอุ่นร่างกายและซ้อมว่ายน้ำครบ","✓ ต้องมี: กินข้าวเย็น","✓ ต้องมี: ทำการบ้าน","✓ ต้องมี: อาบน้ำสระผมหลังลงสระ","✓ อบอุ่นร่างกายก่อนลงสระ","✓ ไม่กินจนอิ่มมากในวันที่ซ้อมว่ายน้ำ","✓ ไม่ลงสระทันทีหลังกินข้าว","✓ จบวันด้วยการนอนหลับ","✓ เข้านอนไม่เกิน 21:00","อบอุ่นร่างกายช่วยให้กล้ามเนื้อพร้อมทำงาน ลดโอกาสเป็นตะคริวและบาดเจ็บ"],"start":"16:00","cards":[{"label":"ของว่างเบา ๆ (นมกับกล้วย)","icon":"🍌","minutes":15,"cat":"meal"},{"label":"ซ้อมว่ายน้ำ","icon":"🏊","minutes":90,"cat":"exercise"},{"label":"อบอุ่นร่างกายข้างสระ","icon":"🤸","minutes":10,"cat":"exercise"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"ทำการบ้าน","icon":"📝","minutes":60,"cat":"study"},{"label":"อาบน้ำสระผม","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"ดูคลิปเทคนิคว่ายน้ำ","icon":"📱","minutes":30,"cat":"screen"},{"label":"นอนหลับ","icon":"😴","minutes":600,"cat":"sleep"},{"label":"กินบุฟเฟต์จนอิ่มมาก","icon":"🍖","minutes":45,"cat":"meal"}],"rules":[{"type":"catMin","cat":"exercise","min":100,"label":"อบอุ่นร่างกายและซ้อมว่ายน้ำครบ"},{"type":"include","card":3,"label":"ต้องมี: กินข้าวเย็น"},{"type":"include","card":4,"label":"ต้องมี: ทำการบ้าน"},{"type":"include","card":5,"label":"ต้องมี: อาบน้ำสระผมหลังลงสระ"},{"type":"before","a":2,"b":1,"label":"อบอุ่นร่างกายก่อนลงสระ"},{"type":"exclude","card":8,"label":"ไม่กินจนอิ่มมากในวันที่ซ้อมว่ายน้ำ"},{"type":"notAfter","a":3,"b":1,"label":"ไม่ลงสระทันทีหลังกินข้าว"},{"type":"last","card":7,"label":"จบวันด้วยการนอนหลับ"},{"type":"startBy","card":7,"time":"21:00","label":"เข้านอนไม่เกิน 21:00"}],"example":[0,2,1,5,3,4,6,7],"notes":["อบอุ่นร่างกายช่วยให้กล้ามเนื้อพร้อมทำงาน ลดโอกาสเป็นตะคริวและบาดเจ็บ"]},{"kind":"order","prompt":"เรียงลำดับการซ้อมว่ายน้ำที่ปลอดภัย","skill":"rules","points":10,"hints":["ต้องมีครูหรือผู้ฝึกสอนอยู่ด้วยก่อนลงน้ำ"],"solution":["รอผู้ฝึกสอน อบอุ่นร่างกาย ลงสระซ้อม แล้วขึ้นมายืดเหยียดคลายกล้ามเนื้อ"],"items":["รอให้ผู้ฝึกสอนมาถึงสระ","อบอุ่นร่างกายข้างสระ","ลงสระซ้อมว่ายตามที่ผู้ฝึกสอนบอก","ขึ้นจากสระแล้วยืดเหยียดคลายกล้ามเนื้อ"]}],"context":[]}', 'medium', 15),
('health_routine', 'อ่านหนังสือแบบมีช่วงพัก', '{"icon":"📚","story":["วันเสาร์ มะปรางจะอ่านคณิตและวิทยาศาสตร์ เริ่ม 09:00 และต้องกินข้าวกลางวันไม่เกิน 12:00","ครั้งก่อนเธออ่านติดกันนานจนปวดตาและจำอะไรไม่ได้"],"tip":"อ่านเสร็จหนึ่งวิชา ให้ลุกขึ้นพักสายตาหรือขยับร่างกายก่อนอ่านต่อ","steps":[{"kind":"schedule","prompt":"จัดตารางอ่านหนังสือตั้งแต่ 09:00 ให้มะปราง ให้ผ่านทุกเงื่อนไข","skill":"planning","points":15,"hints":["วางการ์ดพักหรือยืดเส้นคั่นระหว่างคณิตกับวิทยาศาสตร์","ดูคลิปตอนพักทำให้สายตาไม่ได้พัก"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 09:00 อ่านคณิต → 10:00 พักดื่มน้ำ มองไปไกล ๆ → 10:10 อ่านวิทยาศาสตร์ → 11:10 ยืดเส้นยืดสาย → 11:20 กระโดดเชือก → 11:35 กินข้าวกลางวัน","✓ อ่านครบทั้ง 2 วิชา","✓ อ่านคณิตแล้วพักก่อนอ่านวิทยาศาสตร์","✓ อ่านวิทยาศาสตร์แล้วพักก่อนอ่านคณิต","✓ ไม่ดูคลิปตอนพัก ให้สายตาได้พักจริง","✓ ปิดท้ายด้วยข้าวกลางวัน","✓ กินข้าวกลางวันไม่เกิน 12:00","อ่านแล้วพักเป็นช่วง ๆ ช่วยให้สายตาไม่ล้าและสมองจำได้ดีกว่าอ่านรวดเดียว"],"start":"09:00","cards":[{"label":"อ่านคณิต","icon":"➗","minutes":60,"cat":"study"},{"label":"อ่านวิทยาศาสตร์","icon":"🔬","minutes":60,"cat":"study"},{"label":"พักดื่มน้ำ มองไปไกล ๆ","icon":"💧","minutes":10,"cat":"free"},{"label":"ยืดเส้นยืดสาย","icon":"🤸","minutes":10,"cat":"exercise"},{"label":"กระโดดเชือก","icon":"🪢","minutes":15,"cat":"exercise"},{"label":"กินข้าวกลางวัน","icon":"🍱","minutes":30,"cat":"meal"},{"label":"ดูคลิปตอนพัก","icon":"📱","minutes":40,"cat":"screen"}],"rules":[{"type":"catMin","cat":"study","min":120,"label":"อ่านครบทั้ง 2 วิชา"},{"type":"notAfter","a":0,"b":1,"label":"อ่านคณิตแล้วพักก่อนอ่านวิทยาศาสตร์"},{"type":"notAfter","a":1,"b":0,"label":"อ่านวิทยาศาสตร์แล้วพักก่อนอ่านคณิต"},{"type":"exclude","card":6,"label":"ไม่ดูคลิปตอนพัก ให้สายตาได้พักจริง"},{"type":"last","card":5,"label":"ปิดท้ายด้วยข้าวกลางวัน"},{"type":"startBy","card":5,"time":"12:00","label":"กินข้าวกลางวันไม่เกิน 12:00"}],"example":[0,2,1,3,4,5],"notes":["อ่านแล้วพักเป็นช่วง ๆ ช่วยให้สายตาไม่ล้าและสมองจำได้ดีกว่าอ่านรวดเดียว"]},{"kind":"choice","prompt":"กิจกรรมใดเหมาะที่สุดสำหรับช่วงพักระหว่างอ่านหนังสือ","skill":"reason","points":10,"hints":["ช่วงพักควรให้ตาและร่างกายได้เปลี่ยนจากการจ้องหนังสือ"],"solution":["ลุกขึ้นยืดเส้นและมองไปไกล ๆ ช่วยให้ตาและร่างกายได้พักจริง"],"options":[{"text":"ลุกขึ้นยืดเส้นยืดสาย ดื่มน้ำ และมองไปไกล ๆ","ok":true},{"text":"เล่นเกมในมือถือ","ok":false,"why":"ตายังจ้องจออยู่ ไม่ได้พัก"},{"text":"นั่งอ่านการ์ตูนต่อ","ok":false,"why":"ตายังจ้องตัวหนังสือในระยะใกล้"},{"text":"ไม่ต้องพัก อ่านต่อให้เสร็จเร็ว","ok":false,"why":"อ่านนานโดยไม่พักทำให้ตาล้าและจำได้น้อยลง"}],"answer":0}],"context":[]}', 'medium', 16),
('health_routine', 'วันที่เป็นหวัด', '{"icon":"🤧","story":["ต้นกล้าเป็นหวัด มีน้ำมูกและไอเล็กน้อย แม่ให้พักอยู่บ้านครึ่งวันเช้า","เพื่อนโทรมาชวนไปเตะบอลที่สนาม"],"tip":"เมื่อไม่สบาย ร่างกายต้องการการพักผ่อน น้ำ และอาหารอ่อน ๆ ถ้าอาการไม่ดีขึ้นให้บอกผู้ปกครอง","steps":[{"kind":"multi","prompt":"ขณะเป็นหวัด ต้นกล้าควรทำสิ่งใด (เลือกได้หลายข้อ)","skill":"decision","points":10,"hints":["คิดถึงการดูแลตัวเอง และการไม่แพร่เชื้อให้ผู้อื่น"],"solution":["พักผ่อน ดื่มน้ำ ปิดปากเวลาไอ และบอกผู้ปกครองถ้าอาการแย่ลง ส่วนยาต้องให้ผู้ใหญ่เป็นผู้จัดการ"],"options":[{"text":"นอนพักผ่อนให้มาก","ok":true},{"text":"ดื่มน้ำบ่อย ๆ","ok":true},{"text":"ใช้ทิชชูหรือข้อพับแขนปิดปากเวลาไอจาม","ok":true},{"text":"ไปซื้อยามากินเองโดยไม่บอกผู้ใหญ่","ok":false,"why":"การใช้ยาต้องให้ผู้ปกครองหรือบุคลากรทางการแพทย์ดูแล"},{"text":"ไปเตะบอลให้เหงื่อออกจะหายเร็ว","ok":false,"why":"ร่างกายต้องการพัก การออกแรงมากอาจทำให้เหนื่อยกว่าเดิม"},{"text":"ใช้แก้วน้ำร่วมกับน้อง","ok":false,"why":"อาจแพร่เชื้อหวัดให้น้อง"}]},{"kind":"schedule","prompt":"จัดตารางครึ่งวันเช้าตั้งแต่ 08:00 ให้ต้นกล้าที่เป็นหวัด","skill":"planning","points":15,"hints":["ต้องมีการ์ดนอนพักและดื่มน้ำ","ไม่ใส่การ์ดเตะบอล และดูจอได้ไม่เกิน 30 นาที"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 08:00 กินข้าวต้มอุ่น ๆ → 08:30 ดื่มน้ำอุ่น → 08:40 นอนพัก → 10:40 ล้างมือด้วยสบู่ → 10:45 อ่านหนังสือเบา ๆ → 11:15 ดูการ์ตูน → 11:45 ทบทวนบทเรียนที่ขาด","✓ เวลารวมไม่เกิน 5 ชม.","✓ ไม่ออกไปเล่นกีฬาขณะไม่สบาย","✓ นอนพักอย่างน้อย 2 ชม.","✓ ดื่มน้ำ","✓ กินอาหารอ่อน ๆ","✓ ดูจอ/เล่นเกมไม่เกิน 30 นาที","✓ ทบทวน/การบ้านไม่เกิน 30 นาที","ถ้ามีไข้สูง หายใจลำบาก หรืออาการไม่ดีขึ้น ผู้ปกครองควรพาไปพบแพทย์"],"start":"08:00","cards":[{"label":"กินข้าวต้มอุ่น ๆ","icon":"🥣","minutes":30,"cat":"meal"},{"label":"นอนพัก","icon":"😴","minutes":120,"cat":"sleep"},{"label":"ดื่มน้ำอุ่น","icon":"💧","minutes":10,"cat":"meal"},{"label":"อ่านหนังสือเบา ๆ","icon":"📖","minutes":30,"cat":"free"},{"label":"ไปเตะบอลกับเพื่อน","icon":"⚽","minutes":60,"cat":"exercise"},{"label":"เล