('health_routine', 'เช้าวันกีฬาสี', '{"icon":"🏃","story":["วันกีฬาสี ใบบัวต้องแข่งวิ่งผลัดและชักเยอ เริ่มจัดเวลาตั้งแต่ 07:00","วิ่งผลัดเริ่มไม่เกิน 08:30 และต้องกินข้าวกลางวันเป็นกิจกรรมสุดท้าย"],"tip":"ก่อนแข่งอบอุ่นร่างกาย หลังแข่งคลายกล้ามเนื้อ ระหว่างรายการพักดื่มน้ำ","steps":[{"kind":"schedule","prompt":"จัดตารางวันกีฬาสีตั้งแต่ 07:00 ให้ใบบัว ให้ผ่านทุกเงื่อนไข","skill":"planning","points":15,"hints":["อบอุ่นร่างกายก่อนวิ่งผลัด แล้วคลายกล้ามเนื้อหลังแข่ง","อย่าวางชักเยอต่อจากวิ่งผลัดทันที ให้พักเชียร์เพื่อนก่อน"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 07:00 กินข้าวเช้าเบา ๆ → 07:20 เดินทางไปโรงเรียน → 07:40 อบอุ่นร่างกาย → 07:55 แข่งวิ่งผลัด → 08:25 คลายกล้ามเนื้อ → 08:35 เชียร์เพื่อนในร่มและดื่มน้ำ → 09:35 แข่งชักเยอ → 10:05 กินข้าวกลางวัน","✓ ทุกกิจกรรมต้องอยู่ในตาราง (รวม 3 ชม. 35 นาที)","✓ อบอุ่นร่างกายก่อนวิ่งผลัด","✓ อบอุ่นร่างกายก่อนชักเยอ","✓ มีการคลายกล้ามเนื้อหลังแข่ง","✓ พักก่อนแข่งรายการถัดไป","✓ วิ่งผลัดเริ่มไม่เกิน 08:30","✓ ปิดท้ายด้วยข้าวกลางวัน","พักดื่มน้ำในที่ร่มระหว่างรายการช่วยป้องกันการขาดน้ำและเป็นลมแดด"],"start":"07:00","cards":[{"label":"กินข้าวเช้าเบา ๆ","icon":"🍳","minutes":20,"cat":"meal"},{"label":"เดินทางไปโรงเรียน","icon":"🚌","minutes":20,"cat":"travel"},{"label":"อบอุ่นร่างกาย","icon":"🤸","minutes":15,"cat":"exercise"},{"label":"แข่งวิ่งผลัด","icon":"🏃","minutes":30,"cat":"exercise"},{"label":"คลายกล้ามเนื้อ","icon":"🧘","minutes":10,"cat":"exercise"},{"label":"เชียร์เพื่อนในร่มและดื่มน้ำ","icon":"📣","minutes":60,"cat":"free"},{"label":"แข่งชักเยอ","icon":"🪢","minutes":30,"cat":"exercise"},{"label":"กินข้าวกลางวัน","icon":"🍱","minutes":30,"cat":"meal"}],"rules":[{"type":"total","min":215,"max":215,"label":"ทุกกิจกรรมต้องอยู่ในตาราง (รวม 3 ชม. 35 นาที)"},{"type":"before","a":2,"b":3,"label":"อบอุ่นร่างกายก่อนวิ่งผลัด"},{"type":"before","a":2,"b":6,"label":"อบอุ่นร่างกายก่อนชักเยอ"},{"type":"include","card":4,"label":"มีการคลายกล้ามเนื้อหลังแข่ง"},{"type":"notAfter","a":3,"b":6,"label":"พักก่อนแข่งรายการถัดไป"},{"type":"sta