('health_routine', 'แบ่งเวลาช่วยงานบ้าน', '{"icon":"🧽","story":["บ่ายวันอาทิตย์ ใบเฟิร์นมีเวลาตั้งแต่ 13:00 ถึง 18:00","แม่ขอให้ช่วยงานบ้าน ส่วนเธอก็อยากเล่นกับเพื่อนและวาดรูป"],"tip":"ตารางที่ดีมีทั้งหน้าที่ การเคลื่อนไหว การเรียนรู้ และเวลาว่าง","steps":[{"kind":"schedule","prompt":"จัดตารางตั้งแต่ 13:00 ให้ใบเฟิร์น ให้ผ่านทุกเงื่อนไข","skill":"planning","points":15,"hints":["เลือกงานบ้านรวมอย่างน้อย 45 นาที","เวลาว่างใช้การ์ดวาดรูป แทนการดูจอนาน ๆ"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 13:00 กวาดบ้าน → 13:30 ล้างรถกับพ่อ → 14:15 ทำการบ้าน → 15:15 เล่นฟุตบอลกับเพื่อน → 16:15 อาบน้ำ → 16:35 วาดรูป → 17:20 กินข้าวเย็น","✓ เวลารวมไม่เกิน 5 ชม.","✓ ช่วยงานบ้านอย่างน้อย 45 นาที","✓ ออกกำลังกายอย่างน้อย 1 ชม.","✓ ทบทวน/การบ้านอย่างน้อย 1 ชม.","✓ เวลาว่าง/งานอดิเรกอย่างน้อย 30 นาที","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม.","✓ ปิดท้ายด้วยข้าวเย็น","ช่วยงานบ้านเป็นการเคลื่อนไหวร่างกายและแสดงความรับผิดชอบต่อครอบครัว"],"start":"13:00","cards":[{"label":"ล้างจาน","icon":"🍽️","minutes":15,"cat":"chore"},{"label":"กวาดบ้าน","icon":"🧹","minutes":30,"cat":"chore"},{"label":"ล้างรถกับพ่อ","icon":"🚗","minutes":45,"cat":"chore"},{"label":"ทำการบ้าน","icon":"📝","minutes":60,"cat":"study"},{"label":"เล่นฟุตบอลกับเพื่อน","icon":"⚽","minutes":60,"cat":"exercise"},{"label":"วาดรูป","icon":"🎨","minutes":45,"cat":"free"},{"label":"ดูยูทูบ","icon":"📱","minutes":60,"cat":"screen"},{"label":"เล่นเกม","icon":"🎮","minutes":120,"cat":"screen"},{"label":"อาบน้ำ","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"}],"rules":[{"type":"total","max":300},{"type":"catMin","cat":"chore","min":45},{"type":"catMin","cat":"exercise","min":60},{"type":"catMin","cat":"study","min":60},{"type":"catMin","cat":"free","min":30},{"type":"catMax","cat":"screen","max":60},{"type":"last","card":9,"label":"ปิดท้ายด้วยข้าวเย็น"}],"example":[1,2,3,4,8,5,9],"notes":["ช่วยงานบ้านเป็นการเคลื่อนไหวร่างกายและแสดงความรับผิดชอบต่อครอบครัว"]},{"kind":"multi","prompt":"ทำไมตารางนี