('health_routine', 'ซ่อมตารางของต้นข้าว', '{"icon":"🔧","story":["ต้นข้าวจัดตารางหลังเลิกเรียนเอง แต่ตื่นมาง่วงทุกเช้าและการบ้านไม่ค่อยเสร็จ","นักวางแผนต้องหาปัญหาและซ่อมตารางให้ผ่านทุกเงื่อนไข"],"tip":"ตรวจตารางทีละเงื่อนไข แล้วแก้ทีละจุด","context":[{"type":"table","title":"ตารางเดิมของต้นข้าว","head":["เวลา","กิจกรรม"],"rows":[["16:00–18:00","เล่นเกม"],["18:00–18:15","กินขนมกรุบกรอบระหว่างดูจอ"],["18:15–18:45","กินข้าวเย็น"],["18:45–19:45","เตะบอล"],["19:45–20:45","ทำการบ้าน"],["20:45–21:45","ดูการ์ตูน"],["21:45","นอนหลับ"]]}],"steps":[{"kind":"multi","prompt":"ตารางเดิมของต้นข้าวมีปัญหาใดบ้าง (เลือกได้หลายข้อ)","skill":"analysis","points":10,"hints":["ดูเวลาดูจอรวม เวลาเข้านอน และสิ่งที่ทำหลังกินข้าว"],"solution":["ดูจอรวม 3 ชั่วโมง เตะบอลทันทีหลังกินข้าว ทำการบ้านหลังเล่นเกม และเข้านอนดึกถึง 21:45"],"options":[{"text":"ดูจอรวมนานเกินไป","ok":true},{"text":"เตะบอลทันทีหลังกินข้าวเย็น","ok":true},{"text":"เข้านอนดึกเกินไป","ok":true},{"text":"ทำการบ้านหลังเล่นเกมจนเหนื่อย","ok":true},{"text":"ไม่มีการออกกำลังกายเลย","ok":false,"why":"มีเตะบอล 1 ชั่วโมงแล้ว ปัญหาอยู่ที่เวลาที่เตะ"},{"text":"ไม่ได้กินข้าวเย็น","ok":false,"why":"มีกินข้าวเย็น 18:15"}]},{"kind":"schedule","prompt":"ซ่อมตารางของต้นข้าวตั้งแต่ 16:00 ให้ผ่านทุกเงื่อนไข","skill":"rules","points":15,"hints":["นำเกมและขนมกรุบกรอบออก แล้วเตะบอลก่อนกินข้าว","ทำการบ้านก่อนดูการ์ตูน และเพิ่มงานบ้านถ้ายังมีเวลา"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 16:00 เตะบอล → 17:00 อาบน้ำ → 17:20 กินข้าวเย็น → 17:50 ทำการบ้าน → 18:50 ดูการ์ตูน → 19:50 ช่วยงานบ้าน → 20:10 นอนหลับ","✓ ต้องมี: ทำการบ้าน","✓ ต้องมี: กินข้าวเย็น","✓ ต้องมี: อาบน้ำ","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม.","✓ ออกกำลังกายอย่างน้อย 1 ชม.","✓ นอนหลับอย่างน้อย 9 ชม.","✓ ทำการบ้านก่อนเล่นเกม","✓ ทำการบ้านก่อนดูการ์ตูน","✓ ไม่เตะบอลทันทีหลังกินข้าว","✓ ไม่กินขนมกรุบกรอบระหว่างดูจอ","✓ จบวันด้วยการนอนหลับ","✓ เข้านอนไม่เกิน 21:00","แก้ปัญหาทีละข้อ: ลดจอ ย้ายการออกกำลังกาย ทำการบ้านก่อน แล้วเข้านอนให้ตรงเวลา"],"start":"16:00","cards":[{"label":"เล่นเกม","i