('health_routine', 'อ่านจนดึกก่อนสอบ', '{"icon":"🌃","story":["ภูผาจัดตารางคืนก่อนสอบไว้ว่าจะอ่านหนังสือต่อเนื่องจนดึก แล้วดื่มกาแฟเย็นให้ตาสว่าง","พรุ่งนี้เขาต้องตื่น 06:00 และสอบตอน 09:00"],"tip":"เด็กไม่ควรดื่มกาแฟหรือเครื่องดื่มชูกำลัง การนอนให้พอดีกว่าการฝืนอ่านดึก","steps":[{"kind":"schedule","prompt":"ซ่อมตารางคืนก่อนสอบของภูผาตั้งแต่ 17:00 ให้ผ่านทุกเงื่อนไข","skill":"rules","points":15,"hints":["นำการ์ดอ่านต่อถึงดึก กาแฟ และเกมออก","เหลือทบทวน 1 ชั่วโมง แล้วเติมพักสายตา อาบน้ำ คุยกับพ่อแม่ จัดอุปกรณ์ ก่อนนอน"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 17:00 เดินเล่น → 17:20 กินข้าวเย็น → 17:50 ทบทวนบทเรียนรอบแรก → 18:50 พักสายตา → 19:00 อาบน้ำ → 19:20 คุยกับพ่อแม่เรื่องวันนี้ → 19:50 จัดอุปกรณ์สอบ → 20:00 นอนหลับ","✓ ต้องมี: กินข้าวเย็น","✓ ต้องมี: อาบน้ำ","✓ ทบทวน/การบ้านอย่างน้อย 1 ชม.","✓ ทบทวน/การบ้านไม่เกิน 2 ชม.","✓ ไม่ดื่มกาแฟหรือเครื่องดื่มที่มีคาเฟอีน","✓ ดูจอ/เล่นเกมไม่เกิน 30 นาที","✓ เตรียมอุปกรณ์สอบให้พร้อม","✓ จบวันด้วยการนอนหลับ","✓ เข้านอนไม่เกิน 21:00","คาเฟอีนทำให้หลับยาก เด็กไม่ควรดื่มกาแฟหรือเครื่องดื่มชูกำลัง"],"start":"17:00","cards":[{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"ทบทวนบทเรียนรอบแรก","icon":"📚","minutes":60,"cat":"study"},{"label":"อ่านต่อถึงดึก","icon":"🌙","minutes":180,"cat":"study"},{"label":"ดื่มกาแฟเย็นให้ตาสว่าง","icon":"☕","minutes":10,"cat":"meal"},{"label":"เดินเล่น","icon":"🚶","minutes":20,"cat":"exercise"},{"label":"อาบน้ำ","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"จัดอุปกรณ์สอบ","icon":"✏️","minutes":10,"cat":"chore"},{"label":"นอนหลับ","icon":"😴","minutes":600,"cat":"sleep"},{"label":"พักสายตา","icon":"👀","minutes":10,"cat":"free"},{"label":"เล่นเกมคลายเครียด","icon":"🎮","minutes":60,"cat":"screen"},{"label":"คุยกับพ่อแม่เรื่องวันนี้","icon":"👨‍👩‍👦","minutes":30,"cat":"free"}],"rules":[{"type":"include","card":0,"label":"ต้องมี: กินข้าวเย็น"},{"type":"include","card":5,"label":"ต้องมี: อาบน้ำ"},{"type":"catMin","cat":"study","min":60},{"type":"catMax","cat":"study","max"