('health_routine', 'ตารางซ้อมของทีมฟุตบอล', '{"icon":"🥅","story":["วันเสาร์ ทีมฟุตบอลโรงเรียนซ้อมตั้งแต่ 09:00 และกินข้าวกลางวันด้วยกันก่อน 13:00","กัปตันทีมจัดตารางเริ่มด้วยกินข้าว แล้วซ้อมต่อเนื่องโดยไม่อบอุ่นร่างกาย"],"tip":"อบอุ่นร่างกายก่อน พักดื่มน้ำระหว่างทาง คลายกล้ามเนื้อหลังเล่น และไม่หักโหม","steps":[{"kind":"schedule","prompt":"ซ่อมตารางซ้อมของทีมตั้งแต่ 09:00 ให้ผ่านทุกเงื่อนไข","skill":"rules","points":15,"hints":["เริ่มด้วยการอบอุ่นร่างกาย และกินข้าวกลางวันเป็นอย่างสุดท้าย","ออกกำลังกายรวมไม่เกิน 2 ชั่วโมงครึ่ง จึงใส่ซ้อมยิงประตูเพิ่มไม่ได้"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 09:00 อบอุ่นร่างกาย → 09:15 ซ้อมฟุตบอล → 10:15 พักดื่มน้ำในร่ม → 10:25 ทบทวนแผนการเล่นกับโค้ช → 10:45 แข่งนัดกระชับมิตร → 11:25 คลายกล้ามเนื้อ → 11:35 กินข้าวกลางวัน","✓ เวลารวมไม่เกิน 4 ชม.","✓ เริ่มด้วยการอบอุ่นร่างกาย","✓ มีช่วงพักดื่มน้ำ","✓ ต้องมี: แข่งนัดกระชับมิตร","✓ ซ้อม แข่ง และคลายกล้ามเนื้อครบตามแผนของโค้ช","✓ พักก่อนแข่ง ไม่แข่งต่อจากซ้อมทันที","✓ คลายกล้ามเนื้อหลังแข่ง","✓ ออกกำลังกายรวมไม่เกิน 2 ชม. 30 นาที (ไม่หักโหม)","✓ ปิดท้ายด้วยข้าวกลางวัน","ซ้อมหนักเกินไปทำให้ร่างกายล้าและบาดเจ็บง่าย"],"start":"09:00","cards":[{"label":"อบอุ่นร่างกาย","icon":"🤸","minutes":15,"cat":"exercise"},{"label":"ซ้อมฟุตบอล","icon":"⚽","minutes":60,"cat":"exercise"},{"label":"พักดื่มน้ำในร่ม","icon":"💧","minutes":10,"cat":"free"},{"label":"แข่งนัดกระชับมิตร","icon":"🥅","minutes":40,"cat":"exercise"},{"label":"คลายกล้ามเนื้อ","icon":"🧘","minutes":10,"cat":"exercise"},{"label":"กินข้าวกลางวัน","icon":"🍱","minutes":40,"cat":"meal"},{"label":"ซ้อมยิงประตูเพิ่ม","icon":"🎯","minutes":45,"cat":"exercise"},{"label":"ทบทวนแผนการเล่นกับโค้ช","icon":"📋","minutes":20,"cat":"study"}],"rules":[{"type":"total","max":240},{"type":"first","card":0,"label":"เริ่มด้วยการอบอุ่นร่างกาย"},{"type":"include","card":2,"label":"มีช่วงพักดื่มน้ำ"},{"type":"include","card":3,"label":"ต้องมี: แข่งนัดกระชับมิตร"},{"type":"catMin","cat":"exercise","min":125,"label":"ซ้อม แข่ง และคลายกล้ามเนื้อครบตามแผนของโค้ช"},{"type":"notAfter","a":1,"b":3,"label":"พักก่อนแข่ง ไม่แข่งต่อจากซ้อมทันที"},{"type":"before","a":3,"b":4,"label":"คลายกล้ามเนื้อหลังแข่ง"},{"type":"catMax","cat":"exercise","max":150,"label":"ออกกำลังกายรวมไม่เกิน 2 ชม. 30 นาที (ไม่หักโหม)"},{"type":"last","card":5,"label":"ปิดท้ายด้วยข้าวกลางวัน"}],"preset":[5,1,3,6],"example":[0,1,2,7,3,4,5],"notes":["ซ้อมหนักเกินไปทำให้ร่างกายล้าและบาดเจ็บง่าย"]},{"kind":"multi","prompt":"ตารางเดิมของกัปตันทีมมีความเสี่ยงอะไรบ้าง (เลือกได้หลายข้อ)","skill":"analysis","points":10,"hints":["ตารางเดิม: กินข้าว → ซ้อมฟุตบอล → แข่ง → ซ้อมยิงประตูเพิ่ม"],"solution":["ตารางเดิมเริ่มออกแรงทันทีหลังกินข้าว ไม่อบอุ่นร่างกาย ไม่พักดื่มน้ำ ไม่คลายกล้ามเนื้อ และหักโหมเกินไป"],"options":[{"text":"ไม่ได้อบอุ่นร่างกาย อาจบาดเจ็บ","ok":true},{"text":"ไม่มีช่วงพักดื่มน้ำ อาจขาดน้ำ","ok":true},{"text":"ออกแรงทันทีหลังกินข้าว อาจจุกเสียด","ok":true},{"text":"ได้ซ้อมน้อยเกินไป","ok":false,"why":"ตรงกันข้าม ตารางเดิมหักโหมเกินไป"},{"text":"ไม่มีกติกาการแข่ง","ok":false,"why":"ปัญหาของตารางคือเรื่องสุขภาพและความปลอดภัย"}]},{"kind":"choice","prompt":"ระหว่างซ้อม เพื่อนในทีมบอกว่าเจ็บข้อเท้าแต่อยากเล่นต่อ ควรทำอย่างไร","skill":"decision","points":10,"hints":["ความปลอดภัยสำคัญกว่าการได้ลงเล่น"],"solution":["ให้เพื่อนหยุดพัก และบอกโค้ชหรือครูทันที อย่าฝืนเล่นต่อ"],"options":[{"text":"ให้เพื่อนหยุดพัก และบอกโค้ชทันที","ok":true},{"text":"ให้เล่นต่อ เดี๋ยวก็หายเอง","ok":false,"why":"ฝืนเล่นอาจทำให้บาดเจ็บมากขึ้น"},{"text":"ช่วยนวดข้อเท้าแรง ๆ เอง","ok":false,"why":"การจัดการอาการบาดเจ็บควรให้ผู้ใหญ่ดูแล"},{"text":"ไม่ต้องบอกใคร กลัวทีมแพ้","ok":false,"why":"ต้องบอกผู้ใหญ่เพื่อให้เพื่อนได้รับการดูแล"}],"answer":0}],"context":[]}', 'hard', 26),
('health_routine', 'วันอาทิตย์ก่อนเปิดเทอม', '{"icon":"🎒","story":["พรุ่งนี้เปิดเทอม ใบเฟิร์นต้องตื่น 06:00 วันจันทร์","ตารางเดิมของเธอเริ่ม 15:00 ด้วยการเล่นเกม 3 ชั่วโมง ส่วนการบ้านที่ค้างยังไม่ได้ทำ"],"tip":"นับเวลาจาก 15:00 ถึง 06:00 แล้วแบ่งให้มีที่ว่างสำหรับนอน 9 ชั่วโมง","steps":[{"kind":"schedule","prompt":"ซ่อมตารางของใบเฟิร์นตั้งแต่ 15:00 ถึง 06:00 วันจันทร์ ให้ผ่านทุกเงื่อนไข","skill":"rules","points":15,"hints":["ตารางต้องจบ 06:00 พอดี คือรวม 15 ชั่วโมง โดยนอน 9 ชั่วโมง เหลือเวลาก่อนนอน 6 ชั่วโมง","นำเกมออก ทำการบ้านก่อนดูหนัง และอย่าลืมเตรียมชุดนักเรียน"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 15:00 ทำการบ้านที่ค้าง → 16:30 ปั่นจักรยาน → 17:30 อาบน้ำ → 17:50 กินข้าวเย็น → 18:20 เตรียมชุดนักเรียนและกระเป๋า → 18:40 ดูหนังกับครอบครัว → 20:10 อ่านหนังสือ → 21:00 นอนหลับ","✓ ตารางจบตอน 06:00 วันจันทร์พอดี (รวม 15 ชม.)","✓ นอนหลับอย่างน้อย 9 ชม.","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม. 30 นาที","✓ ออกกำลังกายอย่างน้อย 30 นาที","✓ ทำการบ้านให้เสร็จก่อนดูหนัง","✓ เตรียมของไปโรงเรียน","✓ ไม่ปั่นจักรยานทันทีหลังกินข้าว","✓ จบวันด้วยการนอนหลับ","ก่อนเปิดเทอม ควรปรับเวลานอนให้เหมือนวันเรียน จะได้ตื่นไหว"],"start":"15:00","cards":[{"label":"เล่นเกม","icon":"🎮","minutes":180,"cat":"screen"},{"label":"ทำการบ้านที่ค้าง","icon":"📝","minutes":90,"cat":"study"},{"label":"เตรียมชุดนักเรียนและกระเป๋า","icon":"🎒","minutes":20,"cat":"chore"},{"label":"ปั่นจักรยาน","icon":"🚲","minutes":60,"cat":"exercise"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"อาบน้ำ","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"ดูหนังกับครอบครัว","icon":"🎬","minutes":90,"cat":"screen"},{"label":"นอนหลับ","icon":"😴","minutes":540,"cat":"sleep"},{"label":"อ่านหนังสือ","icon":"📖","minutes":50,"cat":"free"},{"label":"รดน้ำต้นไม้","icon":"🪴","minutes":20,"cat":"chore"}],"rules":[{"type":"total","min":900,"max":900,"label":"ตารางจบตอน 06:00 วันจันทร์พอดี (รวม 15 ชม.)"},{"type":"catMin","cat":"sleep","min":540},{"type":"catMax","cat":"screen","max":90},{"type":"catMin","cat":"exercise","min":30},{"type":"before","a":1,"b":6,"label":"ทำการบ้านให้เสร็จก่อนดูหนัง"},{"type":"include","card":2,"label":"เตรียมของไปโรงเรียน"},{"type":"notAfter","a":4,"b":3,"label":"ไม่ปั่นจักรยานทันทีหลังกินข้าว"},{"type":"last","card":7,"label":"จบวันด้วยการนอนหลับ"}],"preset":[0,4,3,6,1,7],"example":[1,3,5,4,2,6,8,7],"notes":["ก่อนเปิดเทอม ควรปรับเวลานอนให้เหมือนวันเรียน จะได้ตื่นไหว"]},{"kind":"order","prompt":"เรียงลำดับวิธีซ่อมตารางที่ใบเฟิร์นควรใช้","skill":"planning","points":10,"hints":["เริ่มจากสิ่งที่ห้ามขาด แล้วจึงเติมสิ่งที่อยากทำ"],"solution":["กันเวลานอนก่อน ใส่สิ่งจำเป็น เติมการออกกำลังกาย ใส่กิจกรรมที่อยากทำในเวลาที่เหลือ แล้วตรวจเงื่อนไขอีกรอบ"],"items":["กันเวลานอน 9 ชั่วโมงไว้ก่อน","ใส่สิ่งที่ต้องทำ เช่น การบ้าน กินข้าว และเตรียมของ","เติมการออกกำลังกาย","ใส่กิจกรรมที่อยากทำในเวลาที่เหลือ","ตรวจตารางกับเงื่อนไขทุกข้ออีกครั้ง"]}],"context":[]}', 'hard', 27),
('health_routine', 'เที่ยวทะเลอย่างปลอดภัย', '{"icon":"🏖️","story":["ครอบครัวของภูผาไปเที่ยวทะเล มีเวลาตั้งแต่ 09:00 ถึง 13:00","ตารางเดิมของภูผาเริ่มด้วยการกินข้าว แล้วลงเล่นน้ำทันที บางช่วงก็ลงเล่นคนเดียว"],"tip":"เล่นน้ำต้องมีผู้ใหญ่ดูแล ป้องกันแดด และพักดื่มน้ำในร่ม","steps":[{"kind":"sort","prompt":"แยกกิจกรรมที่ทะเลว่าปลอดภัยหรือเสี่ยงอันตราย","skill":"analysis","points":10,"hints":["ถามว่ามีผู้ใหญ่ดูแลไหม และร่างกายพร้อมหรือยัง"],"solution":["เล่นน้ำกับผู้ใหญ่ ทาครีมกันแดด และพักในร่มปลอดภัย ส่วนเล่นน้ำคนเดียวหรือลงน้ำทันทีหลังกินอิ่มเสี่ยงอันตราย"],"bins":["ปลอดภัย","เสี่ยงอันตราย"],"items":[{"text":"เล่นน้ำในบริเวณที่ผู้ปกครองมองเห็น","bin":0},{"text":"ทาครีมกันแดดและใส่หมวก","bin":0},{"text":"พักดื่มน้ำในที่ร่ม","bin":0},{"text":"ลงเล่นน้ำคนเดียวตอนพ่อแม่ไม่เห็น","bin":1,"why":"ถ้าเกิดเหตุจะไม่มีใครช่วยได้ทัน"},{"text":"ลงน้ำทันทีหลังกินอิ่ม","bin":1,"why":"อาจจุกเสียดหรือเป็นตะคริว"},{"text":"ว่ายออกไปไกลเกินธงเตือน","bin":1,"why":"ธงเตือนบอกเขตอันตราย เช่น คลื่นแรง"}]},{"kind":"schedule","prompt":"ซ่อมตารางเที่ยวทะเลของภูผาตั้งแต่ 09:00 ให้ผ่านทุกเงื่อนไข","skill":"rules","points":15,"hints":["ทาครีมกันแดดและอบอุ่นร่างกายก่อนลงน้ำ","นำการเล่นน้ำคนเดียวออก และกินข้าวหลังเล่นน้ำ"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 09:00 ทาครีมกันแดด ใส่หมวก → 09:10 อบอุ่นร่างกายเบา ๆ → 09:20 เล่นน้ำทะเลกับผู้ปกครอง → 10:20 พักในร่มดื่มน้ำ → 10:40 ก่อปราสาททราย → 11:20 กินข้าวกลางวัน → 12:05 ล้างตัวด้วยน้ำจืด","✓ ต้องมี: อบอุ่นร่างกายเบา ๆ","✓ ต้องมี: กินข้าวกลางวัน","✓ เวลารวมไม่เกิน 4 ชม.","✓ ไม่ลงเล่นน้ำโดยไม่มีผู้ใหญ่ดูแล","✓ ได้เล่นน้ำทะเลกับผู้ปกครอง","✓ เริ่มด้วยการทาครีมกันแดด ใส่หมวก","✓ อบอุ่นร่างกายก่อนลงน้ำ","✓ ไม่ลงน้ำทันทีหลังกินอิ่ม","✓ มีช่วงพักในร่มดื่มน้ำ","เล่นน้ำในบริเวณที่มีผู้ใหญ่และเจ้าหน้าที่ดูแล และทำตามป้ายหรือธงเตือน"],"start":"09:00","cards":[{"label":"ทาครีมกันแดด ใส่หมวก","icon":"🧴","minutes":10,"cat":"hygiene"},{"label":"เล่นน้ำทะเลกับผู้ปกครอง","icon":"🌊","minutes":60,"cat":"exercise"},{"label":"เล่นน้ำคนเดียวตอนพ่อแม่ไม่เห็น","icon":"🏊","minutes":60,"cat":"exercise"},{"label":"กินข้าวกลางวัน","icon":"🍤","minutes":45,"cat":"meal"},{"label":"พักในร่มดื่มน้ำ","icon":"⛱️","minutes":20,"cat":"free"},{"label":"ก่อปราสาททราย","icon":"🏰","minutes":40,"cat":"free"},{"label":"ล้างตัวด้วยน้ำจืด","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"อบอุ่นร่างกายเบา ๆ","icon":"🤸","minutes":10,"cat":"exercise"}],"rules":[{"type":"include","card":7,"label":"ต้องมี: อบอุ่นร่างกายเบา ๆ"},{"type":"include","card":3,"label":"ต้องมี: กินข้าวกลางวัน"},{"type":"total","max":240},{"type":"exclude","card":2,"label":"ไม่ลงเล่นน้ำโดยไม่มีผู้ใหญ่ดูแล"},{"type":"include","card":1,"label":"ได้เล่นน้ำทะเลกับผู้ปกครอง"},{"type":"first","card":0,"label":"เริ่มด้วยการทาครีมกันแดด ใส่หมวก"},{"type":"before","a":7,"b":1,"label":"อบอุ่นร่างกายก่อนลงน้ำ"},{"type":"notAfter","a":3,"b":1,"label":"ไม่ลงน้ำทันทีหลังกินอิ่ม"},{"type":"include","card":4,"label":"มีช่วงพักในร่มดื่มน้ำ"}],"preset":[3,1,2,5,6],"example":[0,7,1,4,5,3,6],"notes":["เล่นน้ำในบริเวณที่มีผู้ใหญ่และเจ้าหน้าที่ดูแล และทำตามป้ายหรือธงเตือน"]},{"kind":"choice","prompt":"ถ้าเห็นธงแดงปักอยู่ริมหาด ภูผาควรทำอย่างไร","skill":"decision","points":10,"hints":["ธงแดงเป็นสัญญาณเตือน"],"solution":["ธงแดงเตือนว่าทะเลอันตราย ห้ามลงเล่นน้ำ ควรเล่นบนหาดแทน"],"options":[{"text":"ไม่ลงเล่นน้ำ และเล่นบนชายหาดแทน","ok":true},{"text":"ลงเล่นแค่ริมน้ำคนเดียว","ok":false,"why":"คลื่นอาจซัดแรงแม้ริมน้ำ และไม่ควรเล่นคนเดียว"},{"text":"ว่ายเร็ว ๆ ให้เสร็จก่อนคลื่นมา","ok":false,"why":"ธงแดงหมายถึงห้ามลงน้ำ"},{"text":"ไม่สนใจ เพราะเป็นธงตกแต่ง","ok":false,"why":"ธงริมหาดเป็นสัญญาณความปลอดภัย"}],"answer":0}],"context":[]}', 'hard', 28),
('health_routine', 'วันที่ฝุ่น PM2.5 สูง', '{"icon":"😷","story":["วันนี้ค่าฝุ่น PM2.5 อยู่ในระดับสีส้ม โรงเรียนแนะนำให้ลดกิจกรรมกลางแจ้ง","ตารางเดิมของมะปรางเริ่ม 16:00 ด้วยการวิ่งรอบสนามกลางแจ้ง แล้วปั่นจักรยานไปซื้อขนม"],"tip":"วันที่ฝุ่นสูง ยังออกกำลังกายได้ แต่ควรย้ายเข้าไปในอาคาร","steps":[{"kind":"schedule","prompt":"ซ่อมตารางของมะปรางตั้งแต่ 16:00 ให้ผ่านทุกเงื่อนไข","skill":"rules","points":15,"hints":["นำกิจกรรมกลางแจ้งทั้ง 2 อย่างออก แล้วใช้แอโรบิกกับกระโดดเชือกในบ้านแทน","ออกกำลังกายในบ้านรวมให้ได้อย่างน้อย 45 นาที ก่อนกินข้าว"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 16:00 ทำการบ้าน → 17:00 เต้นแอโรบิกในบ้าน → 17:30 กระโดดเชือกในห้องโถง → 17:45 อาบน้ำ → 18:05 กินข้าวเย็น → 18:35 ดูการ์ตูน → 19:35 อ่านนิทาน → 20:05 นอนหลับ","✓ ต้องมี: ทำการบ้าน","✓ ต้องมี: กินข้าวเย็น","✓ ต้องมี: อาบน้ำ","✓ ไม่วิ่งกลางแจ้งวันที่ฝุ่นสูง","✓ ไม่ปั่นจักรยานกลางแจ้งวันที่ฝุ่นสูง","✓ ออกกำลังกายอย่างน้อย 45 นาที","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม.","✓ ไม่เต้นแอโรบิกทันทีหลังกินข้าว","✓ จบวันด้วยการนอนหลับ","✓ เข้านอนไม่เกิน 21:00","ฝุ่นละอองขนาดเล็กเข้าสู่ปอดได้ลึก วันที่ค่าฝุ่นสูงควรอยู่ในอาคารและลดกิจกรรมกลางแจ้ง"],"start":"16:00","cards":[{"label":"วิ่งรอบสนามกลางแจ้ง","icon":"🏃","minutes":45,"cat":"exercise"},{"label":"เต้นแอโรบิกในบ้าน","icon":"💃","minutes":30,"cat":"exercise"},{"label":"กระโดดเชือกในห้องโถง","icon":"🪢","minutes":15,"cat":"exercise"},{"label":"ทำการบ้าน","icon":"📝","minutes":60,"cat":"study"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"อาบน้ำ","icon":"🚿","minutes":20,"cat":"hygiene"},{"label":"ดูการ์ตูน","icon":"📺","minutes":60,"cat":"screen"},{"label":"ปั่นจักรยานไปซื้อขนม","icon":"🚲","minutes":30,"cat":"exercise"},{"label":"อ่านนิทาน","icon":"📖","minutes":30,"cat":"free"},{"label":"นอนหลับ","icon":"😴","minutes":540,"cat":"sleep"}],"rules":[{"type":"include","card":3,"label":"ต้องมี: ทำการบ้าน"},{"type":"include","card":4,"label":"ต้องมี: กินข้าวเย็น"},{"type":"include","card":5,"label":"ต้องมี: อาบน้ำ"},{"type":"exclude","card":0,"label":"ไม่วิ่งกลางแจ้งวันที่ฝุ่นสูง"},{"type":"exclude","card":7,"label":"ไม่ปั่นจักรยานกลางแจ้งวันที่ฝุ่นสูง"},{"type":"catMin","cat":"exercise","min":45},{"type":"catMax","cat":"screen","max":60},{"type":"notAfter","a":4,"b":1,"label":"ไม่เต้นแอโรบิกทันทีหลังกินข้าว"},{"type":"last","card":9,"label":"จบวันด้วยการนอนหลับ"},{"type":"startBy","card":9,"time":"21:00","label":"เข้านอนไม่เกิน 21:00"}],"preset":[0,7,4,1,6,3,9],"example":[3,1,2,5,4,6,8,9],"notes":["ฝุ่นละอองขนาดเล็กเข้าสู่ปอดได้ลึก วันที่ค่าฝุ่นสูงควรอยู่ในอาคารและลดกิจกรรมกลางแจ้ง"]},{"kind":"multi","prompt":"วันที่ค่าฝุ่นสูง ข้อใดเป็นการดูแลตัวเองที่เหมาะสม (เลือกได้หลายข้อ)","skill":"decision","points":10,"hints":["คิดถึงการลดฝุ่นที่หายใจเข้าไป"],"solution":["ย้ายกิจกรรมเข้าอาคาร สวมหน้ากากเมื่อต้องออกนอกบ้าน และบอกผู้ใหญ่ถ้ามีอาการไอหรือหายใจไม่สะดวก"],"options":[{"text":"ออกกำลังกายในอาคารแทนกลางแจ้ง","ok":true},{"text":"สวมหน้ากากเมื่อต้องออกนอกบ้าน","ok":true},{"text":"บอกผู้ใหญ่ถ้าไอหรือหายใจไม่สะดวก","ok":true},{"text":"งดออกกำลังกายทุกชนิดทั้งสัปดาห์","ok":false,"why":"ยังออกกำลังกายในอาคารได้"},{"text":"วิ่งกลางแจ้งให้นานขึ้นเพื่อให้ปอดแข็งแรง","ok":false,"why":"ยิ่งวิ่งกลางแจ้งนาน ยิ่งหายใจเอาฝุ่นเข้าไปมาก"}]}],"context":[]}', 'hard', 29),
('health_routine', 'ภารกิจใหญ่: หนึ่งวันของใบเฟิร์น', '{"icon":"🏆","story":["ใบเฟิร์นจัดตารางวันเรียนเต็มวันตั้งแต่ 06:00 แต่ตารางมีปัญหาหลายจุด","เธอข้ามมื้อเช้า ซ้อมวอลเลย์บอลหลังกินข้าวเย็นทันที และเล่นเกมต่อจนดึก"],"tip":"ภารกิจใหญ่ต้องตรวจทุกเงื่อนไขพร้อมกัน: เวลารวม การนอน อาหาร การออกกำลังกาย และเวลาดูจอ","steps":[{"kind":"multi","prompt":"จากเรื่องราว ตารางเดิมของใบเฟิร์นผิดเงื่อนไขใดบ้าง (เลือกได้หลายข้อ)","skill":"analysis","points":10,"hints":["อ่านเรื่องราวทีละประโยค แล้วจับคู่กับเงื่อนไข"],"solution":["ข้ามมื้อเช้า ซ้อมกีฬาทันทีหลังกินข้าว และเล่นเกมจนดึก ทำให้นอนน้อยและดูจอเกิน"],"options":[{"text":"ไม่มีมื้อเช้า","ok":true},{"text":"ออกกำลังกายทันทีหลังกินข้าวเย็น","ok":true},{"text":"ดูจอนานเกินและนอนดึก","ok":true},{"text":"ไปโรงเรียนไม่ได้","ok":false,"why":"เรื่องราวไม่ได้บอกว่าไปโรงเรียนไม่ได้"},{"text":"ไม่มีการทำการบ้าน","ok":false,"why":"เรื่องราวไม่ได้บอกปัญหานี้"}]},{"kind":"schedule","prompt":"ซ่อมตาราง 24 ชั่วโมงของใบเฟิร์นตั้งแต่ 06:00 ให้ผ่านทุกเงื่อนไข","skill":"rules","points":20,"hints":["ใส่มื้อเช้าก่อนเดินทาง และเอาเกมต่อถึงดึกออก","เวลารวมต้อง 24 ชั่วโมงพอดี ให้ซ้อมวอลเลย์บอลก่อนกินข้าวเย็น แล้วเติมงานบ้านกับงานอดิเรก"],"solution":["ตัวอย่างตารางที่ผ่านทุกเงื่อนไข: 06:00 ตื่นนอน อาบน้ำแต่งตัว → 06:30 กินข้าวเช้า → 06:50 เดินทางไปโรงเรียน → 07:20 เรียนที่โรงเรียน (รวมพักกลางวัน) → 15:20 เดินทางกลับบ้าน → 15:50 ซ้อมวอลเลย์บอล → 16:50 อาบน้ำตอนเย็น → 17:10 กินข้าวเย็น → 17:40 ทำการบ้าน → 18:40 ดูซีรีส์ → 19:40 ช่วยงานบ้าน → 20:10 อ่านหนังสือ งานอดิเรก → 21:00 นอนหลับ","✓ เวลารวม 24 ชม. พอดี","✓ นอนหลับอย่างน้อย 9 ชม.","✓ มีมื้อเช้า","✓ เริ่มเรียนไม่เกิน 08:00","✓ ออกกำลังกายอย่างน้อย 1 ชม.","✓ ดูจอ/เล่นเกมไม่เกิน 1 ชม.","✓ ทำการบ้านก่อนดูซีรีส์","✓ ไม่ซ้อมกีฬาทันทีหลังกินข้าวเย็น","✓ จบวันด้วยการนอนหลับ","ตารางที่ดีไม่ได้มีคำตอบเดียว แต่ต้องผ่านทุกเงื่อนไขของสุขภาพ"],"start":"06:00","cards":[{"label":"ตื่นนอน อาบน้ำแต่งตัว","icon":"🚿","minutes":30,"cat":"hygiene"},{"label":"กินข้าวเช้า","icon":"🍳","minutes":20,"cat":"meal"},{"label":"เดินทางไปโรงเรียน","icon":"🚌","minutes":30,"cat":"travel"},{"label":"เรียนที่โรงเรียน (รวมพักกลางวัน)","icon":"🏫","minutes":480,"cat":"school"},{"label":"เดินทางกลับบ้าน","icon":"🏠","minutes":30,"cat":"travel"},{"label":"ซ้อมวอลเลย์บอล","icon":"🏐","minutes":60,"cat":"exercise"},{"label":"กินข้าวเย็น","icon":"🍛","minutes":30,"cat":"meal"},{"label":"ทำการบ้าน","icon":"📝","minutes":60,"cat":"study"},{"label":"อาบน้ำตอนเย็น","icon":"🛁","minutes":20,"cat":"hygiene"},{"label":"ดูซีรีส์","icon":"📺","minutes":60,"cat":"screen"},{"label":"ช่วยงานบ้าน","icon":"🧹","minutes":30,"cat":"chore"},{"label":"อ่านหนังสือ งานอดิเรก","icon":"🎨","minutes":50,"cat":"free"},{"label":"เล่นเกมต่อถึงดึก","icon":"🎮","minutes":150,"cat":"screen"},{"label":"นอนหลับ","icon":"😴","minutes":540,"cat":"sleep"}],"rules":[{"type":"total","min":1440,"max":1440},{"type":"catMin","cat":"sleep","min":540},{"type":"include","card":1,"label":"มีมื้อเช้า"},{"type":"startBy","card":3,"time":"08:00","label":"เริ่มเรียนไม่เกิน 08:00"},{"type":"catMin","cat":"exercise","min":60},{"type":"catMax","cat":"screen","max":60},{"type":"before","a":7,"b":9,"label":"ทำการบ้านก่อนดูซีรีส์"},{"type":"notAfter","a":6,"b":5,"label":"ไม่ซ้อมกีฬาทันทีหลังกินข้าวเย็น"},{"type":"last","card":13,"label":"จบวันด้วยการนอนหลับ"}],"preset":[0,2,3,4,6,5,9,12,7,13],"example":[0,1,2,3,4,5,8,6,7,9,10,11,13],"notes":["ตารางที่ดีไม่ได้มีคำตอบเดียว แต่ต้องผ่านทุกเงื่อนไขของสุขภาพ"]},{"kind":"choice","prompt":"ถ้าต้องอธิบายให้เพื่อนฟังว่าตารางใหม่ดีกว่าอย่างไร ข้อใดเป็นเหตุผลที่ครบที่สุด","skill":"reason","points":10,"hints":["เหตุผลที่ดีควรพูดถึงหลายด้านของสุขภาพ ไม่ใช่ด้านเดียว"],"solution":["ตารางใหม่ดีกว่าเพราะได้พลังงานจากมื้อเช้า ออกกำลังกายอย่างปลอดภัย ดูจอไม่เกิน และนอนพอ"],"options":[{"text":"ได้กินมื้อเช้า ออกกำลังกายอย่างปลอดภัย ดูจอไม่เกิน 1 ชั่วโมง และนอนครบ 9 ชั่วโมง","ok":true},{"text":"ได้ดูซีรีส์ 1 ชั่วโมง","ok":false,"why":"เป็นเพียงด้านเดียว ไม่ได้อธิบายเรื่องสุขภาพ"},{"text":"ตารางใหม่มีกิจกรรมมากกว่า","ok":false,"why":"จำนวนกิจกรรมไม่ได้บอกว่าดีต่อสุขภาพ"},{"text":"ตารางใหม่ไม่มีการบ้าน","ok":false,"why":"ตารางใหม่ยังมีการบ้าน 1 ชั่วโมง"}],"answer":0}],"context":[]}', 'hard', 30),
('health_sports', 'อุ่นเครื่องก่อนลงสนามฟุตบอล', '{"icon":"⚽","story":["คาบพลศึกษาวันนี้ ครูให้ห้อง ป.5/1 แข่งฟุตบอลกัน","ภูผาอยากลงเตะทันที แต่ครูบอกว่าทุกคนต้องอบอุ่นร่างกายก่อน 5–10 นาที"],"tip":"การอบอุ่นร่างกายที่ดีควรเริ่มจากเบา ๆ และใช้ท่าที่คล้ายกับกีฬาที่จะเล่น","context":[{"type":"note","text":"ฟุตบอลใช้การวิ่ง การเปลี่ยนทิศทาง และการเตะลูกด้วยขาเป็นหลัก"}],"steps":[{"kind":"choice","prompt":"การอบอุ่นร่างกายแบบใดเหมาะกับฟุตบอลมากที่สุด","skill":"decision","points":10,"options":[{"text":"วิ่งเหยาะรอบสนาม ยืดเหยียดต้นขาและน่อง แล้วเลี้ยงลูกเบา ๆ","ok":true},{"text":"วิ่งเร็วสุดแรง 3 รอบสนามทันที","ok":false,"why":"เริ่มด้วยแรงสูงสุดตอนกล้ามเนื้อยังไม่อุ่นเสี่ยงบาดเจ็บ ควรเริ่มจากเบาไปหนัก"},{"text":"นั่งพักในร่มให้หายร้อนก่อนลงสนาม","ok":false,"why":"การนั่งพักไม่ได้ทำให้กล้ามเนื้อและข้อต่อพร้อมเคลื่อนไหว"},{"text":"หมุนข้อมือและนิ้วอย่างเดียว","ok":false,"why":"ฟุตบอลใช้ขาเป็นหลัก จึงต้องอบอุ่นขา ข้อเท้า และสะโพกด้วย"}],"hints":["ฟุตบอลใช้ร่างกายส่วนไหนมากที่สุด","ควรเริ่มจากเบาไปหนัก หรือหนักไปเบา"],"solution":["การอบอุ่นร่างกายควรเริ่มเบา ๆ แล้วค่อยเพิ่ม และเน้นส่วนที่จะใช้เล่นจริง","วิ่งเหยาะ ยืดขา และเลี้ยงลูกเบา ๆ ทำให้กล้ามเนื้อขาและข้อต่อพร้อม ลดโอกาสบาดเจ็บ"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องอบอุ่นร่างกายก่อนเล่นกีฬา","skill":"reason","points":10,"options":[{"text":"ช่วยให้กล้ามเนื้อและข้อต่อพร้อมเคลื่อนไหว ลดโอกาสบาดเจ็บ","ok":true},{"text":"ทำให้เตะลูกได้แรงกว่าคู่แข่งทุกครั้ง","ok":false,"why":"การอบอุ่นช่วยให้ร่างกายพร้อม แต่ไม่ได้รับประกันว่าจะเตะแรงกว่าหรือชนะเสมอ"},{"text":"เพราะครูสั่ง ถ้าครูไม่อยู่ก็ข้ามได้","ok":false,"why":"เราอบอุ่นร่างกายเพื่อความปลอดภัยของตัวเอง ไม่ใช่เพราะมีคนดูอยู่"},{"text":"ทำให้ไม่ต้องดื่มน้ำระหว่างเล่น","ok":false,"why":"การอบอุ่นร่างกายไม่ได้แทนการดื่มน้ำ ยังต้องดื่มน้ำเปล่าระหว่างพักเสมอ"}],"hints":["ถ้าไม่อบอุ่นร่างกาย อะไรมีโอกาสเกิดขึ้นกับกล้ามเนื้อ"],"solution":["กล้ามเนื้อที่อุ่นแล้วยืดหยุ่นและพร้อมทำงานมากกว่า จึงบาดเจ็บยากขึ้น","เหตุผลที่ดีต้องอ้างถึงความปลอดภัยของร่างกาย ไม่ใช่ผลแพ้ชนะหรือคำสั่งอย่างเดียว"],"answer":0}]}', 'easy', 1),
('health_sports', 'ลำดับอบอุ่นก่อนวอลเลย์บอล', '{"icon":"🏐","story":["มะปรางเป็นหัวหน้ากลุ่ม ต้องพาเพื่อนอบอุ่นร่างกายก่อนเล่นวอลเลย์บอล","ครูบอกว่าให้เริ่มจากเบาไปหนัก และจบด้วยท่าที่ใกล้กับการเล่นจริง"],"context":[],"steps":[{"kind":"order","prompt":"เรียงลำดับการอบอุ่นร่างกายให้ถูกต้อง","skill":"planning","points":10,"items":["เดินเร็วหรือวิ่งเหยาะเบา ๆ ให้ร่างกายอบอุ่น","หมุนข้อมือ ข้อไหล่ และยืดเหยียดกล้ามเนื้อแขนและขา","ฝึกเล่นลูกสองมือล่างกับเพื่อนเบา ๆ","เริ่มเล่นเกมจริง"],"hints":["ขั้นไหนเบาที่สุด ขั้นไหนหนักที่สุด","ท่าที่คล้ายการเล่นจริงควรมาก่อนเริ่มเกมทันที"],"solution":["ร่างกายควรค่อย ๆ อุ่นขึ้น เริ่มจากเคลื่อนไหวทั้งตัวเบา ๆ แล้วยืดเหยียดข้อต่อ","ท่าเฉพาะกีฬาช่วยเตรียมส่วนที่จะใช้จริงก่อนเริ่มเกม"]},{"kind":"choice","prompt":"ควรใช้เวลาอบอุ่นร่างกายประมาณเท่าใด","skill":"rules","points":10,"options":[{"text":"5–10 นาที","ok":true},{"text":"30 วินาที","ok":false,"why":"สั้นเกินไป กล้ามเนื้อยังไม่ทันอุ่น"},{"text":"1 ชั่วโมง","ok":false,"why":"นานเกินไป จะเหนื่อยก่อนเริ่มเล่นจริง"},{"text":"ไม่ต้องกำหนดเวลา ข้ามได้ถ้ารีบ","ok":false,"why":"การอบอุ่นร่างกายไม่ควรข้าม เพราะช่วยป้องกันการบาดเจ็บ"}],"hints":["นึกถึงเวลาที่ครูให้อบอุ่นร่างกายในคาบพลศึกษา"],"solution":["การอบอุ่นร่างกายประมาณ 5–10 นาทีพอให้ร่างกายพร้อม แต่ไม่เหนื่อยเกินไปก่อนเล่น"],"answer":0}]}', 'easy', 2),
('health_sports', 'ปลอดภัยหรือเสี่ยงในสนามฟุตบอล', '{"icon":"🦺","story":["ช่วงพักกลางวัน เพื่อน ๆ ชวนกันเล่นฟุตบอลที่สนามโรงเรียน","ต้นกล้าสังเกตพฤติกรรมของเพื่อนแต่ละคน และอยากช่วยเตือนเรื่องความปลอดภัย"],"context":[],"steps":[{"kind":"sort","prompt":"จัดพฤติกรรมแต่ละข้อลงกลุ่มให้ถูกต้อง","skill":"analysis","points":10,"bins":["ปลอดภัย","เสี่ยงอันตราย"],"items":[{"text":"ถอดสร้อยคอและนาฬิกาก่อนลงเล่น","bin":0,"why":"ช่วยไม่ให้เครื่องประดับเกี่ยวหรือข่วนตัวเองและเพื่อน"},{"text":"ใส่รองเท้าผ้าใบผูกเชือกแน่น","bin":0,"why":"รองเท้าที่พอดีช่วยให้วิ่งมั่นคง ไม่ลื่นหรือหลุด"},{"text":"ดื่มน้ำเปล่าตอนพักครึ่ง","bin":0,"why":"ร่างกายเสียน้ำทางเหงื่อ ควรดื่มน้ำเปล่าชดเชย"},{"text":"เตะลูกแรง ๆ ใส่เพื่อนที่ไม่ได้มอง","bin":1,"why":"ลูกอาจกระแทกหน้าหรือศีรษะเพื่อนได้"},{"text":"ผลักเพื่อนจากด้านหลังเพื่อแย่งลูก","bin":1,"why":"ทำให้เพื่อนล้มได้ และผิดกติกา"},{"text":"เล่นต่อทั้งที่ฟ้าร้องและฝนเริ่มตก","bin":1,"why":"ฟ้าร้องเตือนว่าอาจมีฟ้าผ่า และพื้นเปียกลื่น"},{"text":"บอกครูทันทีเมื่อเพื่อนล้มแล้วลุกไม่ไหว","bin":0,"why":"ครูจะดูแลอาการได้ถูกวิธี"}],"hints":["ถามตัวเองว่า ถ้าทำแบบนี้ ใครมีโอกาสเจ็บบ้าง"],"solution":["พฤติกรรมที่ปลอดภัยคือเตรียมตัวให้พร้อม ดูแลร่างกาย และขอความช่วยเหลือเมื่อมีคนเจ็บ","พฤติกรรมเสี่ยงคือทำให้ตัวเองหรือเพื่อนบาดเจ็บ หรือเล่นในสภาพอากาศอันตราย"]}]}', 'easy', 3),
('health_sports', 'เลือกทักษะให้ตรงสถานการณ์', '{"icon":"🎯","story":["ครูจัดเกมทายท่า ให้นักเรียนเลือกทักษะการเคลื่อนไหวที่เหมาะกับแต่ละสถานการณ์","ใครเลือกถูกครบทุกข้อ จะได้เป็นผู้ช่วยครูในคาบหน้า"],"context":[],"steps":[{"kind":"plan","prompt":"เลือกทักษะที่เหมาะสมที่สุดของแต่ละสถานการณ์","skill":"decision","points":10,"fields":[{"id":"f1","label":"วอลเลย์บอล: ลูกลอยมาสูงกว่าศีรษะ","options":[{"text":"เล่นลูกสองมือบน","ok":true},{"text":"เล่นลูกสองมือล่าง","ok":false,"why":"ลูกสองมือล่างใช้กับลูกที่ต่ำ ระดับเอวลงไป"},{"text":"จับลูกไว้แล้วโยนต่อ","ok":false,"why":"วอลเลย์บอลห้ามจับหรือถือลูก ต้องกระทบลูกออกไป"}],"answer":0},{"id":"f2","label":"บาสเกตบอล: ต้องพาลูกเคลื่อนที่ไปข้างหน้า","options":[{"text":"เลี้ยงลูกให้กระทบพื้นขณะเคลื่อนที่","ok":true},{"text":"กอดลูกไว้แล้ววิ่งไป","ok":false,"why":"ถือลูกแล้ววิ่งโดยไม่เลี้ยงผิดกติกา"},{"text":"เตะลูกไปข้างหน้า","ok":false,"why":"บาสเกตบอลห้ามตั้งใจใช้เท้าเล่นลูก"}],"answer":0},{"id":"f3","label":"ฟุตบอล: เพื่อนอยู่ใกล้ ไม่มีคู่แข่งขวาง","options":[{"text":"ส่งลูกเลียดพื้นด้วยข้างเท้าด้านใน","ok":true},{"text":"เตะด้วยปลายเท้าสุดแรง","ok":false,"why":"ระยะใกล้ไม่ต้องใช้แรงมาก และเตะปลายเท้าบังคับทิศทางยาก"},{"text":"ใช้มือโยนให้เพื่อน","ok":false,"why":"ผู้เล่นที่ไม่ใช่ผู้รักษาประตูห้ามใช้มือเล่นลูก"}],"answer":0},{"id":"f4","label":"ป้องกันบาสเกตบอล: คู่แข่งเลี้ยงลูกไปทางซ้ายและขวา","options":[{"text":"ย่อเข่า สไลด์เท้าไปด้านข้าง หันหน้าหาคู่แข่ง","ok":true},{"text":"หันหลังวิ่งตามไป","ok":false,"why":"หันหลังจะมองไม่เห็นลูกและคู่แข่ง"},{"text":"กระโดดขึ้นลงอยู่กับที่ตลอดเวลา","ok":false,"why":"กระโดดอยู่กับที่ทำให้คู่แข่งผ่านไปง่าย และเหนื่อยเร็ว"}],"answer":0}],"hints":["ดูว่าลูกอยู่สูงหรือต่ำ และกีฬานั้นใช้มือหรือเท้า","ทักษะไหนทำให้ยังมองเห็นคู่แข่งตลอดเวลา"],"solution":["แต่ละกีฬามีทักษะเฉพาะ และกติกากำหนดว่าใช้ส่วนไหนของร่างกายได้","การเลือกทักษะตามระดับลูกและตำแหน่งคู่แข่งทำให้เล่นได้ดีและถูกกติกา"]}]}', 'easy', 4),
('health_sports', 'กระโดดเชือกอย่างปลอดภัย', '{"icon":"🪢","story":["ใบเฟิร์นกับเพื่อนอีก 3 คนจะซ้อมกระโดดเชือกเดี่ยวที่ลานกิจกรรม","ครูให้ช่วยกันเช็กก่อนว่าอะไรช่วยให้ซ้อมได้ปลอดภัย"],"context":[],"steps":[{"kind":"multi","prompt":"ข้อใดช่วยให้กระโดดเชือกได้อย่างปลอดภัย (เลือกทุกข้อที่ถูก)","skill":"rules","points":10,"options":[{"text":"ลงพื้นด้วยปลายเท้า และงอเข่าเล็กน้อย","ok":true},{"text":"ยืนห่างจากเพื่อนให้เชือกแกว่งไม่ถึงกัน","ok":true},{"text":"ใช้เชือกยาวพอดีกับความสูงของตัวเอง","ok":true},{"text":"ซ้อมบนพื้นเรียบที่ไม่ลื่น","ok":true},{"text":"ใส่รองเท้าแตะเพราะเบาสบาย","ok":false,"why":"รองเท้าแตะหลุดง่ายและไม่รองรับเท้า ควรใส่รองเท้าผ้าใบ"},{"text":"ลงพื้นด้วยส้นเท้าแรง ๆ ให้มีเสียงดัง","ok":false,"why":"ลงส้นเท้าแรง ๆ ทำให้ข้อเท้าและเข่ารับแรงกระแทกมาก"}],"hints":["นึกถึงเท้า เชือก พื้น และเพื่อนรอบตัว"],"solution":["ลงปลายเท้าและงอเข่าช่วยลดแรงกระแทก","เชือกยาวพอดี พื้นเรียบ และระยะห่างที่พอช่วยไม่ให้สะดุดหรือเชือกฟาดเพื่อน"]}]}', 'easy', 5),
('health_sports', 'วันหยุดที่สระว่ายน้ำ', '{"icon":"🏊","story":["วันเสาร์ มะปรางไปสระว่ายน้ำกับพ่อ","มะปรางว่ายน้ำได้แล้ว และอยากลงสระให้เร็วที่สุด"],"context":[{"type":"note","text":"ป้ายที่สระ: ห้ามวิ่งรอบขอบสระ ห้ามกระโดดพุ่งหัวในส่วนน้ำตื้น"}],"steps":[{"kind":"choice","prompt":"ก่อนลงสระ มะปรางควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"อบอุ่นร่างกายอยู่กับที่ข้างสระ แล้วลงน้ำเมื่อพ่ออยู่ดูแลใกล้ ๆ","ok":true},{"text":"กระโดดพุ่งหัวลงฝั่งตื้นให้ชินน้ำเร็ว","ok":false,"why":"พุ่งหัวลงน้ำตื้นอาจกระแทกพื้นสระ อันตรายมาก"},{"text":"ลงสระคนเดียวตอนพ่อไปซื้อน้ำ","ok":false,"why":"เด็กควรว่ายน้ำเมื่อมีผู้ใหญ่ดูแลอยู่ใกล้ ๆ เสมอ"},{"text":"วิ่งรอบขอบสระเพื่ออบอุ่นร่างกาย","ok":false,"why":"ขอบสระลื่น วิ่งแล้วอาจล้มศีรษะกระแทกได้"}],"hints":["อ่านป้ายของสระอีกครั้ง","ใครควรอยู่ด้วยตอนเด็กลงน้ำ"],"solution":["อบอุ่นร่างกายช่วยลดตะคริวและการบาดเจ็บ","เด็กต้องว่ายน้ำเมื่อมีผู้ใหญ่ดูแล และทำตามป้ายของสระ"],"answer":0},{"kind":"choice","prompt":"ว่ายไปสักพัก ได้ยินฟ้าร้องและเห็นฟ้าแลบ มะปรางควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"ขึ้นจากสระทันที แล้วไปหลบในอาคาร","ok":true},{"text":"ว่ายต่อเพราะฝนยังไม่ตก","ok":false,"why":"ฟ้าผ่าอาจเกิดได้แม้ฝนยังไม่ตก"},{"text":"ดำลงไปหลบใต้น้ำ","ok":false,"why":"อยู่ในน้ำยังเสี่ยงฟ้าผ่า ต้องขึ้นจากสระ"},{"text":"ไปยืนหลบใต้ต้นไม้ใหญ่ข้างสระ","ok":false,"why":"ต้นไม้สูงกลางแจ้งเสี่ยงฟ้าผ่า ควรเข้าอาคาร"}],"hints":["ที่ไหนปลอดภัยที่สุดเมื่อมีฟ้าแลบ"],"solution":["น้ำและที่โล่งเสี่ยงต่อฟ้าผ่า เมื่อได้ยินฟ้าร้องต้องขึ้นจากน้ำและเข้าอาคารทันที"],"answer":0}]}', 'easy', 6),
('health_sports', 'วิ่ง 50 เมตรในลู่', '{"icon":"🏃","story":["ครูจัดแข่งวิ่ง 50 เมตร ทีละ 4 คน","ใบเฟิร์นได้วิ่งในลู่ที่ 2"],"context":[{"type":"table","title":"ลู่วิ่งของแต่ละคน","head":["ลู่","ผู้วิ่ง"],"rows":[["1","ข้าวหอม"],["2","ใบเฟิร์น"],["3","ภูผา"],["4","มะปราง"]]}],"steps":[{"kind":"order","prompt":"เรียงคำสั่งปล่อยตัวที่ครูใช้ให้ถูกต้อง","skill":"rules","points":10,"items":["เข้าที่","ระวัง","ไป"],"hints":["คำสั่งไหนบอกให้ออกวิ่ง"],"solution":["\"เข้าที่\" ให้ไปอยู่หลังเส้นเริ่ม \"ระวัง\" ให้เตรียมพร้อมนิ่ง ๆ และ \"ไป\" จึงออกวิ่ง"]},{"kind":"choice","prompt":"ระหว่างวิ่ง ใบเฟิร์นควรวิ่งอย่างไร","skill":"rules","points":10,"options":[{"text":"วิ่งอยู่ในลู่ที่ 2 ของตัวเองจนผ่านเส้นชัย","ok":true},{"text":"วิ่งตัดเข้าลู่ที่ 3 เพื่อแซงภูผา","ok":false,"why":"วิ่งระยะสั้นต้องอยู่ในลู่ตัวเอง ตัดลู่ผิดกติกาและอาจชนเพื่อน"},{"text":"หันกลับไปดูเพื่อนบ่อย ๆ","ok":false,"why":"หันไปมองทำให้ช้าลงและเสียหลักได้ ควรมองไปข้างหน้า"},{"text":"ชะลอก่อนถึงเส้นชัยเพื่อหยุดให้ทัน","ok":false,"why":"ควรวิ่งผ่านเส้นชัยไปก่อน แล้วค่อยลดความเร็ว"}],"hints":["ดูตารางว่าใบเฟิร์นได้ลู่ไหน"],"solution":["การวิ่งในลู่ของตัวเองทำให้แข่งได้ยุติธรรม และไม่ชนกัน","วิ่งผ่านเส้นชัยแล้วค่อยลดความเร็วจะได้เวลาดีและไม่ล้ม"],"answer":0}]}', 'easy', 7),
('health_sports', 'ส่งลูกบาสผ่านแขนคู่แข่ง', '{"icon":"🏀","story":["มะปรางถือลูกบาสเกตบอลอยู่กลางสนาม","คู่แข่งยืนขวางข้างหน้าและยกแขนสูง ส่วนต้นกล้ายืนว่างอยู่ทางขวา"],"context":[{"type":"table","title":"ตำแหน่งในสนาม","head":["ผู้เล่น","ตำแหน่ง","สถานการณ์"],"rows":[["มะปราง (ถือลูก)","กลางสนาม","คู่แข่งยืนข้างหน้า ยกแขนสูง"],["ต้นกล้า","ห่างไป 3 ก้าว ทางขวา","ไม่มีคู่แข่งประกบ"]]}],"steps":[{"kind":"choice","prompt":"มะปรางควรส่งลูกแบบใดให้ต้นกล้า","skill":"analysis","points":10,"options":[{"text":"ส่งลูกกระดอนพื้น ให้ลูกกระทบพื้นหนึ่งครั้งก่อนถึงต้นกล้า","ok":true},{"text":"ส่งลูกโด่งข้ามศีรษะคู่แข่ง","ok":false,"why":"คู่แข่งยกแขนสูงอยู่ ลูกโด่งช้าและถูกตัดได้ง่าย"},{"text":"ส่งลูกสองมือระดับอกตรงผ่านตัวคู่แข่ง","ok":false,"why":"คู่แข่งยืนขวางอยู่ ลูกระดับอกอาจโดนแขนคู่แข่ง"},{"text":"ถือลูกวิ่งไปให้ต้นกล้า","ok":false,"why":"ถือลูกเดินหรือวิ่งโดยไม่เลี้ยงผิดกติกา"}],"hints":["แขนของคู่แข่งอยู่สูงหรือต่ำ","ช่องว่างอยู่ตรงไหน"],"solution":["เมื่อคู่แข่งยกแขนสูง ช่องว่างจะอยู่ด้านล่าง ลูกกระดอนพื้นจึงลอดผ่านได้"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่เลือกส่งลูกกระดอนพื้นในสถานการณ์นี้","skill":"reason","points":10,"options":[{"text":"ลูกผ่านใต้แขนที่คู่แข่งยกสูงไว้ จึงถูกตัดได้ยาก","ok":true},{"text":"ลูกกระดอนพื้นเร็วที่สุดเสมอ","ok":false,"why":"ลูกกระดอนพื้นไม่ได้เร็วที่สุด ข้อดีคือลอดใต้แขนคู่แข่ง"},{"text":"กติกาบังคับให้ส่งกระดอนพื้นเท่านั้น","ok":false,"why":"กติกาให้ส่งได้หลายแบบ เราเลือกตามสถานการณ์"},{"text":"ต้นกล้าชอบรับลูกต่ำ ๆ","ok":false,"why":"ควรเลือกจากตำแหน่งคู่แข่งในสนาม ไม่ใช่ความชอบ"}],"hints":["เหตุผลควรเกี่ยวกับตำแหน่งแขนของคู่แข่ง"],"solution":["การเลือกวิธีส่งลูกต้องดูว่าคู่แข่งปิดทางไหนไว้ แล้วส่งไปทางที่ยังเปิดอยู่"],"answer":0}]}', 'easy', 8),
('health_sports', 'คลายอุ่นหลังเล่นบาส', '{"icon":"🧘","story":["ภูผาเล่นบาสเกตบอลมา 30 นาที เหงื่อท่วมตัวและหายใจแรง","ครูเป่านกหวีดหมดเวลา และให้ทุกคนคลายอุ่นก่อนกลับห้อง"],"context":[],"steps":[{"kind":"choice","prompt":"ภูผาควรทำอะไรก่อน","skill":"decision","points":10,"options":[{"text":"เดินช้า ๆ ให้หายใจเป็นปกติ แล้วยืดเหยียดกล้ามเนื้อ","ok":true},{"text":"นั่งลงกับพื้นทันทีแล้วนอนพัก","ok":false,"why":"หยุดทันทีหลังออกแรงหนักอาจทำให้หน้ามืด ควรค่อย ๆ ลดความหนัก"},{"text":"ดื่มน้ำอัดลมเย็น ๆ ให้ชื่นใจ","ok":false,"why":"ควรดื่มน้ำเปล่า น้ำอัดลมมีน้ำตาลมาก"},{"text":"วิ่งเร็วต่ออีกรอบให้เหงื่อออกหมด","ok":false,"why":"หลังเล่นควรลดความหนักลง ไม่ใช่เพิ่ม"}],"hints":["หลังออกแรงหนัก ร่างกายควรค่อย ๆ ช้าลง หรือหยุดทันที"],"solution":["การคลายอุ่นคือค่อย ๆ ลดความหนักของการเคลื่อนไหว แล้วยืดเหยียดกล้ามเนื้อที่ใช้"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องคลายอุ่นหลังเล่นกีฬา","skill":"reason","points":10,"options":[{"text":"ช่วยให้หัวใจและการหายใจค่อย ๆ กลับสู่ปกติ และลดอาการตึงของกล้ามเนื้อ","ok":true},{"text":"ทำให้เหนื่อยมากขึ้น จะได้แข็งแรงเร็ว","ok":false,"why":"การคลายอุ่นคือการลดความเหนื่อยลงอย่างค่อยเป็นค่อยไป"},{"text":"ให้ครูมีเวลาเก็บอุปกรณ์","ok":false,"why":"เหตุผลหลักคือร่างกายของเรา ไม่ใช่เรื่องอุปกรณ์"},{"text":"ทำให้ไม่ต้องอาบน้ำหลังเล่น","ok":false,"why":"การคลายอุ่นไม่เกี่ยวกับความสะอาด ยังควรอาบน้ำหรือเช็ดตัวหลังเล่น"}],"hints":["ระหว่างคลายอุ่น หัวใจและลมหายใจเปลี่ยนไปอย่างไร"],"solution":["ร่างกายควรเปลี่ยนจากหนักไปเบาอย่างช้า ๆ ทั้งก่อนเล่นและหลังเล่น","การยืดเหยียดหลังเล่นช่วยลดอาการตึงของกล้ามเนื้อ"],"answer":0}]}', 'easy', 9),
('health_sports', 'แชร์บอลวันแดดจัด', '{"icon":"☀️","story":["ตอนบ่าย ห้อง ป.5/2 แข่งแชร์บอลที่ลานกลางแจ้ง","ผ่านไปสักพัก ต้นกล้าเหงื่อออกมาก หน้าแดง และบอกเพื่อนว่ามึนหัว"],"context":[{"type":"note","text":"วันนี้อากาศร้อนจัด แดดแรงตลอดบ่าย"}],"steps":[{"kind":"choice","prompt":"ต้นกล้าควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"หยุดเล่น ไปพักในที่ร่ม และบอกครูทันที","ok":true},{"text":"ฝืนเล่นต่อให้จบเกมเพราะทีมกำลังชนะ","ok":false,"why":"มึนหัวในวันร้อนจัดเป็นสัญญาณอันตราย ต้องหยุดก่อน"},{"text":"ไปนั่งรอเพื่อนกลางแดดข้างสนาม","ok":false,"why":"อยู่กลางแดดต่อ ร่างกายจะยิ่งร้อน ต้องไปที่ร่ม"},{"text":"ไปซื้อขนมหวานกินให้มีแรงแล้วเล่นต่อ","ok":false,"why":"ขนมหวานไม่ได้แก้อาการ และควรให้ครูดูอาการก่อน"}],"hints":["อาการของต้นกล้าบอกอะไรเกี่ยวกับร่างกายในวันที่ร้อนจัด"],"solution":["มึนหัว หน้าแดง เหงื่อออกมากในวันร้อน แปลว่าร่างกายร้อนเกินไป","ต้องหยุดเล่น ไปที่ร่ม และบอกครูหรือผู้ใหญ่ให้ช่วยดูแล"],"answer":0},{"kind":"choice","prompt":"ครั้งหน้าถ้าต้องเล่นกีฬาวันที่อากาศร้อน ควรเตรียมตัวแบบใด","skill":"planning","points":10,"options":[{"text":"ดื่มน้ำเปล่าก่อนเล่นและระหว่างพัก ใส่เสื้อผ้าระบายอากาศ และพักในร่มเป็นระยะ","ok":true},{"text":"ใส่เสื้อแขนยาวหนา ๆ ให้เหงื่อออกเยอะ","ok":false,"why":"เสื้อหนาทำให้ความร้อนระบายออกยาก"},{"text":"งดดื่มน้ำจะได้ไม่จุกเวลาวิ่ง","ok":false,"why":"ร่างกายเสียน้ำทางเหงื่อมาก ต้องดื่มน้ำเปล่าเป็นระยะ"},{"text":"เล่นต่อเนื่องไม่พักเลยให้จบเร็ว","ok":false,"why":"วันที่ร้อนจัดควรพักในร่มบ่อยขึ้น"}],"hints":["คิดถึงน้ำ เสื้อผ้า และการพัก"],"solution":["น้ำเปล่า เสื้อผ้าระบายอากาศ และการพักในร่มช่วยไม่ให้ร่างกายร้อนเกินไป"],"answer":0}]}', 'easy', 10),
('health_sports', 'วางแผนก่อนแข่งแชร์บอล', '{"icon":"🪑","story":["ทีมของใบเฟิร์นจะแข่งแชร์บอลกับห้องข้าง ๆ","ครูให้เวลาวางแผน 2 นาที ก่อนเริ่มเกมทีมของใบเฟิร์นจะได้ครองลูกก่อน"],"context":[{"type":"note","text":"กติกาที่ครูย้ำ: ผู้ถือลูกห้ามถือลูกวิ่ง ต้องส่งต่อให้เพื่อน ทีมได้คะแนนเมื่อผู้รับที่ยืนบนเก้าอี้รับลูกได้"},{"type":"table","title":"ตำแหน่งตอนเริ่มเกม","head":["ผู้เล่น","อยู่ตรงไหน","คู่แข่งประกบ"],"rows":[["ใบเฟิร์น (ถือลูก)","กลางสนาม","1 คน"],["ภูผา","ใกล้เก้าอี้ ฝั่งซ้าย","ไม่มี"],["มะปราง","ใกล้เก้าอี้ ฝั่งขวา","2 คน"],["ต้นกล้า","ข้างหลังใบเฟิร์น","ไม่มี"],["น้ำฝน (ผู้รับบนเก้าอี้)","บนเก้าอี้ท้ายสนาม","มีผู้ป้องกันยืนบังด้านหน้า"]]}],"steps":[{"kind":"plan","prompt":"วางแผนให้ครบ 3 เรื่องก่อนเริ่มเกม","skill":"planning","points":10,"fields":[{"id":"f1","label":"อบอุ่นร่างกาย","options":[{"text":"วิ่งเหยาะ แล้วจับคู่ส่ง-รับลูกเบา ๆ","ok":true},{"text":"นั่งเหยียดขานิ่ง ๆ อย่างเดียว","ok":false,"why":"แชร์บอลต้องวิ่ง ส่ง และรับลูก ควรอบอุ่นแบบเคลื่อนไหวและฝึกส่ง-รับ"},{"text":"ซ้อมขว้างลูกแรงที่สุดใส่ผู้รับบนเก้าอี้","ok":false,"why":"ใช้แรงเต็มที่ตั้งแต่แรกเสี่ยงบาดเจ็บ และอาจทำให้เพื่อนบนเก้าอี้เสียหลัก"}],"answer":0},{"id":"f2","label":"การยืนตำแหน่ง","options":[{"text":"กระจายกันให้ทั่วสนาม เพื่อมีทางส่งหลายทาง","ok":true},{"text":"ทุกคนวิ่งไปรวมใกล้ลูก","ok":false,"why":"รวมกันอยู่ที่เดียว คู่แข่งประกบง่าย และไม่มีใครว่างให้ส่ง"},{"text":"ทุกคนไปยืนรอใกล้เก้าอี้","ok":false,"why":"ถ้าไม่มีใครอยู่กลางสนาม ต้องส่งลูกไกลซึ่งถูกตัดง่าย"}],"answer":0},{"id":"f3","label":"ส่งลูกแรกให้ใคร","options":[{"text":"ภูผา","ok":true},{"text":"มะปราง","ok":false,"why":"มะปรางถูกประกบ 2 คน ลูกมีโอกาสถูกตัดสูง"},{"text":"น้ำฝนบนเก้าอี้โดยตรง","ok":false,"why":"ระยะไกลและมีผู้ป้องกันบังอยู่ ควรส่งให้เพื่อนที่ว่างและใกล้กว่าก่อน"},{"text":"ต้นกล้า","ok":false,"why":"ต้นกล้าว่าง แต่อยู่ข้างหลัง ลูกจะไม่ได้เข้าใกล้เก้าอี้เลย"}],"answer":0}],"hints":["ดูตารางว่าใครไม่มีคู่แข่งประกบ และใครอยู่ใกล้เก้าอี้","ทีมที่ยืนกระจายมีทางส่งกี่ทาง"],"solution":["อบอุ่นด้วยการเคลื่อนไหวและฝึกส่ง-รับ ตรงกับทักษะที่จะใช้","ยืนกระจายทำให้มีเพื่อนว่างหลายคน","ภูผาว่างและอยู่ใกล้เก้าอี้ จึงเป็นทางส่งที่ดีที่สุด"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่เลือกส่งลูกแรกให้ภูผา","skill":"reason","points":10,"options":[{"text":"ภูผาว่างและอยู่ใกล้ผู้รับบนเก้าอี้ ลูกถูกตัดยาก และส่งต่อไปทำคะแนนได้","ok":true},{"text":"ภูผาเป็นเพื่อนสนิทที่สุดของใบเฟิร์น","ok":false,"why":"การเลือกส่งควรดูจากสถานการณ์ในสนาม ไม่ใช่ความสนิท"},{"text":"ภูผาถือลูกวิ่งไปหาเก้าอี้ได้เร็ว","ok":false,"why":"แชร์บอลห้ามถือลูกวิ่ง"},{"text":"ส่งไกลที่สุดดีที่สุดเสมอ","ok":false,"why":"ลูกที่ส่งไกลลอยนานและถูกตัดง่าย ควรดูว่าใครว่าง"}],"hints":["เหตุผลที่ดีต้องอ้างข้อมูลจากตาราง"],"solution":["ทางส่งที่ดีคือเพื่อนที่ว่างและอยู่ใกล้เป้าหมาย ทำให้ทีมมีโอกาสทำคะแนนโดยไม่เสียลูก"],"answer":0}]}', 'medium', 11),
('health_sports', 'วอลเลย์บอลสามจังหวะ', '{"icon":"🏐","story":["ทีมของมะปรางรับลูกเสิร์ฟจากฝั่งตรงข้าม","ลูกยังอยู่ฝั่งทีมของมะปราง และกำลังลอยลงมาใกล้ตาข่ายฝั่งที่ใบเฟิร์นยืนอยู่"],"context":[{"type":"note","text":"กติกาพื้นฐาน: แต่ละทีมสัมผัสลูกได้ไม่เกิน 3 ครั้งก่อนส่งข้ามตาข่าย ผู้เล่นคนเดียวห้ามสัมผัสลูกติดกัน 2 ครั้ง และห้ามจับหรือถือลูก"},{"type":"table","title":"การสัมผัสลูกของทีมเราในจังหวะนี้","head":["ครั้งที่","ผู้เล่น","ทำอะไร"],"rows":[["1","มะปราง","รับลูกเสิร์ฟด้วยการเล่นลูกสองมือล่าง"],["2","ภูผา","เซตลูกขึ้นสูงใกล้ตาข่าย"]]}],"steps":[{"kind":"choice","prompt":"ใครควรเล่นลูกครั้งต่อไป และควรทำอย่างไร","skill":"rules","points":10,"options":[{"text":"ใบเฟิร์นที่อยู่ใกล้ตาข่าย ตบหรือส่งลูกข้ามตาข่ายไป","ok":true},{"text":"ภูผาเล่นลูกต่ออีกครั้งเพราะอยู่ใกล้ที่สุด","ok":false,"why":"ภูผาเพิ่งสัมผัสลูก จะสัมผัสติดกันอีกครั้งไม่ได้"},{"text":"ใบเฟิร์นเซตลูกให้มะปรางอีกครั้ง","ok":false,"why":"นี่คือครั้งที่ 3 แล้ว ต้องส่งข้ามตาข่าย ถ้าส่งให้เพื่อนอีกจะเป็นครั้งที่ 4"},{"text":"ใบเฟิร์นจับลูกไว้แล้วโยนข้ามตาข่าย","ok":false,"why":"วอลเลย์บอลห้ามจับหรือถือลูก"}],"hints":["ในตาราง ทีมเราสัมผัสลูกไปแล้วกี่ครั้ง","ใครเพิ่งสัมผัสลูกล่าสุด"],"solution":["ทีมสัมผัสลูกไปแล้ว 2 ครั้ง ครั้งที่ 3 ต้องส่งข้ามตาข่าย","ภูผาเพิ่งสัมผัสลูก จึงต้องเป็นคนอื่นเล่นลูก"],"answer":0},{"kind":"order","prompt":"เรียงลำดับการเล่นลูก 3 จังหวะที่ทีมนี้ใช้","skill":"analysis","points":10,"items":["รับลูกเสิร์ฟด้วยการเล่นลูกสองมือล่าง","เซตลูกขึ้นสูงด้วยการเล่นลูกสองมือบน","ตบหรือส่งลูกข้ามตาข่าย"],"hints":["ลูกเสิร์ฟมักมาเร็วและต่ำ ลูกที่เซตขึ้นมาสูงเหมาะกับอะไร"],"solution":["รับลูกต่ำด้วยสองมือล่าง แล้วเซตลูกให้สูงด้วยสองมือบน เพื่อให้เพื่อนส่งข้ามตาข่ายได้ง่าย","การเล่น 3 จังหวะคือการทำงานเป็นทีม"]}]}', 'medium', 12),
('health_sports', 'ฟุตบอล: ใครว่าง', '{"icon":"⚽","story":["ทีมของต้นกล้ากำลังบุกในเกมฟุตบอลในคาบพลศึกษา","ต้นกล้าคุมลูกอยู่กลางสนาม และมีคู่แข่งวิ่งเข้ามาหา"],"context":[{"type":"note","text":"คะแนนเสมอ 0–0 เหลือเวลา 3 นาที"},{"type":"table","title":"สถานการณ์ในสนาม","head":["ผู้เล่นทีมเรา","ตำแหน่ง","คู่แข่งใกล้ ๆ"],"rows":[["ต้นกล้า (คุมลูก)","กลางสนาม","1 คนกำลังวิ่งเข้ามา"],["ภูผา","ทางขวา ใกล้ประตูคู่แข่ง ห่างต้นกล้าประมาณ 10 ก้าว","ไม่มี"],["มะปราง","หน้าประตูคู่แข่ง","2 คนประกบ"],["ใบเฟิร์น","ด้านหลังต้นกล้า ไกลประตูคู่แข่ง","ไม่มี"]]}],"steps":[{"kind":"choice","prompt":"ต้นกล้าควรส่งลูกให้ใครดีที่สุด","skill":"analysis","points":10,"options":[{"text":"ภูผา","ok":true},{"text":"มะปราง","ok":false,"why":"มะปรางอยู่ใกล้ประตูก็จริง แต่ถูกประกบ 2 คน ลูกจะถูกตัดง่าย"},{"text":"ใบเฟิร์น","ok":false,"why":"ใบเฟิร์นว่าง แต่ลูกจะถอยห่างประตู ขณะที่ภูผาว่างและใกล้ประตูกว่า"},{"text":"ไม่ส่ง เลี้ยงลูกผ่านคู่แข่งเอง","ok":false,"why":"คู่แข่งกำลังวิ่งเข้ามา มีโอกาสเสียลูก ขณะที่มีเพื่อนว่างอยู่"}],"hints":["หาเพื่อนที่ไม่มีคู่แข่งประกบ และอยู่ใกล้ประตูคู่แข่ง"],"solution":["ภูผาไม่มีคู่แข่งประกบและอยู่ใกล้ประตู จึงเป็นทางส่งที่ปลอดภัยและได้เปรียบที่สุด"],"answer":0},{"kind":"choice","prompt":"ระยะส่งให้ภูผาประมาณ 10 ก้าว บนพื้นหญ้าเรียบ ควรส่งแบบใด","skill":"decision","points":10,"options":[{"text":"ส่งลูกเลียดพื้นด้วยข้างเท้าด้านใน ไปข้างหน้าภูผาเล็กน้อย","ok":true},{"text":"เตะโด่งสูงด้วยหลังเท้าสุดแรง","ok":false,"why":"ระยะไม่ไกล ลูกโด่งช้า รับยาก และอาจเลยตัวภูผา"},{"text":"เตะด้วยปลายเท้าให้แรงที่สุด","ok":false,"why":"ปลายเท้าบังคับทิศทางยาก ลูกอาจไม่ไปถึงภูผา"},{"text":"ใช้ส้นเท้าเตะลูกไปข้างหลัง","ok":false,"why":"ภูผาอยู่ข้างหน้าทางขวา ไม่ได้อยู่ข้างหลัง"}],"hints":["ระยะใกล้ต้องการความแม่นยำหรือความแรงมากกว่ากัน"],"solution":["ข้างเท้าด้านในมีพื้นที่สัมผัสลูกกว้าง ส่งได้แม่นในระยะใกล้","ส่งไปข้างหน้าเพื่อนเล็กน้อย เพื่อนจะวิ่งรับต่อได้โดยไม่ต้องหยุด"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ทีมควรส่งลูกให้เพื่อนที่ว่าง","skill":"reason","points":10,"options":[{"text":"ลูกถูกแย่งยาก และเพื่อนมีเวลาเล่นลูกต่อ","ok":true},{"text":"เพื่อนที่ว่างเป็นคนเก่งที่สุดเสมอ","ok":false,"why":"คนที่ว่างไม่จำเป็นต้องเก่งที่สุด แต่มีพื้นที่และเวลามากกว่า"},{"text":"จะได้ไม่ต้องวิ่งเอง","ok":false,"why":"ส่งแล้วยังต้องวิ่งหาตำแหน่งต่อ เพื่อช่วยทีม"},{"text":"กติกาห้ามส่งให้คนที่ถูกประกบ","ok":false,"why":"กติกาไม่ได้ห้าม แต่ส่งให้คนที่ถูกประกบเสี่ยงเสียลูกมากกว่า"}],"hints":["คิดถึงสิ่งที่เกิดขึ้นหลังลูกไปถึงเพื่อน"],"solution":["การเล่นเป็นทีมคือมองหาเพื่อนที่ว่าง ลูกจะปลอดภัยและทีมมีโอกาสมากขึ้น"],"answer":0}]}', 'medium', 13),
('health_sports', 'สนามบาสปลอดภัย', '{"icon":"🏀","story":["ก่อนเกมบาสเกตบอลระหว่างห้อง ครูให้ต้นกล้าเป็นผู้ช่วยตรวจความปลอดภัย","ต้นกล้าจดสิ่งที่เห็นไว้หลายข้อ"],"context":[],"steps":[{"kind":"sort","prompt":"จัดสิ่งที่ต้นกล้าเห็นลงกลุ่มให้ถูกต้อง","skill":"analysis","points":10,"bins":["ทำได้ ปลอดภัย","ไม่ควรทำ เสี่ยงบาดเจ็บ"],"items":[{"text":"ตัดเล็บให้สั้นก่อนเล่น","bin":0,"why":"เล็บสั้นไม่ข่วนเพื่อนเวลาแย่งลูก"},{"text":"ผูกเชือกรองเท้าให้แน่น","bin":0,"why":"ไม่สะดุดเชือกและรองเท้าไม่หลุด"},{"text":"เก็บลูกบอลที่กลิ้งอยู่ในสนามออกไปข้างสนาม","bin":0,"why":"ลูกที่กลิ้งอยู่อาจทำให้คนเหยียบแล้วข้อเท้าพลิก"},{"text":"ยืดเหยียดและวิ่งเหยาะก่อนลงเล่น","bin":0,"why":"เป็นการอบอุ่นร่างกายที่ช่วยลดการบาดเจ็บ"},{"text":"ห้อยพวงกุญแจไว้ที่กางเกง","bin":1,"why":"ของแข็งที่ห้อยอยู่อาจเกี่ยวหรือกระแทกตัวเองและเพื่อน"},{"text":"โหนห่วงบาสเล่นหลังทำคะแนน","bin":1,"why":"อาจหลุดมือตกลงมา หรือแป้นเสียหาย"},{"text":"วิ่งชนเพื่อนแรง ๆ เพื่อแย่งลูก","bin":1,"why":"ทำให้เพื่อนล้มบาดเจ็บ และเป็นการฟาวล์"},{"text":"เล่นต่อบนพื้นที่เปียกน้ำฝน","bin":1,"why":"พื้นเปียกลื่นมาก เสี่ยงล้ม"}],"hints":["แต่ละข้อทำให้ใครเจ็บได้บ้าง หรือช่วยป้องกันอะไร"],"solution":["การเตรียมตัวและเตรียมสนามช่วยป้องกันอุบัติเหตุ","เครื่องประดับ การปะทะแรง ๆ และพื้นเปียกเป็นสาเหตุบาดเจ็บที่พบบ่อย"]},{"kind":"choice","prompt":"มะปรางเพิ่งได้สร้อยข้อมือเส้นใหม่ ไม่อยากถอดก่อนลงเล่น ต้นกล้าควรแนะนำอย่างไร","skill":"decision","points":10,"options":[{"text":"ถอดเก็บไว้ในกระเป๋าก่อนเล่น เพราะอาจเกี่ยวหรือข่วนเพื่อนได้","ok":true},{"text":"ใส่ได้ ถ้าระวังไม่ให้โดนเพื่อน","ok":false,"why":"ในเกมเราควบคุมการปะทะไม่ได้ทั้งหมด จึงควรถอดออก"},{"text":"ห่อด้วยกระดาษแล้วใส่ต่อ","ok":false,"why":"กระดาษหลุดง่าย สร้อยก็ยังเกี่ยวได้"},{"text":"ไม่ต้องลงเล่นเลย","ok":false,"why":"ไม่จำเป็นต้องงดเล่น แค่ถอดสร้อยก่อนก็ปลอดภัยแล้ว"}],"hints":["ทางไหนปลอดภัยและมะปรางยังได้เล่นด้วย"],"solution":["ถอดเครื่องประดับทุกชนิดก่อนเล่นกีฬา เพื่อความปลอดภัยของตัวเองและเพื่อน"],"answer":0}]}', 'medium', 14),
('health_sports', 'วิ่งผลัดส่งไม้', '{"icon":"🏃","story":["ห้อง ป.5/1 ซ้อมวิ่งผลัด 4 คนก่อนวันกีฬาสี","ครูยืนดูที่เขตส่งไม้ และจดสิ่งที่เห็นไว้"],"context":[{"type":"note","text":"ข้อตกลงที่ครูกำหนด: ต้องส่งไม้ผลัดภายในเขตส่งไม้ ต้องยื่นส่งถึงมือ ห้ามโยน ทุกคนต้องวิ่งในลู่ของทีมตัวเอง ถ้าไม้หล่น ผู้ที่ทำหล่นต้องเก็บเอง"},{"type":"table","title":"ลำดับผู้วิ่งทีมเรา","head":["ช่วง","ผู้วิ่ง"],"rows":[["1","ข้าวหอม"],["2","ภูผา"],["3","มะปราง"],["4","ต้นกล้า"]]}],"steps":[{"kind":"multi","prompt":"ข้อใดทำให้ทีมผิดข้อตกลงหรือเสี่ยงอันตราย (เลือกทุกข้อที่ถูก)","skill":"rules","points":10,"options":[{"text":"ส่งไม้หลังจากวิ่งเลยเขตส่งไม้ไปแล้ว","ok":true},{"text":"ผู้รับไม้วิ่งออกนอกลู่ไปขวางทีมอื่น","ok":true},{"text":"โยนไม้ผลัดให้เพื่อนแทนการยื่นส่ง","ok":true},{"text":"ผู้ส่งร้องบอก \"รับ\" ก่อนยื่นไม้","ok":false,"why":"การส่งเสียงบอกช่วยให้จังหวะส่งตรงกัน เป็นเรื่องดี"},{"text":"ผู้รับเริ่มขยับวิ่งเบา ๆ ภายในเขตส่งไม้","ok":false,"why":"ขยับก่อนเพื่อรับไม้ขณะวิ่งได้ ไม่ผิด ถ้าส่งไม้ในเขต"},{"text":"ส่งไม้ถึงมือกันภายในเขตส่งไม้","ok":false,"why":"ถูกต้องตามข้อตกลงที่ครูกำหนด"}],"hints":["อ่านข้อตกลงของครูทีละข้อ แล้วเทียบกับแต่ละตัวเลือก"],"solution":["การส่งไม้ต้องอยู่ในเขต ยื่นถึงมือ และอยู่ในลู่ เพื่อความยุติธรรมและไม่ชนทีมอื่น","การส่งเสียงและเริ่มขยับในเขตเป็นเทคนิคที่ดี ไม่ผิดข้อตกลง"]},{"kind":"choice","prompt":"ภูผาทำไม้ผลัดหล่นในลู่ ระหว่างที่ทีมอื่นยังวิ่งอยู่ ภูผาควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"หยุด มองให้แน่ใจว่าจะไม่ขวางใคร แล้วเก็บไม้ในลู่ของตัวเองวิ่งต่อ","ok":true},{"text":"วิ่งต่อไปโดยไม่เก็บไม้","ok":false,"why":"ต้องถือไม้ผลัดไปส่งให้เพื่อน ถ้าไม่มีไม้ถือว่าส่งไม่สำเร็จ"},{"text":"ให้เพื่อนทีมอื่นที่วิ่งผ่านช่วยเก็บให้","ok":false,"why":"ข้อตกลงให้ผู้ทำหล่นเก็บเอง และจะไปรบกวนทีมอื่น"},{"text":"วิ่งข้ามลู่ไปเก็บไม้ที่กลิ้งไปลู่ข้าง ๆ ทันทีโดยไม่มอง","ok":false,"why":"ข้ามลู่โดยไม่มองอาจชนกับเพื่อนที่กำลังวิ่งมา"}],"hints":["ข้อตกลงบอกว่าใครต้องเก็บไม้","อะไรสำคัญกว่าความเร็ว"],"solution":["ผู้ทำไม้หล่นต้องเก็บเองตา