('health_sports', 'ฟ้าร้องระหว่างซ้อมบอล', '{"icon":"⛈️","story":["หลังเลิกเรียน ทีมฟุตบอลโรงเรียนซ้อมกันที่สนาม ครูผู้ฝึกเดินไปรับโทรศัพท์ที่ห้องพักครูใกล้ ๆ","ท้องฟ้าเริ่มมืดครึ้ม และได้ยินเสียงฟ้าร้อง ภูผาเป็นกัปตันทีม"],"context":[{"type":"note","text":"ข้างสนามมีต้นไม้ใหญ่ อัฒจันทร์กลางแจ้ง และอาคารเรียนห่างไปไม่ไกล"}],"steps":[{"kind":"scene","prompt":"ภูผาควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"ชวนทุกคนหยุดซ้อม เข้าไปหลบในอาคาร และให้เพื่อนคนหนึ่งไปบอกครู","score":1,"result":"ทุกคนปลอดภัยในอาคาร ครูกลับมาชมว่าภูผาตัดสินใจถูก เพราะฟ้าร้องแปลว่าฟ้าผ่าอาจเกิดใกล้ ๆ"},{"text":"หยุดซ้อมแล้วนั่งรอครูบนอัฒจันทร์กลางแจ้ง","score":0.5,"result":"หยุดซ้อมถูกแล้ว แต่อัฒจันทร์กลางแจ้งยังเสี่ยงฟ้าผ่า ครูกลับมาแล้วพาทุกคนเข้าอาคาร"},{"text":"ไปหลบใต้ต้นไม้ใหญ่ข้างสนาม รอให้ฟ้าเงียบ","score":0,"result":"ครูเห็นแล้วรีบเรียกทุกคนเข้าอาคาร และอธิบายว่าต้นไม้สูงกลางแจ้งเป็นจุดที่ฟ้ามีโอกาสผ่าลง"},{"text":"ซ้อมต่อ เพราะฝนยังไม่ตก","score":0,"result":"ไม่นานฟ้าแลบใกล้สนาม ทุกคนตกใจ","then":{"kind":"choice","prompt":"ตอนนี้ฟ้าแลบใกล้มาก ทีมควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"เข้าไปในอาคารที่ใกล้ที่สุดทันที","ok":true},{"text":"วิ่งไปหลบใต้ต้นไม้ใหญ่ริมสนาม","ok":false,"why":"ต้นไม้สูงกลางแจ้งเสี่ยงฟ้าผ่า"},{"text":"ยืนนิ่ง ๆ อยู่กลางสนามรอครู","ok":false,"why":"กลางสนามโล่งเสี่ยงฟ้าผ่า ต้องเข้าอาคาร"}],"hints":["ที่ไหนกันฟ้าผ่าได้ดีที่สุด"],"solution":["เมื่อมีฟ้าแลบฟ้าร้อง ที่ปลอดภัยคือในอาคาร ไม่ใช่ใต้ต้นไม้หรือที่โล่ง"],"answer":0}}],"hints":["ที่ไหนปลอดภัยที่สุดเมื่อได้ยินฟ้าร้อง","ใครควรรู้ว่าทีมทำอะไรอยู่"],"solution":["เมื่อได้ยินฟ้าร้อง ต้องหยุดเล่นกลางแจ้งทันทีและเข้าไปในอาคาร","ต้องบอกครูหรือผู้ใหญ่ให้รู้ด้วย"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องหยุดเล่นทันทีเมื่อได้ยินฟ้าร้อง","skill":"reason","points":10,"options":[{"text":"ได้ยินฟ้าร้องแปลว่าพายุอยู่ใกล้พอที่ฟ้าอาจผ่าลงบริเวณนั้นได้","ok":true},{"text":"เพราะรองเท้าจะเปียกและสกปรก","ok":false,"why":"รองเท้าเปียกเป็นเรื่องเล็ก อันตรายจริงคือฟ้าผ่า"},{"text":"รอให้ฝนตกก่อนค่อยหยุดก็ทัน","ok":false,"why":"ฟ้าผ่าเกิดได้ก่อนฝนตก จึงต้องหยุดตั้งแต่ได้ยินฟ้าร้อง"},{"text":"เพราะลูกฟุตบอลจะเสีย","ok":false,"why":"เหตุผลหลักคือความปลอดภัยของคน ไม่ใช่อุปกรณ์"}],"hints":["ฟ้าร้องกับฟ้าผ่าเกี่ยวข้องกันอย่างไร"],"solution":["ฟ้าร้องเป็นสัญญาณเตือนว่าฟ้าผ่าอาจเกิดใกล้ ๆ แม้ฝนยังไม่ตก ความปลอดภัยต้องมาก่อน"],"answer":0}]}', 'medium', 16),
('health_sports', 'เพื่อนข้อเท้าพลิก', '{"icon":"🩹","story":["ระหว่างเล่นวอลเลย์บอล ใบเฟิร์นกระโดดขึ้นแล้วลงมาเหยียบเท้าเพื่อน ข้อเท้าพลิก","ใบเฟิร์นนั่งกุมข้อเท้า ร้องเจ็บ และลุกเดินไม่ถนัด ครูอยู่อีกฝั่งของโรงยิม"],"context":[],"steps":[{"kind":"scene","prompt":"เพื่อน ๆ ควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"หยุดเกม ให้ใบเฟิร์นนั่งพักอยู่กับที่ แล้วรีบไปบอกครู","score":1,"result":"ครูรีบมาดูอาการ แล้วพาใบเฟิร์นไปห้องพยาบาล ใบเฟิร์นได้รับการดูแลถูกวิธี"},{"text":"ช่วยกันนวดข้อเท้าแรง ๆ ให้หายเร็ว","score":0,"result":"ใบเฟิร์นเจ็บมากขึ้น ครูมาเห็นแล้วบอกว่าไม่ควรนวดจุดที่เพิ่งบาดเจ็บ แล้วพาไปห้องพยาบาล"},{"text":"บอกให้ใบเฟิร์นลุกขึ้นเล่นต่อ เพราะเหลืออีกนิดเดียว","score":0,"result":"ใบเฟิร์นฝืนลุกขึ้น เดินกะเผลก และเจ็บมากขึ้น","then":{"kind":"choice","prompt":"ใบเฟิร์นเจ็บมากขึ้น ตอนนี้ควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"หยุดเล่นทันที ให้นั่งพัก แล้วไปตามครู","ok":true},{"text":"ให้เล่นต่อแต่ยืนอยู่กับที่","ok":false,"why":"ยังต้องลงน้ำหนักที่ข้อเท้า ควรหยุดและให้ครูดู"},{"text":"พยุงใบเฟิร์นเดินกลับบ้านเอง","ok":false,"why":"ต้องให้ครูดูอาการก่อน และครูจะติดต่อผู้ปกครองให้"}],"hints":["ใครควรเป็นคนดูอาการบาดเจ็บ"],"solution":["เมื่อเพื่อนเจ็บ ต้องหยุดเล่นและบอกครูทันที ไม่ฝืนเล่นต่อ"],"answer":0}}],"hints":["ใครควรเป็นคนดูแลอาการบาดเจ็บ","ถ้าฝืนใช้ข้อเท้าที่เจ็บ จะเกิดอะไรขึ้น"],"solution":["เมื่อมีคนบาดเจ็บ ให้หยุดเล่น ให้ผู้บาดเจ็บพักอยู่กับที่ และบอกครูทันที","ไม่ควรรักษาเองหรือให้ฝืนเล่นต่อ"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่เพื่อน ๆ ไม่ควรรักษาข้อเท้าใบเฟิร์นเอง","skill":"reason","points":10,"options":[{"text":"ครูหรือผู้ใหญ่ประเมินอาการและดูแลได้ถูกวิธี ถ้าเราทำผิดวิธีอาจเจ็บมากขึ้น","ok":true},{"text":"เพราะจะเสียเวลาเล่น","ok":false,"why":"เหตุผลหลักคือความปลอดภัยของเพื่อน ไม่ใช่เวลาเล่น"},{"text":"เพราะใบเฟิร์นไม่ใช่เพื่อนสนิท","ok":false,"why":"ไม่ว่าใครเจ็บก็ต้องได้รับการดูแลที่ถูกวิธีเหมือนกัน"},{"text":"เพราะข้อเท้าพลิกหายเองได้ทุกครั้ง","ok":false,"why":"บางครั้งอาการรุนแรงกว่าที่เห็น ต้องให้ผู้ใหญ่ดู"}],"hints":["ใครรู้วิธีดูแลการบาดเจ็บมากกว่ากัน"],"solution":["การบาดเจ็บระหว่างเล่นกีฬาควรให้ครูหรือผู้ใหญ่ดูแล เพราะการช่วยที่ผิดวิธีอาจทำให้อาการแย่ลง"],"answer":0},{"kind":"choice","prompt":"ก่อนเล่นครั้งหน้า ข้อใดช่วยลดโอกาสข้อเท้าพลิกได้ดีที่สุด","skill":"planning","points":10,"options":[{"text":"อบอุ่นร่างกาย หมุนข้อเท้า และเล่นบนพื้นเรียบที่ไม่มีของเกะกะ","ok":true},{"text":"เล่นด้วยถุงเท้าอย่างเดียวจะได้เบา","ok":false,"why":"ถุงเท้าลื่น และไม่รองรับเท้า ควรใส่รองเท้ากีฬา"},{"text":"กระโดดให้สูงที่สุดทุกครั้ง","ok":false,"why":"กระโดดสูงโดยไม่ระวังจุดลงยิ่งเสี่ยงลงไปเหยียบเท้าเพื่อน"},{"text":"ไม่ต้องอบอุ่นร่างกายถ้าเคยเล่นมาแล้ว","ok":false,"why":"ต้องอบอุ่นร่างกายทุกครั้งก่อนเล่น"}],"hints":["คิดถึงร่างกาย รองเท้า และพื้นสนาม"],"solution":["การอบอุ่นข้อเท้าและการเลือกพื้นที่เล่นที่ปลอดภัยช่วยป้องกันข้อเท้าพลิก"],"answer":0}]}', 'medium', 17),
('health_sports', 'อบอุ่นให้ตรงกับกีฬา', '{"icon":"🤸","story":["วันพุธมีกีฬา 3 ชนิดในคาบชมรม: วอลเลย์บอล ว่ายน้ำ และกระโดดเชือก","ภูผาเป็นผู้ช่วยครู ต้องเลือกท่าอบอุ่นร่างกายให้เหมาะกับแต่ละกีฬา"],"context":[{"type":"table","title":"ส่วนของร่างกายที่ใช้มาก","head":["กีฬา","ใช้มาก"],"rows":[["วอลเลย์บอล","ข้อมือ แขน ไหล่ และขาตอนกระโดด"],["ว่ายน้ำ","แขน ไหล่ และขาตอนเตะน้ำ"],["กระโดดเชือก","ข้อเท้า น่อง และเข่า"]]}],"steps":[{"kind":"plan","prompt":"เลือกการอบอุ่นร่างกายที่เหมาะสมที่สุดของแต่ละกีฬา","skill":"planning","points":10,"fields":[{"id":"f1","label":"วอลเลย์บอล","options":[{"text":"หมุนข้อมือ ข้อไหล่ แล้วเล่นลูกสองมือล่างกับเพื่อนเบา ๆ","ok":true},{"text":"เตะลูกฟุตบอลส่งไปมา","ok":false,"why":"วอลเลย์บอลใช้แขนและข้อมือเป็นหลัก ไม่ได้ใช้การเตะ"},{"text":"วิ่งเร็วเต็มแรงทันที","ok":false,"why":"ควรเริ่มเบา ๆ และเตรียมแขน ไหล่ ข้อมือ"}],"answer":0},{"id":"f2","label":"ว่ายน้ำ","options":[{"text":"หมุนแขน หมุนไหล่ ยืดขาบนบก แล้วค่อย ๆ ลงน้ำทางบันได","ok":true},{"text":"กระโดดพุ่งหัวลงน้ำทันทีเพื่อให้ตัวอุ่น","ok":false,"why":"ไม่ได้เตรียมกล้ามเนื้อ และพุ่งหัวลงน้ำอาจกระแทกพื้นสระ"},{"text":"เลี้ยงลูกบาสรอบขอบสระ","ok":false,"why":"ไม่ตรงกับการว่ายน้ำ และขอบสระลื่น"}],"answer":0},{"id":"f3","label":"กระโดดเชือก","options":[{"text":"กระโดดเบา ๆ อยู่กับที่ หมุนข้อเท้า และยืดน่อง","ok":true},{"text":"หมุนข้อมืออย่างเดียว","ok":false,"why":"กระโดดเชือกใช้ข้อเท้า น่อง และเข่ามาก ต้องเตรียมขาด้วย"},{"text":"กระโดดเชือกเร็วที่สุดทันที 1 นาที","ok":false,"why":"เริ่มหนักทันทีโดยไม่อบอุ่นเสี่ยงบาดเจ็บ"}],"answer":0}],"hints":["ดูตารางว่าแต่ละกีฬาใช้ร่างกายส่วนไหนมาก"],"solution":["ท่าอบอุ่นร่างกายควรเตรียมส่วนที่จะใช้มากที่สุดในกีฬานั้น","ทุกกีฬาควรเริ่มจากเบาไปหนัก"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่การอบอุ่นร่างกายควรต่างกันตามชนิดกีฬา","skill":"reason","points":10,"options":[{"text":"แต่ละกีฬาใช้กล้ามเนื้อและข้อต่อต่างกัน จึงควรเตรียมส่วนที่จะใช้มากที่สุด","ok":true},{"text":"จะได้ไม่เบื่อท่าเดิม ๆ","ok":false,"why":"ความสนุกเป็นผลพลอยได้ เหตุผลหลักคือการเตรียมร่างกายส่วนที่ใช้"},{"text":"กีฬาบางชนิดไม่ต้องอบอุ่นร่างกาย","ok":false,"why":"ทุกกีฬาควรอบอุ่นร่างกายก่อน"},{"text":"เพื่อให้เหนื่อยก่อนเริ่มเล่นจริง","ok":false,"why":"การอบอุ่นร่างกายเพื่อให้พร้อม ไม่ใช่ให้เหนื่อย"}],"hints":["เทียบส่วนที่ใช้มากของแต่ละกีฬาในตาราง"],"solution":["การอบอุ่นร่างกายที่ตรงกับกีฬาช่วยให้กล้ามเนื้อและข้อต่อที่จะใช้จริงพร้อม จึงลดการบาดเจ็บได้ดีกว่า"],"answer":0}]}', 'medium', 18),
('health_sports', 'ป้องกันในเกมบาส', '{"icon":"🛡️","story":["มะปรางต้องประกบผู้เล่นทีมตรงข้ามที่เลี้ยงลูกเก่ง","ครูบอกว่า \"ป้องกันให้ดี ต้องเคลื่อนที่ถูกวิธีและไม่ฟาวล์\""],"context":[{"type":"table","title":"สิ่งที่คู่แข่งทำ","head":["จังหวะ","คู่แข่งทำอะไร"],"rows":[["1","เลี้ยงลูกเปลี่ยนทิศไปซ้ายและขวาสลับกัน"],["2","หยุดเลี้ยงลูก ถือลูกไว้สองมือ มองหาเพื่อน"]]}],"steps":[{"kind":"choice","prompt":"จังหวะที่ 1 มะปรางควรเคลื่อนที่อย่างไร","skill":"decision","points":10,"options":[{"text":"ย่อเข่า สไลด์เท้าไปด้านข้าง โดยหันหน้าหาคู่แข่งตลอด","ok":true},{"text":"ไขว้เท้าวิ่งไปด้านข้าง","ok":false,"why":"เท้าไขว้กันทำให้เสียหลัก และเปลี่ยนทิศได้ช้า"},{"text":"ยืนตัวตรง ขาชิดกัน","ok":false,"why":"ยืนตัวตรงขาชิดจะออกตัวช้า คู่แข่งผ่านไปง่าย"},{"text":"วิ่งหันหลังไปดักที่ใต้แป้น","ok":false,"why":"หันหลังจะมองไม่เห็นคู่แข่ง และปล่อยให้เลี้ยงลูกได้สบาย"}],"hints":["ท่าไหนเคลื่อนไปด้านข้างได้เร็วและยังมองเห็นคู่แข่ง"],"solution":["การสไลด์เท้าทำให้เคลื่อนที่ด้านข้างได้เร็ว ทรงตัวดี และหันหน้าหาคู่แข่งตลอด"],"answer":0},{"kind":"choice","prompt":"จังหวะที่ 2 คู่แข่งหยุดเลี้ยงและถือลูกไว้ มะปรางควรทำอย่างไร","skill":"rules","points":10,"options":[{"text":"ยกมือขึ้นบังทางส่ง โดยไม่ตีแขนหรือดึงตัวคู่แข่ง","ok":true},{"text":"ตีที่แขนคู่แข่งให้ลูกหลุด","ok":false,"why":"ตีแขนเป็นฟาวล์ และอาจทำให้เพื่อนเจ็บ"},{"text":"ดึงเสื้อคู่แข่งไว้ไม่ให้ขยับ","ok":false,"why":"ดึงเสื้อเป็นฟาวล์ และไม่มีน้ำใจนักกีฬา"},{"text":"ถอยไปยืนห่าง ๆ ปล่อยให้ส่งสบาย","ok":false,"why":"ถอยห่างทำให้คู่แข่งส่งลูกได้ง่าย ควรยกมือบังทางส่ง"}],"hints":["คู่แข่งที่หยุดเลี้ยงแล้ว ทำอะไรต่อได้บ้าง","ป้องกันแบบไหนไม่ฟาวล์"],"solution":["เมื่อคู่แข่งหยุดเลี้ยงแล้ว จะเลี้ยงต่อไม่ได้ ต้องส่งหรือยิง","ผู้ป้องกันควรยกมือบังทางส่งโดยไม่สัมผัสตัวคู่แข่ง"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ผู้ป้องกันต้องย่อเข่าไว้ตลอด","skill":"reason","points":10,"options":[{"text":"ทรงตัวได้มั่นคง และพร้อมขยับไปทุกทิศได้เร็ว","ok":true},{"text":"ทำให้ตัวเตี้ยลง คู่แข่งจะมองไม่เห็น","ok":false,"why":"ย่อเข่าไม่ได้ทำให้คู่แข่งมองไม่เห็น ประโยชน์คือการทรงตัว"},{"text":"เป็นท่าบังคับตามกติกา","ok":false,"why":"กติกาไม่ได้บังคับท่ายืน แต่ย่อเข่าช่วยให้เคลื่อนที่ดีขึ้น"},{"text":"ช่วยให้ไม่เหนื่อยเลย","ok":false,"why":"ย่อเข่าก็ยังใช้แรง ข้อดีคือความพร้อมในการเคลื่อนที่"}],"hints":["นึกถึงตอนยืนตัวตรงแล้วต้องรีบออกตัว"],"solution":["การย่อเข่าทำให้จุดศูนย์ถ่วงต่ำ ทรงตัวดี และออกตัวได้เร็วทุกทิศทาง"],"answer":0}]}', 'medium', 19),
('health_sports', 'คลายอุ่นหลังวิ่งรอบสนาม', '{"icon":"🌬️","story":["ครูให้ ป.5 วิ่งรอบสนาม 2 รอบเพื่อทดสอบความอดทน","มะปรางวิ่งเข้าเส้นชัย เหนื่อยมาก หายใจแรง และอยากนั่งลงทันที"],"context":[],"steps":[{"kind":"order","prompt":"เรียงลำดับการคลายอุ่นหลังวิ่งให้ถูกต้อง","skill":"planning","points":10,"items":["วิ่งผ่านเส้นชัยแล้วค่อย ๆ ลดความเร็วลง","วิ่งเหยาะช้า ๆ","เดินจนหายใจสบายขึ้น","ยืดเหยียดกล้ามเนื้อต้นขาและน่องค้างไว้ช้า ๆ"],"hints":["การคลายอุ่นคือการเปลี่ยนจากเร็วไปช้า"],"solution":["ลดความหนักลงทีละขั้น จากวิ่ง เป็นวิ่งเหยาะ เป็นเดิน","ยืดเหยียดเมื่อหายใจสบายขึ้นแล้ว เพื่อลดอาการตึงของกล้ามเนื้อ"]},{"kind":"choice","prompt":"มะปรางอยากนั่งลงทันทีที่ผ่านเส้นชัย ควรแนะนำอย่างไร","skill":"decision","points":10,"options":[{"text":"ค่อย ๆ เดินต่ออีกสักพักก่อน ถ้ารู้สึกไม่ไหวหรือหน้ามืดให้บอกครูทันที","ok":true},{"text":"นอนราบลงกลางลู่วิ่งเลย","ok":false,"why":"หยุดทันทีอาจหน้ามืด และนอนกลางลู่อาจถูกคนอื่นวิ่งชน"},{"text":"ดื่มน้ำเย็นจัดให้มาก ๆ ในครั้งเดียว","ok":false,"why":"ควรจิบน้ำเปล่าทีละน้อย ไม่ดื่มรวดเดียวมาก ๆ"},{"text":"วิ่งต่ออีกรอบให้ร่างกายชิน","ok":false,"why":"หลังวิ่งหนัก ควรลดความหนัก ไม่ใช่เพิ่ม"}],"hints":["ร่างกายควรค่อย ๆ ช้าลง และถ้ามีอาการผิดปกติต้องบอกใคร"],"solution":["การค่อย ๆ เดินช่วยให้หัวใจและการหายใจกลับสู่ปกติอย่างปลอดภัย","ถ้ามีอาการผิดปกติ ต้องบอกครูทันที"],"answer":0}]}', 'medium', 20),
('health_sports', 'นัดชิงฟุตบอลกลางแดด', '{"icon":"🏆","story":["รอบชิงชนะเลิศฟุตบอลกีฬาสี ทีมสีฟ้าของภูผาตามหลัง 0–1 กำลังจะเริ่มครึ่งหลัง","อากาศร้อนมาก ภูผาเป็นกัปตัน ต้องวางแผนครึ่งหลังให้ถูกกติกา ปลอดภัย และยุติธรรม"],"context":[{"type":"note","text":"ประกาศจากครู: บ่ายนี้อากาศร้อนจัด ทุกทีมต้องดื่มน้ำเมื่อพักเกม ถ้าใครมึนหัว หน้าแดง หรือคลื่นไส้ ให้ออกจากสนามและแจ้งครูทันที"},{"type":"note","text":"กติกาฟุตบอลกีฬาสีของโรงเรียน: ลงสนามทีมละ 7 คน เปลี่ยนตัวได้ไม่จำกัดเมื่อเกมหยุด ทุกคนในทีมต้องได้ลงเล่น และมีพักดื่มน้ำกลางครึ่งหลัง"},{"type":"table","title":"สถานะผู้เล่นทีมสีฟ้า","head":["ผู้เล่น","ได้ลงเล่นแล้ว","สภาพตอนนี้"],"rows":[["ภูผา (กัปตัน)","ครึ่งแรก","เหนื่อยแต่ไหว"],["ต้นกล้า","ครึ่งแรก","บอกว่ามึนหัว หน้าแดง"],["มะปราง","ครึ่งแรก","สดชื่น"],["ปลื้ม (สำรอง)","ยังไม่ได้ลง","อบอุ่นร่างกายแล้ว"],["ข้าวหอม (สำรอง)","ยังไม่ได้ลง","ยังไม่ได้อบอุ่นร่างกาย"]]}],"steps":[{"kind":"multi","prompt":"จากข้อมูลทั้งหมด ข้อใดเป็นปัญหาที่ทีมต้องจัดการก่อนเริ่มครึ่งหลัง (เลือกทุกข้อที่ถูก)","skill":"analysis","points":10,"options":[{"text":"ต้นกล้ามึนหัวและหน้าแดงในวันที่อากาศร้อนจัด","ok":true},{"text":"ปลื้มและข้าวหอมยังไม่ได้ลงเล่น แต่กติกาให้ทุกคนได้ลง","ok":true},{"text":"ข้าวหอมยังไม่ได้อบอุ่นร่างกาย","ok":true},{"text":"มะปรางยังสดชื่นอยู่","ok":false,"why":"เป็นข้อดีของทีม ไม่ใช่ปัญหา"},{"text":"ปลื้มอบอุ่นร่างกายแล้ว","ok":false,"why":"แปลว่าปลื้มพร้อมลงเล่น ไม่ใช่ปัญหา"}],"hints":["อ่านประกาศและกติกา แล้วไล่ดูตารางทีละแถว","อะไรขัดกับกติกาหรือความปลอดภัย"],"solution":["อาการของต้นกล้าตรงกับประกาศของครูที่ต้องให้ออกจากสนาม","ผู้เล่นสำรองทั้งสองคนต้องได้ลงเล่นตามกติกา และคนที่ยังไม่อบอุ่นร่างกายต้องเตรียมตัวก่อน"]},{"kind":"plan","prompt":"วางแผนผู้เล่นสำหรับครึ่งหลัง","skill":"planning","points":10,"fields":[{"id":"f1","label":"ต้นกล้า","options":[{"text":"ออกจากสนาม พักในร่ม และแจ้งครูทันที","ok":true},{"text":"เล่นต่อแต่ไปเป็นผู้รักษาประตูเพราะไม่ต้องวิ่งมาก","ok":false,"why":"ประกาศของครูให้ออกจากสนามเมื่อมึนหัว ไม่ว่าจะเล่นตำแหน่งใด"},{"text":"ดื่มน้ำแล้วกลับลงเล่นต่อทันที","ok":false,"why":"ต้องพักในร่มและให้ครูดูอาการก่อน"}],"answer":0},{"id":"f2","label":"ผู้ที่ลงแทนต้นกล้าตอนเริ่มครึ่งหลัง","options":[{"text":"ปลื้ม","ok":true},{"text":"ข้าวหอม","ok":false,"why":"ข้าวหอมยังไม่ได้อบอุ่นร่างกาย ลงเล่นทันทีเสี่ยงบาดเจ็บ"},{"text":"ไม่ต้องเปลี่ยนตัว เล่น 6 คน","ok":false,"why":"มีสำรองที่พร้อมอยู่ และสำรองทุกคนต้องได้ลงเล่นตามกติกา"}],"answer":0},{"id":"f3","label":"ข้าวหอม","options":[{"text":"อบอุ่นร่างกายข้างสนาม แล้วลงแทนเพื่อนที่เหนื่อยตอนพักดื่มน้ำ","ok":true},{"text":"นั่งดูจนจบเกม เพราะทีมกำลังตามหลัง","ok":false,"why":"ผิดกติกาที่ทุกคนต้องได้ลงเล่น และไม่ยุติธรรมกับข้าวหอม"},{"text":"วิ่งลงสนามไปช่วยทันทีโดยไม่เปลี่ยนตัว","ok":false,"why":"ทีมจะมีผู้เล่นเกิน 7 คน ผิดกติกา และยังไม่ได้อบอุ่นร่างกาย"}],"answer":0}],"hints":["ใครพร้อมลงทันที ใครต้องเตรียมตัวก่อน","เกมหยุดตอนไหนบ้างในครึ่งหลังที่เปลี่ยนตัวได้"],"solution":["ต้นกล้าต้องพักตามประกาศของครู","ปลื้มอบอุ่นแล้วจึงลงได้ทันที ส่วนข้าวหอมอบอุ่นก่อนแล้วลงตอนพักดื่มน้ำ ทุกคนจึงได้เล่นตามกติกา"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องให้ต้นกล้าออกจากสนาม แม้ทีมกำลังตามหลัง","skill":"reason","points":10,"options":[{"text":"อาการมึนหัวหน้าแดงในวันร้อนจัดเป็นสัญญาณว่าร่างกายร้อนเกินไป ความปลอดภัยสำคัญกว่าผลแพ้ชนะ","ok":true},{"text":"เพราะต้นกล้าเล่นไม่เก่ง","ok":false,"why":"ไม่มีข้อมูลว่าต้นกล้าเล่นไม่เก่ง เหตุผลคืออาการผิดปกติ"},{"text":"เพื่อให้ทีมได้ผู้เล่นที่สดชื่นมายิงประตู","ok":false,"why":"นั่นเป็นผลดีที่ตามมา แต่เหตุผลหลักคือความปลอดภัยของต้นกล้า"},{"text":"เพราะกติกาบังคับให้เปลี่ยนตัวทุกครึ่ง","ok":false,"why":"กติกาให้เปลี่ยนตัวได้ ไม่ได้บังคับ เหตุผลจริงคืออาการของต้นกล้า"}],"hints":["เหตุผลหลักต้องเกี่ยวกับสุขภาพของต้นกล้าเอง"],"solution":["ในวันอากาศร้อนจัด อาการมึนหัว หน้าแดง หรือคลื่นไส้ ต้องหยุดเล่นและแจ้งครูทันที","นักกีฬาที่ดีเลือกความปลอดภัยของเพื่อนก่อนผลการแข่งขัน"],"answer":0}]}', 'hard', 21),
('health_sports', 'แชร์บอลนาทีสุดท้าย', '{"icon":"🪑","story":["แชร์บอลรอบรองชนะเลิศ ทีมของมะปรางตามหลัง 4–5 เหลือเวลา 1 นาที และทีมเราได้ครองลูก","ภูผาเพิ่งชนกับคู่แข่ง บอกว่าเจ็บไหล่ ครูให้ภูผาพักข้างสนาม และให้มิวลงแทน"],"context":[{"type":"note","text":"กติกาที่ครูใช้: ห้ามถือลูกวิ่ง ห้ามแย่งลูกจากมือคู่แข่ง ห้ามผลักหรือดึงตัว ทีมได้คะแนนเมื่อผู้รับบนเก้าอี้รับลูกได้"},{"type":"table","title":"ตำแหน่งตอนนี้","head":["ผู้เล่น","ตำแหน่ง","คู่แข่งประกบ","หมายเหตุ"],"rows":[["มะปราง (ถือลูก)","กลางสนาม","1 คน","ส่งลูกแม่น"],["มิว","ใกล้เก้าอี้ ฝั่งขวา","ไม่มี","เพิ่งลงสนาม อบอุ่นร่างกายแล้ว"],["ใบเฟิร์น","ใกล้เก้าอี้ ฝั่งซ้าย","2 คน","สูงที่สุดในทีม"],["ต้นกล้า","มุมสนามด้านหลัง","ไม่มี","อยู่ไกลเก้าอี้"],["ข้าวหอม (ผู้รับบนเก้าอี้)","บนเก้าอี้","ผู้ป้องกัน 1 คน","ยืนบังด้านซ้าย ด้านขวาโล่ง"]]}],"steps":[{"kind":"choice","prompt":"มะปรางควรส่งลูกให้ใคร จึงมีโอกาสทำคะแนนดีที่สุด","skill":"analysis","points":10,"options":[{"text":"มิว","ok":true},{"text":"ใบเฟิร์น","ok":false,"why":"ใบเฟิร์นสูงก็จริง แต่ถูกประกบ 2 คน ลูกถูกตัดง่าย"},{"text":"ต้นกล้า","ok":false,"why":"ต้นกล้าว่างแต่ไกลเก้าอี้ ต้องส่งต่ออีกหลายทอดในเวลาที่เหลือแค่ 1 นาที"},{"text":"ข้าวหอมบนเก้าอี้โดยตรง","ok":false,"why":"ระยะไกลจากกลางสนาม และมีผู้ป้องกันอยู่ ลูกถูกตัดง่าย"}],"hints":["ใครทั้งว่าง และอยู่ใกล้เก้าอี้"],"solution":["มิวไม่มีคู่แข่งประกบและอยู่ใกล้เก้าอี้ จึงเป็นทางส่งที่ปลอดภัยและใกล้เป้าหมายที่สุด"],"answer":0},{"kind":"plan","prompt":"วางแผนจังหวะทำคะแนนให้ครบทุกคน","skill":"planning","points":10,"fields":[{"id":"f1","label":"มิวส่งต่อให้ข้าวหอมทางใด","options":[{"text":"ส่งไปทางขวาของข้าวหอม ด้านที่ไม่มีผู้ป้องกันบัง","ok":true},{"text":"ส่งไปทางซ้ายของข้าวหอม","ok":false,"why":"ผู้ป้องกันยืนบังด้านซ้ายอยู่"},{"text":"ถือลูกวิ่งเข้าไปใกล้เก้าอี้ก่อนส่ง","ok":false,"why":"ห้ามถือลูกวิ่ง"}],"answer":0},{"id":"f2","label":"ใบเฟิร์นช่วยทีมอย่างไร","options":[{"text":"เคลื่อนที่ไปอีกทาง ดึงผู้ประกบให้ตามไป เปิดพื้นที่ให้มิว","ok":true},{"text":"ผลักผู้ประกบออกไปเพื่อให้ตัวเองว่าง","ok":false,"why":"ผิดกติกาและอาจทำให้เพื่อนเจ็บ"},{"text":"ยืนนิ่งรอให้คนส่งลูกมาให้","ok":false,"why":"ยืนนิ่งขณะถูกประกบ 2 คน ไม่ได้ช่วยเปิดทาง"}],"answer":0},{"id":"f3","label":"ภูผา","options":[{"text":"พักข้างสนามตามที่ครูบอก และเชียร์เพื่อน","ok":true},{"text":"ขอกลับลงไปเล่น เพราะเหลือแค่ 1 นาที","ok":false,"why":"ภูผาเจ็บไหล่และครูให้พักแล้ว ฝืนเล่นอาจเจ็บมากขึ้น"},{"text":"ยืนตะโกนแนะนำอยู่ในเขตสนาม","ok":false,"why":"อยู่ในสนามจะขวางการเล่น และเสี่ยงโดนชนซ้ำ"}],"answer":0}],"hints":["ดูช่องหมายเหตุของข้าวหอม","ผู้เล่นที่ไม่ได้ถือลูกช่วยทีมได้อย่างไรโดยไม่ผิดกติกา"],"solution":["ส่งลูกไปด้านที่โล่งของผู้รับ","การเคลื่อนที่ดึงคู่แข่งเป็นการช่วยทีมที่ถูกกติกา","ผู้เล่นที่เจ็บต้องพักตามคำแนะนำของครู"]},{"kind":"choice","prompt":"มิวส่งลูกแล้ว แต่ผู้ป้องกันปัดลูกได้ทัน เกมจบ ทีมแพ้ 4–5 ทีมควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"จับมือแสดงความยินดีกับคู่แข่ง แล้วคุยกันว่าครั้งหน้าจะปรับอะไร","ok":true},{"text":"โทษมิวว่าทำให้ทีมแพ้","ok":false,"why":"มิวทำตามแผนของทีม แพ้หรือชนะเป็นของทั้งทีม"},{"text":"ขอให้ครูเริ่มนับเวลาใหม่","ok":false,"why":"ต้องยอมรับผลการแข่งขันตามกติกา"},{"text":"เดินออกจากสนามโดยไม่ไหว้หรือจับมือใคร","ok":false,"why":"ไม่แสดงน้ำใจนักกีฬา"}],"hints":["นักกีฬาที่ดีทำอย่างไรเมื่อแพ้"],"solution":["การยอมรับผลและให้เกียรติคู่แข่งคือน้ำใจนักกีฬา","การทบทวนร่วมกันช่วยให้ทีมพัฒนา โดยไม่โทษกัน"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่แผนนี้เป็นแผนที่ดี แม้สุดท้ายจะแพ้","skill":"reason","points":10,"options":[{"text":"ใช้เพื่อนที่ว่างและใกล้เป้าหมาย ทำตามกติกา และไม่ให้คนที่เจ็บฝืนเล่น","ok":true},{"text":"เป็นแผนที่ชนะได้แน่นอนทุกครั้ง","ok":false,"why":"ไม่มีแผนไหนรับประกันชัยชนะ แผนที่ดีคือเพิ่มโอกาสอย่างปลอดภัยและถูกกติกา"},{"text":"ให้คนที่สูงที่สุดได้จับลูกมากที่สุด","ok":false,"why":"แผนนี้ไม่ได้ส่งให้ใบเฟิร์น เพราะใบเฟิร์นถูกประกบ"},{"text":"ภูผาได้พักจะได้ไม่ต้องรับผิดชอบถ้าแพ้","ok":false,"why":"ภูผาพักเพราะเจ็บ ไม่ใช่เพื่อหนีความรับผิดชอบ"}],"hints":["ลองเทียบแผนกับเงื่อนไข 3 อย่าง: การวิเคราะห์สนา