('health_sports', 'วอลเลย์บอลแต้มตัดสิน', '{"icon":"🏐","story":["แข่งวอลเลย์บอลระหว่างห้อง ทีมของใบเฟิร์นเสมอกับคู่แข่ง เหลืออีกไม่กี่แต้มจะจบเซต","ภูผาบอกเพื่อนว่านิ้วเจ็บตั้งแต่รับลูกเมื่อสักครู่ แต่ยังฝืนเล่นอยู่ในแต้มนี้"],"context":[{"type":"note","text":"กติกาที่ใช้ในการแข่งของห้อง: ทีมสัมผัสลูกได้ไม่เกิน 3 ครั้ง ผู้เล่นคนเดียวห้ามสัมผัสลูกติดกัน 2 ครั้ง ห้ามจับหรือถือลูก เปลี่ยนตัวได้เมื่อจบแต้มและครูอนุญาต และทุกคนในรายชื่อควรได้ลงเล่น"},{"type":"table","title":"จังหวะที่กำลังเล่น (ลูกยังอยู่ฝั่งเรา)","head":["ครั้งที่","ผู้เล่น","ทำอะไร","ลูกไปทางไหน"],"rows":[["1","มะปราง","เล่นลูกสองมือล่างรับลูกเสิร์ฟ","ลอยไปหาใบเฟิร์น"],["2","ใบเฟิร์น","เซตลูกด้วยสองมือบน","ลอยสูงใกล้ตาข่ายฝั่งต้นกล้า"]]},{"type":"table","title":"ผู้เล่นสำรอง","head":["ชื่อ","ได้ลงเล่นแล้ว","สภาพ"],"rows":[["ปลื้ม","1 เซต","อบอุ่นร่างกายแล้ว"],["น้ำฝน","ยังไม่ได้ลง","อบอุ่นร่างกายแล้ว"]]}],"steps":[{"kind":"choice","prompt":"ลูกครั้งต่อไปควรเป็นอย่างไร","skill":"rules","points":10,"options":[{"text":"ต้นกล้าตบหรือส่งลูกข้ามตาข่าย","ok":true},{"text":"ใบเฟิร์นเล่นลูกต่ออีกครั้งเพราะเซตได้ดี","ok":false,"why":"ใบเฟิร์นเพิ่งสัมผัสลูก จะสัมผัสติดกันอีกไม่ได้"},{"text":"ต้นกล้าเซตลูกให้มะปรางตบ","ok":false,"why":"นี่คือครั้งที่ 3 แล้ว ถ้าส่งให้เพื่อนอีกจะเป็นครั้งที่ 4 ผิดกติกา"},{"text":"ต้นกล้าจับลูกแล้วโยนข้ามตาข่าย","ok":false,"why":"ห้ามจับหรือถือลูก"}],"hints":["ทีมสัมผัสลูกไปแล้วกี่ครั้ง ใครสัมผัสล่าสุด"],"solution":["ทีมสัมผัสไปแล้ว 2 ครั้ง ครั้งที่ 3 ต้องส่งข้ามตาข่าย และต้องไม่ใช่ใบเฟิร์นที่เพิ่งสัมผัส","ลูกลอยไปฝั่งต้นกล้า ต้นกล้าจึงเหมาะที่จะเล่นลูกนี้"],"answer":0},{"kind":"plan","prompt":"แต้มนี้จบแล้ว ครูให้ทีมตัดสินใจเรื่องภูผา","skill":"planning","points":10,"fields":[{"id":"f1","label":"ภูผา","options":[{"text":"ออกมาพัก และให้ครูดูนิ้วที่เจ็บ","ok":true},{"text":"เล่นต่อแต่ไม่ใช้นิ้วที่เจ็บ","ok":false,"why":"วอลเลย์บอลต้องใช้มือทั้งสองข้าง ฝืนเล่นอาจเจ็บมากขึ้น ควรให้ครูดูก่อน"},{"text":"พันนิ้วเองแล้วเล่นต่อ","ok":false,"why":"ไม่ควรรักษาเองแล้วฝืนเล่น ต้องให้ครูดูอาการ"}],"answer":0},{"id":"f2","label":"ผู้ที่ลงแทนภูผา","options":[{"text":"น้ำฝน","ok":true},{"text":"ปลื้ม","ok":false,"why":"ปลื้มพร้อมก็จริง แต่ได้ลงแล้ว 1 เซต น้ำฝนยังไม่ได้ลงเลย ให้น้ำฝนลงจึงยุติธรรมกว่า"},{"text":"ไม่ต้องเปลี่ยนตัว เล่น 5 คน","ok":false,"why":"มีสำรองที่พร้อมอยู่ และทุกคนในรายชื่อควรได้ลงเล่น"}],"answer":0}],"hints":["สำรองทั้งสองคนพร้อมเหมือนกัน ข้อมูลไหนในตารางที่ต่างกัน"],"solution":["ผู้เล่นที่เจ็บต้องพักและให้ครูดูแล","เมื่อสำรองพร้อมพอ ๆ กัน ให้คนที่ยังไม่ได้ลงเล่นได้ลงก่อน ตามกติกาที่ทุกคนควรได้เล่น"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ทีมเลือกแบบนี้ แม้กำลังจะจบเซตและแต้มสูสี","skill":"reason","points":10,"options":[{"text":"ทำตามกติกา ดูแลเพื่อนที่เจ็บ และให้ทุกคนได้เล่นอย่างยุติธรรม แม้คะแนนจะสูสี","ok":true},{"text":"เพราะน้ำฝนเล่นเก่งกว่าภูผา","ok":false,"why":"ไม่มีข้อมูลว่าใครเก่งกว่า เหตุผลคือภูผาเจ็บและน้ำฝนยังไม่ได้ลง"},{"text":"เพราะครูจะดุถ้าไม่เปลี่ยนตัว","ok":false,"why":"เราทำเพื่อความปลอดภัยและความยุติธรรม ไม่ใช่เพราะกลัวถูกดุ"},{"text":"เพราะทีมยอมแพ้เซตนี้แล้ว","ok":false,"why":"ทีมยังเล่นเต็มที่ แค่เลือกวิธีที่ปลอดภัยและยุติธรรม"}],"hints":["แผนนี้ตอบเงื่อนไขอะไรบ้าง"],"solution":["การตัดสินใจที่ดีในกีฬาต้องคิดถึงกติกา ความปลอดภัย และความยุติธรรมไปพร้อมกัน ไม่ใช่แค่คะแนน"],"answer":0}]}', 'hard', 23),
('health_sports', 'จัดทีมวิ่งผลัดกีฬาสี', '{"icon":"🥇","story":["ห้อง ป.5/2 ต้องส่งทีมวิ่งผลัด 4 คนแข่งกีฬาสี มีนักเรียนอยากวิ่ง 5 คน","ครูให้ทีมวางแผนเอง โดยต้องทำตามข้อมูลการซ้อมและคำแนะนำของครู"],"context":[{"type":"table","title":"ข้อมูลจากการซ้อม","head":["ชื่อ","จุดเด่น","หมายเหตุ"],"rows":[["ภูผา","ออกตัวเร็วที่สุดเมื่อได้ยินสัญญาณ","-"],["มะปราง","วิ่งช่วงท้ายได้เร็ว ไม่ค่อยหมดแรง","-"],["ต้นกล้า","รับและส่งไม้ผลัดคล่องมาก","-"],["ข้าวหอม","วิ่งสม่ำเสมอ รับไม้ได้ดี","-"],["ใบเฟิร์น","วิ่งเร็วพอ ๆ กับต้นกล้า","ข้อเท้าเพิ่งหายเจ็บ ครูให้งดวิ่งเร็วสัปดาห์นี้"]]},{"type":"note","text":"ไม้ที่ 1 ออกตัวจากจุดปล่อยตัวและส่งไม้อย่างเดียว ไม้ที่ 4 รับไม้แล้ววิ่งเข้าเส้นชัย ไม้ที่ 2 และ 3 ต้องทั้งรับและส่งไม้"},{"type":"note","text":"ข้อตกลงของห้อง: คนที่ไม่ได้วิ่งจะเป็นผู้ช่วยครูดูเขตส่งไม้ และทุกคนต้องทำตามคำแนะนำของครูเรื่องสุขภาพ"}],"steps":[{"kind":"choice","prompt":"ใครไม่ควรอยู่ในทีมวิ่ง 4 คนวันนี้","skill":"analysis","points":10,"options":[{"text":"ใบเฟิร์น","ok":true},{"text":"ข้าวหอม","ok":false,"why":"ข้าวหอมไม่มีข้อห้ามเรื่องสุขภาพ และรับไม้ได้ดี"},{"text":"ต้นกล้า","ok":false,"why":"ต้นกล้าไม่มีข้อห้าม และเด่นเรื่องรับส่งไม้"},{"text":"ภูผา","ok":false,"why":"ภูผาไม่มีข้อห้าม และออกตัวเร็วที่สุด"}],"hints":["ดูช่องหมายเหตุในตาราง"],"solution":["ครูให้ใบเฟิร์นงดวิ่งเร็วเพราะข้อเท้าเพิ่งหายเจ็บ ทีมต้องทำตามคำแนะนำเรื่องสุขภาพ"],"answer":0},{"kind":"plan","prompt":"จัดตำแหน่งให้ทุกคนตามจุดเด่นและเงื่อนไข","skill":"planning","points":10,"fields":[{"id":"f1","label":"ไม้ที่ 1","options":[{"text":"ภูผา","ok":true},{"text":"มะปราง","ok":false,"why":"มะปรางเด่นช่วงท้าย เหมาะกับไม้สุดท้ายมากกว่า"},{"text":"ต้นกล้า","ok":false,"why":"ไม้ที่ 1 ไม่ต้องรับไม้ จุดเด่นเรื่องรับส่งไม้ของต้นกล้าจะไม่ได้ใช้เต็มที่"}],"answer":0},{"id":"f2","label":"ไม้ที่ 2 และ 3","options":[{"text":"ต้นกล้า และ ข้าวหอม","ok":true},{"text":"ต้นกล้า และ ใบเฟิร์น","ok":false,"why":"ครูให้ใบเฟิร์นงดวิ่งเร็วสัปดาห์นี้"},{"text":"ภูผา และ มะปราง","ok":false,"why":"สองคนนี้เหมาะกับไม้แรกและไม้สุดท้าย"}],"answer":0},{"id":"f3","label":"ไม้ที่ 4","options":[{"text":"มะปราง","ok":true},{"text":"ภูผา","ok":false,"why":"ภูผาเด่นเรื่องการออกตัว เหมาะกับไม้แรก"},{"text":"ข้าวหอม","ok":false,"why":"ข้าวหอมรับไม้ได้ดีและวิ่งสม่ำเสมอ แต่มะปรางเด่นเรื่องวิ่งช่วงท้ายโดยตรง"}],"answer":0},{"id":"f4","label":"ใบเฟิร์น","options":[{"text":"เป็นผู้ช่วยครูดูเขตส่งไม้","ok":true},{"text":"เป็นตัวสำรอง วิ่งแทนถ้าใครเหนื่อย","ok":false,"why":"ครูให้งดวิ่งเร็วทั้งสัปดาห์ แม้เป็นตัวสำรองก็ไม่ควรวิ่ง"},{"text":"ไม่ต้องร่วมกิจกรรม กลับห้องเรียนไปก่อน","ok":false,"why":"ไม่ตรงข้อตกลงของห้อง และใบเฟิร์นยังช่วยทีมได้โดยไม่ต้องวิ่ง"}],"answer":0}],"hints":["จับคู่จุดเด่นของแต่ละคนกับงานของแต่ละไม้","อ่านข้อตกลงของห้องเรื่องคนที่ไม่ได้วิ่ง"],"solution":["ไม้แรกต้องออกตัวเร็ว ไม้กลางต้องรับส่งไม้ดี ไม้สุดท้ายต้องวิ่งช่วงท้ายได้ดี","ใบเฟิร์นทำตามคำแนะนำของครู และยังมีบทบาทกับทีม"]},{"kind":"sort","prompt":"วันแข่งจริง จัดพฤติกรรมเหล่านี้ลงกลุ่มให้ถูกต้อง","skill":"rules","points":10,"bins":["มีน้ำใจนักกีฬา","ไม่มีน้ำใจนักกีฬา"],"items":[{"text":"ยอมรับผลการตัดสินของกรรมการ","bin":0,"why":"การเคารพกรรมการคือน้ำใจนักกีฬา"},{"text":"ปรบมือให้ทีมที่ชนะ","bin":0,"why":"เป็นการให้เกียรติคู่แข่ง"},{"text":"เห็นนักวิ่งทีมอื่นล้ม รีบเรียกครูมาช่วย","bin":0,"why":"ช่วยให้เพื่อนได้รับการดูแลเร็ว"},{"text":"ยื่นขาขวางลู่ของทีมอื่น","bin":1,"why":"อันตรายและผิดกติกา"},{"text":"โห่ไล่ทีมที่วิ่งช้า","bin":1,"why":"ทำให้เพื่อนเสียใจ ไม่ให้เกียรติกัน"},{"text":"ออกตัวก่อนได้ยินสัญญาณ","bin":1,"why":"เป็นการเอาเปรียบ ผิดกติกา"}],"hints":["พฤติกรรมไหนให้เกียรติคนอื่น พฤติกรรมไหนเอาเปรียบหรือทำร้าย"],"solution":["น้ำใจนักกีฬาคือเล่นตามกติกา ให้เกียรติคู่แข่ง และช่วยเหลือเมื่อมีคนเจ็บ"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่แผนจัดทีมนี้เหมาะสม","skill":"reason","points":10,"options":[{"text":"จัดคนตามจุดเด่นของแต่ละไม้ ทำตามคำแนะนำของครูเรื่องสุขภาพ และทุกคนมีบทบาท","ok":true},{"text":"เลือกเพื่อนที่สนิทกันที่สุดให้อยู่ไม้ติดกัน","ok":false,"why":"แผนนี้จัดตามจุดเด่น ไม่ได้จัดตามความสนิท"},{"text":"ให้คนที่เร็วที่สุดวิ่งทุกไม้","ok":false,"why":"คนเดียววิ่งทุกไม้ไม่ได้ และไม่ยุติธรรม"},{"text":"ไม่ต้องสนใจคำแนะนำของครู ถ้าอยากชนะ","ok":false,"why":"สุขภาพและความปลอดภัยต้องมาก่อนการชนะ"}],"hints":["แผนนี้ใช้ข้อมูลจากตารางและโน้ตส่วนไหนบ้าง"],"solution":["แผนที่ดีใช้จุดเด่นของสมาชิก เคารพเรื่องสุขภาพ และให้ทุกคนมีส่วนร่วม"],"answer":0}]}', 'hard', 24),
('health_sports', 'ว่ายน้ำค่ายฤดูร้อน', '{"icon":"🏊","story":["ค่ายฤดูร้อนมีกิจกรรมว่ายน้ำที่สระของค่ายตอนบ่าย กลุ่มของต้นกล้ามี 4 คน","ตอนนี้ 13:00 ทุกคนเพิ่งกินข้าวกลางวันอิ่มเสร็จ และอยากลงสระทันที"],"context":[{"type":"table","title":"ป้ายข้อปฏิบัติของสระ","head":["ข้อ","ข้อปฏิบัติ"],"rows":[["1","ลงสระได้เมื่อเจ้าหน้าที่ช่วยชีวิตประจำอยู่ที่จุดเฝ้าเท่านั้น"],["2","ห้ามวิ่งรอบขอบสระ"],["3","ห้ามกระโดดพุ่งหัวในส่วนน้ำตื้น"],["4","ว่ายเป็นคู่ (บัดดี้) และอยู่ในโซนตามความสามารถ"]]},{"type":"note","text":"เจ้าหน้าที่ช่วยชีวิตไปพักกลางวัน จะกลับมาประจำจุดเฝ้าเวลา 13:30 ท้องฟ้าแจ่มใส"},{"type":"table","title":"ความสามารถของกลุ่ม","head":["ชื่อ","ว่ายน้ำ"],"rows":[["ต้นกล้า","ว่ายได้คล่อง"],["มะปราง","ว่ายได้คล่อง"],["ใบเฟิร์น","ว่ายได้ระยะสั้น"],["ภูผา","ลอยตัวได้ แต่ยังว่ายไม่คล่อง"]]}],"steps":[{"kind":"multi","prompt":"ตอนนี้ (13:00) อะไรบ้างที่ยังไม่พร้อมให้ลงสระ (เลือกทุกข้อที่ถูก)","skill":"analysis","points":10,"options":[{"text":"เจ้าหน้าที่ช่วยชีวิตยังไม่อยู่ที่จุดเฝ้า","ok":true},{"text":"ทุกคนเพิ่งกินข้าวอิ่ม","ok":true},{"text":"ยังไม่มีใครอบอุ่นร่างกาย","ok":true},{"text":"ท้องฟ้าแจ่มใส","ok":false,"why":"อากาศดีไม่ใช่ปัญหา ถ้ามีฟ้าร้องจึงต้องงดว่าย"},{"text":"กลุ่มมี 4 คน จับคู่บัดดี้ได้ครบ","ok":false,"why":"จับคู่ได้ครบเป็นเรื่องดี ตรงกับป้ายข้อ 4"}],"hints":["เทียบป้ายข้อ 1 กับโน้ต","นึกถึงสิ่งที่ควรทำก่อนลงน้ำทุกครั้ง"],"solution":["ต้องมีเจ้าหน้าที่ช่วยชีวิตเฝ้าอยู่ก่อนลงสระ","ไม่ควรว่ายน้ำทันทีหลังกินอิ่ม และต้องอบอุ่นร่างกายก่อนลงน้ำ"]},{"kind":"plan","prompt":"วางแผนการว่ายน้ำของกลุ่มให้ตรงกับป้ายและข้อมูล","skill":"planning","points":10,"fields":[{"id":"f1","label":"เวลาที่เริ่มลงสระ","options":[{"text":"หลัง 13:30 เมื่อเจ้าหน้าที่กลับมาประจำจุด และพักหลังกินข้าวแล้ว","ok":true},{"text":"13:00 ทันที","ok":false,"why":"ยังไม่มีเจ้าหน้าที่เฝ้า และเพิ่งกินข้าวอิ่ม"},{"text":"แอบลงตอนพี่เลี้ยงไม่เห็น","ok":false,"why":"ผิดป้ายข้อ 1 และไม่มีใครช่วยได้ถ้าเกิดอันตราย"}],"answer":0},{"id":"f2","label":"บัดดี้และโซนของภูผา","options":[{"text":"คู่กับต้นกล้า ว่ายในโซนน้ำตื้น","ok":true},{"text":"คู่กับใบเฟิร์น ไปโซนน้ำลึก","ok":false,"why":"ภูผายังว่ายไม่คล่อง ต้องอยู่โซนน้ำตื้น และควรคู่กับคนที่ว่ายคล่อง"},{"text":"ว่ายคนเดียว เกาะขอบสระไว้","ok":false,"why":"ป้ายข้อ 4 ให้ทุกคนว่ายเป็นคู่"}],"answer":0},{"id":"f3","label":"วิธีอบอุ่นร่างกาย","options":[{"text":"หมุนแขน หมุนไหล่ และยืดขาอยู่กับที่บนพื้นที่แห้ง","ok":true},{"text":"วิ่งเร็ว ๆ รอบขอบสระ","ok":false,"why":"ผิดป้ายข้อ 2 ขอบสระลื่น"},{"text":"กระโดดพุ่งหัวลงน้ำตื้นให้ตัวอุ่น","ok":false,"why":"ผิดป้ายข้อ 3 อาจกระแทกพื้นสระ"}],"answer":0}],"hints":["ตรวจแต่ละหัวข้อกับป้ายข้อ 1–4","คนที่ยังว่ายไม่คล่องควรอยู่โซนไหน"],"solution":["รอเจ้าหน้าที่และพักหลังกินอิ่มก่อนลงน้ำ","คนที่ว่ายไม่คล่องอยู่โซนตื้นกับบัดดี้ที่ว่ายคล่อง","อบอุ่นร่างกายอยู่กับที่บนพื้นแห้ง"]},{"kind":"scene","prompt":"ระหว่างว่าย ภูผาเผลอลอยไปใกล้เส้นแบ่งโซนน้ำลึก แล้วเริ่มตะเกียกตะกาย ต้นกล้าที่อยู่ใกล้ ๆ ควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"ตะโกนเรียกเจ้าหน้าที่ช่วยชีวิต และยื่นหรือโยนอุปกรณ์ลอยน้ำให้ภูผาจับ","score":1,"result":"เจ้าหน้าที่ได้ยินและลงไปช่วยทันที ภูผาจับอุปกรณ์ลอยน้ำไว้ได้และปลอดภัย"},{"text":"ตะโกนเรียกเจ้าหน้าที่ แล้วยืนดูอยู่เฉย ๆ","score":0.5,"result":"เจ้าหน้าที่มาช่วยได้ แต่ถ้ายื่นอุปกรณ์ลอยน้ำให้ด้วย ภูผาจะลอยตัวได้เร็วขึ้น"},{"text":"ว่ายเข้าไปดึงภูผากลับมาเอง","score":0,"result":"ภูผาตกใจเกาะต้นกล้าแน่น ทั้งคู่เริ่มลำบาก โชคดีเจ้าหน้าที่ลงไปช่วยได้ทัน ครูย้ำว่าเด็กไม่ควรเข้าไปช่วยในน้ำเอง"},{"text":"ว่ายไปตามเพื่อนอีกฝั่งสระมาช่วยกันคิด","score":0,"result":"เสียเวลานาน เจ้าหน้าที่เห็นเองแล้วลงไปช่วย ถ้าตะโกนเรียกตั้งแต่แรกจะเร็วกว่ามาก"}],"hints":["ใครคือคนที่ช่วยคนตกน้ำได้ปลอดภัยที่สุด","เราช่วยได้อย่างไรโดยไม่ต้องลงไปในน้ำลึก"],"solution":["เมื่อเห็นคนกำลังจะจมน้ำ ให้ตะโกนเรียกผู้ใหญ่หรือเจ้าหน้าที่ และยื่นหรือโยนอุปกรณ์ลอยน้ำให้","ไม่ควรเข้าไปช่วยในน้ำเอง"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่เด็กไม่ควรเข้าไปช่วยเพื่อนที่กำลังจมน้ำเอง","skill":"reason","points":10,"options":[{"text":"คนที่กำลังจมมักตกใจและเกาะคนช่วยแน่น อาจจมทั้งสองคน จึงควรเรียกผู้ใหญ่และช่วยจากบนฝั่ง","ok":true},{"text":"เพราะเสื้อผ้าจะเปียก","ok":false,"why":"เหตุผลไม่ใช่เรื่องเสื้อผ้า แต่เป็นอันตรายต่อชีวิต"},{"text":"เพราะไม่ใช่หน้าที่ของเรา ปล่อยให้คนอื่นจัดการ","ok":false,"why":"เราช่วยได้ด้วยการเรียกผู้ใหญ่และยื่นอุปกรณ์ลอยน้ำ"},{"text":"เพราะเจ้าหน้าที่จะดุ","ok":false,"why":"เหตุผลหลักคือความปลอดภัย ไม่ใช่การถูกดุ"}],"hints":["คิดถึงสิ่งที่คนตกใจในน้ำมักทำ"],"solution":["การช่วยคนจมน้ำในน้ำต้องใช้ผู้ที่ฝึกมา เด็กช่วยได้ดีที่สุดด้วยการตะโกนเรียกและยื่นอุปกรณ์ลอยน้ำจากบนฝั่ง"],"answer":0}]}', 'hard', 25),
('health_sports', 'บาสเกตบอลที่ทุกคนได้เล่น', '{"icon":"🏀","story":["ห้อง ป.5/3 เล่นบาสเกตบอลฝึกซ้อม 5 คนต่อ 5 คน","ครึ่งแรกครูสังเกตว่าลูกไปอยู่ที่ภูผาเกือบตลอด เพื่อนบางคนเริ่มไม่อยากเล่น"],"context":[{"type":"table","title":"สถิติครึ่งแรก (ครูจดไว้)","head":["ผู้เล่น","ได้รับลูก (ครั้ง)","ส่งต่อให้เพื่อน (ครั้ง)","สภาพตอนนี้"],"rows":[["ภูผา","15","1","เหนื่อยมาก หายใจหอบ"],["มะปราง","3","3","ปกติ"],["ต้นกล้า","2","2","ปกติ"],["ใบเฟิร์น","0","0","ยังไม่ได้แตะลูกเลย"],["ข้าวหอม","4","4","ปกติ"]]},{"type":"note","text":"คะแนนครึ่งแรกเสมอ 6–6 ครึ่งหลังเปลี่ยนตัวได้ มีสำรอง 1 คนคือปลื้ม อบอุ่นร่างกายแล้ว"},{"type":"note","text":"จังหวะสุดท้ายของครึ่งแรก ภูผาเลี้ยงลูกเข้าไปหาคู่แข่ง 3 คนแล้วถูกแย่งลูก ขณะที่มะปรางยืนว่างใต้แป้น"}],"steps":[{"kind":"multi","prompt":"จากข้อมูล ข้อใดเป็นปัญหาของทีม (เลือกทุกข้อที่ถูก)","skill":"analysis","points":10,"options":[{"text":"ภูผาได้รับลูก 15 ครั้ง แต่ส่งต่อแค่ 1 ครั้ง","ok":true},{"text":"ใบเฟิร์นยังไม่ได้แตะลูกเลย","ok":true},{"text":"ภูผาเหนื่อยมากจนหายใจหอบ","ok":true},{"text":"มะปรางยืนว่างใต้แป้นแต่ไม่ได้รับลูก","ok":true},{"text":"ข้าวหอมส่งต่อทุกครั้งที่ได้รับลูก","ok":false,"why":"นี่คือการเล่นเป็นทีมที่ดี ไม่ใช่ปัญหา"},{"text":"คะแนนเสมอ 6–6","ok":false,"why":"คะแนนเสมอไม่ใช่ปัญหาของการเล่นเป็นทีม"}],"hints":["เทียบช่องได้รับลูกกับช่องส่งต่อ","อ่านโน้ตจังหวะสุดท้ายด้วย"],"solution":["ลูกไม่ได้กระจาย คนหนึ่งเล่นคนเดียวจนเหนื่อย และเพื่อนที่ว่างไม่ได้รับลูก","ทั้งเรื่องความยุติธรรมและความปลอดภัยต้องได้รับการแก้"]},{"kind":"plan","prompt":"วางแผนครึ่งหลังให้ทีมเล่นได้ดี ยุติธรรม และปลอดภัย","skill":"planning","points":10,"fields":[{"id":"f1","label":"ภูผา","options":[{"text":"พักช่วงต้นครึ่งหลังและดื่มน้ำ ให้ปลื้มลงแทน แล้วค่อยกลับมาเล่น","ok":true},{"text":"เล่นต่อทั้งครึ่งเพราะเก่งที่สุด","ok":false,"why":"ภูผาเหนื่อยมาก ฝืนต่อเสี่ยงบาดเจ็บ และปลื้มพร้อมลงอยู่แล้ว"},{"text":"ออกไปนั่ง ไม่ต้องกลับมาเล่นอีก","ok":false,"why":"ไม่ยุติธรรมกับภูผา พักหายเหนื่อยแล้วกลับมาเล่นได้"}],"answer":0},{"id":"f2","label":"ข้อตกลงการส่งลูก","options":[{"text":"ส่งให้เพื่อนที่ว่างกว่าเสมอ และพยายามให้ทุกคนได้มีส่วนร่วม","ok":true},{"text":"ส่งให้คนเก่งที่สุดยิงคนเดียว","ok":false,"why":"ทำให้เพื่อนไม่ได้เล่น และคู่แข่งรู้ทางง่าย"},{"text":"ไม่ต้องส่งให้ใบเฟิร์น เพราะยังไม่ได้แตะลูก","ok":false,"why":"ยิ่งไม่ได้แตะลูก ยิ่งควรได้โอกาส ทุกคนในทีมต้องได้เล่น"}],"answer":0},{"id":"f3","label":"การป้องกัน","options":[{"text":"แต่ละคนประกบคู่แข่งของตัวเอง ใช้สไลด์เท้า ไม่ผลักไม่ดึง","ok":true},{"text":"ทุกคนรุมไปที่ลูก","ok":false,"why":"คู่แข่งคนอื่นจะว่าง ส่งลูกผ่านได้ง่าย"},{"text":"ผลักคู่แข่งที่ถือลูกให้เสียหลัก","ok":false,"why":"เป็นฟาวล์ และอาจทำให้คู่แข่งบาดเจ็บ"}],"answer":0}],"hints":["แผนต้องแก้ทุกปัญหาที่พบในข้อแรก"],"solution":["ให้คนที่เหนื่อยได้พักและใช้ตัวสำรองที่พร้อม","กระจายลูกให้คนที่ว่างและให้ทุกคนมีส่วนร่วม","ป้องกันแบบตัวต่อตัวโดยไม่ฟาวล์"]},{"kind":"choice","prompt":"ครึ่งหลัง มะปรางเลี้ยงลูกเข้าใกล้แป้น คู่แข่ง 2 คนเข้ามาบัง ส่วนใบเฟิร์นยืนว่างใกล้แป้น มะปรางควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"ส่งลูกให้ใบเฟิร์นที่ว่าง","ok":true},{"text":"ฝืนยิงทั้งที่ถูกบัง 2 คน","ok":false,"why":"ถูกบังอยู่ โอกาสยิงลงน้อย ขณะที่มีเพื่อนว่าง"},{"text":"หยุดเลี้ยง แล้วเริ่มเลี้ยงใหม่เพื่อหลอกคู่แข่ง","ok":false,"why":"หยุดเลี้ยงแล้วเลี้ยงใหม่ผิดกติกา"},{"text":"ถือลูกวิ่งหลบออกมา","ok":false,"why":"ถือลูกวิ่งโดยไม่เลี้ยงผิดกติกา"}],"hints":["ทำตามข้อตกลงการส่งลูกที่ทีมวางแผนไว้"],"solution":["เมื่อถูกบังหลายคน เพื่อนที่ว่างคือทางเลือกที่ดีที่สุด และตรงกับข้อตกลงของทีม"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่แผนครึ่งหลังดีกว่าการเล่นในครึ่งแรก","skill":"reason","points":10,"options":[{"text":"ลูกกระจายไปยังคนที่ว่าง ทุกคนมีส่วนร่วม และคนที่เหนื่อยได้พัก","ok":true},{"text":"ภูผาจะได้ไม่ต้องรับผิดชอบถ้าแพ้","ok":false,"why":"แผนนี้ไม่ได้ทำเพื่อโยนความรับผิดชอบ แต่เพื่อทีมและความปลอดภัย"},{"text":"ใบเฟิร์นจะได้ยิงทุกลูก","ok":false,"why":"แผนนี้ให้ส่งให้คนที่ว่าง ไม่ได้ให้ใครคนเดียวยิงทุกลูก"},{"text":"แผนนี้ทำให้ชนะแน่นอน","ok":false,"why":"ไม่มีแผนไหนรับประกันชัยชนะ แต่แผนนี้ทำให้ทีมเล่นได้ดีและยุติธรรม"}],"hints":["แผนใหม่แก้ปัญหาอะไรบ้างจากสถิติครึ่งแรก"],"solution":["การเล่นเป็นทีมที่ดีคือกระจายลูก ให้ทุกคนมีส่วนร่วม และดูแลความปลอดภัยของสมาชิก"],"answer":0}]}', 'hard', 26),
