('health_sports', 'น้ำใจนักกีฬาในนัดชิง', '{"icon":"🤝","story":["ฟุตบอลกีฬาสีนัดชิง ทีมของต้นกล้ากำลังบุก ต้นกล้าคุมลูกอยู่ใกล้ประตูคู่แข่ง","ทันใดนั้น ผู้เล่นทีมตรงข้ามล้มลงกลางสนาม กุมขาและร้องเจ็บ กรรมการยังไม่เป่านกหวีด"],"context":[{"type":"table","title":"สถานการณ์","head":["เรื่อง","ข้อมูล"],"rows":[["คะแนน","เสมอ 1–1"],["เวลาที่เหลือ","5 นาที"],["ต้นกล้า","คุมลูก ห่างประตูคู่แข่งประมาณ 15 ก้าว"],["ผู้เล่นที่ล้ม","ทีมตรงข้าม อยู่กลางสนาม ลุกไม่ได้"]]},{"type":"note","text":"กติกาการทุ่ม: เมื่อลูกออกข้างสนาม ทีมที่ไม่ได้ทำลูกออกจะได้ทุ่มลูกเข้าเล่น ผู้ทุ่มต้องใช้สองมือ ส่งลูกจากด้านหลังผ่านเหนือศีรษะ และเท้าทั้งสองข้างต้องแตะพื้น"},{"type":"note","text":"ธรรมเนียมน้ำใจนักกีฬา: ถ้ามีผู้เล่นบาดเจ็บ ทีมที่ครองลูกมักเตะลูกออกให้เกมหยุด เมื่อเริ่มเล่นใหม่ อีกทีมจะคืนลูกให้"}],"steps":[{"kind":"scene","prompt":"ต้นกล้าควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"เตะลูกออกข้างสนามให้เกมหยุด แล้วยกมือเรียกกรรมการและครู","score":1,"result":"กรรมการหยุดเกม ครูพยาบาลเข้าไปดูแลผู้เล่นที่เจ็บ ทุกคนปรบมือให้ต้นกล้า"},{"text":"วิ่งไปพยุงผู้เล่นที่ล้มให้ลุกขึ้นเดินเอง","score":0.5,"result":"ต้นกล้ามีน้ำใจ แต่การพยุงให้ลุกเดินอาจทำให้เจ็บมากขึ้น ครูเข้ามาบอกว่าควรหยุดเกมแล้วให้ครูดูแล"},{"text":"บุกต่อไปยิงประตู เพราะกรรมการยังไม่เป่า","score":0,"result":"ต้นกล้ายิงเข้า แต่ทุกคนรู้สึกไม่ดี ผู้เล่นที่เจ็บต้องรอนานขึ้น และครูเรียกคุยเรื่องน้ำใจนักกีฬาหลังเกม"}],"hints":["อะไรสำคัญกว่า ประตูหรือคนที่เจ็บ","ใครควรเป็นคนดูแลคนเจ็บ"],"solution":["เมื่อมีคนเจ็บในสนาม ให้หยุดเกมและเรียกผู้ใหญ่มาดูแล ไม่เคลื่อนย้ายคนเจ็บเอง","การเตะลูกออกเป็นวิธีหยุดเกมที่ทุกฝ่ายเข้าใจ"]},{"kind":"choice","prompt":"เกมเริ่มใหม่ด้วยการทุ่ม ผู้เล่นทีมตรงข้ามจะทุ่มลูกคืนให้ทีมต้นกล้า ท่าทุ่มแบบใดถูกกติกา","skill":"rules","points":10,"options":[{"text":"ใช้สองมือ ส่งลูกจากด้านหลังผ่านเหนือศีรษะ และเท้าทั้งสองข้างแตะพื้น","ok":true},{"text":"ใช้มือเดียวขว้างให้ไกล ๆ","ok":false,"why":"การทุ่มต้องใช้สองมือ"},{"text":"กระโดดขึ้นแล้วทุ่มกลางอากาศ","ok":false,"why":"เท้าทั้งสองข้างต้องแตะพื้นขณะทุ่ม"},{"text":"วางลูกบนเส้นแล้วเตะเข้าสนาม","ok":false,"why":"ลูกออกข้างสนามต้องเริ่มใหม่ด้วยการทุ่ม ไม่ใช่การเตะ"}],"hints":["อ่านกติกาการทุ่มในโน้ต"],"solution":["การทุ่มที่ถูกต้องใช้สองมือ ส่งจากหลังผ่านเหนือศีรษะ และเท้าแตะพื้นทั้งสองข้าง"],"answer":0},{"kind":"sort","prompt":"จัดพฤติกรรมในการแข่งขันลงกลุ่มให้ถูกต้อง","skill":"analysis","points":10,"bins":["มีน้ำใจนักกีฬา","ไม่มีน้ำใจนักกีฬา"],"items":[{"text":"คืนลูกให้อีกทีมหลังหยุดเกมเพราะมีคนเจ็บ","bin":0,"why":"เป็นการเล่นอย่างยุติธรรม ไม่เอาเปรียบ"},{"text":"จับมือคู่แข่งหลังจบเกม","bin":0,"why":"ให้เกียรติคู่แข่งไม่ว่าแพ้หรือชนะ"},{"text":"ยอมรับคำตัดสินแม้ไม่พอใจ","bin":0,"why":"เคารพกรรมการและกติกา"},{"text":"แกล้งล้มเพื่อให้กรรมการเป่าฟาวล์","bin":1,"why":"เป็นการโกง ไม่ยุติธรรม"},{"text":"เถียงกรรมการเสียงดัง","bin":1,"why":"ไม่เคารพกรรมการ"},{"text":"ล้อเลียนผู้เล่นที่ทำพลาด","bin":1,"why":"ทำให้คนอื่นเสียใจ ไม่ให้เกียรติกัน"}],"hints":["พฤติกรรมไหนให้เกียรติคนอื่นและเล่นตามกติกา"],"solution":["น้ำใจนักกีฬาคือการเล่นอย่างยุติธรรม เคารพกติกาและกรรมการ และให้เกียรติทุกคน"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้นกล้าควรหยุดเกม แม้กำลังจะได้ยิงประตูในเกมที่สกอร์เสมอ","skill":"reason","points":10,"options":[{"text":"ความปลอดภัยของผู้เล่นทุกคนสำคัญกว่าการได้ประตู และทำให้การแข่งขันยุติธรรม","ok":true},{"text":"เพราะกรรมการจะไม่นับประตูอยู่แล้ว","ok":false,"why":"ไม่แน่ว่ากรรมการจะไม่นับ เหตุผลที่ดีคือความปลอดภัยและน้ำใจนักกีฬา"},{"text":"เพราะต้นกล้ากลัวยิงไม่เข้า","ok":false,"why":"ไม่มีข้อมูลว่าต้นกล้ากลัว เหตุผลคือมีคนเจ็บ"},{"text":"เพื่อให้คนดูชมว่าเป็นคนดี","ok":false,"why":"เราทำเพราะห่วงความปลอดภัยของเพื่อน ไม่ใช่เพื่อคำชม"}],"hints":["เหตุผลควรเกี่ยวกับผู้เล่นที่เจ็บและความยุติธรรม"],"solution":["ในการแข่งขัน ความปลอดภัยของทุกคนมาก่อนผลการแข่งขันเสมอ","การไม่เอาเปรียบตอนอีกทีมมีคนเจ็บคือน้ำใจนักกีฬา"],"answer":0}]}', 'hard', 28),
('health_sports', 'ออกแบบสถานีฝึกทักษะ', '{"icon":"🧭","story":["ครูให้กลุ่มของมะปรางออกแบบคาบฝึกทักษะการเคลื่อนไหว 3 สถานี สำหรับเพื่อน 12 คน แบ่งกลุ่มละ 4 คน","เมื่อเช้าฝนตก พื้นบางจุดยังเปียก กลุ่มต้องเลือกพื้นที่ให้เหมาะกับแต่ละสถานี"],"context":[{"type":"table","title":"สถานีที่ต้องจัด","head":["สถานี","ทักษะ","สิ่งที่ต้องระวัง"],"rows":[["ก","ขว้างและรับลูกบอลยาง","ลูกที่รับพลาดอาจกระเด็นไปโดนกลุ่มอื่น"],["ข","กระโดดเชือกเดี่ยว","ต้องมีพื้นแข็ง เรียบ และที่ว่างรอบตัว"],["ค","เลี้ยงลูกฟุตบอลอ้อมกรวย","ต้องมีพื้นที่ยาวพอวางกรวยเป็นแนว"]]},{"type":"table","title":"พื้นที่ที่ใช้ได้","head":["พื้นที่","ลักษณะ"],"rows":[["ลาน 1","ลานซีเมนต์ ติดรั้วตาข่ายสูง"],["ลาน 2","ลานซีเมนต์เรียบ โล่ง ไม่มีอะไรเกะกะ"],["ลาน 3","สนามหญ้า มีแอ่งน้ำขังหลังฝน"],["ลาน 4","สนามหญ้าแห้ง ยาวประมาณ 20 เมตร"]]},{"type":"note","text":"ครูกำหนด: หนึ่งสถานีใช้หนึ่งพื้นที่ และห้ามใช้พื้นที่ที่ลื่นหรือมีน้ำขัง"}],"steps":[{"kind":"plan","prompt":"เลือกพื้นที่ให้แต่ละสถานี","skill":"planning","points":10,"fields":[{"id":"f1","label":"สถานี ก ขว้างและรับลูก","options":[{"text":"ลาน 1","ok":true},{"text":"ลาน 3","ok":false,"why":"มีแอ่งน้ำขัง ลื่น ครูห้ามใช้"},{"text":"ลาน 2","ok":false,"why":"ลาน 2 ไม่มีรั้วกันลูกที่กระเด็น และเป็นพื้นที่เดียวที่ทั้งเรียบและโล่งพอสำหรับกระโดดเชือก"}],"answer":0},{"id":"f2","label":"สถานี ข กระโดดเชือก","options":[{"text":"ลาน 2","ok":true},{"text":"ลาน 3","ok":false,"why":"พื้นเปียกลื่น เสี่ยงล้ม ครูห้ามใช้"},{"text":"ลาน 4","ok":false,"why":"พื้นหญ้าไม่เรียบแข็งพอสำหรับกระโดดเชือก และลาน 4 ยาวเหมาะกับการเลี้ยงลูกอ้อมกรวยมากกว่า"}],"answer":0},{"id":"f3","label":"สถานี ค เลี้ยงลูกฟุตบอลอ้อมกรวย","options":[{"text":"ลาน 4","ok":true},{"text":"ลาน 3","ok":false,"why":"มีแอ่งน้ำขัง ลื่น ครูห้ามใช้"},{"text":"ลาน 1","ok":false,"why":"ลาน 1 มีรั้วกันลูก เหมาะกับสถานีขว้างรับมากกว่า และสนามหญ้ายาวเหมาะกับการเลี้ยงฟุตบอล"}],"answer":0}],"hints":["ตัดพื้นที่ที่ครูห้ามออกก่อน","แต่ละสถานีต้องการอะไรจากพื้นที่ ดูในช่องสิ่งที่ต้องระวัง"],"solution":["ลาน 3 ใช้ไม่ได้เพราะมีน้ำขัง","รั้วของลาน 1 กันลูกที่กระเด็น ลาน 2 เรียบและโล่งสำหรับกระโดดเชือก และลาน 4 ยาวพอวางกรวย"]},{"kind":"sort","prompt":"จัดข้อปฏิบัติด้านความปลอดภัยให้ตรงกับสถานี","skill":"rules","points":10,"bins":["สถานี ก ขว้างและรับลูก","สถานี ข กระโดดเชือก","สถานี ค เลี้ยงลูกอ้อมกรวย"],"items":[{"text":"มองให้แน่ใจว่าคู่พร้อมรับก่อนขว้าง","bin":0,"why":"ข้อนี้เกี่ยวกับการขว้างให้เพื่อน"},{"text":"ขว้างลูกระดับอก ไม่ขว้างใส่หน้า","bin":0,"why":"ข้อนี้เกี่ยวกับทิศทางของลูกที่ขว้าง"},{"text":"ยืนห่างกันให้เชือกแกว่งไม่ถึงเพื่อน","bin":1,"why":"ข้อนี้เกี่ยวกับเชือกที่แกว่ง"},{"text":"ลงพื้นด้วยปลายเท้าและงอเข่าเล็กน้อย","bin":1,"why":"ข้อนี้เกี่ยวกับการกระโดดลงพื้น"},{"text":"รอให้คนข้างหน้าอ้อมกรวยครบก่อนออกตัว","bin":2,"why":"ข้อนี้เกี่ยวกับคิวเลี้ยงลูกอ้อมกรวย"},{"text":"เลี้ยงลูกเบา ๆ ให้ลูกอยู่ใกล้เท้า","bin":2,"why":"ข้อนี้เกี่ยวกับการควบคุมลูกฟุตบอล"}],"hints":["แต่ละข้อพูดถึงอุปกรณ์อะไร ลูกบอลยาง เชือก หรือกรวย"],"solution":["แต่ละทักษะมีความเสี่ยงต่างกัน ข้อปฏิบัติจึงต้องตรงกับอุปกรณ์และการเคลื่อนไหวของสถานีนั้น"]},{"kind":"choice","prompt":"ระหว่างฝึก ลูกบอลกลิ้งไปทางลาน 3 นิดวิ่งตามไปเก็บแล้วลื่นล้ม เข่าถลอกเล็กน้อย กลุ่มควรทำอย่างไร","skill":"decision","points":10,"options":[{"text":"ให้นิดหยุดพัก แจ้งครูให้ช่วยดูแผล และตกลงกันว่าลูกที่กลิ้งไปลาน 3 ให้ครูเป็นคนเก็บ","ok":true},{"text":"ให้นิดฝึกต่อเพราะแผลเล็ก","ok":false,"why":"แม้แผลเล็กก็ควรให้ครูช่วยดูแลความสะอาดก่อน"},{"text":"เอาทรายถูแผลให้เลือดหยุด","ok":false,"why":"ทรายสกปรก ทำให้แผลติดเชื้อได้ ต้องให้ครูดูแล"},{"text":"ปล่อยลูกไว้ที่ลาน 3 แล้วไม่ใช้ลูกนั้นอีกเลยโดยไม่บอกใคร","ok":false,"why":"ไม่ได้ช่วยนิด และคนอื่นอาจวิ่งไปเก็บจนลื่นล้มซ้ำ ควรแจ้งครู"}],"hints":["ต้องดูแลทั้งนิด และป้องกันไม่ให้เกิดซ้ำ"],"solution":["เมื่อมีคนบาดเจ็บ ให้หยุดพักและแจ้งครู","ต้องแก้ต้นเหตุด้วย คือไม่ให้ใครเข้าไปในพื้นที่ลื่นอีก"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องเลือกพื้นที่ให้เหมาะกับแต่ละสถานี","skill":"reason","points":10,"options":[{"text":"แต่ละทักษะต้องการพื้นที่และพื้นผิวต่างกัน การจับคู่ให้เหมาะช่วยลดอุบัติเหตุและฝึกได้เต็มที่","ok":true},{"text":"เพื่อให้แต่ละกลุ่มอยู่ห่างจากครูมากที่สุด","ok":false,"why":"ครูควรมองเห็นทุกสถานี เหตุผลคือความเหมาะสมของพื้นที่"},{"text":"เพราะสนามหญ้าดีกว่าลานซีเมนต์ทุกกรณี","ok":false,"why":"กระโดดเชือกเหมาะกับพื้นเรียบแข็ง ไม่ใช่สนามหญ้าเสมอไป"},{"text":"เพื่อให้ใช้พื้นที่ครบทุกลาน","ok":false,"why":"ลาน 3 ไม่ควรใช้เลย เพราะมีน้ำขัง"}],"hints":["เทียบสิ่งที่ต้องระวังของแต่ละสถานีกับลักษณะพื้นที่"],"solution":["การเลือกพื้นที่ที่เหมาะเป็นการป้องกันอุบัติเหตุตั้งแต่ก่อนเริ่มฝึก"],"answer":0}]}', 'hard', 29),
('health_sports', 'ทีมกระโดดเชือกพี่ช่วยน้อง', '{"icon":"🪢","story":["ชมรมกีฬาจะแข่งกระโดดเชือกหมู่ ใช้เชือกยาวที่มีคนแกว่ง 2 คน และผู้กระโดดเข้าไปกระโดดในเชือก","ทีมของภูผามีพี่ ป.5 สี่คน และน้อง ป.3 สองคนมาร่วมทีมตามที่ชมรมจัดให้"],"context":[{"type":"table","title":"สมาชิกทีม","head":["ชื่อ","ชั้น","ข้อมูล"],"rows":[["ภูผา","ป.5","สูงที่สุด แกว่งเชือกได้สม่ำเสมอ"],["มะปราง","ป.5","แกว่งเชือกจังหวะดี"],["ต้นกล้า","ป.5","กระโดดเก่ง ช่วยนับจังหวะให้เพื่อนได้"],["ใบเฟิร์น","ป.5","เมื่อเช้าบอกครูว่าไม่สบาย ครูให้งดกิจกรรมที่ออกแรง"],["น้องโอ๊ต","ป.3","กระโดดได้ แต่ยังเข้าเชือกไม่เป็นจังหวะ"],["น้องแพรว","ป.3","กลัวเชือกฟาดขา"]]},{"type":"note","text":"พื้นที่ซ้อมที่เลือกได้: โรงยิมในร่มพื้นเรียบ หรือลานหินกรวดกลางแจ้ง วันนี้แดดข้างนอกร้อนจัด"}],"steps":[{"kind":"multi","prompt":"ข้อใดเป็นปัญหาหรือความเสี่ยงที่ทีมต้องวางแผนรับมือ (เลือกทุกข้อที่ถูก)","skill":"analysis","points":10,"options":[{"text":"ใบเฟิร์นไม่สบาย ครูให้งดกิจกรรมที่ออกแรง","ok":true},{"text":"น้องแพรวกลัวเชือกฟาดขา","ok":true},{"text":"น้องโอ๊ตยังเข้าเชือกไม่เป็นจังหวะ","ok":true},{"text":"แดดข้างนอกร้อนจัด","ok":true},{"text":"ภูผาแกว่งเชือกได้สม่ำเสมอ","ok":false,"why":"เป็นจุดแข็งของทีม ไม่ใช่ปัญหา"},{"text":"มีโรงยิมในร่มให้ใช้","ok":false,"why":"เป็นทางเลือกที่ดี ไม่ใช่ความเสี่ยง"}],"hints":["อ่านช่องข้อมูลทีละคน แล้วอ่านโน้ตเรื่องพื้นที่"],"solution":["ทีมต้องคิดถึงทั้งสุขภาพของสมาชิก ความพร้อมของน้อง และสภาพอากาศ ก่อนวางแผนซ้อม"]},{"kind":"plan","prompt":"วางแผนการซ้อมของทีม","skill":"planning","points":10,"fields":[{"id":"f1","label":"สถานที่ซ้อม","options":[{"text":"โรงยิมในร่มพื้นเรียบ","ok":true},{"text":"ลานหินกรวดกลางแจ้ง","ok":false,"why":"พื้นหินกรวดไม่เรียบ เสี่ยงข้อเท้าพลิก และแดดร้อนจัด"}],"answer":0},{"id":"f2","label":"ผู้แกว่งเชือก 2 คน","options":[{"text":"ภูผา และ มะปราง","ok":true},{"text":"ต้นกล้า และ น้องโอ๊ต","ok":false,"why":"ต้นกล้าควรเป็นผู้กระโดดที่ช่วยนับจังหวะให้น้อง และน้องโอ๊ตยังจับจังหวะเชือกไม่ได้"},{"text":"น้องโอ๊ต และ น้องแพรว","ok":false,"why":"น้องยังจับจังหวะเชือกไม่ได้ เชือกจะแกว่งไม่สม่ำเสมอ"}],"answer":0},{"id":"f3","label":"ใบเฟิร์น","options":[{"text":"เป็นผู้นับจำนวนครั้งและจับเวลาให้ทีม","ok":true},{"text":"กระโดดด้วยแต่กระโดดช้า ๆ","ok":false,"why":"ครูให้งดกิจกรรมที่ออกแรง ทีมต้องทำตาม"},{"text":"ไม่ต้องมาร่วมกับทีม","ok":false,"why":"ใบเฟิร์นยังช่วยทีมได้โดยไม่ต้องออกแรง"}],"answer":0},{"id":"f4","label":"ช่วยน้องแพรวที่กลัวเชือก","options":[{"text":"ให้ซ้อมกับเชือกที่แกว่งช้า ๆ ก่อน โดยต้นกล้าช่วยนับจังหวะ","ok":true},{"text":"แกว่งเชือกเร็ว ๆ ให้น้องชิน","ok":false,"why":"เชือกเร็วยิ่งฟาดขาง่ายและทำให้น้องกลัวมากขึ้น"},{"text":"บังคับให้น้องเข้าเชือกพร้อมทุกคนทันที","ok":false,"why":"น้องยังไม่พร้อม ควรฝึกจากง่ายไปยาก"}],"answer":0}],"hints":["จับคู่ข้อมูลในตารางกับหน้าที่แต่ละอย่าง","คนที่ครูให้งดออกแรงจะช่วยทีมได้อย่างไร"],"solution":["ซ้อมในที่ร่มพื้นเรียบเลี่ยงทั้งความร้อนและการสะดุด","ให้คนที่แกว่งเชือกเก่งเป็นผู้แกว่ง ใบเฟิร์นช่วยโดยไม่ออกแรง และพาน้องฝึกจากช้าไปเร็ว"]},{"kind":"order","prompt":"เรียงขั้นตอนฝึกน้องโอ๊ตเข้าเชือก จากง่ายไปยาก","skill":"planning","points":10,"items":["ยืนดูเชือกแกว่งและนับจังหวะตามพี่","ยืนอยู่กลางเชือกตั้งแต่แรก ให้พี่แกว่งช้า ๆ แล้วกระโดดทีละครั้ง","วิ่งเข้าเชือกขณะเชือกแกว่งช้า ๆ","เข้าเชือกพร้อมเพื่อนในจังหวะแข่งจริง"],"hints":["ขั้นไหนยังไม่ต้องกระโดดเลย ขั้นไหนยากที่สุด"],"solution":["การฝึกทักษะใหม่ควรเริ่มจากดูและนับจังหวะ แล้วกระโดดอยู่กับที่ จึงค่อยวิ่งเข้าเชือก","สุดท้ายจึงเล่นพร้อมทีมในจังหวะจริง"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่แผนนี้เหมาะกับทีม","skill":"reason","points":10,"options":[{"text":"จัดหน้าที่ตามความสามารถ ทำตามคำแนะนำของครูเรื่องสุขภาพ ช่วยน้องฝึกจากง่ายไปยาก และเลี่ยงความร้อน","ok":true},{"text":"ให้พี่ ป.5 ได้กระโดดมากที่สุดเพราะเก่งกว่า","ok":false,"why":"แผนนี้ให้น้องได้ฝึกและมีส่วนร่วม ไม่ได้ให้พี่เล่นคนเดียว"},{"text":"ทำให้ชนะการแข่งขันได้แน่นอน","ok":false,"why":"ไม่มีแผนไหนรับประกันชัยชนะ แต่แผนนี้ปลอดภัยและยุติธรรม"},{"text":"ให้ใบเฟิร์นได้พักเพราะไม่อยากซ้อม","ok":false,"why":"ใบเฟิร์นพักเพราะไม่สบายตามที่ครูแนะนำ ไม่ใช่เพราะไม่อยากซ้อม"}],"hints":["แผนนี้ใช้ข้อมูลจากตารางและโน้ตอะไรบ้าง"],"solution":["ทีมที่ดีใช้จุดแข็งของสมาชิก ดูแลคนที่ไม่สบาย และช่วยคนที่ยังไม่พร้อมให้ค่อย ๆ พัฒนา"],"answer":0}]}', 'hard', 30),
('health_safety', 'ปลั๊กพ่วงมีรอยไหม้', '{"icon":"🔌","story":["น้องต้นกล้าจะเสียบสายชาร์จแท็บเล็ตที่ปลั๊กพ่วงในห้องนั่งเล่น","เขาเห็นว่าปลั๊กพ่วงมีรอยไหม้สีดำ และสายไฟตรงโคนมีเทปพันไว้หลายรอบ"],"tip":"อุปกรณ์ไฟฟ้าที่ชำรุด อย่าใช้และอย่าซ่อมเอง ให้บอกผู้ใหญ่","context":[{"type":"note","text":"รอยไหม้สีดำที่ปลั๊ก แปลว่าเคยเกิดความร้อนสูงหรือประกายไฟมาก่อน"}],"steps":[{"kind":"scene","prompt":"ต้นกล้าควรทำอย่างไร","skill":"decision","points":10,"hints":["รอยไหม้บอกอะไรเราเกี่ยวกับปลั๊กอันนี้","ใครควรเป็นคนจัดการอุปกรณ์ไฟฟ้าที่ชำรุด"],"solution":["ปลั๊กที่มีรอยไหม้อาจทำให้ไฟดูดหรือไฟไหม้ได้","ทางที่ปลอดภัยคือไม่ใช้ และบอกผู้ใหญ่ให้เปลี่ยนอันใหม่"],"options":[{"text":"ไม่เสียบปลั๊ก แล้วไปบอกพ่อแม่ว่าปลั๊กพ่วงมีรอยไหม้","score":1,"result":"พ่อถอดปลั๊กพ่วงออกและซื้ออันใหม่มาใช้ ต้นกล้าชาร์จแท็บเล็ตได้อย่างปลอดภัย"},{"text":"เสียบชาร์จไปก่อน เพราะเมื่อวานก็ยังใช้ได้","score":0,"result":"ไม่นานปลั๊กเริ่มมีกลิ่นเหม็นไหม้และร้อนขึ้น","then":{"kind":"choice","prompt":"ได้กลิ่นไหม้จากปลั๊ก ตอนนี้ต้นกล้าควรทำอะไรก่อน","skill":"decision","points":10,"hints":["ถ้าเอามือไปจับปลั๊กที่ร้อนจะเกิดอะไรขึ้น"],"solution":["เมื่ออุปกรณ์ไฟฟ้ามีกลิ่นไหม้ ไม่ควรจับเอง ให้ออกห่างและเรียกผู้ใหญ่มาตัดไฟ"],"options":[{"text":"ออกห่างจากปลั๊ก แล้วรีบเรียกผู้ใหญ่มาจัดการทันที","ok":true},{"text":"ดึงปลั๊กออกเองให้เร็วที่สุด","ok":false,"why":"ปลั๊กที่ร้อนและชำรุดอาจทำให้ไฟดูดหรือมือพองได้"},{"text":"เอาน้ำราดที่ปลั๊กให้เย็นลง","ok":false,"why":"น้ำนำไฟฟ้า ราดน้ำใส่ปลั๊กอาจทำให้ไฟดูดได้"}],"answer":0}},{"text":"เอาเทปมาพันปลั๊กเพิ่มอีกหลายรอบ แล้วใช้ต่อ","score":0,"result":"เทปช่วยไม่ได้ ปลั๊กยังร้อนเหมือนเดิม และแม่ต้องมาถอดออกในภายหลัง"}]}]}', 'easy', 1),
('health_safety', 'ข้ามถนนหน้าโรงเรียน', '{"icon":"🚸","story":["ใบเฟิร์นเลิกเรียนแล้วจะข้ามถนนไปร้านเครื่องเขียนฝั่งตรงข้าม","ถนนหน้าโรงเรียนมีทางม้าลาย และรถวิ่งทางซ้ายของถนน"],"context":[{"type":"note","text":"ในประเทศไทย รถวิ่งชิดซ้าย รถคันที่ใกล้เราที่สุดจะมาจากทางขวามือก่อน"}],"steps":[{"kind":"order","prompt":"เรียงขั้นตอนการข้ามถนนอย่างปลอดภัย","skill":"rules","points":10,"hints":["ต้องหยุดก่อนจึงจะมองได้ทั่ว","รถคันแรกที่จะถึงตัวเรามาจากทางไหน"],"solution":["หยุดที่ขอบทางม้าลาย มองขวา มองซ้าย และมองขวาอีกครั้ง","เมื่อแน่ใจว่าไม่มีรถหรือรถหยุดแล้ว จึงเดินข้ามตรง ๆ โดยไม่วิ่ง"],"items":["หยุดยืนที่ขอบทางม้าลาย","มองทางขวา","มองทางซ้าย","มองทางขวาอีกครั้ง","เดินข้ามตรง ๆ โดยไม่วิ่งและไม่เล่นโทรศัพท์"]}]}', 'easy', 2),
('health_safety', 'พลัดหลงในห้าง', '{"icon":"🏬","story":["ภูผาไปห้างกับแม่ เขาเดินดูของเล่นเพลินจนหันกลับมาไม่เห็นแม่","รอบตัวมีคนเดินเยอะมาก ภูผาเริ่มใจเต้นแรง"],"tip":"จำเบอร์โทรของพ่อแม่ให้ได้ และนัดจุดเจอกันไว้ก่อนเข้าห้าง","context":[{"type":"note","text":"ในห้างมีพนักงานที่ใส่ชุดฟอร์มและป้ายชื่อ และมีจุดประชาสัมพันธ์"}],"steps":[{"kind":"scene","prompt":"ภูผาควรทำอย่างไร","skill":"decision","points":10,"hints":["ใครในห้างที่ไว้ใจได้และช่วยประกาศตามหาแม่ได้"],"solution":["เมื่อพลัดหลง ให้ตั้งสติ อยู่ในห้าง และขอให้พนักงานที่มีชุดฟอร์มหรือจุดประชาสัมพันธ์ช่วย","ไม่ออกไปนอกห้าง และไม่ไปกับคนแปลกหน้า"],"options":[{"text":"ตั้งสติ แล้วเดินไปหาพนักงานที่ใส่ชุดฟอร์มให้ช่วยประกาศตามหาแม่","score":1,"result":"พนักงานพาภูผาไปจุดประชาสัมพันธ์และประกาศชื่อแม่ ไม่กี่นาทีแม่ก็มารับ"},{"text":"วิ่งออกไปที่ลานจอดรถเพื่อรอแม่ที่รถ","score":0,"result":"ลานจอดรถมีรถวิ่งไปมาและไม่มีใครรู้จักภูผา เขายิ่งหาแม่ไม่เจอ","then":{"kind":"choice","prompt":"ภูผาอยู่ที่ลานจอดรถและหาแม่ไม่เจอ ควรทำอะไรต่อ","skill":"decision","points":10,"hints":["ที่ไหนปลอดภัยกว่าระหว่างลานจอดรถกับในห้าง"],"solution":["ลานจอดรถมีรถวิ่งและคนน้อย ควรกลับเข้าไปในห้างแล้วขอความช่วยเหลือจากพนักงาน"],"options":[{"text":"เดินกลับเข้าห้างทางเดิม แล้วขอให้พนักงานหรือ รปภ. ช่วยตามหาแม่","ok":true},{"text":"ยืนรอข้างถนนในลานจอดรถจนกว่าแม่จะมา","ok":false,"why":"ลานจอดรถมีรถถอยเข้าออก อันตราย และแม่อาจกำลังหาอยู่ในห้าง"},{"text":"ขอติดรถคนที่ผ่านมาให้ไปส่งที่บ้าน","ok":false,"why":"ไม่ควรไปกับคนแปลกหน้า เพราะอาจถูกพาไปที่อันตราย"}],"answer":0}},{"text":"นั่งร้องไห้อยู่ตรงนั้น ไม่พูดกับใครเลย","score":0.5,"result":"การอยู่กับที่ช่วยให้แม่หาเจอง่ายขึ้น แต่ภูผาเสียเวลานานกว่าจะมีพนักงานเดินมาเห็น"}]}]}', 'easy', 3),
('health_safety', 'ขวดน้ำยาใต้ซิงก์', '{"icon":"🧴","story":["มะปรางช่วยแม่ทำความสะอาดบ้าน","ใต้ซิงก์มีขวดหลายแบบ บางขวดมีรูปเตือนอันตรายที่ฉลาก"],"context":[{"type":"note","text":"น้ำยาล้างห้องน้ำ น้ำยาฟอกขาว และยาฆ่าแมลง เป็นสารเคมีที่ทำให้ระคายเคืองหรือเป็นพิษได้"}],"steps":[{"kind":"sort","prompt":"แยกว่างานไหนมะปรางทำได้ด้วยตนเอง และงานไหนต้องแจ้งผู้ใหญ่","skill":"analysis","points":10,"hints":["งานไหนต้องจับหรือผสมสารเคมีโดยตรง"],"solution":["งานที่ไม่ต้องจับสารเคมีอันตราย เด็กทำเองได้","งานที่เกี่ยวกับสารเคมีแรงหรือขวดที่รั่วหก ต้องให้ผู้ใหญ่จัดการ"],"bins":["ทำได้ด้วยตนเอง","ต้องแจ้งผู้ใหญ่"],"items":[{"text":"เช็ดโต๊ะด้วยผ้าชุบน้ำเปล่า","bin":0,"why":"ใช้แค่น้ำเปล่า ไม่มีสารเคมีอันตราย ทำเองได้"},{"text":"อ่านฉลากเพื่อดูว่าขวดไหนมีรูปเตือนอันตราย","bin":0,"why":"การอ่านฉลากโดยไม่เปิดขวดเป็นวิธีระวังภัยที่ทำเองได้"},{"text":"ขวดน้ำยาล้างห้องน้ำล้มและไหลนองพื้น","bin":1,"why":"น้ำยาที่หกอาจระคายผิวและมีไอระเหย ต้องให้ผู้ใหญ่เก็บกวาด"},{"text":"พบน้ำยาฆ่าแมลงวางอยู่ใกล้ขวดน้ำดื่ม","bin":1,"why":"อาจหยิบผิดจนดื่มเข้าไป ต้องบอกผู้ใหญ่ให้แยกเก็บที่ปลอดภัย"},{"text":"อยากผสมน้ำยาสองชนิดให้สะอาดเร็วขึ้น","bin":1,"why":"การผสมน้ำยาบางชนิดเกิดแก๊สพิษได้ ห้ามผสมเองเด็ดขาด"},{"text":"เก็บของเล่นที่วางเกะกะทางเดินเข้าที่","bin":0,"why":"เป็นงานป้องกันการสะดุดล้มที่ทำเองได้"}]}]}', 'easy', 4),
('health_safety', 'คนแปลกหน้าชวนดูลูกแมว', '{"icon":"🐱","story":["ระหว่างรอแม่มารับหน้าโรงเรียน ชายคนหนึ่งเดินมาหาน้องข้าวหอม","เขาบอกว่า \"ที่รถพี่มีลูกแมวน่ารัก ไปดูด้วยกันไหม\""],"tip":"จำไว้ว่า ปฏิเสธ ถอยห่าง และบอกผู้ใหญ่ที่ไว้ใจ","context":[{"type":"note","text":"ข้าวหอมไม่รู้จักชายคนนี้ และครูเวรยืนอยู่ที่ประตูโรงเรียน"}],"steps":[{"kind":"scene","prompt":"ข้าวหอมควรตอบสนองอย่างไร","skill":"decision","points":10,"hints":["ใครอยู่ใกล้ที่สุดที่ช่วยข้าวหอมได้"],"solution":["ไม่ไปกับคนแปลกหน้าไม่ว่าจะชวนด้วยของน่าสนใจแค่ไหน","ให้ปฏิเสธเสียงดัง ถอยไปหาผู้ใหญ่ที่ไว้ใจ แล้วเล่าให้ฟัง"],"options":[{"text":"พูดว่า \"ไม่ไปค่ะ\" แล้วเดินไปหาครูเวรที่ประตู เล่าให้ครูฟัง","score":1,"result":"ครูมาดูแลข้าวหอมจนแม่มารับ และแจ้ง รปภ. ให้ช่วยสังเกตชายคนนั้น"},{"text":"เดินตามไปดูแค่แป๊บเดียว เพราะรถจอดอยู่ใกล้ ๆ","score":0,"result":"ชายคนนั้นเปิดประตูรถและบอกให้ขึ้นไปดูข้างใน ข้าวหอมเริ่มรู้สึกไม่ปลอดภัย","then":{"kind":"choice","prompt":"ชายคนนั้นบอกให้ขึ้นรถ ข้าวหอมควรทำอย่างไร","skill":"decision","points":10,"hints":["ตอนนี้สิ่งสำคัญที่สุดคือออกห่างจากรถให้เร็วที่สุด"],"solution":["เมื่อรู้สึกไม่ปลอดภัย ให้ปฏิเสธเสียงดัง วิ่งกลับไปที่ที่มีผู้ใหญ่ที่ไว้ใจ และเล่าทันที"],"options":[{"text":"ตะโกนว่า \"ไม่ไป\" แล้ววิ่งกลับไปหาครูเวรทันที","ok":true},{"text":"ขึ้นรถไปดูลูกแมวแล้วรีบลงมา","ok":false,"why":"เมื่อขึ้นรถไปแล้ว อาจถูกปิดประตูและพาไปได้"},{"text":"ยืนคุยต่อเพื่อถามว่าเขาเป็นใคร","ok":false,"why":"ยิ่งอยู่ใกล้นานยิ่งเสี่ยง ควรออกห่างก่อนแล้วให้ผู้ใหญ่เป็นคนจัดการ"}],"answer":0}},{"text":"ยืนเงียบ ๆ ไม่ตอบ แต่ยังอยู่ตรงนั้น","score":0.5,"result":"ชายคนนั้นยังพยายามชวนต่อ ข้าวหอมไม่ได้ไปก็จริง แต่ยังไม่ได้ออกห่างหรือบอกใคร"}]}]}', 'easy', 5),
('health_safety', 'ห้องน้ำลื่น', '{"icon":"🛁","story":["คุณยายของน้องปุยฝ้ายเคยลื่นในห้องน้ำ","ปุยฝ้ายอยากช่วยทำให้ห้องน้ำที่บ้านปลอดภัยขึ้น"],"context":[{"type":"note","text":"การลื่นล้มในห้องน้ำมักเกิดจากพื้นเปียก มีคราบสบู่ หรือมีของวางเกะกะ"}],"steps":[{"kind":"multi","prompt":"เลือกทุกวิธีที่ช่วยป้องกันการลื่นล้มในห้องน้ำ","skill":"analysis","points":10,"hints":["คิดถึงสิ่งที่ทำให้พื้นลื่นและสิ่งที่ทำให้สะดุด"],"solution":["ทำพื้นให้แห้ง ใช้แผ่นกันลื่น และเก็บของให้เรียบร้อย ช่วยลดการลื่นล้ม","การวิ่งหรือเล่นในห้องน้ำเพิ่มความเสี่ยง"],"options":[{"text":"ใช้แผ่นยางกันลื่นในบริเวณที่อาบน้ำ","ok":true},{"text":"เช็ดพื้นให้แห้งหลังอาบน้ำเสร็จ","ok":true},{"text":"เก็บขวดสบู่และแชมพูไว้บนชั้น ไม่วางบนพื้น","ok":true},{"text":"วิ่งเข้าออกห้องน้ำให้เร็วจะได้ไม่เปียก","ok":false,"why":"การวิ่งบนพื้นเปียกทำให้ลื่นล้มง่ายขึ้น"},{"text":"เทแชมพูลงพื้นให้หอมก่อนอาบน้ำ","ok":false,"why":"แชมพูบนพื้นทำให้พื้นลื่นมากขึ้น"}]}]}', 'easy', 6),
('health_safety', 'มีดในครัว', '{"icon":"🔪","story":["น้องเอิร์ธช่วยแม่เตรียมผลไม้ในครัว","แม่ใช้มีดปอกเสร็จแล้ววางมีดไว้ริมโต๊ะ ปลายมีดยื่นออกมานอกขอบโต๊ะ"],"context":[{"type":"note","text":"น้องคนเล็กของเอิร์ธอายุ 3 ขวบ ชอบเดินเข้ามาในครัว"}],"steps":[{"kind":"choice","prompt":"เอิร์ธควรทำอย่างไรกับมีดเล่มนี้","skill":"decision","points":10,"hints":["ถ้าน้องเดินมาชนโต๊ะจะเกิดอะไรขึ้น","จับมีดตรงไหนจึงปลอดภัย"],"solution":["ของมีคมควรวางห่างจากขอบโต๊ะและเก็บให้พ้นมือเด็กเล็ก","ถ้าต้องหยิบ ให้จับที่ด้ามและหันปลายมีดลงพื้น หรือบอกแม่ให้เก็บ"],"options":[{"text":"บอกแม่ หรือจับที่ด้ามมีดหันปลายลง แล้ววางเข้าไปด้านในโต๊ะให้พ้นมือน้อง","ok":true},{"text":"ปล่อยไว้แบบเดิม เพราะแม่เป็นคนวาง","ok":false,"why":"มีดที่ยื่นออกนอกโต๊ะอาจหล่นหรือถูกน้องคว้า ควรช่วยทำให้ปลอดภัย"},{"text":"หยิบมีดที่ใบมีดแล้วยื่นให้น้องถือไปให้แม่","ok":false,"why":"จับใบมีดอาจโดนบาด และเด็ก 3 ขวบไม่ควรถือของมีคม"},{"text":"เอามีดไปซ่อนใต้หมอนให้น้องหาไม่เจอ","ok":false,"why":"ซ่อนมีดในที่แปลก ๆ ทำให้คนอื่นโดนบาดโดยไม่รู้ตัว ควรเก็บในที่เก็บมีด"}],"answer":0}]}', 'easy', 7),
('health_safety', 'ซ้อนท้ายมอเตอร์ไซค์', '{"icon":"🛵","story":["ลุงจะขี่มอเตอร์ไซค์พาน้องโฟมไปตลาดใกล้บ้าน ระยะทางแค่ 1 กิโลเมตร","ลุงยื่นหมวกกันน็อกให้ แต่โฟมบอกว่า \"ใกล้แค่นี้ไม่ต้องใส่ก็ได้มั้ง\""],"context":[{"type":"note","text":"ตามกฎหมาย ทั้งคนขี่และคนซ้อนต้องสวมหมวกกันน็อกทุกครั้ง"}],"steps":[{"kind":"choice","prompt":"โฟมควรทำอย่างไร","skill":"decision","points":10,"hints":["อุบัติเหตุเลือกเกิดเฉพาะทางไกลหรือเปล่า"],"solution":["สวมหมวกกันน็อกและรัดสายคางทุกครั้ง แม้เป็นระยะทางใกล้"],"options":[{"text":"สวมหมวกกันน็อกและรัดสายคางให้แน่นก่อนขึ้นรถ","ok":true},{"text":"ถือหมวกไว้ในมือ ถ้ามีตำรวจค่อยใส่","ok":false,"why":"หมวกในมือป้องกันศีรษะไม่ได้ อุบัติเหตุเกิดได้ทุกเมื่อ"},{"text":"ใส่หมวกแต่ไม่รัดสายคาง เพราะอึดอัด","ok":false,"why":"ถ้าไม่รัดสายคาง หมวกจะหลุดออกเมื่อล้ม"}],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องใส่หมวกกันน็อกแม้ไปใกล้ ๆ","skill":"reason","points":10,"hints":["หมวกกันน็อกปกป้องอวัยวะส่วนไหน"],"solution":["หมวกกันน็อกช่วยป้องกันศีรษะซึ่งเป็นส่วนที่บาดเจ็บรุนแรงได้ง่ายที่สุดเมื่อเกิดอุบัติเหตุ"],"options":[{"text":"เพราะช่วยป้องกันศีรษะเมื่อล้ม และอุบัติเหตุเกิดได้แม้ในระยะใกล้","ok":true},{"text":"เพราะจะได้ไม่ถูกตำรวจจับ","ok":false,"why":"กฎหมายเป็นเรื่องจริง แต่เหตุผลสำคัญคือความปลอดภัยของศีรษะ ไม่ใช่แค่กลัวถูกจับ"},{"text":"เพราะหมวกช่วยกันแดดและฝุ่น","ok":false,"why":"กันแดดได้ก็จริง แต่ไม่ใช่เหตุผลหลักของการสวมหมวกกันน็อก"}],"answer":0}]}', 'easy', 8),
('health_safety', 'จำเบอร์ฉุกเฉิน', '{"icon":"📞","story":["ครูให้น้องกันต์ทำบัตรเบอร์โทรฉุกเฉินติดไว้ข้างโทรศัพท์ที่บ้าน","กันต์ต้องจับคู่เหตุการณ์กับเบอร์ที่ถูกต้อง"],"context":[{"type":"table","title":"เบอร์โทรฉุกเฉิน","head":["เบอร์","หน่วยงาน"],"rows":[["1669","เจ็บป่วยฉุกเฉิน รถพยาบาล"],["199","ดับเพลิง"],["191","ตำรวจ"]]}],"steps":[{"kind":"plan","prompt":"เลือกเบอร์ที่ควรโทรสำหรับแต่ละเหตุการณ์","skill":"rules","points":10,"hints":["เหตุการณ์นี้ต้องการรถพยาบาล รถดับเพลิง หรือตำรวจ"],"solution":["เจ็บป่วยหรือบาดเจ็บรุนแรง โทร 1669","ไฟไหม้ โทร 199","มีคนร้ายหรือเหตุร้าย โทร 191"],"fields":[{"id":"f1","label":"คุณตาล้มหมดสติในบ้าน","options":[{"text":"1669","ok":true},{"text":"199","ok":false,"why":"199 คือดับเพลิง แต่คุณตาต้องการรถพยาบาล"},{"text":"191","ok":false,"why":"191 คือตำรวจ แต่คุณตาต้องการรถพยาบาล"}],"answer":0},{"id":"f2","label":"เห็นควันไฟพวยพุ่งจากบ้านข้าง ๆ","options":[{"text":"1669","ok":false,"why":"ไฟไหม้ต้องเรียกรถดับเพลิงที่ 199"},{"text":"199","ok":true},{"text":"191","ok":false,"why":"ไฟไหม้ต้องเรียกรถดับเพลิงที่ 199"}],"answer":1},{"id":"f3","label":"เห็นคนแปลกหน้างัดประตูบ้านเพื่อนบ้าน","options":[{"text":"1669","ok":false,"why":"เหตุร้ายแบบนี้ต้องแจ้งตำรวจที่ 191"},{"text":"199","ok":false,"why":"เหตุร้ายแบบนี้ต้องแจ้งตำรวจที่ 191"},{"text":"191","ok":true}],"answer":2}]}]}', 'easy', 9),
('health_safety', 'ข้อความล้อเลียนในกลุ่มแชต', '{"icon":"💬","story":["เพื่อนในกลุ่มแชตห้องเรียนเอารูปตลก ๆ ของน้องน้ำใสมาแต่งเติมแล้วล้อเลียน","หลายคนส่งสติกเกอร์หัวเราะ น้ำใสรู้สึกเสียใจมาก"],"tip":"ถูกรังแกออนไลน์ อย่าตอบโต้ เก็บหลักฐาน บล็อก และบอกผู้ใหญ่","context":[{"type":"note","text":"การรังแกออนไลน์ (Cyberbullying) คือการใช้ข้อความ รูป หรือคลิป ทำให้ผู้อื่นอับอายหรือเสียใจ"}],"steps":[{"kind":"scene","prompt":"น้ำใสควรทำอย่างไร","skill":"decision","points":10,"hints":["ถ้าตอบโต้กลับ เรื่องจะเบาลงหรือแรงขึ้น","หลักฐานสำคัญอย่างไร"],"solution":["ไม่ตอบโต้ เก็บภาพหน้าจอเป็นหลักฐาน แล้วบอกพ่อแม่หรือครู","ผู้ใหญ่ช่วยให้คนที่ทำลบรูปและหยุดการรังแกได้"],"options":[{"text":"ไม่ตอบโต้ แคปหน้าจอเก็บไว้ แล้วไปเล่าให้แม่และครูประจำชั้นฟัง","score":1,"result":"ครูคุยกับเพื่อนในห้อง เพื่อนลบรูปและขอโทษน้ำใส"},{"text":"พิมพ์ด่ากลับแรง ๆ ในกลุ่ม","score":0,"result":"เพื่อนบางคนเริ่มด่ากลับ เรื่องลุกลามจนทะเลาะกันทั้งกลุ่ม","then":{"kind":"choice","prompt":"เรื่องลุกลามไปแล้ว น้ำใสควรทำอะไรต่อ","skill":"decision","points":10,"hints":["ใครช่วยหยุดเรื่องนี้ได้ดีที่สุด"],"solution":["หยุดพิมพ์โต้ตอบ แล้วให้ผู้ใหญ่ช่วยจัดการ เพราะการโต้ตอบทำให้เรื่องลุกลาม"],"options":[{"text":"หยุดพิมพ์ เก็บภาพหน้าจอไว้ แล้วบอกพ่อแม่หรือครูให้ช่วย","ok":true},{"text":"สร้างกลุ่มใหม่เพื่อล้อเพื่อนคนที่เริ่มก่อนบ้าง","ok":false,"why":"การแก้แค้นทำให้เรากลายเป็นผู้รังแกเสียเอง"},{"text":"ลบแอปทิ้งแล้วไม่บอกใครเลย","ok":false,"why":"รูปยังอยู่ในกลุ่มและการรังแกอาจเกิดต่อ ควรให้ผู้ใหญ่ช่วย"}],"answer":0}},{"text":"เก็บเรื่องไว้คนเดียว เพราะกลัวถูกล้อหนักกว่าเดิม","score":0,"result":"รูปยังถูกส่งต่อไปเรื่อย ๆ และน้ำใสรู้สึกแย่ลงทุกวัน"}]}]}', 'easy', 10),
('health_safety', 'กลิ่นแก๊สในครัว', '{"icon":"🔥","story":["หลังเลิกเรียน น้องภูมิเดินเข้าครัวแล้วได้กลิ่นเหม็นคล้ายไข่เน่าแรงมาก","เตาแก๊สไม่ได้จุดไฟ แต่ปุ่มเตาหมุนค้างไว้ แม่กำลังตากผ้าอยู่หลังบ้าน"],"context":[{"type":"note","text":"แก๊สหุงต้มมีการเติมกลิ่นไว้ให้ได้กลิ่นเมื่อรั่ว ประกายไฟเล็ก ๆ จากสวิตช์ไฟหรือไฟแช็กทำให้แก๊สที่รั่วติดไฟได้"}],"steps":[{"kind":"scene","prompt":"ภูมิควรทำอะไรเป็นอย่างแรก","skill":"decision","points":10,"hints":["อะไรบ้างที่อาจทำให้เกิดประกายไฟ","แม่อยู่ใกล้แค่ไหน"],"solution":["เมื่อได้กลิ่นแก๊ส ห้ามกดสวิตช์ไฟหรือจุดไฟ","ออกห่างจากครัว และรีบบอกผู้ใหญ่ให้ปิดวาล์วแก๊สและเปิดประตูหน้าต่าง"],"options":[{"text":"ไม่แตะสวิตช์ไฟ ออกจากครัวแล้ววิ่งไปบอกแม่ที่หลังบ้าน","score":1,"result":"แม่ปิดวาล์วถังแก๊ส เปิดประตูหน้าต่างให้อากาศถ่ายเท แล้วพาภูมิออกไปรอข้างนอก"},{"text":"เปิดไฟในครัวเพื่อจะได้มองเห็นว่าแก๊สรั่วตรงไหน","score":0,"result":"โชคดีที่ไม่เกิดประกายไฟ แต่ภูมิยังอยู่ในครัวที่มีแก๊สรั่วอยู่","then":{"kind":"choice","prompt":"ภูมิยังอยู่ในครัวที่มีกลิ่นแก๊ส ควรทำอะไรต่อ","skill":"decision","points":10,"hints":["สิ่งที่ปลอดภัยที่สุดตอนนี้คือออกห่างหรือสำรวจต่อ"],"solution":["ไม่ควรสำรวจหาจุดรั่วเอง ให้ออกจากบริเวณนั้นและบอกผู้ใหญ่ทันที"],"options":[{"text":"ออกจากครัวทันที ไม่กดสวิตช์ใด ๆ แล้วไปบอกแม่","ok":true},{"text":"ก้มดูใกล้ ๆ ถังแก๊สเพื่อหาจุดรั่ว","ok":false,"why":"อยู่ใกล้แก๊สนานทำให้เวียนศีรษะ และการหาจุดรั่วเป็นงานของผู้ใหญ่"},{"text":"เปิดพัดลมไฟฟ้าเป่าไล่กลิ่น","ok":false,"why":"การเปิดเครื่องใช้ไฟฟ้าอาจเกิดประกายไฟจนแก๊สติดไฟ"}],"answer":0}},{"text":"เอาไฟแช็กมาจุดเตาให้ติด แก๊สจะได้ไม่รั่วออกมา","score":0,"result":"แม่วิ่งมาห้ามทัน และอธิบายว่าการจุดไฟตอนแก๊สรั่วอาจทำให้ลุกไหม้ทั้งครัว"}]},{"kind":"order","prompt":"เรียงขั้นตอนที่ถูกต้องเมื่อได้กลิ่นแก๊สรั่วในบ้าน","skill":"planning","points":10,"hints":["ต้องตั้งสติก่อนทำอย่างอื่น","โทรศัพท์ก็อาจเกิดประกายไฟ ควรโทรจากที่ไหน"],"solution":["ตั้งสติ ไม่ทำให้เกิดประกายไฟ ออกห่าง แล้วบอกผู้ใหญ่","ถ้ามีไฟลุกหรือแก๊สรั่วมาก ให้โทร 199 จากนอกบ้าน"],"items":["ตั้งสติ และไม่กดสวิตช์ไฟหรือจุดไฟ","ออกจากบริเวณที่มีกลิ่นแก๊ส","บอกผู้ใหญ่ให้ปิดวาล์วแก๊สและเปิดประตูหน้าต่าง","ถ้ารั่วมากหรือมีไฟ ให้ผู้ใหญ่โทร 199 จากนอกบ้าน"]}]}', 'medium', 11),
('health_safety', 'เพื่อนเป็นลมหน้าเสาธง', '{"icon":"😵","story":["ระหว่างเข้าแถวเคารพธงชาติตอนเช้า มีนาที่ยืนข้างน้องกิ๊ฟบ่นว่าตาลาย แล้วค่อย ๆ ทรุดลงนั่ง","มีนาหน้าซีด เหงื่อออก แต่ยังพูดตอบได้ เพื่อน ๆ เริ่มมามุงดู"],"context":[{"type":"note","text":"ครูประจำชั้นยืนอยู่ท้ายแถว ห่างไปประมาณ 10 ก้าว"},{"type":"note","text":"คนที่เป็นลมต้องการอากาศถ่ายเท การมุงดูทำให้อากาศไม่พอ"}],"steps":[{"kind":"scene","prompt":"กิ๊ฟควรทำอย่างไร","skill":"decision","points":10,"hints":["ใครอยู่ใกล้และช่วยดูแลมีนาได้ถูกวิธี"],"solution":["เมื่อเพื่อนเป็นลม ให้รีบเรียกครู และช่วยให้เพื่อนคนอื่นถอยออกให้อากาศถ่ายเท","ครูจะให้นอนราบในที่ร่ม คลายเสื้อผ้า และดูแลต่อ"],"options":[{"text":"ตะโกนเรียกครูทันที และบอกเพื่อน ๆ ให้ถอยออกไปไม่ให้มุง","score":1,"result":"ครูมาถึงเร็ว พามีนาไปนอนพักในที่ร่ม ไม่นานมีนาก็อาการดีขึ้น"},{"text":"พยุงมีนาให้ลุกยืนต่อ เพราะใกล้เคารพธงชาติเสร็จแล้ว","score":0,"result":"มีนาเซจะล้มอีกครั้ง กิ๊ฟต้องประคองไว้และยังไม่มีผู้ใหญ่มาช่วย"},{"text":"วิ่งไปซื้อน้ำหวานที่โรงอาหารมาให้มีนาดื่ม","score":0.5,"result":"กิ๊ฟหายไปนาน ระหว่างนั้นยังไม่มีใครเรียกครู เพื่อน ๆ ยังมุงมีนาอยู่"}]},{"kind":"order","prompt":"ถ้ามีนาไม่ตอบสนองและครูให้กิ๊ฟช่วยโทรขอความช่วยเหลือ เรียงขั้นตอนการโทรให้ถูก","skill":"planning","points":10,"hints":["ก่อนโทรต้องรู้ว่าจะโทรเบอร์อะไร","เจ้าหน้าที่ต้องรู้อะไรจึงจะมาถึงได้"],"solution":["โทร 1669 บอกอาการ บอกสถานที่ให้ชัดเจน แล้วรอคำแนะนำ ไม่วางสายก่อนเจ้าหน้าที่บอก"],"items":["ตั้งสติ แล้วโทร 1669","บอกว่ามีนักเรียนหมดสติและไม่ตอบสนอง","บอกชื่อโรงเรียนและจุดที่เกิดเหตุให้ชัดเจน","ทำตามคำแนะนำ และไม่วางสายจนเจ้าหน้าที่บอกให้วาง"]}]}', 'medium', 12),
('health_safety', 'เพื่อนตกสระน้ำ', '{"icon":"🏊","story":["น้องนนท์และเพื่อนไปเล่นที่สวนสาธารณะ ข้าง ๆ มีสระน้ำลึก","เพื่อนชื่อแบงค์ลื่นตกลงไปในสระ ตะเกียกตะกายและว่ายน้ำไม่เป็น นนท์ก็ว่ายน้ำไม่เก่ง"],"tip":"จำหลัก ตะโกน โยน ยื่น ช่วยจากบนฝั่ง ไม่กระโดดลงไป","context":[{"type":"note","text":"ริมสระมีห่วงยางชูชีพแขวนอยู่ที่เสา และมีลุงยามนั่งอยู่ที่ป้อมห่างไปไม่ไกล"}],"steps":[{"kind":"scene","prompt":"นนท์ควรทำอย่างไร","skill":"decision","points":10,"hints":["ถ้าคนว่ายน้ำไม่เก่งกระโดดลงไปช่วย จะเกิดอะไรขึ้น","ริมสระมีอุปกรณ์อะไรบ้าง"],"solution":["คนจมน้ำมักเกาะคนที่ลงไปช่วยจนจมทั้งคู่","ให้ตะโกนเรียกผู้ใหญ่ และโยนอุปกรณ์ลอยน้ำจากบนฝั่ง"],"options":[{"text":"ตะโกนเรียกลุงยาม แล้วโยนห่วงยางชูชีพให้แบงค์จากบนฝั่ง","score":1,"result":"แบงค์เกาะห่วงยางไว้ได้ ลุงยามวิ่งมาดึงเชือกพาแบงค์ขึ้นฝั่งอย่างปลอดภัย"},{"text":"กระโดดลงไปดึงแบงค์ขึ้นมาเอง","score":0,"result":"แบงค์ตกใจคว้าคอนนท์ไว้แน่น ทั้งคู่จมลง โชคดีที่ลุงยามได้ยินเสียงและวิ่งมาช่วย","then":{"kind":"choice","prompt":"หลังเหตุการณ์ ข้อคิดที่ถูกต้องที่สุดคือข้อใด","skill":"reason","points":10,"hints":["คนจมน้ำทำอะไรกับคนที่ลงไปช่วย"],"solution":["เด็กไม่ควรลงน้ำไปช่วยคนจมน้ำ ให้ช่วยจากบนฝั่งด้วยการตะโกน โยน ยื่น"],"options":[{"text":"ครั้งหน้าต้องช่วยจากบนฝั่ง ตะโกนเรียกผู้ใหญ่และโยนของลอยน้ำ เพราะคนจมน้ำจะเกาะคนช่วยจนจมทั้งคู่","ok":true},{"text":"ครั้งหน้าต้องกระโดดให้เร็วกว่านี้","ok":false,"why":"ความเร็วไม่ช่วย คนจมน้ำยังจะเกาะคนช่วยจนจมทั้งคู่"},{"text":"ครั้งหน้าต้องถอดเสื้อก่อนลงไปช่วย","ok":false,"why":"ปัญหาไม่ใช่เสื้อ แต่เป็นการลงไปในน้ำเอง ซึ่งอันตรายมาก"}],"answer":0}},{"text":"วิ่งกลับบ้านไปเรียกพ่อซึ่งอยู่ห่างไป 2 ซอย","score":0.5,"result":"นนท์ตั้งใจหาผู้ใหญ่ซึ่งถูกต้อง แต่บ้านไกลเกินไป ลุงยามที่อยู่ใกล้กว่าได้ยินเสียงคนอื่นเรียกจึงมาช่วยแทน"}]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องโยนห่วงยางแทนการยื่นมือไปดึง","skill":"reason","points":10,"hints":["ถ้ายื่นมือไป แล้วแบงค์ดึงแรง ๆ จะเป็นอย่างไร"],"solution":["การโยนอุปกรณ์ลอยน้ำทำให้ผู้ช่วยอยู่บนฝั่งอย่างปลอดภัย และผู้ประสบภัยมีของเกาะล