('health_safety', 'ควันจากถังขยะ', '{"icon":"🗑️","story":["ช่วงพักกลางวัน น้องฝ้ายเห็นควันลอยออกมาจากถังขยะหลังอาคารเรียน","มีเปลวไฟเล็ก ๆ อยู่ในถัง เพื่อนบางคนบอกว่าจะเอาน้ำในขวดไปราด"],"context":[{"type":"note","text":"ห้องครูอยู่ชั้นล่างของอาคารเดียวกัน และมีถังดับเพลิงติดผนังที่ทางเดิน"}],"steps":[{"kind":"scene","prompt":"ฝ้ายควรทำอย่างไร","skill":"decision","points":10,"hints":["ไฟเล็ก ๆ อาจลามใหญ่ได้เร็วแค่ไหน","ใครควรเป็นคนใช้ถังดับเพลิง"],"solution":["เด็กไม่ควรเข้าไปดับไฟเอง แม้ไฟจะเล็ก","ให้ออกห่าง ห้ามเพื่อนเข้าใกล้ และรีบแจ้งครูให้จัดการ"],"options":[{"text":"ชวนเพื่อนถอยออกห่าง แล้ววิ่งไปบอกครูที่ห้องครูทันที","score":1,"result":"ครูนำถังดับเพลิงมาดับไฟได้ และให้นักเรียนอยู่ห่างจากบริเวณนั้น"},{"text":"ยกถังดับเพลิงจากผนังมาฉีดเอง","score":0.5,"result":"ถังหนักมากและฝ้ายไม่รู้วิธีใช้ เสียเวลาไปนาน ครูที่ได้ยินเสียงจึงต้องมาช่วย"},{"text":"เข้าไปเป่าและใช้กิ่งไม้เขี่ยให้ไฟดับ","score":0,"result":"การเขี่ยทำให้ขยะที่ติดไฟปลิวออกมา ไฟลามไปที่ใบไม้แห้งรอบถัง ครูต้องรีบมาดับและพาเด็ก ๆ ออกห่าง"}]},{"kind":"sort","prompt":"แยกสิ่งที่ฝ้ายทำได้ด้วยตนเอง และสิ่งที่ต้องแจ้งผู้ใหญ่","skill":"analysis","points":10,"hints":["สิ่งไหนต้องเข้าใกล้ไฟหรือใช้อุปกรณ์ดับเพลิง"],"solution":["เด็กทำได้คือออกห่าง เตือนเพื่อน และไปแจ้ง","การดับไฟและใช้ถังดับเพลิงเป็นหน้าที่ของผู้ใหญ่"],"bins":["ทำได้ด้วยตนเอง","ต้องแจ้งผู้ใหญ่"],"items":[{"text":"บอกเพื่อน ๆ ให้ถอยออกห่างจากถังขยะ","bin":0,"why":"เป็นการป้องกันที่ทำเองได้โดยไม่ต้องเข้าใกล้ไฟ"},{"text":"วิ่งไปที่ห้องครูเพื่อแจ้งเหตุ","bin":0,"why":"การไปแจ้งเหตุเป็นสิ่งที่เด็กทำได้และควรทำ"},{"text":"ใช้ถังดับเพลิงดับไฟ","bin":1,"why":"ถังดับเพลิงหนักและต้องใช้อย่างถูกวิธี ควรให้ผู้ใหญ่ทำ"},{"text":"ตัดสินใจว่าจะโทร 199 หรือไม่","bin":1,"why":"ครูจะประเมินว่าไฟใหญ่แค่ไหนและต้องเรียกดับเพลิงหรือไม่"},{"text":"ตรวจดูว่าในถังขยะมีอะไรที่ทำให้ไฟติด","bin":1,"why":"ต้องเข้าใกล้ไฟและควันจึงอันตราย ให้ผู้ใหญ่ตรวจหลังไฟดับ"}]}]}', 'medium', 14),
('health_safety', 'สายไฟพัดลมห้องเรียน', '{"icon":"🌀","story":["ก่อนเริ่มเรียน หัวหน้าห้องชื่อน้องเพชรมีหน้าที่เปิดพัดลม","เพชรสังเกตเห็นสิ่งผิดปกติหลายอย่างรอบ ๆ พัดลมตั้งพื้น"],"context":[{"type":"table","title":"สิ่งที่เพชรสังเกตเห็น","head":["จุด","สภาพ"],"rows":[["สายไฟพัดลม","ฉนวนแตก เห็นทองแดงข้างใน"],["พื้นใต้พัดลม","มีน้ำหกจากถังน้ำดื่ม"],["ใบพัด","มีฝุ่นเกาะ"],["ปุ่มเปิดปิด","ใช้งานได้ปกติ"]]}],"steps":[{"kind":"multi","prompt":"เลือกทุกจุดที่อาจทำให้เกิดไฟดูด","skill":"analysis","points":10,"hints":["ไฟฟ้ากับน้ำเมื่ออยู่ใกล้กันอันตรายอย่างไร","อะไรควรห่อหุ้มสายทองแดงไว้"],"solution":["สายไฟที่ฉนวนแตกทำให้สัมผัสกระแสไฟได้โดยตรง","น้ำบนพื้นนำไฟฟ้า ทำให้ไฟรั่วมาถึงตัวเราได้"],"options":[{"text":"สายไฟที่ฉนวนแตกเห็นทองแดง","ok":true},{"text":"น้ำที่หกอยู่ใต้พัดลม","ok":true},{"text":"ฝุ่นที่ใบพัด","ok":false,"why":"ฝุ่นควรทำความสะอาด แต่ไม่ได้ทำให้ไฟดูด"},{"text":"ปุ่มเปิดปิดที่ใช้งานได้ปกติ","ok":false,"why":"ปุ่มที่ทำงานปกติไม่ใช่จุดเสี่ยงไฟดูด"}]},{"kind":"scene","prompt":"เพชรควรทำอย่างไรกับพัดลมตัวนี้","skill":"decision","points":10,"hints":["ใครควรจัดการสายไฟที่ชำรุด"],"solution":["ไม่ใช้และไม่จับอุปกรณ์ไฟฟ้าที่ชำรุด","เตือนเพื่อนให้อยู่ห่าง และแจ้งครูให้ตัดไฟและส่งซ่อม"],"options":[{"text":"ไม่เปิดพัดลม บอกเพื่อนอย่าเข้าใกล้ แล้วไปแจ้งครู","score":1,"result":"ครูให้ภารโรงตัดไฟ เช็ดพื้น และนำพัดลมไปเปลี่ยนสายไฟใหม่"},{"text":"เปิดพัดลมตามหน้าที่ เพราะอากาศร้อนมาก","score":0,"result":"พัดลมหมุนได้ แต่เพื่อนคนหนึ่งเดินเหยียบน้ำแล้วรู้สึกเหมือนไฟช็อตเบา ๆ ที่เท้า","then":{"kind":"choice","prompt":"เพื่อนบอกว่ารู้สึกเหมือนไฟช็อต เพชรควรทำอะไรต่อ","skill":"decision","points":10,"hints":["ใครควรเป็นคนตัดไฟ","ทุกคนควรอยู่ตรงไหน"],"solution":["เมื่อมีอาการไฟรั่ว ให้ทุกคนออกห่างจากจุดนั้นและรีบตามครูมาตัดไฟ"],"options":[{"text":"บอกทุกคนออกห่างจากพัดลมและพื้นเปียก แล้วรีบตามครูมาตัดไฟ","ok":true},{"text":"เดินลุยน้ำเข้าไปถอดปลั๊กพัดลม","ok":false,"why":"การเหยียบน้ำที่มีไฟรั่วแล้วจับปลั๊กอาจทำให้ถูกไฟดูดรุนแรง"},{"text":"เอาผ้ามาเช็ดน้ำใต้พัดลมให้แห้ง","ok":fals