:["ภาพหน้าจอเป็นหลักฐานให้ผู้ใหญ่และโรงเรียนใช้จัดการปัญหา แม้โพสต์จะถูกลบไปแล้ว"],"options":[{"text":"เป็นหลักฐานให้ผู้ใหญ่ใช้จัดการปัญหา แม้โพสต์จะถูกลบไปแล้ว","ok":true},{"text":"เอาไว้ส่งต่อให้เพื่อนดูว่าใครเป็นคนทำ","ok":false,"why":"การส่งต่อทำให้คลิปแพร่กระจายมากขึ้น หลักฐานควรให้ผู้ใหญ่เท่านั้น"},{"text":"เอาไว้ดูซ้ำเพื่อจำว่าใครว่าร้ายเรา","ok":false,"why":"ดูซ้ำทำให้เสียใจมากขึ้น จุดประสงค์ของหลักฐานคือให้ผู้ใหญ่ช่วยจัดการ"}],"answer":0}]}', 'medium', 16),
('health_safety', 'เพื่อนในเกมขอนัดเจอ', '{"icon":"🎮","story":["น้องโอ๊ตเล่นเกมออนไลน์กับผู้เล่นคนหนึ่งมาหลายเดือน คนนั้นบอกว่าอายุ 11 ปีเหมือนกัน","วันหนึ่งเขาขอที่อยู่บ้านและชวนนัดเจอที่ร้านเกมโดยบอกว่า \"อย่าบอกพ่อแม่นะ\""],"context":[{"type":"note","text":"คนในโลกออนไลน์อาจไม่ใช่คนที่เขาบอก เราไม่สามารถยืนยันอายุหรือตัวตนจริงได้จากการแชต"}],"steps":[{"kind":"scene","prompt":"โอ๊ตควรทำอย่างไร","skill":"decision","points":10,"hints":["คำว่า \"อย่าบอกพ่อแม่\" เป็นสัญญาณอะไร"],"solution":["ไม่ให้ข้อมูลส่วนตัว ไม่นัดเจอคนที่รู้จักทางออนไลน์","การขอให้เก็บเป็นความลับจากพ่อแม่เป็นสัญญาณอันตราย ต้องบอกผู้ใหญ่ทันที"],"options":[{"text":"ไม่บอกที่อยู่ ไม่ไปตามนัด แล้วให้พ่อแม่ดูแชตทั้งหมด","score":1,"result":"พ่อช่วยรายงานและบล็อกบัญชีนั้น และสอนวิธีตั้งค่าความเป็นส่วนตัวในเกม"},{"text":"ไปเจอแต่ชวนเพื่อนอีกคนไปด้วย","score":0,"result":"คนที่มาตามนัดเป็นผู้ใหญ่ที่โอ๊ตไม่รู้จัก โอ๊ตตกใจมากจึงรีบพาเพื่อนกลับ และไม่กล้าบอกใคร"},{"text":"ไม่ไปตามนัด แต่บอกที่อยู่บ้านไปเพราะเกรงใจ","score":0,"result":"คนนั้นส่งข้อความมาบอกว่าจะมาหาที่บ้าน โอ๊ตเริ่มกลัวมาก"}]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ไม่ควรนัดเจอคนที่รู้จักแค่ทางออนไลน์","skill":"reason","points":10,"hints":["เรารู้ได้อย่างไรว่าเขาอายุ 11 ปีจริง"],"solution":["คนออนไลน์อาจปลอมตัวตนได้ การนัดเจอโดยไม่มีผู้ใหญ่รู้อาจทำให้ตกอยู่ในอันตราย"],"options":[{"text":"เพราะเราไม่รู้ตัวตนจริงของเขา และเขาอาจหลอกเรื่องอายุหรือความตั้งใจ","ok":true},{"text":"เพราะร้านเกมเสียงดัง คุยกันไม่รู้เรื่อง","ok":false,"why":"สถานที่ไม่ใช่ปัญหาหลัก ปัญหาคือเราไม่รู้ว่าเขาเป็นใครจริง"},{"text":"เพราะเขาเล่นเกมเก่งกว่าเรา","ok":false,"why":"ความเก่งในเกมไม่เกี่ยวกับความปลอดภัย"}],"answer":0}]}', 'medium', 17),
('health_safety', 'คุณยายลื่นในห้องน้ำ', '{"icon":"🚿","story":["น้องแพรวได้ยินเสียงดังจากห้องน้ำ เมื่อไปดูก็พบว่าคุณยายลื่นล้มนั่งอยู่บนพื้น","คุณยายบอกว่าเจ็บที่สะโพกมาก ขยับขาไม่ได้ ที่บ้านมีแค่แพรวกับคุณยาย"],"context":[{"type":"note","text":"ผู้สูงอายุที่ล้มแล้วเจ็บมากหรือขยับไม่ได้ อาจกระดูกหัก การพยายามดึงให้ลุกอาจทำให้บาดเจ็บมากขึ้น"}],"steps":[{"kind":"scene","prompt":"แพรวควรทำอย่างไร","skill":"decision","points":10,"hints":["ถ้าดึงคุณยายขึ้นแล้วกระดูกหักจะเป็นอย่างไร","ที่บ้านไม่มีผู้ใหญ่คนอื่น จะขอความช่วยเหลือจากใครได้"],"solution":["ไม่ดึงคนที่บาดเจ็บรุนแรงให้ลุกเอง","อยู่เป็นเพื่อน โทรหาพ่อแม่หรือ 1669 และเรียกเพื่อนบ้านที่เป็นผู้ใหญ่มาช่วย"],"options":[{"text":"ไม่ดึงคุณยาย หยิบผ้าขนหนูมาห่มให้อุ่น แล้วโทร 1669 และโทรบอกแม่","score":1,"result":"เจ้าหน้าที่ 1669 แนะนำให้คุณยายอยู่นิ่ง ๆ และมาถึงพร้อมเปลหาม แม่รีบกลับมาที่บ้าน"},{"text":"ออกแรงดึงแขนคุณยายให้ลุกขึ้นเดินไปนอนบนเตียง","score":0,"result":"คุณยายร้องเจ็บมากขึ้น แพรวดึงไม่ไหว ทั้งคู่เกือบลื่นล้มซ้ำ"},{"text":"วิ่งไปเรียกป้าข้างบ้านมาช่วยดู","score":0.5,"result":"ป้าข้างบ้านมาช่วยโทร 1669 ให้ ซึ่งดีกว่าอยู่คนเดียว แต่เสียเวลาไปและคุณยายต้องอยู่ลำพังระหว่างนั้น"}]},{"kind":"order","prompt":"เรียงสิ่งที่แพรวต้องบอกเจ้าหน้าที่ 1669","skill":"planning","points":10,"hints":["เจ้าหน้าที่ต้องรู้ก่อนว่าเกิดอะไร แล้วจึงต้องรู้ว่าจะมาที่ไหน"],"solution":["บอกว่าเกิดอะไรขึ้น อาการ สถานที่ และเบอร์ติดต่อ เพื่อให้เจ้าหน้าที่มาถึงได้เร็ว"],"items":["บอกว่าคุณยายลื่นล้มในห้องน้ำ","บอกอาการว่าเจ็บสะโพก ขยับขาไม่ได้ แต่ยังพูดได้","บอกบ้านเลขที่ ซอย และจุดสังเกตใกล้บ้าน","บอกเบอร์โทรที่ติดต่อกลับได้ และรอฟังคำแนะนำ"]}]}', 'medium', 18),
('health_safety', 'ปั่นจักรยานไปโรงเรียน', '{"icon":"🚲","story":["น้องเก่งได้จักรยานคันใหม่ และขออนุญาตแม่ปั่นไปโรงเรียนซึ่งต้องผ่านถนนในหมู่บ้าน","ก่อนออกจากบ้าน แม่ให้เก่งตรวจความพร้อม"],"context":[{"type":"table","title":"สภาพจักรยานและตัวเก่ง","head":["รายการ","สภาพ"],"rows":[["เบรก","บีบแล้วล้อหยุด"],["ยางล้อหลัง","แบนเกือบหมด"],["หมวกจักรยาน","อยู่ในตู้ ยังไม่ได้ใส่"],["กระดิ่ง","กดดังปกติ"],["เชือกผูกรองเท้า","หลุดลุ่ย"]]}],"steps":[{"kind":"multi","prompt":"เลือกทุกอย่างที่เก่งต้องแก้ก่อนออกเดินทาง","skill":"analysis","points":10,"hints":["อ่านคอลัมน์สภาพทีละแถว อะไรยังไม่พร้อม"],"solution":["ยางแบนทำให้ควบคุมรถยาก หมวกต้องสวมทุกครั้ง และเชือกรองเท้าอาจพันโซ่จนล้ม"],"options":[{"text":"สูบลมยางล้อหลัง","ok":true},{"text":"สวมหมวกจักรยานและรัดสายคาง","ok":true},{"text":"ผูกเชือกรองเท้าให้เรียบร้อย","ok":true},{"text":"เปลี่ยนเบรกใหม่","ok":false,"why":"เบรกบีบแล้วล้อหยุด แปลว่ายังใช้งานได้ดี"},{"text":"ซื้อกระดิ่งอันใหม่","ok":false,"why":"กระดิ่งยังกดดังปกติ ไม่ต้องเปลี่ยน"}]},{"kind":"scene","prompt":"ระหว่างทาง เพื่อนชวนปั่นแข่งกันแบบปล่อยมือทั้งสองข้าง เก่งควรทำอย่างไร","skill":"decision","points":10,"hints":["ปล่อยมือแล้วจะเบรกได้ทันหรือไม่ถ้ามีรถออกจากซอย"],"solution":["ต้องจับแฮนด์ทั้งสองมือ ปั่นชิดซ้าย และไม่ปั่นแข่งบนถนน","การปฏิเสธเพื่อนอย่างสุภาพเป็นความกล้าที่ถูกต้อง"],"options":[{"text":"ปฏิเสธ แล้วปั่นชิดซ้ายโดยจับแฮนด์ทั้งสองมือตามปกติ","score":1,"result":"มีรถถอยออกจากบ้านข้างทาง เก่งเบรกได้ทันเพราะมือจับแฮนด์อยู่"},{"text":"ลองปล่อยมือแข่งแค่ช่วงสั้น ๆ","score":0,"result":"มีรถถอยออกจากบ้านข้างทาง เก่งคว้าแฮนด์ไม่ทัน ต้องหักหลบจนล้มลงข้างทาง ถลอกที่เข่าเล็กน้อย","then":{"kind":"choice","prompt":"เก่งล้มมีแผลถลอกเล็กน้อยที่เข่า จักรยานโซ่หลุด ควรทำอย่างไรต่อ","skill":"decision","points":10,"hints":["ตอนนี้อยู่บนถนน ควรอยู่ตรงไหนก่อน"],"solution":["ย้ายตัวเองและจักรยานออกจากถนนก่อน แผลถลอกเล็กน้อยล้างด้วยน้ำสะอาด แล้วบอกครูหรือผู้ปกครอง"],"options":[{"text":"จูงจักรยานออกไปข้างทาง แล้วบอกครูหรือโทรบอกแม่ให้ช่วยดูแผล","ok":true},{"text":"นั่งใส่โซ่จักรยานกลางถนนให้เสร็จก่อน","ok":false,"why":"อยู่กลางถนนเสี่ยงถูกรถชน ต้องออกไปข้างทางก่อน"},{"text":"รีบปั่นต่อไปโดยไม่บอกใคร เพราะกลัวถูกดุ","ok":false,"why":"ผู้ใหญ่ควรรู้เพื่อช่วยดูแผลและซ่อมจักรยานให้ปลอดภัย"}],"answer":0}},{"text":"ไม่ปล่อยมือ แต่ปั่นแข่งเร็ว ๆ แซงกลางถนน","score":0,"result":"มีรถยนต์ตามมาข้างหลัง ต้องบีบแตรเตือน เก่งตกใจเกือบเสียหลัก"}]}]}', 'medium', 19),
('health_safety', 'หลงทางในงานวัด', '{"icon":"🎡","story":["น้องข้าวตังไปงานวัดกับพี่สาว คนเยอะมากจนพลัดกัน","ข้าวตังไม่มีโทรศัพท์ แต่จำเบอร์แม่ได้ และในงานมีเต็นท์ประชาสัมพันธ์ที่มีเครื่องขยายเสียง"],"context":[{"type":"note","text":"ก่อนเข้างาน พี่สาวนัดไว้ว่าถ้าหลงกันให้ไปเจอที่เต็นท์ประชาสัมพันธ์"},{"type":"note","text":"มีผู้ชายคนหนึ่งเข้ามาบอกว่าจะพาไปตามหาพี่ที่ลานจอดรถหลังวัด"}],"steps":[{"kind":"scene","prompt":"ข้าวตังควรทำอย่างไร","skill":"decision","points":10,"hints":["พี่สาวนัดเจอกันไว้ที่ไหน","ลานจอดรถหลังวัดมีคนพลุกพล่านหรือเปลี่ยว"],"solution":["ทำตามจุดนัดหมายที่ตกลงกันไว้ และขอความช่วยเหลือจากเจ้าหน้าที่ของงาน","ไม่ไปกับคนแปลกหน้า โดยเฉพาะไปยังที่เปลี่ยว"],"options":[{"text":"ขอบคุณแต่ปฏิเสธผู้ชายคนนั้น แล้วเดินไปเต็นท์ประชาสัมพันธ์ตามที่นัดไว้","score":1,"result":"เจ้าหน้าที่ประกาศชื่อพี่สาว พี่สาวรีบมารับที่เต็นท์"},{"text":"ไปกับผู้ชายคนนั้น เพราะเขาดูใจดี","score":0,"result":"ลานจอดรถหลังวัดมืดและเงียบ ข้าวตังรู้สึกไม่ปลอดภัยจึงวิ่งกลับเข้ามาในงานที่มีคนเยอะ ตัวสั่นไปหมด"},{"text":"เดินวนหาพี่ไปทั่วงาน","score":0.5,"result":"ข้าวตังไม่ได้ไปกับใคร แต่พี่สาวไปรอที่เต็นท์ตามนัด ทั้งคู่จึงสวนกันไปมานานกว่าจะเจอ"}]},{"kind":"plan","prompt":"เลือกสิ่งที่ข้าวตังควรทำในแต่ละเรื่อง","skill":"planning","points":10,"hints":["ข้อมูลอะไรที่ช่วยให้คนอื่นติดต่อพ่อแม่ได้"],"solution":["ขอความช่วยเหลือจากเจ้าหน้าที่ของงาน บอกชื่อตัวเองและเบอร์แม่ และรออยู่ที่จุดนัด"],"fields":[{"id":"f1","label":"ขอความช่วยเหลือจาก","options":[{"text":"เจ้าหน้าที่ที่เต็นท์ประชาสัมพันธ์","ok":true},{"text":"คนที่ยืนขายลูกโป่งคนเดียวท้ายงาน","ok":false,"why":"จุดประชาสัมพันธ์มีเจ้าหน้าที่และเครื่องขยายเสียงช่วยตามหาได้ดีกว่า"},{"text":"วัยรุ่นกลุ่มที่ยืนอยู่หน้าเวที","ok":false,"why":"ควรขอความช่วยเหลือจากเจ้าหน้าที่ของงานที่มีหน้าที่ดูแล"}],"answer":0},{"id":"f2","label":"ข้อมูลที่บอกเจ้าหน้าที่","options":[{"text":"ชื่อตัวเอง ชื่อพี่สาว และเบอร์โทรแม่","ok":true},{"text":"รหัสผ่านโทรศัพท์ของแม่","ok":false,"why":"รหัสผ่านเป็นข้อมูลส่วนตัว ไม่จำเป็นต่อการตามหา"},{"text":"ไม่บอกอะไรเลย","ok":false,"why":"ถ้าไม่บอกชื่อและเบอร์โทร เจ้าหน้าที่จะตามหาพี่ไม่ได้"}],"answer":0},{"id":"f3","label":"ระหว่างรอ","options":[{"text":"อยู่ที่เต็นท์ประชาสัมพันธ์จนพี่มารับ","ok":true},{"text":"ออกไปรอที่ถนนหน้าวัด","ok":false,"why":"ถ้าย้ายที่ พี่ที่มาตามนัดจะหาไม่เจอ และถนนมีรถวิ่ง"},{"text":"เดินไปซื้อขนมแล้วค่อยกลับมา","ok":false,"why":"ควรอยู่ที่จุดนัดตลอด เพื่อให้พี่หาเจอทันที"}],"answer":0}]}]}', 'medium', 20),
('health_safety', 'กระทะน้ำมันลุกไหม้', '{"icon":"🍳","story":["น้องมิวช่วยแม่ทำไก่ทอด แม่ออกไปรับพัสดุหน้าบ้าน ทิ้งกระทะน้ำมันตั้งไฟไว้","ไม่นานน้ำมันในกระทะเกิดควันและลุกเป็นไฟ ข้างเตามีขันน้ำ ฝาหม้อ และผ้าขนหนูเปียก"],"tip":"ไฟจากน้ำมันห้ามใช้น้ำดับเด็ดขาด","context":[{"type":"table","title":"สิ่งที่อยู่ในครัว","head":["สิ่งของ","อยู่ที่ไหน"],"rows":[["ขันน้ำ","ข้างซิงก์"],["ฝาหม้อใบใหญ่","ข้างเตา"],["ประตูครัว","เปิดออกไปหน้าบ้าน"],["แม่","หน้าบ้าน ห่างไปประมาณ 15 ก้าว"]]},{"type":"note","text":"น้ำหนักกว่าน้ำมัน เมื่อเทน้ำลงในน้ำมันร้อน น้ำจะเดือดเป็นไอทันทีและดันน้ำมันติดไฟให้กระเด็นออกมา"}],"steps":[{"kind":"scene","prompt":"มิวควรทำอย่างไรทันที","skill":"decision","points":10,"hints":["อ่านข้อมูลเรื่องน้ำกับน้ำมันอีกครั้ง","ใครอยู่ใกล้และดับไฟได้อย่างปลอดภัยกว่า"],"solution":["ห้ามเทน้ำใส่ไฟจากน้ำมัน เพราะไฟจะลุกพุ่งแรงขึ้น","เด็กควรออกห่างจากไฟและเรียกผู้ใหญ่ทันที ผู้ใหญ่จะปิดเตาและปิดฝาให้ไฟดับ"],"options":[{"text":"ออกจากครัวทางประตู แล้วตะโกนเรียกแม่ว่ากระทะไฟไหม้","score":1,"result":"แม่รีบเข้ามาปิดเตาแก๊สและเอาฝาหม้อปิดกระทะ ไฟดับลงเพราะขาดอากาศ"},{"text":"ตักน้ำจากขันราดลงไปในกระทะ","score":0,"result":"ไฟพุ่งขึ้นสูงจนถึงตู้ด้านบน น้ำมันกระเด็น มิวถอยหลังทันและไม่โดนตัว แต่ไฟเริ่มลามไปที่ตู้","then":{"kind":"order","prompt":"ไฟลามไปที่ตู้แล้ว เรียงสิ่งที่มิวต้องทำต่อ","skill":"planning","points":10,"hints":["อะไรสำคัญที่สุดตอนนี้ ระหว่างของในบ้านกับตัวเรา"],"solution":["เมื่อไฟลาม ให้ออกจากบ้านก่อน แล้วบอกผู้ใหญ่และโทร 199 จากที่ปลอดภัย","ห้ามกลับเข้าไปเอาของ"],"items":["ออกจากบ้านทันที ไม่กลับไปเอาของ","ตะโกนบอกแม่และเพื่อนบ้านว่าไฟไหม้","ให้ผู้ใหญ่โทร 199 บอกที่อยู่บ้านให้ชัดเจน","รออยู่นอกบ้านในที่ปลอดภัยจนเจ้าหน้าที่มาถึง"]}},{"text":"เอาผ้าขนหนูเปียกฟาดไฟให้ดับ","score":0,"result":"การฟาดทำให้น้ำมันกระฉอกและไฟกระเด็น มิวตกใจถอยออกมา แม่ได้ยินเสียงจึงวิ่งเข้ามาช่วย"},{"text":"ปิดเตาแก๊สก่อน แล้วค่อยไปเรียกแม่","score":0.5,"result":"ปิดเตาได้ แต่มิวต้องเอื้อมมือเข้าใกล้ไฟ ซึ่งเสี่ยงโดนไฟลวก แม่บอกว่าครั้งหน้าให้ออกมาเรียกเลย"}]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ฝาหม้อดับไฟในกระทะได้ แต่น้ำทำให้แย่ลง","skill":"reason","points":10,"hints":["ไฟต้องการอะไรจึงลุกอยู่ได้","อ่านข้อมูลเรื่องน้ำกับน้ำมันร้อน"],"solution":["ไฟต้องใช้อากาศ การปิดฝาตัดอากาศทำให้ไฟดับ","น้ำจะเดือดเป็นไอทันทีและดันน้ำมันติดไฟกระเด็นออกมา"],"options":[{"text":"ฝาตัดอากาศที่ไฟต้องใช้ แต่น้ำจะกลายเป็นไอทันทีและดันน้ำมันติดไฟให้กระเด็น","ok":true},{"text":"ฝาหม้อเป็นโลหะจึงเย็นกว่าน้ำ","ok":false,"why":"ความเย็นของฝาไม่ใช่เหตุผล ฝาดับไฟได้เพราะตัดอากาศ"},{"text":"น้ำในขันมีปริมาณน้อยเกินไป ถ้าใช้น้ำมากกว่านี้จะดับได้","ok":false,"why":"น้ำยิ่งมาก ไอน้ำยิ่งดันน้ำมันติดไฟกระจายมากขึ้น ห้ามใช้น้ำเลย"},{"text":"ฝาหม้อทำให้แก๊สหยุดไหล","ok":false,"why":"ฝาไม่ได้ปิดแก๊ส ต้องปิดที่ปุ่มเตาหรือวาล์ว ฝาดับไฟเพราะตัดอากาศ"}],"answer":0},{"kind":"multi","prompt":"เลือกทุกวิธีที่ช่วยป้องกันไม่ให้เกิดไฟไหม้กระทะน้ำมันแบบนี้อีก","skill":"analysis","points":10,"hints":["ไฟเริ่มเพราะอะไรในเรื่องนี้"],"solution":["ไม่ทิ้งเตาที่เปิดไฟไว้โดยไม่มีผู้ใหญ่ดู และให้ผู้ใหญ่ปิดเตาก่อนออกจากครัวเสมอ"],"options":[{"text":"ปิดเตาทุกครั้งก่อนเดินออกจากครัว","ok":true},{"text":"ไม่ปล่อยให้เด็กอยู่กับเตาที่เปิดไฟลำพัง","ok":true},{"text":"วางฝาหม้อขนาดพอดีไว้ใกล้เตาเสมอเวลาทอด","ok":true},{"text":"เตรียมถังน้ำไว้ข้างเตาสำหรับดับไฟกระทะ","ok":false,"why":"น้ำใช้ดับไฟจากน้ำมันไม่ได้ จะทำให้ไฟลุกแรงขึ้น"},{"text":"เปิดไฟแรงสุดให้ทอดเสร็จเร็ว ๆ","ok":false,"why":"ไฟแรงทำให้น้ำมันร้อนจัดจนลุกไหม้ได้ง่ายขึ้น"}]}]}', 'hard', 21),
('health_safety', 'ไดร์เป่าผมตกอ่างน้ำ', '{"icon":"💇","story":["น้องพลอยใช้ไดร์เป่าผมในห้องน้ำ มือยังเปียกจากการล้างหน้า","ไดร์ที่ยังเสียบปลั๊กอยู่หลุดมือตกลงไปในอ่างล้างหน้าที่มีน้ำเต็ม"],"context":[{"type":"table","title":"สิ่งที่พลอยเห็นตอนนี้","head":["สิ่งที่เห็น","สภาพ"],"rows":[["ไดร์เป่าผม","จมอยู่ในอ่าง สายยังเสียบปลั๊ก"],["มือของพลอย","เปียก"],["พื้นห้องน้ำ","มีน้ำนอง"],["ตู้ไฟ (เบรกเกอร์)","อยู่ที่ผนังข้างประตูหน้าบ้าน"],["พ่อ","อยู่ในห้องนั่งเล่น"]]},{"type":"note","text":"ไฟฟ้าวิ่งผ่านน้ำและร่างกายที่เปียกได้ง่าย การสับเบรกเกอร์ลงจะตัดไฟทั้งบ้าน"}],"steps":[{"kind":"scene","prompt":"พลอยควรทำอย่างไร","skill":"decision","points":10,"hints":["มือเปียกกับพื้นเปียก ทำให้การจับปลั๊กอันตรายแค่ไหน","ใครตัดไฟทั้งบ้านได้อย่างปลอดภัย"],"solution":["ห้ามแตะไดร์ ห้ามล้วงน้ำ และห้ามดึงปลั๊กด้วยมือเปียก","ออกจากห้องน้ำแล้วเรียกพ่อให้สับเบรกเกอร์ตัดไฟก่อน จึงค่อยเก็บไดร์"],"options":[{"text":"ไม่แตะอะไรเลย ค่อย ๆ ออกจากห้องน้ำ แล้วเรียกพ่อให้ไปตัดไฟที่เบรกเกอร์","score":1,"result":"พ่อสับเบรกเกอร์ลง แล้วจึงถอดปลั๊กและนำไดร์ออกจากอ่าง ไดร์ตัวนั้นถูกทิ้งไป ไม่นำมาใช้อีก"},{"text":"รีบล้วงมือลงไปหยิบไดร์ขึ้นจากน้ำ","score":0,"result":"พ่อที่เดินผ่านมาตะโกนห้ามได้ทันก่อนพลอยจะแตะน้ำ พ่อบอกว่าน้ำในอ่างอาจมีไฟฟ้าอยู่"},{"text":"ดึงปลั๊กไดร์ออกจากเต้ารับทันที","score":0,"result":"พลอยเอื้อมมือเปียกไปที่ปลั๊ก แต่รู้สึกเหมือนมีไฟช็อตที่ปลายนิ้วจึงชักมือกลับ พลอยตกใจมากแต่ไม่ได้รับบาดเจ็บ","then":{"kind":"choice","prompt":"พลอยรู้สึกเหมือนไฟช็อตที่นิ้ว และยังยืนบนพื้นเปียก ควรทำอย่างไรต่อ","skill":"decision","points":10,"hints":["ตอนนี้ยังมีไฟอยู่ในห้องน้ำหรือไม่"],"solution":["ออกห่างจากน้ำและอุปกรณ์ไฟฟ้า เรียกผู้ใหญ่มาตัดไฟ และบอกผู้ใหญ่ว่าโดนไฟช็อต เพื่อให้ช่วยดูอาการ"],"options":[{"text":"ไม่ลองดึงซ้ำ ออกจากห้องน้ำ แล้วบอกพ่อว่าโดนไฟช็อตและให้พ่อตัดไฟที่เบรกเกอร์","ok":true},{"text":"เอาผ้ามาเช็ดมือให้แห้งแล้วกลับไปดึงปลั๊กอีกครั้ง","ok":false,"why":"พื้นยังเปียกและไดร์ยังจมน้ำ ไม่ควรจับปลั๊กเอง ให้ผู้ใหญ่ตัดไฟที่เบรกเกอร์"},{"text":"ไม่บอกใคร เพราะกลัวพ่อดุเรื่องทำไดร์ตก","ok":false,"why":"ไฟยังรั่วอยู่ในห้องน้ำ และผู้ใหญ่ควรรู้ว่าพลอยโดนไฟช็อต"}],"answer":0}}]},{"kind":"sort","prompt":"แยกสิ่งที่พลอยทำได้ด้วยตนเอง และสิ่งที่ต้องแจ้งผู้ใหญ่","skill":"analysis","points":10,"hints":["สิ่งไหนต้องแตะไฟฟ้าหรือน้ำที่อาจมีไฟ"],"solution":["เด็กทำได้คือออกห่าง เตือนคนอื่น และเรียกผู้ใหญ่","การตัดไฟ ถอดปลั๊ก และตรวจอุปกรณ์ เป็นงานของผู้ใหญ่"],"bins":["ทำได้ด้วยตนเอง","ต้องแจ้งผู้ใหญ่"],"items":[{"text":"ออกจากห้องน้ำโดยไม่แตะน้ำในอ่าง","bin":0,"why":"การออกห่างจากอันตรายเป็นสิ่งแรกที่ทำเองได้"},{"text":"บอกน้องไม่ให้เข้าห้องน้ำ","bin":0,"why":"การเตือนผู้อื่นทำได้เองโดยไม่ต้องเข้าใกล้อันตราย"},{"text":"สับเบรกเกอร์ตัดไฟทั้งบ้าน","bin":1,"why":"ตู้ไฟเป็นอุปกรณ์ที่ผู้ใหญ่ควรจัดการ"},{"text":"ถอดปลั๊กและนำไดร์ออกจากอ่าง","bin":1,"why":"ต้องทำหลังตัดไฟแล้วเท่านั้น และควรให้ผู้ใหญ่ทำ"},{"text":"ตัดสินใจว่าไดร์ยังใช้ต่อได้หรือไม่","bin":1,"why":"ไดร์ที่ตกน้ำไม่ควรใช้อีก ผู้ใหญ่ต้องเป็นคนตัดสินใจทิ้งหรือส่งตรวจ"}]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องตัดไฟที่เบรกเกอร์ก่อนแทนการดึงปลั๊ก","skill":"reason","points":10,"hints":["การดึงปลั๊กต้องเอามือไปจับอะไร"],"solution":["การสับเบรกเกอร์ตัดไฟได้โดยไม่ต้องแตะอุปกรณ์ที่เปียกน้ำหรือยืนใกล้น้ำ"],"options":[{"text":"ตัดไฟได้โดยไม่ต้องแตะปลั๊กหรือเข้าใกล้น้ำที่อาจมีไฟฟ้า","ok":true},{"text":"เพราะเบรกเกอร์อยู่ใกล้กว่าปลั๊ก","ok":false,"why":"ในเรื่องนี้เบรกเกอร์อยู่ไกลกว่า แต่ปลอดภัยกว่าเพราะไม่ต้องแตะสิ่งที่เปียก"},{"text":"เพราะการดึงปลั๊กทำให้ไดร์เสีย","ok":false,"why":"ไดร์ที่ตกน้ำไม่ควรใช้ต่ออยู่แล้ว เหตุผลคือความปลอดภัยของคน"}],"answer":0}]}', 'hard', 22),
('health_safety', 'เพื่อนจมน้ำตอนทัศนศึกษา', '{"icon":"🌊","story":["ชั้น ป.5 ไปทัศนศึกษาริมแม่น้ำ ครูให้ทุกคนอยู่บนท่าน้ำ","น้องโอมแอบลงไปเล่นน้ำตื้นแล้วถูกกระแสน้ำพาออกไปไกลจากท่า น้องบีมเพื่อนสนิทเห็นเป็นคนแรก บีมว่ายน้ำได้เล็กน้อย"],"context":[{"type":"table","title":"สิ่งที่มีอยู่บนท่าน้ำ","head":["สิ่งของหรือคน","รายละเอียด"],"rows":[["ห่วงยางมีเชือกผูก","แขวนที่เสาท่าน้ำ"],["ไม้ไผ่ยาว","วางอยู่ข้างท่า แต่สั้นเกินกว่าจะถึงตัวโอม"],["ครูสมชาย","อยู่ห่างไป 20 ก้าว กำลังนับจำนวนนักเรียน"],["ขวดน้ำพลาสติกเปล่าปิดฝา","มีหลายใบในถุงขยะ"]]},{"type":"note","text":"ในแม่น้ำมีกระแสน้ำแรง แม้คนว่ายน้ำเก่งก็อาจถูกพัดไปได้"}],"steps":[{"kind":"scene","prompt":"บีมควรทำอย่างไรเป็นอย่างแรก","skill":"decision","points":10,"hints":["ไม้ไผ่ยาวพอถึงตัวโอมไหม","หลักการช่วยคนจมน้ำคือ ตะโกน โยน ยื่น"],"solution":["ห้ามกระโดดลงไปช่วย โดยเฉพาะในแม่น้ำที่มีกระแสน้ำ","ตะโกนเรียกครู แล้วโยนห่วงยางที่มีเชือกจากบนท่า"],"options":[{"text":"ตะโกนเรียกครูสมชายเสียงดัง แล้วโยนห่วงยางที่มีเชือกผูกไปให้โอม","score":1,"result":"โอมคว้าห่วงยางได้ ครูสมชายวิ่งมาช่วยดึงเชือกพาโอมเข้าท่าอย่างปลอดภัย"},{"text":"กระโดดลงไปว่ายไปหาโอม เพราะเป็นเพื่อนสนิท","score":0,"result":"กระแสน้ำพาบีมออกไปเช่นกัน ครูได้ยินเสียงเพื่อน ๆ ร้องจึงรีบโยนห่วงยางช่วยทั้งสองคนขึ้นมาได้","then":{"kind":"choice","prompt":"บีมถูกกระแสน้ำพาออกไปและเหนื่อยมาก ควรทำอย่างไรเพื่อให้รอดจนความช่วยเหลือมาถึง","skill":"decision","points":10,"hints":["ว่ายสู้กระแสน้ำทำให้หมดแรงเร็วหรือช้า"],"solution":["ตั้งสติ ลอยตัวหงายเพื่อประหยัดแรง และไม่ว่ายสวนกระแสน้ำ รอให้ผู้ใหญ่ช่วยจากบนฝั่ง"],"options":[{"text":"ตั้งสติ ลอยตัวหงายไว้ ไม่ว่ายสวนกระแส แล้วรอคว้าห่วงยางที่ผู้ใหญ่โยนมา","ok":true},{"text":"ว่ายสวนกระแสน้ำกลับท่าให้เร็วที่สุด","ok":false,"why":"ว่ายสวนกระแสทำให้หมดแรงเร็วจนจมได้"},{"text":"ว่ายไปคว้าตัวโอมไว้ก่อน","ok":false,"why":"โอมตกใจอาจเกาะบีมไว้แน่นจนจมทั้งคู่"}],"answer":0}},{"text":"ยื่นไม้ไผ่ออกไปให้โอมคว้า","score":0.5,"result":"ไม้สั้นเกินกว่าจะถึงตัวโอม บีมเสียเวลาไปช่วงหนึ่งก่อนเพื่อนอีกคนจะตะโกนเรียกครูได้"}]},{"kind":"order","prompt":"เรียงขั้นตอนการช่วยคนตกน้ำจากบนฝั่ง","skill":"planning","points":10,"hints":["สิ่งแรกที่ทำได้ทันทีโดยไม่ต้องหยิบอะไรคืออะไร"],"solution":["ตะโกนเรียกผู้ใหญ่ โยนอุปกรณ์ลอยน้ำ ยื่นของยาวถ้าถึง โดยตัวเราอยู่บนฝั่ง แล้วให้ผู้ใหญ่โทร 1669"],"items":["ตะโกนเรียกผู้ใหญ่ให้มาช่วย","โยนอุปกรณ์ลอยน้ำ เช่น ห่วงยางมีเชือก หรือขวดพลาสติกปิดฝา","ถ้าคนในน้ำอยู่ใกล้ ให้ยื่นไม้ยาวโดยหมอบตัวต่ำอยู่บนฝั่ง","ให้ผู้ใหญ่โทร 1669 และบอกสถานที่ให้ชัดเจน"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ขวดพลาสติกเปล่าปิดฝาใช้ช่วยคนตกน้ำได้","skill":"reason","points":10,"hints":["ขวดที่มีอากาศอยู่ข้างในจะจมหรือลอย"],"solution":["ขวดเปล่าปิดฝามีอากาศข้างในจึงลอยน้ำ คนในน้ำกอดไว้ช่วยพยุงตัวได้"],"options":[{"text":"ขวดมีอากาศข้างในจึงลอยน้ำ คนในน้ำกอดไว้ช่วยพยุงตัวได้","ok":true},{"text":"ขวดมีน้ำหนักมาก โยนไปได้ไกล","ok":false,"why":"ขวดเปล่าเบามาก ประโยชน์ของมันคือลอยน้ำได้"},{"text":"คนในน้ำจะได้ใช้ขวดตักน้ำออก","ok":false,"why":"ตักน้ำออกไม่ได้ช่วยอะไร ขวดช่วยเพราะทำให้ลอยตัวได้"}],"answer":0}]}', 'hard', 23),
('health_safety', 'กลิ่นแก๊สตอนกลางคืน', '{"icon":"🌙","story":["ตอนสามทุ่ม น้องตะวันตื่นขึ้นมาเข้าห้องน้ำ บ้านมืด และได้กลิ่นแก๊สแรงมากจากทางครัว","ตะวันมีโทรศัพท์มือถืออยู่ในมือ และพ่อแม่นอนอยู่ในห้องนอนชั้นบน"],"context":[{"type":"table","title":"สิ่งที่อยู่รอบตัวตะวัน","head":["สิ่งของ","ข้อควรรู้"],"rows":[["สวิตช์ไฟในครัว","เมื่อกดอาจเกิดประกายไฟเล็ก ๆ"],["โทรศัพท์มือถือ","อาจเกิดประกายไฟได้ ควรใช้นอกบริเวณที่มีแก๊ส"],["ประตูหน้าบ้าน","เปิดออกไปสนามหญ้า"],["ไฟฉายถ่าน","อยู่ในลิ้นชักห้องนอน"]]},{"type":"note","text":"แก๊สหุงต้มหนักกว่าอากาศ จึงมักสะสมอยู่ต่ำ ๆ ใกล้พื้น"}],"steps":[{"kind":"multi","prompt":"เลือกทุกการกระทำที่อาจทำให้แก๊สติดไฟ","skill":"analysis","points":10,"hints":["อ่านตารางว่าอะไรอาจเกิดประกายไฟได้"],"solution":["ประกายไฟจากสวิตช์ เครื่องใช้ไฟฟ้า หรือการจุดไฟ อาจทำให้แก๊สที่รั่วติดไฟได้"],"options":[{"text":"กดสวิตช์เปิดไฟในครัว","ok":true},{"text":"จุดเทียนเพื่อส่องหาจุดรั่ว","ok":true},{"text":"โทรศัพท์ในครัวที่มีกลิ่นแก๊สแรง","ok":true},{"text":"เปิดประตูหน้าบ้านให้อากาศถ่ายเท","ok":false,"why":"การเปิดประตูช่วยระบายแก๊สออกไป และไม่ทำให้เกิดประกายไฟ"},{"text":"เดินขึ้นไปเรียกพ่อแม่ที่ชั้นบน","ok":false,"why":"การเดินไปเรียกผู้ใหญ่ไม่ทำให้เกิดประกายไฟ และเป็นสิ่งที่ควรทำ"}]},{"kind":"scene","prompt":"ตะวันควรทำอย่างไร","skill":"decision","points":10,"hints":["ทางเลือกไหนดูเหมือนช่วยได้ แต่ซ่อนประกายไฟไว้"],"solution":["ไม่เปิดไฟหรือโทรในบริเวณที่มีแก๊ส","ไปปลุกพ่อแม่ทันที ให้ผู้ใหญ่ปิดวาล์ว เปิดประตูหน้าต่าง และโทรขอความช่วยเหลือจากนอกบ้าน"],"options":[{"text":"ไม่กดสวิตช์ใด ๆ รีบขึ้นไปปลุกพ่อแม่ให้มาจัดการ","score":1,"result":"พ่อเปิดประตูหน้าต่างทุกบานโดยไม่เปิดไฟ ปิดวาล์วถังแก๊ส แล้วพาทุกคนออกไปรอที่สนามหญ้า"},{"text":"โทรหา 199 ทันทีจากในครัว","score":0,"result":"ตะวันยืนอยู่ในครัวที่มีแก๊สแรงขณะใช้โทรศัพท์ ซึ่งเสี่ยงเกิดประกายไฟ เจ้าหน้าที่จึงบอกให้ออกไปข้างนอกก่อน","then":{"kind":"choice","prompt":"เจ้าหน้าที่บอกให้ออกไปข้างนอก ตะวันควรทำอะไรต่อ","skill":"decision","points":10,"hints":["พ่อแม่ยังนอนอยู่ในบ้าน"],"solution":["ต้องให้ทุกคนในบ้านรู้และออกจากบ้าน ผู้ใหญ่จะปิดวาล์วแก๊สและเปิดประตูหน้าต่าง"],"options":[{"text":"ขึ้นไปปลุกพ่อแม่ให้ทุกคนออกจากบ้าน แล้วโทรคุยต่อจากนอกบ้าน","ok":true},{"text":"ออกไปข้างนอกคนเดียวแล้วรอรถดับเพลิง","ok":false,"why":"พ่อแม่ยังนอนอยู่ในบ้านที่มีแก๊สรั่ว ต้องปลุกให้ออกมาด้วย"},{"text":"เปิดไฟทั้งบ้านให้สว่างเพื่อช่วยให้เจ้าหน้าที่หาบ้านเจอ","ok":false,"why":"การเปิดไฟอาจเกิดประกายไฟจนแก๊สติดไฟ"}],"answer":0}},{"text":"เปิดไฟในครัวเพื่อดูว่าลืมปิดเตาหรือเปล่า","score":0,"result":"โชคดีที่ไม่เกิดประกายไฟ แต่ถ้าแก๊สสะสมมากกว่านี้อาจลุกไหม้ได้ทันที พ่อบอกว่าห้ามแตะสวิตช์เด็ดขาดเมื่อได้กลิ่นแก๊ส"}]},{"kind":"order","prompt":"เรียงขั้นตอนของครอบครัวตะวันเมื่อแก๊สรั่วตอนกลางคืน","skill":"planning","points":10,"hints":["ต้องรู้ก่อนว่ามีอันตราย แล้วจึงลดอันตราย และออกไปขอความช่วยเหลือ"],"solution":["ตั้งสติ ปลุกผู้ใหญ่ ผู้ใหญ่ปิดวาล์วและเปิดประตูหน้าต่างโดยไม่แตะสวิตช์ ออกจากบ้าน แล้วโทรจากนอกบ้าน"],"items":["ตั้งสติ ไม่กดสวิตช์หรือจุดไฟ","ไปปลุกพ่อแม่บอกว่าได้กลิ่นแก๊ส","ผู้ใหญ่ปิดวาล์วถังแก๊สและเปิดประตูหน้าต่าง","ทุกคนออกไปรอนอกบ้าน","ผู้ใหญ่โทร 199 จากนอกบ้านเพื่อให้เจ้าหน้าที่มาตรวจ"]}]}', 'hard', 24),
('health_safety', 'เพื่อนถูกไฟดูดจากพัดลม', '{"icon":"⚡","story":["ที่บ้านเพื่อน น้องจีนเห็นน้องเติ้ลจับขาพัดลมตั้งพื้นแล้วตัวแข็งค้าง ปล่อยมือไม่ได้","สายไฟพัดลมเก่ามาก และเติ้ลเท้าเปล่ายืนอยู่บนพื้นปูน"],"context":[{"type":"table","title":"สิ่งที่อยู่ในห้อง","head":["สิ่งของหรือคน","รายละเอียด"],"rows":[["ปลั๊กพัดลม","เสียบอยู่ที่ผนังใกล้ตัวเติ้ล"],["ไม้กวาดด้ามไม้แห้ง","พิงอยู่ที่มุมห้อง"],["แม่ของเติ้ล","อยู่ในครัวติดกัน"],["ตู้ไฟ (เบรกเกอร์)","อยู่ที่ผนังครัว"]]},{"type":"note","text":"ถ้าเอามือไปจับคนที่กำลังถูกไฟดูด ไฟฟ้าจะวิ่งผ่านมาที่ตัวเราด้วย"}],"steps":[{"kind":"scene","prompt":"จีนควรทำอย่างไรทันที","skill":"decision","points":10,"hints":["อ่านข้อมูลเรื่องการจับตัวคนที่ถูกไฟดูด","แม่ของเติ้ลอยู่ใกล้ตู้ไฟหรือไม่"],"solution":["ห้ามจับตัวคนที่กำลังถูกไฟดูด","ตะโกนเรียกผู้ใหญ่ให้ตัดไฟที่เบรกเกอร์ทันที แล้วโทร 1669"],"options":[{"text":"ไม่แตะตัวเติ้ล ตะโกนให้แม่เติ้ลสับเบรกเกอร์ในครัวทันที","score":1,"result":"แม่ของเติ้ลสับเบรกเกอร์ลง เติ้ลหลุดจากพัดลม แม่โทร 1669 และเจ้าหน้าที่แนะนำวิธีดูแลจนรถพยาบาลมาถึง"},{"text":"วิ่งเข้าไปกอดดึงเติ้ลออกจากพัดลม","score":0,"result":"แม่ของเติ้ลที่วิ่งออกมาจากครัวคว้าแขนจีนไว้ได้ทันก่อนจีนจะแตะตัวเติ้ล แล้วรีบไปสับเบรกเกอร์","then":{"kind":"choice","prompt":"แม่ห้ามจีนไว้ทัน จีนควรเข้าใจว่าทำไมแม่ห้าม","skill":"reason","points":10,"hints":["ถ้าจีนแตะตัวเติ้ล ไฟฟ้าจะวิ่งไปที่ไหนต่อ"],"solution":["ไฟฟ้าจะวิ่งผ่านตัวเติ้ลมาที่ตัวผู้ช่วย ทำให้ถูกไฟดูดเพิ่มอีกคน จึงต้องตัดไฟก่อนเสมอ"],"options":[{"text":"เพราะไฟฟ้าจะวิ่งผ่านตัวเติ้ลมาที่จีน ทำให้ถูกไฟดูดทั้งสองคน","ok":true},{"text":"เพราะจีนตัวเล็กกว่าเติ้ล ดึงไม่ไหว","ok":false,"why":"แม้ตัวใหญ่ก็ห้ามจับ เพราะไฟฟ้าจะวิ่งเข้าตัวผู้ช่วย"},{"text":"เพราะต้องรอให้เติ้ลปล่อยมือเอง","ok":false,"why":"คนที่ถูกไฟดูดมักปล่อยมือเองไม่ได้ ต้องตัดไฟให้เร็วที่สุด"}],"answer":0}},{"text":"ใช้ไม้กวาดด้ามไม้แห้งเขี่ยมือเติ้ลออกเอง","score":0.5,"result":"ไม้แห้งไม่นำไฟฟ้าจึงช่วยได้ แต่จีนยืนเท้าเปล่าใกล้มาก และไม่มีใครไปตัดไฟ แม่เติ้ลได้ยินเสียงจึงรีบสับเบรกเกอร์"}]},{"kind":"choice","prompt":"หลังตัดไฟแล้ว เติ้ลนอนนิ่งไม่ตอบสนอง ควรโทรเบอร์ใด","skill":"rules","points":10,"hints":["ตอนนี้ต้องการรถพยาบาล รถดับเพลิง หรือตำรวจ"],"solution":["คนที่ถูกไฟดูดแล้วไม่ตอบสนองเป็นภาวะเจ็บป่วยฉุกเฉิน ต้องโทร 1669"],"options":[{"text":"1669","ok":true},{"text":"199","ok":false,"why":"199 คือดับเพลิง ใช้เมื่อมีไฟไหม้ แต่เติ้ลต้องการรถพยาบาล"},{"text":"191","ok":false,"why":"191 คือตำรวจ ไม่ใช่เบอร์สำหรับเจ็บป่วยฉุกเฉิน"}],"answer":0},{"kind":"sort","prompt":"แยกสิ่งที่จีนทำได้ด้วยตนเอง และสิ่งที่ต้องแจ้งผู้ใหญ่","skill":"analysis","points":10,"hints":["สิ่งไหนต้องแตะไฟฟ้าหรือต้องมีความรู้ปฐมพยาบาล"],"solution":["เด็กช่วยได้ด้วยการเรียกผู้ใหญ่ ไม่แตะตัวผู้บาดเจ็บ และกันคนอื่นออกห่าง","การตัดไฟและดูแลผู้บาดเจ็บเป็นงานของผู้ใหญ่และเจ้าหน้าที่"],"bins":["ทำได้ด้วยตนเอง","ต้องแจ้งผู้ใหญ่"],"items":[{"text":"ตะโกนเรียกผู้ใหญ่ให้มาช่วย","bin":0,"why":"ทำได้ทันทีโดยไม่ต้องเข้าใกล้อันตราย"},{"text":"บอกน้อง ๆ ไม่ให้เข้ามาใกล้พัดลม","bin":0,"why":"การกันคนอื่นออกห่างช่วยไม่ให้มีผู้บาดเจ็บเพิ่ม"},{"text":"สับเบรกเกอร์ตัดไฟ","bin":1,"why":"ตู้ไฟควรให้ผู้ใหญ่จัดการ"},{"text":"ดูแลเติ้ลระหว่างรอรถพยาบาล","bin":1,"why":"ผู้ใหญ่ทำตามคำแนะนำของเจ้าหน้าที่ 1669 ได้ถูกต้องกว่า"},{"text":"ตรวจสายไฟพัดลมว่าชำรุดตรงไหน","bin":1,"why":"การตรวจอุปกรณ์ไฟฟ้าเป็นงานของผู้ใหญ่หรือช่างไฟ"}]}]}', 'hard', 25),
