('health_safety', 'คนอ้างว่าแม่ให้มารับ', '{"icon":"🚗","story":["หลังเลิกเรียน ผู้หญิงคนหนึ่งเดินมาหาน้องปลื้ม บอกว่า \"แม่หนูป่วยเข้าโรงพยาบาล ให้น้ามารับ รีบขึ้นรถเร็ว\"","เธอรู้ชื่อปลื้มและชื่อแม่ด้วย แต่ปลื้มไม่เคยเห็นหน้าเธอมาก่อน"],"context":[{"type":"note","text":"ครอบครัวปลื้มตกลงรหัสลับกันไว้ว่า ใครมารับแทนต้องพูดคำว่า \"ช้างน้อยสีฟ้า\""},{"type":"table","title":"สิ่งที่ปลื้มสังเกต","head":["เรื่อง","สิ่งที่เห็น"],"rows":[["รหัสลับ","เมื่อถามแล้ว เธอบอกว่าจำไม่ได้"],["ชื่อปลื้ม","เขียนอยู่บนป้ายชื่อที่กระเป๋านักเรียน"],["ท่าทาง","เร่งให้รีบขึ้นรถ และบอกว่าไม่ต้องบอกครู"],["ครูเวร","ยืนอยู่ที่ประตูโรงเรียน"]]}],"steps":[{"kind":"multi","prompt":"เลือกทุกข้อที่เป็นสัญญาณเตือนว่าอาจไม่ปลอดภัย","skill":"analysis","points":10,"hints":["เธอรู้ชื่อปลื้มได้จากที่ไหน","คนที่แม่ให้มารับจริงจะพูดอะไรได้"],"solution":["จำรหัสลับไม่ได้ เร่งรีบ และห้ามบอกครู เป็นสัญญาณอันตราย","การรู้ชื่อไม่ได้แปลว่ารู้จักจริง เพราะชื่ออาจเห็นจากป้ายกระเป๋า"],"options":[{"text":"บอกรหัสลับของครอบครัวไม่ได้","ok":true},{"text":"เร่งให้รีบขึ้นรถทันที","ok":true},{"text":"บอกว่าไม่ต้องบอกครู","ok":true},{"text":"ปลื้มเรียนชั้น ป.5","ok":false,"why":"ชั้นเรียนของปลื้มไม่ใช่สัญญาณอันตรายจากคนแปลกหน้า"},{"text":"วันนี้ฝนตก","ok":false,"why":"สภาพอากาศไม่เกี่ยวกับการตัดสินว่าคนนี้ไว้ใจได้หรือไม่"}]},{"kind":"scene","prompt":"ปลื้มควรทำอย่างไร","skill":"decision","points":10,"hints":["ใครช่วยตรวจสอบกับแม่ได้จริง"],"solution":["ไม่ไปกับคนที่ไม่รู้รหัสลับ ให้ไปหาครูเวรทันที","ครูจะโทรตรวจสอบกับผู้ปกครองโดยตรง"],"options":[{"text":"บอกว่า \"หนูต้องถามครูก่อน\" แล้วเดินไปหาครูเวรที่ประตู ให้ครูโทรหาแม่","score":1,"result":"ครูโทรหาแม่ แม่บอกว่าไม่ได้ป่วยและไม่ได้ให้ใครมารับ ครูแจ้ง รปภ. และ 191"},{"text":"ขึ้นรถไป เพราะเป็นห่วงแม่มาก","score":0,"result":"ระหว่างทาง ผู้หญิงคนนั้นไม่ขับไปโรงพยาบาล ปลื้มเริ่มรู้สึกกลัว","then":{"kind":"choice","prompt":"รถติดไฟแดงหน้าร้านสะดวกซื้อที่มีคนอยู่มาก ปลื้มควรทำอย่างไร","skill":"decision","points":10,"hints":["ที่ไหนมีผู้ใหญ่ที่ช่วยได้"],"solution":["เมื่อรู้