('health_safety', 'เพื่อนเป็นลมแดดวันกีฬาสี', '{"icon":"☀️","story":["วันกีฬาสีอากาศร้อนจัด น้องตั้มซ้อมเชียร์กลางแดดมาตั้งแต่เช้า","ตอนบ่าย ตั้มบ่นว่าปวดหัว ตัวร้อนจัด แล้วเริ่มพูดจาสับสน น้องฟ้าใสอยู่ข้าง ๆ"],"context":[{"type":"table","title":"อาการของตั้ม","head":["อาการ","สิ่งที่ฟ้าใสเห็น"],"rows":[["ตัว","ร้อนจัด ผิวแดง"],["การพูด","สับสน ตอบไม่ค่อยตรงคำถาม"],["การเดิน","เซ"],["ครูพยาบาล","อยู่ที่เต็นท์ปฐมพยาบาลข้างสนาม"]]},{"type":"note","text":"ลมแดด (ฮีทสโตรก) เกิดเมื่อร่างกายร้อนเกินไปจนระบายความร้อนไม่ทัน ถ้ามีอาการสับสนหรือหมดสติเป็นภาวะฉุกเฉิน"}],"steps":[{"kind":"scene","prompt":"ฟ้าใสควรทำอย่างไร","skill":"decision","points":10,"hints":["อาการพูดสับสนบอกอะไร","ใครที่ดูแลเรื่องนี้ได้ถูกวิธี"],"solution":["อาการสับสนเป็นสัญญาณอันตราย ต้องรีบแจ้งครูพยาบาลทันที","ระหว่างรอ ช่วยพาเพื่อนเข้าที่ร่มและไม่ให้ซ้อมต่อ"],"options":[{"text":"ให้ตั้มหยุดเชียร์ พาเข้าที่ร่มใกล้ที่สุด แล้วให้เพื่อนอีกคนวิ่งไปตามครูพยาบาลทันที","score":1,"result":"ครูพยาบาลมาถึงเร็ว ช่วยลดความร้อนให้ตั้ม และให้ครูโทร 1669 เพราะตั้มยังสับสน"},{"text":"บอกให้ตั้มอดทนเชียร์ต่อ อีกนิดเดียวก็เสร็จ","score":0,"result":"ไม่กี่นาทีตั้มล้มลงนั่งและไม่ค่อยตอบสนอง เพื่อน ๆ ตกใจมาก","then":{"kind":"order","prompt":"ตั้มล้มลงและไม่ค่อยตอบสนอง เรียงสิ่งที่ฟ้าใสต้องทำ","skill":"planning","points":10,"hints":["ใครต้องรู้เรื่องนี้ก่อน"],"solution":["เรียกครูทันที ให้ครูโทร 1669 บอกอาการและสถานที่ แล้วรอความช่วยเหลือโดยอยู่ในที่ร่ม"],"items":["ตะโกนเรียกครูที่อยู่ใกล้ที่สุด","บอกครูว่าตั้มตัวร้อนจัด พูดสับสน และล้มลง","ครูโทร 1669 บอกชื่อโรงเรียนและจุดที่เกิดเหตุ","ช่วยกันเพื่อน ๆ ไม่ให้มุง และรอเจ้าหน้าที่"]}},{"text":"ป้อนน้ำเย็นให้ตั้มดื่มเยอะ ๆ ทันที โดยยังอยู่กลางแดด","score":0.5,"result":"ตั้มสับสนจนดื่มแล้วสำลัก และยังอยู่กลางแดด ครูที่เดินมาเห็นรีบพาเข้าที่ร่มและเรียกครูพยาบาล"}]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ไม่ควรรอให้ตั้มดีขึ้นเอง","skill":"reason","points":10,"hints":["อ่านข้อมูลเรื่องอาการสับสนอีกครั้ง"],"solution":["อาการสับสนแสดงว่าร่างกายร้อนจนกระทบสมอง เป็นภาวะฉุกเฉินที่ต้องให้ผู้ใหญ่ช่วยทันที"],"options":[{"text":"เพราะอาการพูดสับสนแสดงว่าเป็นภาวะฉุกเฉิน อาจแย่ลงเร็ว","ok":true},{"text":"เพราะตั้มจะได้ไม่ต้องเชียร์ต่อ","ok":false,"why":"ไม่ใช่เรื่องเลี่ยงการเชียร์ แต่เป็นเรื่องอาการที่อันตราย"},{"text":"เพราะครูจะดุถ้าไม่รายงาน","ok":false,"why":"เหตุผลหลักคือความปลอดภัยของตั้ม ไม่ใช่กลัวถูกดุ"}],"answer":0},{"kind":"multi","prompt":"เลือกทุกวิธีที่ช่วยป้องกันลมแดดในวันกีฬาสี","skill":"analysis","points":10,"hints":["คิดถึงน้ำ ร่มเงา และเวลาที่อยู่กลางแดด"],"solution":["ดื่มน้ำเปล่าบ่อย ๆ พักในที่ร่มเป็นระยะ สวมหมวกและเสื้อผ้าระบายอากาศ และบอกครูทันทีเมื่อรู้สึกผิดปกติ"],"options":[{"text":"จิบน้ำเปล่าบ่อย ๆ แม้ยังไม่กระหาย","ok":true},{"text":"พักในที่ร่มเป็นระยะ","ok":true},{"text":"สวมหมวกและเสื้อผ้าที่ระบายอากาศดี","ok":true},{"text":"อดน้ำไว้จะได้ไม่ต้องเข้าห้องน้ำบ่อย","ok":false,"why":"การอดน้ำทำให้ร่างกายขาดน้ำและร้อนเกินได้ง่าย"},{"text":"ใส่เสื้อแขนยาวหนา ๆ หลายชั้นกันแดด","ok":false,"why":"เสื้อหนาหลายชั้นเก็บความร้อน ทำให้ระบายความร้อนไม่ได้"}]}]}', 'hard', 28),
('health_safety', 'ข้อมูลส่วนตัวหลุดในโซเชียล', '{"icon":"🔒","story":["น้องไอซ์โพสต์รูปหน้าบ้านพร้อมชุดนักเรียนที่เห็นชื่อโรงเรียน","ไม่นานมีบัญชีปลอมเอารูปไอซ์ไปตัดต่อล้อเลียน และมีคนแปลกหน้าทักมาว่า \"รู้นะว่าบ้านอยู่ไหน\""],"context":[{"type":"table","title":"สิ่งที่อยู่ในโพสต์ของไอซ์","head":["ข้อมูล","คนอื่นรู้อะไรได้"],"rows":[["ป้ายบ้านเลขที่ในรูป","ที่อยู่บ้าน"],["ตราโรงเรียนบนเสื้อ","โรงเรียนที่เรียน"],["ตั้งค่าโพสต์เป็นสาธารณะ","ใครก็เห็นได้"],["ชื่อเล่นในโปรไฟล์","ชื่อที่ใช้เรียก"]]},{"type":"note","text":"ข้อความขู่และการตัดต่อรูปล้อเลียน เป็นการรังแกออนไลน์ ผู้ใหญ่สามารถช่วยรายงานหรือแจ้งความได้"}],"steps":[{"kind":"scene","prompt":"ไอซ์เห็นข้อความขู่และรูปตัดต่อ ควรทำอย่างไร","skill":"decision","points":10,"hints":["ข้อความขู่เป็นเรื่องที่เด็กควรจัดการคนเดียวหรือไม่"],"solution":["ไม่ตอบโต้ เก็บหลักฐาน แล้วบอกผู้ใหญ่ทันที เพราะมีการขู่ที่เกี่ยวกับความปลอดภัย","ผู้ใหญ่ช่วยลบโพสต์ ตั้งค่าความเป็นส่วนตัว รายงานบัญชีปลอม และแจ้ง 191 ได้ถ้าจำเป็น"],"options":[{"text":"ไม่ตอบ แคปหน้าจอข้อความขู่และรูปตัดต่อ แล้วบอกพ่อแม่ทันที","score":1,"result":"พ่อแม่ช่วยลบรูปหน้าบ้าน รายงานบัญชีปลอม และพาไปแจ้งตำรวจเรื่องข้อความขู่"},{"text":"ตอบกลับไปว่า \"ไม่กลัวหรอก มาเลย\"","score":0,"result":"คนแปลกหน้าส่งข้อความมาเพิ่มอีกหลายข้อความ ไอซ์เริ่มกลัวจนนอนไม่หลับ","then":{"kind":"sort","prompt":"ไอซ์ต้องแก้ไขสถานการณ์ แยกสิ่งที่ทำได้ด้วยตนเอง และสิ่งที่ต้องแจ้งผู้ใหญ่","skill":"analysis","points":10,"hints":["เรื่องไหนเกี่ยวกับการขู่หรือกฎหมาย"],"solution":["เด็กหยุดตอบ บล็อก และเก็บหลักฐานเองได้","เรื่องข้อความขู่ การรายงานบัญชีปลอม และการแจ้งตำรวจ ต้องให้ผู้ใหญ่ช่วย"],"bins":["ทำได้ด้วยตนเอง","ต้องแจ้งผู้ใหญ่"],"items":[{"text":"หยุดตอบข้อความทุกข้อความ","bin":0,"why":"การหยุดตอบทำได้ทันทีและช่วยไม่ให้เรื่องลุกลาม"},{"text":"แคปหน้าจอข้อความขู่เก็บไว้","bin":0,"why":"เก็บหลักฐานไว้ให้ผู้ใหญ่ใช้ได้"},{"text":"บล็อกบัญชีคนแปลกหน้า","bin":0,"why":"ทำได้เองเพื่อไม่ให้เขาส่งข้อความมาอีก"},{"text":"แจ้งตำรวจเรื่องข้อความขู่","bin":1,"why":"การแจ้งความต้องให้ผู้ปกครองพาไปหรือโทร 191"},{"text":"ตัดสินใจว่าที่บ้านยังปลอดภัยหรือไม่","bin":1,"why":"เป็นเรื่องความปลอดภัยของครอบครัว ผู้ใหญ่ต้องรู้และตัดสินใจ"}]}},{"text":"ลบโพสต์ของตัวเองเงียบ ๆ แล้วไม่บอกใคร","score":0.5,"result":"รูปหน้าบ้านหายไปจากโพสต์ของไอซ์ แต่บัญชีปลอมยังมีรูปอยู่ และยังไม่มีผู้ใหญ่รู้เรื่องข้อความขู่"}]},{"kind":"multi","prompt":"ถ้าจะโพสต์รูปครั้งหน้า ไอซ์ควรระวังข้อมูลใดบ้าง","skill":"analysis","points":10,"hints":["ดูตาราง ข้อมูลไหนทำให้คนแปลกหน้าหาตัวไอซ์เจอได้"],"solution":["ไม่เปิดเผยที่อยู่ โรงเรียน หรือตำแหน่งที่อยู่ปัจจุบัน และตั้งค่าโพสต์ให้เห็นเฉพาะคนที่รู้จัก"],"options":[{"text":"ป้ายบ้านเลขที่หรือที่อยู่บ้าน","ok":true},{"text":"ตราหรือชื่อโรงเรียนบนชุดนักเรียน","ok":true},{"text":"การตั้งค่าโพสต์เป็นสาธารณะ","ok":true},{"text":"รูปวาดการ์ตูนที่วาดเอง","ok":false,"why":"รูปวาดไม่ได้บอกว่าไอซ์อยู่ที่ไหน จึงไม่ใช่ข้อมูลอันตราย"}]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่เรื่องนี้ต้องให้ผู้ใหญ่ช่วย ไม่จัดการเองคนเดียว","skill":"reason","points":10,"hints":["ข้อความ \"รู้นะว่าบ้านอยู่ไหน\" เกี่ยวกับใครบ้าง"],"solution":["ข้อความขู่เกี่ยวกับความปลอดภัยของทั้งครอบครัว และอาจต้องแจ้งตำรวจ ซึ่งเด็กทำเองคนเดียวไม่ได้"],"options":[{"text":"เพราะเป็นการขู่ที่เกี่ยวกับความปลอดภัยของทั้งบ้าน และอาจต้องแจ้งตำรวจ","ok":true},{"text":"เพราะผู้ใหญ่ใช้โทรศัพท์เก่งกว่า","ok":false,"why":"ไม่ใช่เรื่องความเก่ง แต่เป็นเรื่องความปลอดภัยและกฎหมาย"},{"text":"เพราะไอซ์จะได้ไม่ต้องใช้โซเชียลอีกเลย","ok":false,"why":"จุดประสงค์ไม่ใช่ห้ามใช้ แต่เพื่อให้ผู้ใหญ่ช่วยแก้ปัญหาและสอนใช้อย่างปลอดภัย"}],"answer":0}]}', 'hard', 29),
('health_safety', 'หลงในห้างตอนแบตหมด', '{"icon":"🔋","story":["น้องจิ๊บไปห้างกับพ่อ พ่อบอกให้รอหน้าร้านหนังสือชั้น 3 แต่จิ๊บเดินไปดูร้านของเล่นชั้น 2 แล้วหาทางกลับไม่ถูก","โทรศัพท์ของจิ๊บแบตหมด มีวัยรุ่นคนหนึ่งเสนอว่า \"พี่พาไปหาพ่อที่ลานจอดรถเอง พ่อน่าจะไปรอที่รถ\""],"context":[{"type":"table","title":"สิ่งที่อยู่ใกล้จิ๊บ","head":["สิ่งที่เห็น","อยู่ที่ไหน"],"rows":[["พนักงานร้านของเล่น ใส่ชุดฟอร์มมีป้ายชื่อ","ในร้านของเล่นตรงหน้า"],["จุดประชาสัมพันธ์","ชั้น 1"],["บันไดเลื่อนขึ้นชั้น 3","อยู่ห่างไป 30 ก้าว"],["วัยรุ่นที่เสนอความช่วยเหลือ","ยืนอยู่ข้างจิ๊บ"]]},{"type":"note","text":"จิ๊บจำเบอร์โทรของพ่อได้"}],"steps":[{"kind":"scene","prompt":"จิ๊บควรทำอย่างไร","skill":"decision","points":10,"hints":["ใครในตารางเป็นคนที่ไว้ใจได้มากที่สุดและอยู่ใกล้ที่สุด","ลานจอดรถเหมาะกับการตามหาพ่อหรือไม่"],"solution":["ไม่ไปกับคนแปลกหน้าแม้เขาจะดูใจดี","ขอความช่วยเหลือจากพนักงานที่ใส่ชุดฟอร์มซึ่งอยู่ใกล้ที่สุด ให้ช่วยโทรหาพ่อหรือประกาศตามหา"],"options":[{"text":"ขอบคุณแต่ปฏิเสธวัยรุ่น แล้วเข้าไปขอให้พนักงานร้านของเล่นช่วยโทรหาพ่อ","score":1,"result":"พนักงานโทรหาพ่อตามเบอร์ที่จิ๊บจำได้ พ่อรีบลงมารับที่ร้านของเล่น"},{"text":"ไปกับวัยรุ่นคนนั้นที่ลานจอดรถ","score":0,"result":"ลานจอดรถเงียบและไม่มีพ่อ วัยรุ่นชวนให้ออกไปข้างนอกต่อ จิ๊บรู้สึกไม่ปลอดภัย","then":{"kind":"choice","prompt":"จิ๊บอยู่ที่ลานจอดรถกับคนที่ไม่รู้จัก ควรทำอย่างไร","skill":"decision","points":10,"hints":["ที่ไหนใกล้ที่สุดที่มีผู้ใหญ่ที่ทำหน้าที่ดูแลความปลอดภัย"],"solution":["ปฏิเสธเสียงดัง แล้วรีบกลับเข้าห้างไปหา รปภ. หรือพนักงาน","ไม่ไปไหนต่อกับคนที่ไม่รู้จัก"],"options":[{"text":"บอกว่า \"ไม่ไป\" เสียงดัง แล้วรีบเดินไปหา รปภ. ที่ประตูทางเข้าห้าง","ok":true},{"text":"ไปต่อด้วยเพราะเกรงใจที่เขาพามาแล้ว","ok":false,"why":"ความเกรงใจไม่สำคัญเท่าความปลอดภัย ห้ามไปไหนต่อกับคนแปลกหน้า"},{"text":"นั่งรอพ่อที่ลานจอดรถกับวัยรุ่นคนนั้น","ok":false,"why":"ลานจอดรถเปลี่ยวและอยู่กับคนแปลกหน้า ควรกลับไปหาเจ้าหน้าที่ในห้าง"}],"answer":0}},{"text":"ขึ้นบันไดเลื่อนไปชั้น 3 หน้าร้านหนังสือคนเดียว","score":0.5,"result":"จิ๊บไปถึงจ