('health_teamwork', 'แพ้ชักเยอแล้วพูดอย่างไร', '{"icon":"🪢","story":["วันกีฬาสี สีเขียวของใบเฟิร์นแพ้ชักเยอสีแดงไปอย่างสูสี","ภูผาหงุดหงิดและพูดว่า \"แพ้เพราะมะปรางดึงไม่แรงเลย\" มะปรางก้มหน้าเงียบ"],"tip":"ทีมชนะด้วยกัน และแพ้ด้วยกัน","context":[{"type":"note","text":"ช่วงบ่ายสีเขียวยังต้องแข่งวิ่งผลัดด้วยกันอีก 1 รายการ"}],"steps":[{"kind":"choice","prompt":"ใบเฟิร์นควรพูดกับทีมอย่างไรดีที่สุด","skill":"decision","points":10,"hints":["คำพูดแบบไหนทำให้ทีมพร้อมแข่งต่อในช่วงบ่าย","มะปรางรู้สึกอย่างไรตอนนี้"],"options":[{"text":"ใช่ มะปรางไปนั่งพักเถอะ บ่ายนี้ไม่ต้องลงแข่ง","ok":false,"why":"เป็นการโทษเพื่อนคนเดียวและกีดกันไม่ให้เล่น ทีมจะแตกแยก"},{"text":"ทุกคนดึงเต็มที่แล้ว เราแพ้ด้วยกัน บ่ายนี้มาสู้กันใหม่นะ","ok":true},{"text":"ไม่ต้องพูดอะไร ปล่อยให้ทุกคนเงียบไป","ok":false,"why":"มะปรางยังเสียใจอยู่คนเดียว และทีมยังไม่พร้อมแข่งต่อ"},{"text":"สีแดงต้องโกงแน่ ๆ ไปฟ้องครูกัน","ok":false,"why":"กล่าวหาคู่แข่งโดยไม่มีหลักฐาน ไม่มีน้ำใจนักกีฬา"}],"solution":["ผลการแข่งขันของทีมเกิดจากทุกคนร่วมกัน","คำพูดให้กำลังใจช่วยให้เพื่อนหายเสียใจ และทีมพร้อมสู้รายการต่อไป"],"answer":1},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ไม่ควรโทษมะปรางคนเดียว","skill":"reason","points":10,"hints":["ชักเยอใช้แรงของกี่คน","การโทษคนเดียวยุติธรรมไหม"],"options":[{"text":"เพราะมะปรางเป็นเพื่อนสนิทของใบเฟิร์น","ok":false,"why":"ความสนิทไม่ใช่เหตุผล ต่อให้ไม่สนิทก็ไม่ควรโทษคนเดียว"},{"text":"เพราะครูอาจได้ยินแล้วตักเตือน","ok":false,"why":"เราไม่ควรทำดีเพราะกลัวถูกดุ แต่เพราะเคารพเพื่อน"},{"text":"เพราะผลของทีมเกิดจากทุกคน การโทษคนเดียวไม่ยุติธรรมและทำให้ทีมร่วมมือกันน้อยลง","ok":true},{"text":"เพราะแพ้ไปแล้ว พูดอะไรก็ไม่มีประโยชน์","ok":false,"why":"คำพูดดี ๆ มีประโยชน์ ช่วยให้ทีมพร้อมแข่งต่อ"}],"solution":["ความยุติธรรม: ทุกคนในทีมมีส่วนต่อผลแพ้ชนะ","การร่วมมือ: ทีมที่ไม่โทษกันจะกล้าเล่นและช่วยกันมากขึ้น"],"answer":2}]}', 'easy', 1),
('health_teamwork', 'ลูกบอลมีลูกเดียว', '{"icon":"⚽","story":["ช่วงพักกลางวัน ห้องเก็บอุปกรณ์เหลือลูกฟุตบอลเพียง 1 ลูก","กลุ่มของต้นกล้าและกลุ่มของน้ำหวานมาถึงพร้อมกัน และอยากเล่นทั้งคู่"],"context":[{"type":"table","title":"เวลาพักกลางวัน","head":["ช่วง","เวลา"],"rows":[["ช่วงที่ 1","12:10–12:30"],["ช่วงที่ 2","12:30–12:50"]]},{"type":"note","text":"กติกาห้องเก็บอุปกรณ์: ยืมแล้วต้องนำมาคืนที่ห้องก่อน 12:50"}],"steps":[{"kind":"choice","prompt":"วิธีใดแบ่งลูกบอลได้ยุติธรรมที่สุด","skill":"decision","points":10,"hints":["ดูตาราง มีเวลาพักกี่ช่วง","วิธีไหนทำให้ทั้งสองกลุ่มได้เล่น"],"options":[{"text":"ผลัดกันเล่นกลุ่มละ 1 ช่วง โดยเป่ายิ้งฉุบเลือกว่าใครได้ช่วงแรก","ok":true},{"text":"กลุ่มที่มีคนมากกว่าได้เล่นทั้งหมด","ok":false,"why":"อีกกลุ่มไม่ได้เล่นเลย ไม่ยุติธรรม"},{"text":"แย่งกัน ใครได้ลูกก่อนคนนั้นเล่น","ok":false,"why":"การแย่งกันเสี่ยงบาดเจ็บและทำให้ทะเลาะกัน"},{"text":"กลุ่มต้นกล้าเล่นจนพอใจก่อน แล้วค่อยให้อีกกลุ่ม","ok":false,"why":"ไม่กำหนดเวลา อีกกลุ่มอาจไม่ได้เล่นก่อนหมดพัก"}],"solution":["การแบ่งเวลาเท่ากันทำให้ทุกคนได้เล่น","การเป่ายิ้งฉุบเป็นวิธีเลือกที่ทุกฝ่ายยอมรับได้ ไม่มีใครได้เปรียบ"],"answer":0},{"kind":"choice","prompt":"ถ้ากลุ่มน้ำหวานได้เล่นช่วงที่ 2 เมื่อเล่นเสร็จต้องทำอย่างไร","skill":"rules","points":10,"hints":["อ่านกติกาห้องเก็บอุปกรณ์อีกครั้ง"],"options":[{"text":"วางลูกบอลไว้ที่สนาม เดี๋ยวคนอื่นเก็บเอง","ok":false,"why":"ผิดกติกาการยืม และลูกบอลอาจหาย"},{"text":"เก็บลูกบอลไว้ในห้องเรียนตัวเองเพื่อเล่นพรุ่งนี้","ok":false,"why":"ลูกบอลเป็นของส่วนรวม ต้องคืนให้คนอื่นยืมได้"},{"text":"นำลูกบอลไปคืนห้องเก็บอุปกรณ์ก่อน 12:50","ok":true}],"solution":["อุปกรณ์กีฬาเป็นของส่วนรวม","การคืนตรงเวลาตามกติกาทำให้คนอื่นได้ใช้ต่อ"],"answer":2}]}', 'easy', 2),
('health_teamwork', 'ชวนเพื่อนใหม่เข้าทีม', '{"icon":"🤗","story":["ภูผากำลังแบ่งทีมเล่นแชร์บอลในคาบพละ","มะปรางเพิ่งย้ายมาใหม่ เดินมาขอเล่นด้วย แต่เพื่อนบางคนบอกว่า \"ทีมเต็มแล้ว ไม่รู้จักกัน\""],"context":[{"type":"table","title":"จำนวนผู้เล่นตอนนี้","head":["ทีม","จำนวนคน"],"rows":[["ทีมฟ้า","5 คน"],["ทีมส้ม","4 คน"]]},{"type":"note","text":"ครูกำหนดว่าคาบนี้เล่นได้ทีมละไม่เกิน 6 คน"}],"steps":[{"kind":"scene","prompt":"ภูผาควรทำอย่างไร","skill":"decision","points":10,"hints":["ทีมไหนยังรับคนได้ตามที่ครูกำหนด","มะปรางจะรู้สึกอย่างไรถ้าไม่ได้เล่น"],"options":[{"text":"เงียบไว้ ปล่อยให้เพื่อนบอกว่าทีมเต็ม","score":0,"result":"มะปรางเดินกลับไปนั่งคนเดียว และไม่กล้ามาขอเล่นอีก"},{"text":"ชวนมะปรางเข้าทีมส้มที่ยังมีคนน้อยกว่า แล้วแนะนำให้เพื่อน ๆ รู้จัก","score":1,"result":"สองทีมมีคนเท่ากัน 5 ต่อ 5 มะปรางยิ้มได้ และส่งบอลได้แม่นจนเพื่อนชม"},{"text":"บอกมะปรางให้รอเล่นคาบหน้า","score":0.5,"result":"ไม่มีใครว่าร้ายมะปราง แต่เธอต้องนั่งดูทั้งคาบ ทั้งที่ทีมส้มยังรับคนได้"}],"solution":["ทุกคนมีสิทธิ์ร่วมเล่น การชวนเพื่อนใหม่ไม่ให้ถูกทิ้งคือน้ำใจ","ทีมส้มมี 4 คน รับเพิ่มได้ตามกติกา และทำให้สองทีมสมดุล"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ควรชวนมะปรางเข้าทีมส้ม","skill":"reason","points":10,"hints":["คิดถึงทั้งสิทธิ์ของมะปรางและกติกาของครู"],"options":[{"text":"เพราะมะปรางอาจเล่นเก่ง จะได้ชนะทีมฟ้า","ok":false,"why":"ต่อให้มะปรางเล่นไม่เก่งก็ควรได้เล่น เป้าหมายไม่ใช่การได้เปรียบ"},{"text":"เพราะครูจะได้ไม่ดุ","ok":false,"why":"ควรชวนเพราะเคารพเพื่อน ไม่ใช่เพราะกลัวถูกดุ"},{"text":"เพราะทุกคนมีสิทธิ์ร่วมเล่น และทีมส้มยังรับคนได้ตามกติกา ทำให้สองทีมเท่ากัน","ok":true}],"solution":["การไม่กีดกันเพื่อนคือความยุติธรรม","การเลือกทีมที่ยังรับคนได้คือการทำตามกติกา"],"answer":2}]}', 'easy', 3),
('health_teamwork', 'แพ้ฟุตบอลแต่ยังมีน้ำใจ', '{"icon":"🥅","story":["ทีมฟุตบอลของต้นกล้าแพ้ทีมห้อง 5/2 ไป 1–2 ประตู","ต้นกล้าเสียใจมาก เพราะซ้อมกันมาทั้งสัปดาห์"],"context":[{"type":"note","text":"หลังเสียงนกหวีดจบเกม ผู้เล่นทั้งสองทีมกำลังเดินมาที่กลางสนาม"}],"steps":[{"kind":"multi","prompt":"ข้อใดเป็นการแสดงน้ำใจนักกีฬาหลังแพ้ (เลือกทุกข้อที่ใช่)","skill":"decision","points":10,"hints":["ข้อไหนให้เกียรติคู่แข่ง กรรมการ และเพื่อนร่วมทีม"],"options":[{"text":"จับมือและแสดงความยินดีกับทีมที่ชนะ","ok":true},{"text":"เดินออกจากสนามทันทีโดยไม่มองใคร","ok":false,"why":"ไม่ให้เกียรติคู่แข่งที่เล่นด้วยกันมา"},{"text":"ขอบคุณกรรมการที่ช่วยตัดสิน","ok":true},{"text":"บอกว่ากรรมการลำเอียง","ok":false,"why":"กล่าวหาโดยไม่มีหลักฐาน ไม่เคารพการตัดสิน"},{"text":"บอกเพื่อนในทีมว่า \"เราเล่นเต็มที่แล้ว ซ้อมต่อกันนะ\"","ok":true},{"text":"เตะลูกบอลทิ้งด้วยความโมโห","ok":false,"why":"แสดงอารมณ์รุนแรง และลูกบอลอาจไปโดนคนอื่นบาดเจ็บ"}],"solution":["น้ำใจนักกีฬา คือ ยอมรับผล ให้เกียรติคู่แข่งและกรรมการ และให้กำลังใจทีม","การควบคุมอารมณ์ตอนแพ้ทำให้ทุกคนปลอดภัย"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ควรยอมรับผลแพ้อย่างสุภาพ","skill":"reason","points":10,"hints":["ถ้าทุกคนแพ้แล้วโกรธ จะยังมีใครอยากแข่งด้วยกันไหม"],"options":[{"text":"เพราะถ้าไม่ทำ ครูจะตัดคะแนน","ok":false,"why":"ควรทำเพราะเคารพผู้อื่น ไม่ใช่เพราะกลัวถูกตัดคะแนน"},{"text":"เพราะทีมที่แพ้ไม่มีสิทธิ์พูดอะไร","ok":false,"why":"ทุกคนพูดได้ แต่ควรพูดอย่างสุภาพ"},{"text":"เพราะแพ้แปลว่าเราเล่นไม่ดีเลย","ok":false,"why":"แพ้ไม่ได้แปลว่าไม่ดี แต่เป็นโอกาสให้เรียนรู้และพัฒนา"},{"text":"เพราะการแข่งขันมีแพ้มีชนะ การเคารพคู่แข่งและกติกาทำให้ทุกคนอยากเล่นด้วยกันอีก","ok":true}],"solution":["กีฬามีไว้ฝึกร่างกายและฝึกใจ","การยอมรับผลอย่างสุภาพคือหัวใจของน้ำใจนักกีฬา"],"answer":3}]}', 'easy', 4),
('health_teamwork', 'ออกตัวก่อนนกหวีด', '{"icon":"🚩","story":["คาบพละวันนี้เล่นเกมวิ่งเก็บธงแข่งกันทีละคู่","ใบเฟิร์นสังเกตว่าธามไทจากอีกทีมออกวิ่งก่อนครูเป่านกหวีด"],"context":[{"type":"table","title":"สิ่งที่ใบเฟิร์นเห็น","head":["รอบ","เหตุการณ์"],"rows":[["รอบ 1","ธามไทออกวิ่งก่อนเสียงนกหวีด"],["รอบ 2","ธามไทออกวิ่งก่อนเสียงนกหวีดอีกครั้ง"]]},{"type":"note","text":"ครูพละเป็นกรรมการ ยืนอยู่ที่เส้นชัย จึงอาจมองไม่เห็นจุดปล่อยตัว"}],"steps":[{"kind":"scene","prompt":"ใบเฟิร์นควรทำอย่างไร","skill":"decision","points":10,"hints":["ใครเป็นคนตัดสินในเกมนี้","วิธีไหนแก้ปัญหาโดยไม่ทำให้ใครอับอาย"],"options":[{"text":"ออกตัวก่อนนกหวีดบ้าง จะได้ไม่เสียเปรียบ","score":0,"result":"ครูเห็นพอดี ทีมใบเฟิร์นถูกปรับแพ้รอบนั้น และเกมวุ่นวายเพราะหลายคนเริ่มโกงตาม"},{"text":"ตะโกนว่าธามไทขี้โกงต่อหน้าทุกคน","score":0.5,"result":"ครูรู้เรื่อง แต่ธามไทอายและโกรธ สองทีมเถียงกันเสียงดังจนบรรยากาศแย่ลง"},{"text":"บอกครูอย่างสุภาพว่าเห็นธามไทออกตัวก่อนสองรอบ และให้ครูเป็นคนตัดสิน","score":1,"result":"ครูย้ายมาดูที่จุดปล่อยตัวและเห็นเอง ครูเตือนธามไทแล้วเริ่มใหม่ ทุกคนแข่งกันอย่างยุติธรรม"},{"text":"ไม่ทำอะไร เพราะแค่เกมเล่น ๆ","score":0,"result":"ธามไทออกตัวก่อนไปเรื่อย ๆ เพื่อนอีกทีมเริ่มไม่อยากเล่น"}],"solution":["เมื่อเห็นคนผิดกติกา ให้บอกกรรมการอย่างสุภาพ ไม่ตัดสินเองหรือโกงตาม","กรรมการเป็นคนตัดสิน ผู้เล่นทำหน้าที่บอกสิ่งที่เห็นตามจริง"]}]}', 'easy', 5),
('health_teamwork', 'แบ่งงานทำป้ายนิเทศ', '{"icon":"🖍️","story":["ครูให้กลุ่มของน้ำหวานทำป้ายนิเทศเรื่อง \"ล้างมือ 7 ขั้นตอน\" แล้วนำเสนอหน้าชั้น","ทุกคนอยากช่วย แต่ยังไม่รู้ว่าใครควรทำอะไร"],"context":[{"type":"table","title":"สมาชิกในกลุ่ม","head":["สมาชิก","จุดเด่น","ความเห็น"],"rows":[["น้ำหวาน","วาดรูปสวย ระบายสีเก่ง","อยากให้ป้ายมีรูปเยอะ ๆ"],["ภูผา","พูดเสียงดังชัดเจน ไม่ตื่นเต้น","อยากเล่าเรื่องให้เพื่อนฟังสนุก ๆ"],["ต้นกล้า","ลายมือสวย สรุปเนื้อหาเก่ง","อยากให้ข้อความสั้นอ่านง่าย"]]},{"type":"note","text":"แต่ละคนรับผิดชอบงาน 1 อย่าง ไม่ซ้ำกัน"}],"steps":[{"kind":"plan","prompt":"จัดหน้าที่ให้เหมาะกับจุดเด่นของแต่ละคน","skill":"planning","points":10,"hints":["ดูช่องจุดเด่นของแต่ละคนในตาราง","งานแต่ละอย่างใช้ได้คนเดียว"],"fields":[{"id":"f1","label":"น้ำหวาน","options":[{"text":"วาดภาพประกอบ","ok":true},{"text":"เขียนข้อความ","ok":false,"why":"ต้นกล้าลายมือสวยและสรุปเก่งกว่า"},{"text":"นำเสนอหน้าชั้น","ok":false,"why":"ภูผาพูดชัดและไม่ตื่นเต้น เหมาะกว่า"}],"answer":0},{"id":"f2","label":"ภูผา","options":[{"text":"วาดภาพประกอบ","ok":false,"why":"น้ำหวานวาดรูปและระบายสีเก่งกว่า"},{"text":"เขียนข้อความ","ok":false,"why":"ต้นกล้าลายมือสวยและสรุปเก่งกว่า"},{"text":"นำเสนอหน้าชั้น","ok":true}],"answer":2},{"id":"f3","label":"ต้นกล้า","options":[{"text":"วาดภาพประกอบ","ok":false,"why":"น้ำหวานวาดรูปและระบายสีเก่งกว่า"},{"text":"เขียนข้อความ","ok":true},{"text":"นำเสนอหน้าชั้น","ok":false,"why":"ภูผาพูดชัดและไม่ตื่นเต้น เหมาะกว่า"}],"answer":1}],"solution":["น้ำหวานวาดภาพ ต้นกล้าเขียนข้อความ ภูผานำเสนอ","แบ่งงานตามจุดเด่นทำให้งานออกมาดี และทุกคนได้ช่วยคนละส่วนเท่า ๆ กัน"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ควรแบ่งงานตามจุดเด่น","skill":"reason","points":10,"hints":["คิดถึงทั้งผลงานและความเท่าเทียมของงาน"],"options":[{"text":"เพราะงานจะออกมาดี และทุกคนได้ช่วยคนละส่วน ไม่มีใครทำงานหนักคนเดียว","ok":true},{"text":"เพราะจะได้ไม่ต้องคุยกันอีกเลย","ok":false,"why":"ทีมยังต้องคุยกันเพื่อให้ภาพ ข้อความ และการนำเสนอไปในทางเดียวกัน"},{"text":"เพราะคนที่เก่งที่สุดควรเป็นหัวหน้าสั่งทุกคน","ok":false,"why":"จุดเด่นใช้เลือกหน้าที่ ไม่ได้ทำให้ใครมีสิทธิ์สั่งคนอื่น"}],"solution":["การร่วมมือที่ดี คือใช้จุดเด่นของทุกคนและแบ่งงานอย่างยุติธรรม"],"answer":0}]}', 'easy', 6),
('health_teamwork', 'เล่นเกมไหนดี', '{"icon":"🗣️","story":["คาบพละอิสระวันนี้ครูให้กลุ่มเลือกเกมเอง","ครึ่งกลุ่มอยากเล่นฟุตบอล อีกครึ่งอยากเล่นแชร์บอล ทุกคนเริ่มเถียงกันเสียงดัง"],"context":[{"type":"table","title":"ความเห็นของสมาชิก","head":["สมาชิก","อยากเล่น","เหตุผล"],"rows":[["ภูผา","ฟุตบอล","วิ่งได้เยอะ สนุก"],["มะปราง","แชร์บอล","ทุกคนได้จับบอล"],["ต้นกล้า","ฟุตบอล","อยากฝึกไว้แข่งกีฬาสี"],["ใบเฟิร์น","แชร์บอล","ไม่ถนัดเตะบอล"]]},{"type":"note","text":"คาบพละอิสระมีเวลา 40 นาที"}],"steps":[{"kind":"order","prompt":"เรียงขั้นตอนแก้ปัญหาความเห็นไม่ตรงกันให้ถูกต้อง","skill":"rules","points":10,"hints":["ก่อนจะเสนอทางออก ทุกคนต้องเข้าใจกันก่อน","ขั้นสุดท้ายคือการลงมือทำและดูผล"],"items":["หยุดเถียง ตั้งสติ แล้วผลัดกันฟังเหตุผลของทุกคน","ระบุปัญหาให้ชัด: มีเวลา 40 นาที แต่อยากเล่นสองเกม","ช่วยกันเสนอทางเลือก เช่น เล่นเกมละ 20 นาที","ตกลงร่วมกันว่าจะใช้ทางเลือกไหน","ลงมือเล่นตามที่ตกลง แล้วคุยกันหลังเล่นว่าดีไหม"],"solution":["ตั้งสติและฟัง → ระบุปัญหา → เสนอทางเลือก → ตกลงร่วมกัน → ลงมือและทบทวน","ถ้าข้ามขั้นฟังกัน ทางเลือกที่ได้อาจไม่มีใครยอมรับ"]}]}', 'easy', 7),
('health_teamwork', 'ทีมเวิร์กดีหรือยัง', '{"icon":"🧩","story":["ครูให้นักเรียนสังเกตพฤติกรรมของเพื่อนระหว่างเล่นบาสเกตบอลในคาบพละ","ภารกิจของเธอคือแยกว่าพฤติกรรมไหนทำให้ทีมเข้มแข็ง และพฤติกรรมไหนทำให้ทีมอ่อนแอ"],"context":[{"type":"note","text":"ทีมที่เข้มแข็งคือทีมที่ฟังกัน ช่วยกัน เคารพกติกา และไม่ทิ้งใคร"}],"steps":[{"kind":"sort","prompt":"จัดพฤติกรรมแต่ละข้อลงกลุ่มให้ถูก","skill":"analysis","points":10,"hints":["ถามตัวเองว่า ถ้าเพื่อนทำแบบนี้ ทีมจะเล่นด้วยกันได้ดีขึ้นหรือแย่ลง"],"bins":["ช่วยให้ทีมเข้มแข็ง","ทำให้ทีมอ่อนแอ"],"items":[{"text":"ฟังความเห็นเพื่อนจนจบก่อนพูด","bin":0,"why":"การฟังกันทำให้ทีมเข้าใจกันและช่วยกันได้ดี"},{"text":"เลี้ยงบอลคนเดียว ไม่ส่งให้ใคร","bin":1,"why":"เพื่อนไม่ได้มีส่วนร่วม ทีมเล่นเป็นทีมไม่ได้"},{"text":"ชมเพื่อนเมื่อส่งบอลได้ดี","bin":0,"why":"คำชมทำให้เพื่อนมั่นใจและอยากเล่นเป็นทีม"},{"text":"หัวเราะเยาะเพื่อนที่ทำพลาด","bin":1,"why":"ทำให้เพื่อนอาย ไม่กล้าเล่น ทีมเสียกำลังใจ"},{"text":"เคารพการตัดสินของกรรมการ","bin":0,"why":"การเคารพกติกาทำให้เกมยุติธรรมและเล่นต่อได้"},{"text":"แอบเปลี่ยนกติกาให้ทีมตัวเองได้เปรียบ","bin":1,"why":"เป็นการโกง ไม่ยุติธรรมกับทุกคน"},{"text":"ชวนเพื่อนที่ยืนอยู่คนเดียวมาเล่นด้วย","bin":0,"why":"ไม่ทิ้งใคร ทุกคนได้มีส่วนร่วม"},{"text":"ตัดสินใจแทนทั้งทีมโดยไม่ถามใคร","bin":1,"why":"ไม่ฟังความเห็นของคนอื่น ทีมจะไม่เต็มใจทำตาม"}],"solution":["ทีมเข้มแข็งเพราะฟังกัน ชมกัน เคารพกติกา และชวนทุกคนเล่น","การเล่นคนเดียว การล้อเลียน และการโกงทำให้ทีมแตกแยก"]}]}', 'easy', 8),
('health_teamwork', 'เลือกหัวข้อโครงงานสุขภาพ', '{"icon":"📋","story":["กลุ่มของใบเฟิร์นต้องเลือกหัวข้อโครงงานสุขภาพ 1 เรื่อง","แต่ละคนเสนอหัวข้อไม่เหมือนกัน และทุกคนอยากให้เลือกหัวข้อของตัวเอง"],"context":[{"type":"table","title":"หัวข้อที่เพื่อนเสนอ","head":["สมาชิก","หัวข้อที่เสนอ","เหตุผล"],"rows":[["ใบเฟิร์น","ดื่มน้ำเปล่าแทนน้ำหวาน","เพื่อนในห้องซื้อน้ำหวานบ่อย"],["ภูผา","เกมมือถือที่สนุกที่สุด","ชอบเล่นเกม"],["มะปราง","ล้างมือก่อนกินข้าว","เห็นเพื่อนไม่ล้างมือก่อนกินข้าว"]]},{"type":"note","text":"เงื่อนไขของครู: หัวข้อต้องช่วยให้เพื่อนในห้องมีสุขภาพดีขึ้น"}],"steps":[{"kind":"choice","prompt":"วิธีใดเลือกหัวข้อได้ยุติธรรมที่สุด","skill":"decision","points":10,"hints":["วิธีไหนทำให้ทุกคนได้พูด และยังตรวจเงื่อนไขของครูด้วย"],"options":[{"text":"ให้หัวหน้ากลุ่มเลือกคนเดียว","ok":false,"why":"คนอื่นไม่ได้ออกความเห็น ไม่ยุติธรรม"},{"text":"เลือกหัวข้อของคนที่พูดเสียงดังที่สุด","ok":false,"why":"เสียงดังไม่ได้แปลว่าหัวข้อดีที่สุด"},{"text":"จับสลากเลยโดยไม่ต้องคุย","ok":false,"why":"อาจได้หัวข้อที่ไม่ตรงเงื่อนไขของครู เพราะยังไม่ได้ตรวจกัน"},{"text":"ให้ทุกคนเล่าเหตุผล ตรวจว่าหัวข้อไหนตรงเงื่อนไขของครู แล้วโหวตจากหัวข้อที่ผ่าน","ok":true}],"solution":["ฟังทุกคนก่อน แล้วใช้เงื่อนไขเป็นเกณฑ์กลาง ทำให้การตัดสินยุติธรรม","การโหวตหลังฟังเหตุผลทำให้ทุกคนยอมรับผลได้"],"answer":3},{"kind":"choice","prompt":"หัวข้อใดไม่ตรงกับเงื่อนไขของครู","skill":"analysis","points":10,"hints":["หัวข้อไหนไม่ได้ช่วยให้เพื่อนมีสุขภาพดีขึ้น"],"options":[{"text":"ดื่มน้ำเปล่าแทนน้ำหวาน","ok":false,"why":"ช่วยลดน้ำตาล ตรงกับเงื่อนไข"},{"text":"เกมมือถือที่สนุกที่สุด","ok":true},{"text":"ล้างมือก่อนกินข้าว","ok":false,"why":"ช่วยป้องกันเชื้อโรค ตรงกับเงื่อนไข"}],"solution":["หัวข้อเกมมือถือไม่ได้ช่วยให้สุขภาพดีขึ้น","ภูผาอาจปรับเป็น \"ลดเวลาเล่นจอให้ไม่เกินวันละ 2 ชั่วโมง\" ก็จะตรงเงื่อนไข"],"answer":1}]}', 'easy', 9),
('health_teamwork', 'เสิร์ฟพลาดแล้วพูดอะไรดี', '{"icon":"🏐","story":["สีฟ้าแข่งวอลเลย์บอลในวันกีฬาสี","มะปรางเสิร์ฟลูกติดตาข่ายสองครั้งติดกัน เธอเริ่มมือสั่นและไม่อยากเสิร์ฟอีก"],"context":[{"type":"note","text":"ในวอลเลย์บอล ผู้เล่นหมุนตำแหน่งและผลัดกันเสิร์ฟตามลำดับ"}],"steps":[{"kind":"choice","prompt":"คำพูดใดช่วยทีมได้มากที่สุด","skill":"decision","points":10,"hints":["คำพูดไหนทั้งให้กำลังใจและบอกวิธีแก้"],"options":[{"text":"เสิร์ฟอีกทีก็พลาดอีกแหละ","ok":false,"why":"ซ้ำเติมให้เพื่อนยิ่งเสียความมั่นใจ"},{"text":"ให้คนอื่นเสิร์ฟแทนมะปรางไปตลอดเลย","ok":false,"why":"ผู้เล่นต้องผลัดกันเสิร์ฟตามลำดับ และเป็นการกีดกันเพื่อน"},{"text":"ไม่เป็นไรนะ ลองหายใจลึก ๆ แล้วโยนบอลให้สูงขึ้นอีกนิด เราเชื่อว่าทำได้","ok":true},{"text":"ไม่พูดอะไร แต่ทำหน้าเบื่อ","ok":false,"why":"ท่าทางก็สื่อสารได้ ทำให้เพื่อนรู้สึกว่าทีมไม่พอใจ"}],"solution":["คำพูดให้กำลังใจพร้อมวิธีแก้ ช่วยให้เพื่อนหายตื่นเต้นและรู้ว่าต้องทำอะไร"],"answer":2},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่คำพูดให้กำลังใจช่วยทีมได้","skill":"reason","points":10,"hints":["คำพูดเปลี่ยนคะแนนได้ตรง ๆ ไหม หรือเปลี่ยนอะไร"],"options":[{"text":"เพราะเพื่อนจะได้หายตื่นเต้น มีสมาธิ และทีมร่วมมือกันได้ดีขึ้น","ok":true},{"text":"เพราะคำพูดดี ๆ ทำให้ได้คะแนนเพิ่มทันที","ok":false,"why":"คำพูดไม่ได้เพิ่มคะแนนเอง แต่ช่วยให้เพื่อนเล่นได้ดีขึ้น"},{"text":"เพราะเพื่อนจะได้เลี้ยงขนมเราหลังแข่ง","ok":false,"why":"เราให้กำลังใจเพราะเป็นทีมเดียวกัน ไม่ใช่เพื่อหวังของตอบแทน"}],"solution":["การสื่อสารเชิงบวกทำให้ทีมมั่นใจและร่วมมือกันได้ดี"],"answer":0}]}', 'easy', 10),
('health_teamwork', 'จัดทีมขบวนพาเหรดกีฬาสี', '{"icon":"🎺","story":["สีส้มต้องจัดขบวนพาเหรดเดินรอบสนามในวันกีฬาสี","หัวหน้าสีให้ใบเฟิร์นแบ่งหน้าที่ 4 อย่างให้เพื่อน 4 คน แต่ละคนมีความเห็นของตัวเอง"],"context":[{"type":"table","title":"สมาชิกและความเห็น","head":["สมาชิก","จุดเด่น","ข้อจำกัด/ความเห็น"],"rows":[["ภูผา","ตัวสูง แข็งแรง เดินตรงจังหวะ","อยากตีกลอง แต่ยังจับจังหวะไม่แม่น"],["มะปราง","เรียนดนตรี จับจังหวะแม่น","ไม่ชอบเต้นต่อหน้าคนเยอะ"],["ใบเฟิร์น","เต้นเก่ง ร่าเริง จำท่าได้เร็ว","อยากถือป้าย"],["ต้นกล้า","รอบคอบ จดของครบ","ข้อเท้าเพิ่งหายเจ็บ ครูให้เลี่ยงการเดินไกล"]]},{"type":"note","text":"หน้าที่: ถือป้ายนำขบวน (เดินรอบสนาม), ตีกลองให้จังหวะ (เดินรอบสนาม), นำเต้นเชียร์, ดูแลน้ำดื่มและอุปกรณ์ที่จุดพัก คนละ 1 หน้าที่"}],"steps":[{"kind":"plan","prompt":"จัดหน้าที่ให้เหมาะกับจุดเด่นและข้อจำกัดของแต่ละคน","skill":"planning","points":10,"hints":["เริ่มจากคนที่มีข้อจำกัดก่อน ใครเดินไกลไม่ได้","จุดเด่นสำคัญกว่าความอยากเมื่อต้องทำงานให้ทีม"],"fields":[{"id":"f1","label":"ภูผา","options":[{"text":"ถือป้ายนำขบวน","ok":true},{"text":"ตีกลองให้จังหวะ","ok":false,"why":"ภูผายังจับจังหวะไม่แม่น มะปรางจับจังหวะได้ดีกว่า"},{"text":"นำเต้นเชียร์","ok":false,"why":"ใบเฟิร์นเต้นเก่งและจำท่าได้เร็วกว่า"},{"text":"ดูแลน้ำดื่มและอุปกรณ์","ok":false,"why":"หน้าที่นี้ไม่ต้องเดินไกล เหมาะกับต้นกล้าที่ข้อเท้าเพิ่งหาย"}],"answer":0},{"id":"f2","label":"มะปราง","options":[{"text":"ถือป้ายนำขบวน","ok":false,"why":"ภูผาตัวสูงแข็งแรง ถือป้ายได้มั่นคงกว่า"},{"text":"ตีกลองให้จังหวะ","ok":true},{"text":"นำเต้นเชียร์","ok":false,"why":"มะปรางไม่ชอบเต้นต่อหน้าคนเยอะ"},{"text":"ดูแลน้ำดื่มและอุปกรณ์","ok":false,"why":"หน้าที่นี้เหมาะกับต้นกล้าที่ควรเลี่ยงการเดินไกล"}],"answer":1},{"id":"f3","label":"ใบเฟิร์น","options":[{"text":"ถือป้ายนำขบวน","ok":false,"why":"ใบเฟิร์นอยากถือป้าย แต่จุดเด่นคือการเต้น ภูผาถือป้ายได้มั่นคงกว่า"},{"text":"ตีกลองให้จังหวะ","ok":false,"why":"มะปรางเรียนดนตรี จับจังหวะแม่นกว่า"},{"text":"นำเต้นเชียร์","ok":true},{"text":"ดูแลน้ำดื่มและอุปกรณ์","ok":false,"why":"หน้าที่นี้เหมาะกับต้นกล้าที่ควรเลี่ยงการเดินไกล"}],"answer":2},{"id":"f4","label":"ต้นกล้า","options":[{"text":"ถือป้ายนำขบวน","ok":false,"why":"ต้องเดินรอบสนาม ข้อเท้าของต้นกล้าอาจเจ็บซ้ำ"},{"text":"ตีกลองให้จังหวะ","ok":false,"why":"ต้องเดินรอบสนาม ข้อเท้าของต้นกล้าอาจเจ็บซ้ำ"},{"text":"นำเต้นเชียร์","ok":false,"why":"ใบเฟิร์นเต้นเก่งกว่า และการเต้นใช้ข้อเท้ามาก"},{"text":"ดูแลน้ำดื่มและอุปกรณ์","ok":true}],"answer":3}],"solution":["ภูผาถือป้าย มะปรางตีกลอง ใบเฟิร์นนำเต้น ต้นกล้าดูแลน้ำดื่มและอุปกรณ์","จัดตามจุดเด่น และดูแลความปลอดภัยของต้นกล้าที่ข้อเท้าเพิ่งหาย"]},{"kind":"choice","prompt":"ภูผาอยากตีกลองแต่ได้ถือป้าย เหตุผลใดอธิบายให้ภูผาเข้าใจได้ดีที่สุด","skill":"reason","points":10,"hints":["เหตุผลที่ดีอ้างถึงจุดเด่นและประโยชน์ของทีม ไม่ใช่ตำหนิภูผา"],"options":[{"text":"เพราะมะปรางขอตีกลองก่อน","ok":false,"why":"ขอก่อนไม่ได้แปลว่าเหมาะกว่า เหตุผลนี้ไม่ได้อ้างจุดเด่น"},{"text":"เพราะภูผาตีกลองไม่เป็น ไม่ต้องลองอีกแล้ว","ok":false,"why":"เป็นคำพูดดูถูก ทำให้เพื่อนเสียใจ ทีมร่วมมือกันยากขึ้น"},{"text":"เพราะหัวหน้าสีสั่งมาแบบนี้","ok":false,"why":"ไม่ได้อธิบายเหตุผล ภูผาจะไม่เข้าใจว่าทำไม"},{"text":"มะปรางจับจังหวะแม่นจึงทำให้ขบวนเดินพร้อมกัน ส่วนภูผาตัวสูงแข็งแรงจึงถือป้ายได้มั่นคง ทุกคนได้ช่วยทีมด้วยจุดเด่นของตัวเอง","ok":true}],"solution":["อธิบายด้วยจุดเด่นและประโยชน์ของทีม ทำให้เพื่อนยอมรับได้โดยไม่เสียใจ","ภูผายังฝึกตีกลองกับมะปรางเพื่อปีหน้าได้"],"answer":3}]}', 'medium', 11),
('health_teamwork', 'แพ้แล้วอย่าโทษผู้รักษาประตู', '{"icon":"🧤","story":["ทีมฟุตบอลห้อง 5/1 แพ้รอบรองชนะเลิศ 0–3","ภูผาพูดว่า \"แพ้เพราะธามไทรับลูกไม่ได้\" ธามไทผู้รักษาประตูนั่งเงียบอยู่คนเดียว ต้นกล้าเป็นกัปตันทีม"],"context":[{"type":"table","title":"สรุปเกมจากครูผู้ฝึก","head":["ช่วง","สิ่งที่เกิดขึ้น"],"rows":[["ครึ่งแรก","กองหลังไม่ค่อยกลับมาช่วยป้องกัน ผู้รักษาประตูต้องรับคนเดียว"],["ครึ่งหลัง","ส่งบอลพลาดบ่อย เพราะไม่เรียกชื่อกันก่อนส่ง"],["ประตูที่เสีย","ทั้ง 3 ลูกเกิดจากคู่แข่งหลุดเข้ามาหลายคนพร้อมกัน"]]}],"steps":[{"kind":"choice","prompt":"จากสรุปเกม สาเหตุหลักที่ทีมเสียประตูคืออะไร","skill":"analysis","points":10,"hints":["อ่านทุกแถวในตาราง ปัญหาเกิดกับคนเดียวหรือหลายคน"],"options":[{"text":"ผู้รักษาประตูรับบอลไม่ดีคนเดียว","ok":false,"why":"ตารางบอกว่าคู่แข่งหลุดเข้ามาหลายคน เพราะทีมไม่ช่วยป้องกัน"},{"text":"ทั้งทีมไม่ช่วยกันป้องกัน และไม่สื่อสารกันก่อนส่งบอล","ok":true},{"text":"คู่แข่งโกงกติกา","ok":false,"why":"ไม่มีข้อมูลในตารางที่บอกว่าคู่แข่งโกง"},{"text":"สนามลื่นเกินไป","ok":false,"why":"ไม่มีข้อมูลเรื่องสนามในตาราง"}],"solution":["ประตูที่เสียเกิดจากการเล่นของทั้งทีม ไม่ใช่ของคนเดียว","ข้อมูลช่วยให้เราแก้ปัญหาตรงจุดแทนการโทษกัน"],"answer":1},{"kind":"scene","prompt":"ในฐานะกัปตัน ต้นกล้าควรทำอย่างไรหลังเกม","skill":"decision","points":10,"hints":["ทางไหนช่วยทั้งธามไทและช่วยให้ทีมรู้ว่าต้องปรับอะไร"],"options":[{"text":"เรียกทีมล้อมวง บอกว่าเราแพ้ด้วยกัน แล้วชวนดูว่าทั้งทีมพลาดตรงไหน","score":1,"result":"ธามไทรู้สึกดีขึ้น ทุกคนยอมรับว่าไม่ได้กลับมาช่วยป้องกัน และตกลงฝึกเรียกชื่อกันก่อนส่งบอล"},{"text":"บอกให้ธามไทเลิกเป็นผู้รักษาประตู","score":0,"result":"ธามไทเสียใจจนไม่อยากมาซ้อม ทีมยังเสียประตูแบบเดิม เพราะปัญหาการป้องกันไม่ได้ถูกแก้"},{"text":"ไม่พูดเรื่องเกม แยกย้ายกลับบ้าน","score":0.5,"result":"ไม่มีใครทะเลาะกัน แต่ธามไทยังคิดว่าตัวเองผิดคนเดียว และทีมไม่รู้ว่าจะปรับอะไร","then":{"kind":"choice","prompt":"วันรุ่งขึ้น ต้นกล้าจะแก้สถานการณ์อย่างไรดีที่สุด","skill":"decision","points":10,"hints":["ยังไม่สายเกินไปที่จะคุยกันทั้งทีม"],"options":[{"text":"ปล่อยไว้ เดี๋ยวทุกคนก็ลืม","ok":false,"why":"ธามไทยังรู้สึกผิดคนเดียว และทีมจะพลาดแบบเดิมอีก"},{"text":"คุยกับภูผาคนเดียวแล้วสรุปเองว่าใครผิด","ok":false,"why":"ไม่ได้ฟังทุกฝ่าย และยังเป็นการหาคนผิดแทนการแก้ปัญหา"},{"text":"ชวนทั้งทีมดูสรุปเกมด้วยกัน และบอกธามไทว่าทีมไม่ได้โทษเขาคนเดียว","ok":true}],"solution":["การทบทวนเกมด้วยกันทั้งทีมช่วยให้ทุกคนเห็นปัญหาจริง และไม่มีใครถูกโทษคนเดียว"],"answer":2}}],"solution":["กัปตันที่ดีรวมทีมหลังแพ้ ไม่ปล่อยให้ใครถูกโทษคนเดียว","การทบทวนว่าทั้งทีมพลาดตรงไหนนำไปสู่การฝึกที่ตรงจุด"]}]}', 'medium', 12),
('health_teamwork', 'ชนะเพราะนับเกิน', '{"icon":"⚖️","story":["ห้องแข่งกระโดดเชือกหมู่ ทีมละ 1 นาที แต่ละทีมมีคนนับให้ทีมตัวเอง","ภูผานับให้ทีมของใบเฟิร์น และแอบนับเกินจนทีมได้ที่ 1 ใบเฟิร์นนับตามในใจไปด้วย"],"context":[{"type":"table","title":"ผลการกระโดด","head":["ทีม","ครั้งที่กระโดดได้จริง","ครั้งที่ประกาศ"],"rows":[["ทีมใบเฟิร์น","85","95"],["ทีมสีฟ้า","90","90"]]},{"type":"note","text":"กติกา: นับเฉพาะครั้งที่เชือกผ่านใต้เท้าครบ คนนับต้องนับตามจริง"}],"steps":[{"kind":"choice","prompt":"ถ้านับตามจริง ทีมใดชนะ","skill":"analysis","points":10,"hints":["ดูช่อง \"ครั้งที่กระโดดได้จริง\" ไม่ใช่ \"ครั้งที่ประกาศ\""],"options":[{"text":"ทีมใบเฟิร์น เพราะได้ 95 ครั้ง","ok":false,"why":"95 คือตัวเลขที่ภูผานับเกิน ของจริงคือ 85"},{"text":"เสมอกัน","ok":false,"why":"นับจริงได้ 85 กับ 90 ไม่เท่ากัน"},{"text":"ทีมสีฟ้า เพราะกระโดดได้จริง 90 ครั้ง มากกว่า 85","ok":true}],"solution":["ตามจริงทีมสีฟ้าได้ 90 ครั้ง ทีมใบเฟิร์นได้ 85 ครั้ง ทีมสีฟ้าจึงชนะ"],"answer":2},{"kind":"choice","prompt":"ใบเฟิร์นควรทำอย่างไร","skill":"decision","points":10,"hints":["ทางไหนแก้ผลให้ถูกต้อง โดยไม่ทำให้ภูผาอับอายต่อหน้าทุกคน"],"options":[{"text":"ชวนภูผาไปบอกครูตามจริงว่านับเกิน และยอมรับผลใหม่","ok":true},{"text":"เงียบไว้ เพราะทีมเราได้ประโยชน์","ok":false,"why":"ไม่ยุติธรรมกับทีมสีฟ้าที่ทำตามกติกา"},{"text":"ประกาศต่อหน้าทุกคนว่าภูผาขี้โกง","ok":false,"why":"ทำให้ภูผาอับอาย ควรชวนกันไปแก้ไขอย่างสุภาพก่อน"},{"text":"บอกทีมสีฟ้าว่ารอบหน้าให้นับเกินบ้าง","ok":false,"why":"ยิ่งทำให้ทุกทีมโกงกัน กติกาไม่มีความหมาย"}],"solution":["ความซื่อสัตย์ต่อกติกาสำคัญกว่าการชนะ","การชวนเพื่อนไปแก้ไขเองเป็นการช่วยเพื่อน ไม่ใช่การประจาน"],"answer":0},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ต้องแก้ผลให้ถูกต้อง","skill":"reason","points":10,"hints":["คิดถึงทีมที่ทำตามกติกาแล้วกลับแพ้"],"options":[{"text":"เพราะกลัวครูรู้ทีหลังแล้วโดนดุ","ok":false,"why":"ควรทำเพราะถูกต้อง ไม่ใช่เพราะกลัวถูกจับได้"},{"text":"เพราะกติกาใช้กับทุกทีมเท่ากัน ชัยชนะจากการโกงไม่ยุติธรรมกับทีมที่ทำตามกติกา","ok":true},{"text":"เพราะนับเกินแค่ 10 ครั้ง น้อยเกินไปที่จะโกง","ok":false,"why":"โกงมากหรือน้อยก็ไม่ยุติธรรมเท่ากัน"},{"text":"เพราะทีมสีฟ้าเป็นเพื่อนสนิท","ok":false,"why":"ต่อให้ไม่สนิท ก็ต้องแก้ผลให้ถูกต้อง"}],"solution":["กติกาที่ใช้เท่ากันทุกทีมทำให้การแข่งขันยุติธรรมและน่าเชื่อถือ"],"answer":1}]}', 'medium', 13),
('health_teamwork', 'แบ่งไม้แบดให้พอทุกคน', '{"icon":"🏸","story":["คาบพละวันนี้ฝึกตีแบดมินตัน ครูให้ต้นกล้าช่วยแจกไม้แบดให้ 3 กลุ่ม","ทุกกลุ่มขอไม้มากกว่าที่มี และเริ่มเถียงกันว่าใครควรได้เท่าไร"],"context":[{"type":"table","title":"คำขอของแต่ละกลุ่ม","head":["กลุ่ม","จำนวนสมาชิก","ไม้แบดที่ขอ"],"rows":[["กลุ่ม 1","6 คน","8 อัน"],["กลุ่ม 2","4 คน","4 อัน"],["กลุ่ม 3","2 คน","4 อัน"]]},{"type":"note","text":"มีไม้แบดทั้งหมด 12 อัน ครูกำหนดให้ทุกคนมีไม้ของตัวเองคนละ 1 อัน"}],"steps":[{"kind":"choice","prompt":"ควรแบ่งไม้แบดให้แต่ละกลุ่มอย่างไร","skill":"analysis","points":10,"hints":["นับจำนวนสมาชิกรวมกันทั้งหมดก่อน","เทียบกับจำนวนไม้ที่มี"],"options":[{"text":"กลุ่มละ 4 อันเท่ากัน","ok":false,"why":"กลุ่ม 1 มี 6 คน จะมี 2 คนไม่มีไม้ ส่วนกลุ่ม 3 มีไม้เหลือ 2 อัน"},{"text":"ให้ตามที่ขอ 8, 4 และ 4 อัน","ok":false,"why":"รวมเป็น 16 อัน แต่มีไม้แค่ 12 อัน"},{"text":"กลุ่ม 1 ได้ 8 อัน กลุ่ม 2 ได้ 4 อัน กลุ่ม 3 ไม่ได้","ok":false,"why":"กลุ่ม 3 ไม่ได้เล่นเลย และกลุ่ม 1 ได้ไม้เกินจำนวนคน"},{"text":"กลุ่ม 1 ได้ 6 อัน กลุ่ม 2 ได้ 4 อัน กลุ่ม 3 ได้ 2 อัน","ok":true}],"solution":["สมาชิกรวม 6 + 4 + 2 = 12 คน พอดีกับไม้ 12 อัน","แจกตามจำนวนคน ทุกคนได้ไม้คนละ 1 อันตามที่ครูกำหนด"],"answer":3},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่การแบ่งตามจำนวนสมาชิกยุติธรรมกว่าการแบ่งเท่ากันทุกกลุ่ม","skill":"reason","points":10,"hints":["ความยุติธรรมดูที่กลุ่ม หรือดูที่ทุกคน"],"options":[{"text":"เพราะกลุ่มใหญ่สำคัญกว่ากลุ่มเล็ก","ok":false,"why":"ไม่มีกลุ่มไหนสำคัญกว่า ทุกคนสำคัญเท่ากัน"},{"text":"เพราะทำให้ทุกคนมีไม้คนละ 1 อันเท่ากัน และทุกคนได้ฝึกจริง","ok":true},{"text":"เพราะคำนวณง่ายกว่า","ok":false,"why":"ความง่ายไม่ใช่เหตุผลเรื่องความยุติธรรม"},{"text":"เพราะกลุ่มเล็กตีไม่เก่ง","ok":false,"why":"ไม่มีข้อมูลเรื่องฝีมือ และฝีมือไม่ควรใช้ตัดสินว่าใครได้อุปกรณ์"}],"solution":["ความยุติธรรมบางครั้งไม่ใช่ \"เท่ากันทุกกลุ่ม\" แต่เป็น \"ทุกคนได้สิ่งที่จำเป็นเท่ากัน\""],"answer":1}]}', 'medium', 14),
('health_teamwork', 'ไม่มีใครเลือกภูมิ', '{"icon":"🫂","story":["ในคาบพละ หัวหน้าทีมสองคนผลัดกันเลือกสมาชิกทีละคน ภูมิถูกเลือกคนสุดท้ายทุกครั้ง","วันนี้มีเพื่อนพูดว่า \"ไม่ต้องเอาภูมิก็ได้ วิ่งช้า\" ภูมิบอกใบเฟิร์นหัวหน้าห้องว่าไม่อยากเรียนพละอีกแล้ว"],"context":[{"type":"table","title":"ความรู้สึกของแต่ละคน","head":["คน","ความเห็น"],"rows":[["ภูมิ","อายที่ถูกเลือกคนสุดท้าย และเสียใจกับคำพูดของเพื่อน"],["ธามไท (หัวหน้าทีม)","อยากชนะ จึงเลือกคนวิ่งเร็วก่อน"],["มะปราง","อยากให้สองทีมสมดุล ไม่ใช่คนเก่งรวมกันทีมเดียว"]]}],"steps":[{"kind":"order","prompt":"เรียงขั้นตอนที่ใบเฟิร์นจะชวนเพื่อนแก้ปัญหานี้","skill":"planning","points":10,"hints":["ก่อนจะแก้วิธีเลือกทีม ต้องฟังความรู้สึกของทุกฝ่ายก่อน"],"items":["ชวนทุกคนนั่งคุยอย่างใจเย็น และฟังความรู้สึกของภูมิ ธามไท และมะปราง","ระบุปัญหา: วิธีเลือกทีมทำให้มีคนถูกทิ้งและรู้สึกอาย","เสนอทางเลือก เช่น นับเลข 1–2 แบ่งทีม หรือให้ครูจับสลาก","ตกลงร่วมกันว่าคาบหน้าจะใช้วิธีไหน","ลองใช้วิธีใหม่ แล้วถามทุกคนหลังเล่นว่ารู้สึกอย่างไร"],"solution":["ตั้งสติและฟังทุกฝ่าย → ระบุปัญหา → เสนอทางเลือก → ตกลงร่วมกัน → ลงมือและทบทวน","การฟังภูมิก่อนทำให้ทุกคนเห็นว่าปัญหาไม่ใช่ความเร็ว แต่เป็นวิธีเลือกทีม"]},{"kind":"multi","prompt":"การนับเลข 1–2 แบ่งทีม ตรงกับหลักใดบ้าง (เลือกทุกข้อที่ใช่)","skill":"reason","points":10,"hints":["คิดว่าวิธีนี้เปลี่ยนอะไร และไม่ได้เปลี่ยนอะไร"],"options":[{"text":"ยุติธรรม ทุกคนมีโอกาสอยู่ทีมไหนก็ได้เท่ากัน","ok":true},{"text":"ทำให้ทีมของธามไทชนะแน่นอน","ok":false,"why":"การแบ่งแบบนี้ไม่ได้รับประกันว่าใครชนะ"},{"text":"ไม่กีดกันใคร ไม่มีใครถูกเลือกคนสุดท้าย","ok":true},{"text":"แต่ละทีมมีทั้งคนวิ่งเร็วและวิ่งช้า ต้องร่วมมือกันมากขึ้น","ok":true},{"text":"ทำให้ไม่ต้องเล่นตามกติกาของเกม","ok":false,"why":"แบ่งทีมวิธีไหนก็ยังต้องเล่นตามกติกา"}],"solution":["วิธีแบ่งทีมที่ดีทำให้ทุกคนได้เล่นอย่างเท่าเทียม และทีมต้องช่วยกันมากขึ้น"]}]}', 'medium', 15),
('health_teamwork', 'เพื่อนไม่ช่วยทำรายงาน', '{"icon":"📚","story":["กลุ่มของมะปรางทำรายงานเรื่องการป้องกันไข้เลือดออก ต้องส่งวันศุกร์","ภูผายังไม่เริ่มงานของตัวเองเลย มะปรางเริ่มโกรธ"],"context":[{"type":"table","title":"ความคืบหน้า (วันอังคาร)","head":["สมาชิก","งานที่รับ","ความคืบหน้า"],"rows":[["มะปราง","หาข้อมูล","เสร็จแล้ว"],["ต้นกล้า","ทำภาพประกอบ","เสร็จครึ่งหนึ่ง"],["ภูผา","เขียนสรุป","ยังไม่เริ่ม บอกว่าอ่านข้อมูลแล้วไม่เข้าใจ ไม่รู้จะเริ่มอย่างไร"]]}],"steps":[{"kind":"choice","prompt":"มะปรางควรพูดกับภูผาอย่างไรดีที่สุด","skill":"decision","points":10,"hints":["ดูช่องความคืบหน้าของภูผา เขาติดปัญหาอะไร"],"options":[{"text":"ภูผาขี้เกียจที่สุด เราจะฟ้องครูให้ตัดคะแนน","ok":false,"why":"ตำหนิก่อนถามสาเหตุ ทั้งที่ภูผาบอกว่าไม่เข้าใจข้อมูล"},{"text":"ไม่เป็นไร เดี๋ยวเราเขียนแทนเอง","ok":false,"why":"มะปรางรับงานหนักคนเดียว ภูผาไม่ได้เรียนรู้ ไม่ยุติธรรม"},{"text":"เราเป็นห่วงว่างานจะไม่ทันวันศุกร์ ภูผาติดตรงไหน ให้เราช่วยอธิบายข้อมูลไหม","ok":true},{"text":"ไม่คุยกับภูผาอีกเลย","ok":false,"why":"ปัญหาไม่ได้ถูกแก้ และกลุ่มจะส่งงานไม่ทัน"}],"solution":["บอกความรู้สึกของเราและถามปัญหาของเพื่อน ดีกว่าการตำหนิ","ภูผาไม่ได้ไม่อยากทำ แต่ไม่เข้าใจข้อมูล การช่วยอธิบายจึงแก้ตรงจุด"],"answer":2},{"kind":"order","prompt":"เรียงขั้นตอนที่กลุ่มจะใช้แก้ปัญหานี้","skill":"planning","points":10,"hints":["เริ่มจากฟังภูผาก่อน","จบด้วยการตรวจงานก่อนวันส่ง"],"items":["ตั้งสติ แล้วฟังภูผาเล่าว่าติดปัญหาตรงไหน","ระบุปัญหา: ภูผาไม่เข้าใจข้อมูล งานสรุปจึงยังไม่เริ่ม","เสนอทางเลือก เช่น มะปรางอธิบายข้อมูล 10 นาที หรือสลับงานกับต้นกล้า","ตกลงร่วมกันว่าใครทำอะไร และเสร็จภายในวันไหน","ลงมือทำ แล้วนัดตรวจงานด้วยกันวันพฤหัสก่อนส่ง"],"solution":["ฟัง → ระบุปัญหา → เสนอทางเลือก → ตกลงร่วมกัน → ลงมือและทบทวน","การนัดตรวจงานก่อนวันส่งช่วยให้แก้ไขทันถ้ายังมีจุดพลาด"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่มะปรางไม่ควรเขียนสรุปแทนภูผา","skill":"reason","points":10,"hints":["คิดถึงทั้งภาระงานและการเรียนรู้ของทุกคน"],"options":[{"text":"เพราะงานกลุ่มควรแบ่งความรับผิดชอบให้ทุกคน ทุกคนได้เรียนรู้ และไม่มีใครแบกงานคนเดียว","ok":true},{"text":"เพราะมะปรางเขียนสรุปไม่เก่ง","ok":false,"why":"ไม่มีข้อมูลบอกว่ามะปรางเขียนไม่เก่ง"},{"text":"เพราะครูห้ามเพื่อนช่วยเพื่อน","ok":false,"why":"การช่วยอธิบายทำได้ สิ่งที่ไม่ควรคือทำแทนทั้งหมด"}],"solution":["ความยุติธรรมในงานกลุ่มคือทุกคนรับผิดชอบส่วนของตัวเอง","การช่วยกันคืออธิบายให้เข้าใจ ไม่ใช่ทำแทน"],"answer":0}]}', 'medium', 16),
('health_teamwork', 'โครงงานสำรวจการล้างมือ', '{"icon":"🧼","story":["กลุ่มของใบเฟิร์นทำโครงงานสุขภาพ สำรวจว่าเพื่อนล้างมือก่อนกินข้าวกี่คน แล้วสาธิตการล้างมือ 7 ขั้นตอน","ทุกคนอยากทำงานที่ตัวเองชอบ แต่ต้องแบ่ง 4 หน้าที่ให้ 4 คน"],"context":[{"type":"table","title":"สมาชิกในกลุ่ม","head":["สมาชิก","จุดเด่น","ความเห็น"],"rows":[["ใบเฟิร์น","คิดเลขแม่น ชอบทำแผนภูมิ","อยากไปสังเกตที่อ่างล้างมือด้วย"],["ภูผา","กล้าแสดงออก จำขั้นตอนล้างมือได้ครบ 7 ขั้น","อยากสาธิตให้น้อง ๆ ดู"],["มะปราง","ช่างสังเกต จดละเอียด","อยากไปสังเกตที่อ่างล้างมือ"],["ต้นกล้า","สุภาพ ตรงต่อเวลา","อยากช่วยงานไหนก็ได้"]]},{"type":"note","text":"หน้าที่: สังเกตและจดบันทึกที่อ่างล้างมือ, ทำแผนภูมิสรุปผล, สาธิตล้างมือ 7 ขั้นตอน, นัดเวลากับครูและน้อง ๆ แต่ละงานมีคนรับผิดชอบ 1 คน"}],"steps":[{"kind":"plan","prompt":"จัดหน้าที่ให้เหมาะกับจุดเด่นของแต่ละคน","skill":"planning","points":10,"hints":["มีสองคนอยากไปสังเกต ใครมีจุดเด่นตรงกับงานนั้นมากกว่า"],"fields":[{"id":"f1","label":"ใบเฟิร์น","options":[{"text":"สังเกตและจดบันทึก","ok":false,"why":"มะปรางช่างสังเกตและจดละเอียดกว่า ใบเฟิร์นเด่นเรื่องตัวเลข"},{"text":"ทำแผนภูมิสรุปผล","ok":true},{"text":"สาธิตล้างมือ","ok":false,"why":"ภูผาจำขั้นตอนได้ครบและกล้าแสดงออกกว่า"},{"text":"นัดเวลากับครูและน้อง ๆ","ok":false,"why":"ต้นกล้าสุภาพและตรงต่อเวลา เหมาะกว่า"}],"answer":1},{"id":"f2","label":"ภูผา","options":[{"text":"สังเกตและจดบันทึก","ok":false,"why":"มะปรางช่างสังเกตและจดละเอียดกว่า"},{"text":"ทำแผนภูมิสรุปผล","ok":false,"why":"ใบเฟิร์นคิดเลขแม่นและชอบทำแผนภูมิ"},{"text":"สาธิตล้างมือ","ok":true},{"text":"นัดเวลากับครูและน้อง ๆ","ok":false,"why":"ต้นกล้าสุภาพและตรงต่อเวลา เหมาะกว่า"}],"answer":2},{"id":"f3","label":"มะปราง","options":[{"text":"สังเกตและจดบันทึก","ok":true},{"text":"ทำแผนภูมิสรุปผล","ok":false,"why":"ใบเฟิร์นคิดเลขแม่นและชอบทำแผนภูมิ"},{"text":"สาธิตล้างมือ","ok":false,"why":"ภูผาจำขั้นตอนได้ครบและกล้าแสดงออกกว่า"},{"text":"นัดเวลากับครูและน้อง ๆ","ok":false,"why":"ต้นกล้าสุภาพและตรงต่อเวลา เหมาะกว่า"}],"answer":0},{"id":"f4","label":"ต้นกล้า","options":[{"text":"สังเกตและจดบันทึก","ok":false,"why":"มะปรางช่างสังเกตและจดละเอียดกว่า"},{"text":"ทำแผนภูมิสรุปผล","ok":false,"why":"ใบเฟิร์นคิดเลขแม่นและชอบทำแผนภูมิ"},{"text":"สาธิตล้างมือ","ok":false,"why":"ภูผาจำขั้นตอนได้ครบและกล้าแสดงออกกว่า"},{"text":"นัดเวลากับครูและน้อง ๆ","ok":true}],"answer":3}],"solution":["ใบเฟิร์นทำแผนภูมิ ภูผาสาธิต มะปรางสังเกตและจด ต้นกล้านัดเวลา","เมื่อสองคนอยากทำงานเดียวกัน ให้ใช้จุดเด่นเป็นเกณฑ์ตัดสิน"]},{"kind":"multi","prompt":"แผนแบ่งงานนี้ตรงกับหลักใดบ้าง (เลือกทุกข้อที่ใช่)","skill":"reason","points":10,"hints":["ตรวจทีละหลัก: ภาระงาน การใช้จุดเด่น และเงื่อนไขในข้อมูล"],"options":[{"text":"ทุกคนมีงานคนละ 1 อย่าง ภาระเท่า ๆ กัน","ok":true},{"text":"ใช้จุดเด่นของแต่ละคนให้ทีมทำงานได้ดี","ok":true},{"text":"ทำตามเงื่อนไขว่าแต่ละงานมีคนรับผิดชอบ 1 คน","ok":true},{"text":"ทุกคนได้ทำงานที่ตัวเองอยากทำที่สุด","ok":false,"why":"ใบเฟิร์นอยากไปสังเกต แต่ได้ทำแผนภูมิซึ่งตรงกับจุดเด่นมากกว่า"},{"text":"ไม่ต้องคุยกันอีกจนกว่าจะส่งงาน","ok":false,"why":"ทีมยังต้องนัดคุยเพื่อส่งต่อข้อมูลจากคนจดไปคนทำแผนภูมิ"}],"solution":["แผนนี้ยุติธรรม ใช้จุดเด่นให้ร่วมมือกันได้ดี และทำตามเงื่อนไข","แต่ไม่ได้แปลว่าทุกคนได้งานที่อยากทำที่สุด และยังต้องสื่อสารกันตลอด"]}]}', 'medium', 17),
('health_teamwork', 'ท่าเต้นเชียร์ยากหรือง่าย', '{"icon":"📣","story":["สีเหลืองต้องคิดท่าเต้นเชียร์ให้กองเชียร์ทั้งหมด","ใบเฟิร์นกับต้นกล้าเสนอไม่เหมือนกัน และต่างฝ่ายต่างมีเพื่อนสนับสนุน"],"context":[{"type":"table","title":"ข้อเสนอสองฝ่าย","head":["ฝ่าย","ข้อเสนอ","เหตุผล"],"rows":[["ฝ่ายใบเฟิร์น","ท่ายาก 10 ท่า","ดูสวย น่าจะชนะการประกวด"],["ฝ่ายต้นกล้า","ท่าง่าย 4 ท่า","มีน้อง ป.1 ในกองเชียร์ด้วย กลัวจำไม่ทัน"]]},{"type":"note","text":"ซ้อมได้ 5 วัน วันละ 30 นาที กองเชียร์มีนักเรียน ป.1–ป.6 และครูอยากให้ทุกคนได้เต้น"}],"steps":[{"kind":"choice","prompt":"ทางเลือกใดดีที่สุดสำหรับกองเชียร์ทั้งหมด","skill":"decision","points":10,"hints":["มีทางที่รวมข้อดีของทั้งสองฝ่ายไหม"],"options":[{"text":"ใช้ท่ายาก 10 ท่า ใครจำไม่ได้ก็ไม่ต้องเต้น","ok":false,"why":"น้อง ๆ ถูกกีดกัน ขัดกับที่ครูอยากให้ทุกคนได้เต้น"},{"text":"โหวตทันทีโดยไม่ต้องฟังเหตุผล","ok":false,"why":"ไม่ได้ฟังกัน อีกฝ่ายจะรู้สึกว่าไม่ได้รับความสนใจ"},{"text":"ใช้ท่าง่ายที่ทุกคนทำได้เป็นหลัก แล้วเพิ่มท่ายาก 2 ท่าให้พี่ ๆ ที่ซ้อมไหวเต้นแถวหน้า","ok":true},{"text":"เลิกเต้น ไม่ต้องประกวด","ok":false,"why":"ไม่ได้แก้ปัญหา ทุกฝ่ายเสียโอกาส"}],"solution":["การประนีประนอมที่ดีรวมข้อดีของทั้งสองฝ่าย","ทุกคนได้เต้น และกองเชียร์ยังมีท่าเด่นให้ประกวด"],"answer":2},{"kind":"choice","prompt":"เหตุผลใดสนับสนุนทางเลือกนี้ได้ดีที่สุด","skill":"reason","points":10,"hints":["ย้อนดูเงื่อนไขในข้อมูล: เวลาซ้อม และใครอยู่ในกองเชียร์"],"options":[{"text":"เพราะฝ่ายต้นกล้าเป็นรุ่นพี่","ok":false,"why":"ความเป็นรุ่นพี่ไม่ใช่เหตุผลว่าใครถูก"},{"text":"เพราะท่ายากไม่สวย","ok":false,"why":"ไม่มีข้อมูลบอกแบบนั้น ท่ายากก็สวยได้"},{"text":"เพราะทำให้ไม่ต้องซ้อมเลย","ok":false,"why":"ยังต้องซ้อมทุกวัน แค่ซ้อมทันมากขึ้น"},{"text":"เพราะทุกคนในกองเชียร์ได้ร่วมเต้น ซ้อมทันใน 5 วัน และยังใช้ความคิดของทั้งสองฝ่าย","ok":true}],"solution":["เหตุผลที่ดีอ้างข้อมูลจริง: เวลาซ้อม 5 วัน และกองเชียร์มีน้องเล็ก","และคำนึงถึงทุกฝ่าย ไม่ใช่ฝ่ายใดฝ่ายหนึ่ง"],"answer":3}]}', 'medium', 18),
('health_teamwork', 'รีบจนลืมอบอุ่นร่างกาย', '{"icon":"🏃","story":["ทีมวิ่งผลัดเหลือเวลาซ้อม 15 นาทีก่อนแข่งกีฬาสี","ภูผาเสนอให้ข้ามการอบอุ่นร่างกาย เพื่อซ้อมส่งไม้ให้นานที่สุด"],"context":[{"type":"table","title":"ความเห็นในทีม","head":["สมาชิก","ความเห็น"],"rows":[["ภูผา","ข้ามการอบอุ่นร่างกาย ซ้อมส่งไม้ 15 นาทีเต็ม"],["มะปราง","อบอุ่นร่างกายก่อน กลัวกล้ามเนื้อบาดเจ็บ"],["ต้นกล้า","ต้องซ้อมส่งไม้ เพราะรอบที่แล้วไม้หล่น"]]},{"type":"note","text":"ครูพละย้ำว่า ต้องอบอุ่นร่างกาย 5–10 นาทีก่อนออกกำลังกายทุกครั้ง"}],"steps":[{"kind":"scene","prompt":"ทีมควรใช้เวลา 15 นาทีอย่างไร","skill":"decision","points":10,"hints":["มีทางที่ดูแลทั้งความปลอดภัยและปัญหาไม้หล่นไหม"],"options":[{"text":"ข้ามการอบอุ่นร่างกาย ซ้อมส่งไม้ 15 นาทีเต็ม","score":0,"result":"ช่วงท้ายภูผารู้สึกตึงที่น่อง ต้องหยุดวิ่ง ทีมเลยซ้อมได้น้อยกว่าเดิม","then":{"kind":"choice","prompt":"ภูผารู้สึกตึงที่น่อง ทีมควรทำอย่างไรต่อ","skill":"decision","points":10,"hints":["ใครควรเป็นคนดูแลเมื่อมีคนบาดเจ็บ"],"options":[{"text":"ให้ภูผาวิ่งต่อ เดี๋ยวก็หาย","ok":false,"why":"อาจทำให้บาดเจ็บมากขึ้น"},{"text":"ให้ภูผาหยุดวิ่ง นั่งพัก และบอกครูพละทันที","ok":true},{"text":"หายาในกระเป๋าเพื่อนมาทาให้","ok":false,"why":"ไม่ควรใช้ยาเอง ควรให้ครูหรือผู้ใหญ่ดูแล"}],"solution":["เมื่อรู้สึกเจ็บหรือตึงขณะออกกำลังกาย ให้หยุดทันทีและบอกครู"],"answer":1}},{"text":"อบอุ่นร่างกาย 5 นาที แล้วซ้อมส่งไม้ 10 นาที","score":1,"result":"ทุกคนพร้อมทั้งร่างกาย ส่งไม้ได้คล่องขึ้น และไม่มีใครบาดเจ็บ ความเห็นของมะปรางและต้นกล้าได้รับการดูแลทั้งคู่"},{"text":"อบอุ่นร่างกาย 15 นาทีเต็ม ไม่ซ้อมส่งไม้","score":0.5,"result":"ร่างกายพร้อม แต่ปัญหาไม้หล่นยังไม่ได้แก้ ต้นกล้ากังวลว่าวันแข่งจะพลาดอีก"}],"solution":["อบอุ่นร่างกาย 5–10 นาทีก่อนเสมอ แล้วใช้เวลาที่เหลือแก้ปัญหาที่สำคัญ","แผนที่ดีดูแลความปลอดภัยและเป้าหมายของทีมไปพร้อมกัน"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ไม่ควรข้ามการอบอุ่นร่างกาย","skill":"reason","points":10,"hints":["การอบอุ่นร่างกายช่วยอะไรกับกล้ามเนื้อ"],"options":[{"text":"เพราะมะปรางพูดก่อนภูผา","ok":false,"why":"ใครพูดก่อนไม่ใช่เหตุผล"},{"text":"เพราะอบอุ่นร่างกายแล้วจะวิ่งเร็วขึ้นสองเท่า","ok":false,"why":"ไม่จริง จุดสำคัญของการอบอุ่นร่างกายคือความปลอดภัย"},{"text":"เพราะการอบอุ่นร่างกายเตรียมกล้ามเนื้อและข้อต่อ ลดโอกาสบาดเจ็บ และเป็นกติกาความปลอดภัยที่ครูกำหนด","ok":true},{"text":"เพราะจะได้มีเวลาพักเหนื่อย","ok":false,"why":"การอบอุ่นร่างกายไม่ใช่การพัก แต่เป็นการเตรียมร่างกาย"}],"solution":["การอบอุ่นร่างกายทำให้กล้ามเนื้อพร้อม ลดการบาดเจ็บ","ความปลอดภัยต้องมาก่อนการซ้อมให้ได้นาน"],"answer":2}]}', 'medium', 19),
('health_teamwork', 'วิ่งสามขาต้องคุยกัน', '{"icon":"👣","story":["ต้นกล้าและใบเฟิร์นจับคู่แข่งวิ่งสามขาในวันกีฬาสี","ซ้อมกี่ครั้งก็ล้ม เพราะก้าวขาไม่พร้อมกัน และเริ่มโทษกันไปมา"],"context":[{"type":"note","text":"วิ่งสามขา: ผูกข้อเท้าข้างหนึ่งของสองคนไว้ด้วยกัน ต้องก้าวขาที่ผูกพร้อมกันจึงจะไม่ล้ม"}],"steps":[{"kind":"sort","prompt":"จัดคำพูดแต่ละข้อลงกลุ่มให้ถูก","skill":"analysis","points":10,"hints":["คำพูดไหนช่วยให้สองคนรู้ว่าต้องก้าวเมื่อไร"],"bins":["ช่วยให้คู่ก้าวพร้อมกัน","ทำให้คู่ทะเลาะหรือสับสน"],"items":[{"text":"นับ 1–2 พร้อมกัน ขาที่ผูกก้าวก่อนนะ","bin":0,"why":"บอกสัญญาณชัดเจน ทั้งคู่ก้าวพร้อมกันได้"},{"text":"ทำไมก้าวช้าแบบนี้ ล้มเพราะเธอเลย","bin":1,"why":"เป็นการโทษกัน ไม่ได้บอกวิธีแก้"},{"text":"ช้าลงนิดหนึ่งได้ไหม เราตามไม่ทัน","bin":0,"why":"บอกปัญหาของตัวเองอย่างสุภาพ คู่จะปรับได้"},{"text":"วิ่งไปเลย เดี๋ยวเราตามเอง","bin":1,"why":"ไม่มีจังหวะร่วมกัน วิ่งสามขาจะล้ม"},{"text":"ไม่เป็นไร ลุกขึ้นแล้วลองใหม่ด้วยกัน","bin":0,"why":"ให้กำลังใจ ทำให้ทั้งคู่กล้าลองต่อ"},{"text":"ตกลงกันก่อนว่าใครเป็นคนนับจังหวะ","bin":0,"why":"แบ่งหน้าที่ชัดเจน ไม่สับสนว่าจะฟังใคร"},{"text":"เงียบแล้วเร่งวิ่งสุดแรง","bin":1,"why":"ไม่สื่อสารกันเลย อีกคนไม่รู้ว่าจะก้าวเมื่อไร"}],"solution":["การสื่อสารที่ดีบอกสัญญาณชัดเจน บอกปัญหาอย่างสุภาพ และให้กำลังใจ","การโทษกันหรือไม่พูดกันทำให้ล้มซ้ำ"]},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่การตกลงสัญญาณก่อนวิ่งสำคัญมากในเกมนี้","skill":"reason","points":10,"hints":["อ่านข้อมูลอีกครั้ง เกมนี้ต้องทำอะไรพร้อมกัน"],"options":[{"text":"เพราะทั้งสองคนต้องก้าวพร้อมกัน สัญญาณที่ชัดเจนช่วยให้ไม่ล้มและไม่บาดเจ็บ","ok":true},{"text":"เพราะเกมนี้วัดว่าใครพูดเสียงดังกว่า","ok":false,"why":"เกมวัดว่าวิ่งถึงเส้นชัยได้ดีแค่ไหน ไม่ได้วัดเสียง"},{"text":"เพราะจะได้รู้ว่าใครผิดเมื่อล้ม","ok":false,"why":"สัญญาณมีไว้ช่วยกัน ไม่ใช่ไว้หาคนผิด"},{"text":"เพราะกรรมการบังคับให้พูด","ok":false,"why":"ไม่มีกติกาบังคับ แต่การสื่อสารช่วยทีมเอง"}],"solution":["เกมที่ต้องทำพร้อมกันต้องอาศัยการสื่อสารชัดเจน","การสื่อสารที่ดีทำให้ปลอดภัยและร่วมมือกันได้"],"answer":0}]}', 'medium', 20),
('health_teamwork', 'จัดนักวิ่งผลัดกีฬาสี', '{"icon":"🏅","story":["สีส้มต้องส่งนักวิ่งผลัด 4 คน และผู้ช่วยทีม 1 คน ลงแข่งวันกีฬาสี","ต้นกล้าอยากวิ่งไม้สุดท้าย แต่เมื่อวานข้อเท้าพลิก ครูพยาบาลบอกให้งดวิ่ง 1 สัปดาห์","ทีมมีสมาชิก 5 คน ทุกคนอยากมีส่วนร่วม"],"context":[{"type":"table","title":"ข้อมูลสมาชิก","head":["สมาชิก","เวลาวิ่ง 50 เมตร","จุดเด่น/ข้อสังเกต"],"rows":[["ภูผา","8.1 วินาที","เร็วที่สุด ใจสู้ช่วงท้าย"],["ต้นกล้า","8.3 วินาที","ข้อเท้าพลิก ครูให้งดวิ่ง 1 สัปดาห์"],["มะปราง","8.6 วินาที","ออกตัวเร็วมาก ตั้งใจฟังเสียงปล่อยตัว"],["ใบเฟิร์น","8.9 วินาที","รับและส่งไม้แม่นที่สุดในทีม"],["ธามไท","9.0 วินาที","วิ่งทางโค้งได้ดี ไม่เสียหลัก"]]},{"type":"note","text":"กติกา: นักวิ่งแต่ละคนวิ่งได้ 1 ช่วงเท่านั้น ไม้ 1 ออกตัวตามเสียงปล่อย ไม้ 2 รับและส่งไม้บนทางตรง ไม้ 3 วิ่งช่วงโค้งยาว ไม้ 4 วิ่งเข้าเส้นชัย ผู้ช่วยทีมจับเวลาซ้อมและเตรียมน้ำดื่ม"}],"steps":[{"kind":"choice","prompt":"แผนใดคำนึงถึงความยุติธรรม การร่วมมือ กติกา และความปลอดภัยครบทุกข้อ","skill":"decision","points":10,"hints":["ตรวจทีละแผน: มีใครเสี่ยงบาดเจ็บไหม ผิดกติกาไหม ทิ้งใครไว้ไหม","แผนที่ผิดแต่ละแผนพลาดเพียงหลักเดียว"],"options":[{"text":"ให้ต้นกล้าวิ่งไม้ 4 เพราะวิ่งเร็วเป็นอันดับสองและอยากวิ่ง ส่วนคนอื่นจัดตามจุดเด่น และซ้อมส่งไม้ด้วยกัน","ok":false,"why":"ไม่ปลอดภัย ครูให้ต้นกล้างดวิ่ง ข้อเท้าอาจบาดเจ็บซ้ำ"},{"text":"ให้ภูผาวิ่งทั้งไม้ 1 และไม้ 4 เพราะเร็วที่สุด ให้ต้นกล้าเป็นผู้ช่วยทีม และซ้อมส่งไม้ด้วยกัน","ok":false,"why":"ผิดกติกา นักวิ่งแต่ละคนวิ่งได้ 1 ช่วงเท่านั้น"},{"text":"ให้ต้นกล้าเป็นผู้ช่วยทีมตามคำแนะนำครู ใช้อีก 4 คนวิ่งตามจุดเด่น และชวนต้นกล้าช่วยดูจังหวะส่งไม้ตอนซ้อม","ok":true},{"text":"จัด 4 คนวิ่งตามจุดเด่น และซ้อมส่งไม้ด้วยกัน ส่วนต้นกล้าไม่ต้องมาร่วมทีม เพราะวิ่งไม่ได้แล้ว","ok":false,"why":"ไม่ยุติธรรม ต้นกล้ายังเป็นสมาชิกทีมและมีหน้าที่ผู้ช่วยทีมได้ ไม่ควรถูกทิ้ง"}],"solution":["แผนที่ถูกปลอดภัย (ต้นกล้าไม่วิ่ง) ทำตามกติกา (คนละ 1 ช่วง) ยุติธรรม (ทุกคนมีหน้าที่) และร่วมมือกัน (ซ้อมด้วยกัน)"],"answer":2},{"kind":"plan","prompt":"จัดหน้าที่ให้สมาชิกทั้ง 5 คน","skill":"planning","points":10,"hints":["เริ่มจากคนที่วิ่งไม่ได้ก่อน","จับคู่จุดเด่นในตารางกับคำอธิบายแต่ละไม้ในกติกา"],"fields":[{"id":"f1","label":"ภูผา","options":[{"text":"ไม้ 1 ออกตัว","ok":false,"why":"มะปรางออกตัวเร็วที่สุด ภูผาเร็วและใจสู้ เหมาะกับช่วงเข้าเส้นชัย"},{"text":"ไม้ 2 รับและส่งไม้","ok":false,"why":"ใบเฟิร์นรับส่งไม้แม่นที่สุด"},{"text":"ไม้ 3 ช่วงโค้ง","ok":false,"why":"ธามไทวิ่งทางโค้งได้ดีที่สุด"},{"text":"ไม้ 4 เข้าเส้นชัย","ok":true},{"text":"ผู้ช่วยทีม","ok":false,"why":"ภูผาวิ่งได้และเร็วที่สุด ผู้ช่วยทีมควรเป็นคนที่ครูให้งดวิ่ง"}],"answer":3},{"id":"f2","label":"ต้นกล้า","options":[{"text":"ไม้ 1 ออกตัว","ok":false,"why":"ครูให้ต้นกล้างดวิ่ง 1 สัปดาห์"},{"text":"ไม้ 2 รับและส่งไม้","ok":false,"why":"ครูให้ต้นกล้างดวิ่ง 1 สัปดาห์"},{"text":"ไม้ 3 ช่วงโค้ง","ok":false,"why":"ครูให้ต้นกล้างดวิ่ง 1 สัปดาห์"},{"text":"ไม้ 4 เข้าเส้นชัย","ok":false,"why":"ครูให้ต้นกล้างดวิ่ง 1 สัปดาห์ แม้จะอยากวิ่งไม้นี้"},{"text":"ผู้ช่วยทีม","ok":true}],"answer":4},{"id":"f3","label":"มะปราง","options":[{"text":"ไม้ 1 ออกตัว","ok":true},{"text":"ไม้ 2 รับและส่งไม้","ok":false,"why":"ใบเฟิร์นรับส่งไม้แม่นกว่า มะปรางเด่นเรื่องออกตัว"},{"text":"ไม้ 3 ช่วงโค้ง","ok":false,"why":"ธามไทวิ่งทางโค้งได้ดีกว่า"},{"text":"ไม้ 4 เข้าเส้นชัย","ok":false,"why":"ภูผาเร็วที่สุดและใจสู้ช่วงท้าย"},{"text":"ผู้ช่วยทีม","ok":false,"why":"มะปรางวิ่งได้ ผู้ช่วยทีมควรเป็นคนที่ครูให้งดวิ่ง"}],"answer":0},{"id":"f4","label":"ใบเฟิร์น","options":[{"text":"ไม้ 1 ออกตัว","ok":false,"why":"มะปรางออกตัวเร็วกว่า"},{"text":"ไม้ 2 รับและส่งไม้","ok":true},{"text":"ไม้ 3 ช่วงโค้ง","ok":false,"why":"ธามไทวิ่งทางโค้งได้ดีกว่า"},{"text":"ไม้ 4 เข้าเส้นชัย","ok":false,"why":"ภูผาเร็วที่สุดและใจสู้ช่วงท้าย"},{"text":"ผู้ช่วยทีม","ok":false,"why":"ใบเฟิร์นวิ่งได้ ผู้ช่วยทีมควรเป็นคนที่ครูให้งดวิ่ง"}],"answer":1},{"id":"f5","label":"ธามไท","options":[{"text":"ไม้ 1 ออกตัว","ok":false,"why":"มะปรางออกตัวเร็วกว่า"},{"text":"ไม้ 2 รับและส่งไม้","ok":false,"why":"ใบเฟิร์นรับส่งไม้แม่นกว่า"},{"text":"ไม้ 3 ช่วงโค้ง","ok":true},{"text":"ไม้ 4 เข้าเส้นชัย","ok":false,"why":"ภูผาเร็วที่สุดและใจสู้ช่วงท้าย"},{"text":"ผู้ช่วยทีม","ok":false,"why":"ธามไทวิ่งได้ ผู้ช่วยทีมควรเป็นคนที่ครูให้งดวิ่ง"}],"answer":2}],"solution":["มะปรางไม้ 1 ใบเฟิร์นไม้ 2 ธามไทไม้ 3 ภูผาไม้ 4 ต้นกล้าเป็นผู้ช่วยทีม","ทุกคนได้หน้าที่ตามจุดเด่น และต้นกล้ายังเป็นส่วนหนึ่งของทีมอย่างปลอดภัย"]},{"kind":"choice","prompt":"ภูผาบอกว่า \"ต้นกล้าเร็วกว่าใบเฟิร์น ควรได้วิ่ง\" เหตุผลใดตอบได้ดีที่สุด","skill":"reason","points":10,"hints":["ข้อมูลไหนในตารางสำคัญกว่าเวลาวิ่ง"],"options":[{"text":"เพราะใบเฟิร์นอยากวิ่งมากกว่า","ok":false,"why":"ความอยากไม่ใช่เหตุผลหลัก ต้นกล้าก็อยากวิ่ง"},{"text":"เพราะต้นกล้าวิ่งไม่เก่งแล้ว","ok":false,"why":"ไม่จริง ต้นกล้าวิ่งเร็ว แต่ตอนนี้ต้องพักรักษาข้อเท้า"},{"text":"เพราะถ้าแพ้ จะได้ไม่โทษต้นกล้า","ok":false,"why":"ไม่ควรเลือกเพื่อหาคนผิด ทีมแพ้ชนะด้วยกัน"},{"text":"เพราะความปลอดภัยของเพื่อนสำคัญกว่าการชนะ ครูให้ต้นกล้างดวิ่ง ถ้าฝืนอาจบาดเจ็บหนักขึ้น","ok":true}],"solution":["ข้อมูลเรื่องการบาดเจ็บสำคัญกว่าเวลาวิ่ง","ความปลอดภัยต้องมาก่อนชัยชนะเสมอ"],"answer":3}]}', 'hard', 21),
('health_teamwork', 'ละครสั้นวันสุขภาพ', '{"icon":"🎭","story":["กลุ่มของใบเฟิร์นต้องแสดงละครสั้นเรื่อง \"กินอาหารครบ 5 หมู่\" ในวันสุขภาพ","มะปรางกับธามไทเถียงกันเรื่องบทจนภูผาไม่อยากมาซ้อม","เหลือเวลาซ้อมอีก 3 วัน"],"context":[{"type":"table","title":"สมาชิกในกลุ่ม","head":["สมาชิก","ความเห็น","จุดเด่น"],"rows":[["มะปราง","อยากเล่นบทยาว มีมุกตลกเยอะ","แต่งบทเก่ง"],["ธามไท","อยากให้บทสั้น เพราะกลัวเกินเวลา","จับเวลาเก่ง ละเอียด"],["ภูผา","ไม่อยากเลือกข้าง จึงไม่มาซ้อม","เสียงดัง แสดงเก่ง"],["ใบเฟิร์น","อยากให้ทุกคนกลับมาซ้อมด้วยกัน","ประดิษฐ์อุปกรณ์ประกอบฉากเก่ง"]]},{"type":"note","text":"กติกาจากครู: แสดงได้ไม่เกิน 5 นาที และทุกคนในกลุ่มต้องมีหน้าที่"}],"steps":[{"kind":"order","prompt":"เรียงขั้นตอนที่กลุ่มจะใช้แก้ความขัดแย้งนี้","skill":"planning","points":10,"hints":["ภูผาไม่มาซ้อมเพราะอะไร ต้องฟังให้ครบทุกคนก่อน"],"items":["นัดคุยกันทั้งกลุ่ม ทุกคนใจเย็น และผลัดกันพูดโดยไม่ขัดจังหวะ","ระบุปัญหา: บทยาวเสี่ยงเกิน 5 นาที และภูผาไม่มาซ้อมเพราะไม่อยากเลือกข้าง","เสนอทางเลือก เช่น เก็บมุกที่ดีที่สุดไว้ แล้วตัดฉากที่ยาวออก","ตกลงร่วมกันเรื่องบทและตารางซ้อม 3 วัน","ซ้อมจริงพร้อมจับเวลา แล้วทบทวนว่าต้องปรับอะไรอีก"],"solution":["ฟังทุกฝ่าย → ระบุปัญหา → เสนอทางเลือก → ตกลงร่วมกัน → ลงมือและทบทวน","การจับเวลาตอนซ้อมคือการตรวจว่าแผนทำตามกติกาจริง"]},{"kind":"plan","prompt":"จัดหน้าที่ให้สมาชิกตามจุดเด่น","skill":"planning","points":10,"hints":["ความเห็นที่ต่างกันอาจกลายเป็นจุดแข็ง ถ้าได้หน้าที่ที่ใช่"],"fields":[{"id":"f1","label":"มะปราง","options":[{"text":"ปรับบทให้กระชับ","ok":true},{"text":"จับเวลาและบอกคิว","ok":false,"why":"ธามไทจับเวลาเก่งและละเอียดกว่า"},{"text":"นักแสดงนำ","ok":false,"why":"ภูผาเสียงดังและแสดงเก่งกว่า"},{"text":"ทำอุปกรณ์ประกอบฉาก","ok":false,"why":"ใบเฟิร์นประดิษฐ์เก่งกว่า"}],"answer":0},{"id":"f2","label":"ธามไท","options":[{"text":"ปรับบทให้กระชับ","ok":false,"why":"มะปรางแต่งบทเก่ง และรู้ว่ามุกไหนควรเก็บไว้"},{"text":"จับเวลาและบอกคิว","ok":true},{"text":"นักแสดงนำ","ok":false,"why":"ภูผาเสียงดังและแสดงเก่งกว่า"},{"text":"ทำอุปกรณ์ประกอบฉาก","ok":false,"why":"ใบเฟิร์นประดิษฐ์เก่งกว่า"}],"answer":1},{"id":"f3","label":"ภูผา","options":[{"text":"ปรับบทให้กระชับ","ok":false,"why":"มะปรางแต่งบทเก่งกว่า"},{"text":"จับเวลาและบอกคิว","ok":false,"why":"ธามไทจับเวลาเก่งกว่า"},{"text":"นักแสดงนำ","ok":true},{"text":"ทำอุปกรณ์ประกอบฉาก","ok":false,"why":"ใบเฟิร์นประดิษฐ์เก่งกว่า"}],"answer":2},{"id":"f4","label":"ใบเฟิร์น","options":[{"text":"ปรับบทให้กระชับ","ok":false,"why":"มะปรางแต่งบทเก่งกว่า"},{"text":"จับเวลาและบอกคิว","ok":false,"why":"ธามไทจับเวลาเก่งกว่า"},{"text":"นักแสดงนำ","ok":false,"why":"ภูผาเสียงดังและแสดงเก่งกว่า"},{"text":"ทำอุปกรณ์ประกอบฉาก","ok":true}],"answer":3}],"solution":["มะปรางปรับบท ธามไทจับเวลา ภูผาแสดงนำ ใบเฟิร์นทำอุปกรณ์","สองคนที่เถียงกันได้หน้าที่ที่ช่วยกันคนละด้าน: คนหนึ่งดูแลความสนุก อีกคนดูแลเวลา"]},{"kind":"choice","prompt":"แผนการแสดงแบบใดคำนึงถึงความยุติธรรม การร่วมมือ กติกา และความปลอดภัยครบทุกข้อ","skill":"decision","points":10,"hints":["ตรวจเวลา ภาระงาน และอุปกรณ์ในแต่ละแผน","แผนที่ผิดแต่ละแผนพลาดเพียงหลักเดียว"],"options":[{"text":"ใช้บทเต็มของมะปรางยาว 8 นาที ทุกคนมีหน้าที่ ใช้อุปกรณ์ทำจากกระดาษ และซ้อมพร้อมกันทุกวัน","ok":false,"why":"ผิดกติกา ครูกำหนดให้แสดงได้ไม่เกิน 5 นาที"},{"text":"บท 5 นาที ทุกคนมีหน้าที่ ซ้อมพร้อมกันทุกวัน แต่ใช้มีดทำครัวจริงในฉากทำอาหารให้ดูสมจริง","ok":false,"why":"ไม่ปลอดภัย มีดจริงอาจบาดผู้แสดงหรือผู้ชม ควรใช้อุปกรณ์จำลอง"},{"text":"บท 5 นาทีที่เก็บมุกเด่นของมะปราง ทุกคนมีหน้าที่ ใช้อุปกรณ์ทำจากกระดาษแข็ง และซ้อมพร้อมกันวันละ 30 นาที","ok":true},{"text":"บท 5 นาที ใช้อุปกรณ์กระดาษ ซ้อมพร้อมกัน แต่ให้ใบเฟิร์นทำอุปกรณ์ทุกชิ้นและพิมพ์บทแจกทุกคนคนเดียว","ok":false,"why":"ไม่ยุติธรรม ใบเฟิร์นแบกงานมากกว่าคนอื่นมาก"}],"solution":["แผนที่ถูกทำตามกติกาเวลา ใช้อุปกรณ์ที่ปลอดภัย แบ่งงานยุติธรรม และซ้อมร่วมกัน","ความคิดของมะปรางและธามไทอยู่ในแผนเดียวกัน"],"answer":2},{"kind":"choice","prompt":"เหตุผลใดดีที่สุดที่ควรชวนภูผากลับมาซ้อม แทนที่จะแสดงกันแค่ 3 คน","skill":"reason","points":10,"hints":["ย้อนดูกติกาของครู และจุดเด่นของภูผา"],"options":[{"text":"เพราะครูกำหนดให้ทุกคนมีหน้าที่ และภูผาแสดงเก่ง ทีมจะทำได้ดีที่สุดเมื่อทุกคนร่วมมือกัน","ok":true},{"text":"เพราะภูผาจะได้ไม่ไปบอกครูว่ากลุ่มทะเลาะกัน","ok":false,"why":"เราไม่ได้ชวนเพื่อนเพื่อปิดเรื่อง แต่เพื่อให้ทุกคนมีส่วนร่วม"},{"text":"เพราะภูผาเป็นคนผิดที่ไม่มาซ้อม ต้องมาชดใช้","ok":false,"why":"ภูผาไม่มาเพราะไม่อยากเลือกข้าง การโทษภูผาไม่ช่วยแก้ปัญหา"}],"solution":["ทุกคนในกลุ่มมีสิทธิ์และหน้าที่ร่วมกัน","การชวนเพื่อนกลับมาด้วยความเข้าใจทำให้ทีมแข็งแรงขึ้น"],"answer":0}]}', 'hard', 22),
('health_teamwork', 'แพ้นัดชิงแล้วถูกล้อ', '{"icon":"🏆","story":["ทีมฟุตบอลห้อง 5/1 แพ้นัดชิงชนะเลิศ 1–2 ในนาทีสุดท้าย","ผู้เล่นทีมชนะบางคนตะโกนล้อว่า \"ทีมขาอ่อน\" ภูผาโกรธ กำหมัดจะเดินเข้าไปหา","อีก 10 นาทีจะมีพิธีมอบเหรียญ ต้นกล้าเป็นกัปตันทีม"],"context":[{"type":"table","title":"ความเห็นในทีมตอนนี้","head":["คนในทีม","ความเห็น"],"rows":[["ภูผา","จะไปต่อว่าให้รู้เรื่อง"],["มะปราง","ไม่อยากขึ้นรับเหรียญ เพราะอายและเสียใจ"],["ต้นกล้า (กัปตัน)","อยากให้ทีมสงบ และจบอย่างมีน้ำใจนักกีฬา"],["ธามไท","อยากบอกครูว่าอีกทีมพูดไม่สุภาพ"]]},{"type":"note","text":"กติกาการแข่งขัน: ผู้เล่นที่ใช้ความรุนแรงจะถูกตัดสิทธิ์รับเหรียญ และทั้งสองทีมต้องเข้าร่วมพิธีมอบเหรียญ"}],"steps":[{"kind":"scene","prompt":"ต้นกล้าควรทำอย่างไรกับภูผาทันที","skill":"decision","points":10,"hints":["ใครควรเป็นคนจัดการเรื่องคำพูดไม่สุภาพ","อะไรจะเกิดขึ้นถ้าภูผาเดินเข้าไปตอนกำลังโกรธ"],"options":[{"text":"ปล่อยภูผาไป เพราะอีกทีมเป็นฝ่ายผิดก่อน","score":0,"result":"ภูผาผลักผู้เล่นอีกทีมจนเกือบล้ม ทั้งสองฝ่ายเริ่มผลักกันไปมา","then":{"kind":"choice","prompt":"มีการผลักกันแล้ว ต้นกล้าควรทำอะไรต่อทันที","skill":"decision","points":10,"hints":["ใครช่วยหยุดเหตุการณ์ได้ปลอดภัยที่สุด"],"options":[{"text":"เข้าไปผลักคืนเพื่อช่วยภูผา","ok":false,"why":"ยิ่งทำให้รุนแรงขึ้นและเสี่ยงบาดเจ็บ"},{"text":"เรียกครูหรือกรรมการที่อยู่ใกล้ที่สุดมาช่วยแยกทันที","ok":true},{"text":"ยืนถ่ายคลิปไว้เป็นหลักฐานก่อน","ok":false,"why":"ต้องขอความช่วยเหลือจากผู้ใหญ่ก่อน เพื่อไม่ให้ใครบาดเจ็บ"}],"solution":["เมื่อเกิดความรุนแรง ให้เรียกผู้ใหญ่ช่วยทันที ไม่เข้าไปร่วมวง"],"answer":1}},{"text":"จับแขนภูผาเบา ๆ ชวนถอยออกมาหายใจลึก ๆ แล้วบอกว่าเรื่องคำพูดไม่สุภาพ ให้ธามไทไปแจ้งครู","score":1,"result":"ภูผาค่อย ๆ ใจเย็นลง ครูเรียกผู้เล่นที่ล้อมาตักเตือน ไม่มีใครถูกตัดสิทธิ์และไม่มีใครบาดเจ็บ"},{"text":"ห้ามภูผาไว้ได้ แล้วพาทั้งทีมกลับห้องเลย ไม่ขึ้นรับเหรียญ","score":0.5,"result":"ไม่มีใครทะเลาะกัน แต่ทีมไม่ไปร่วมพิธีตามกติกา ครูต้องตามหา และเรื่องคำพูดไม่สุภาพก็ไม่มีใครแจ้ง"}],"solution":["ตั้งสติก่อนเสมอ ความรุนแรงทำให้บาดเจ็บและถูกตัดสิทธิ์","เรื่องที่อีกฝ่ายทำผิด ให้ครูหรือกรรมการเป็นคนจัดการ"]},{"kind":"choice","prompt":"ก่อนพิธีมอบเหรียญ แผนใดคำนึงถึงความยุติธรรม การร่วมมือ กติกา และความปลอดภัยครบทุกข้อ","skill":"decision","points":10,"hints":["ดูความเห็นของมะปรางและธามไทในตารางด้วย","แผนที่ผิดแต่ละแผนพลาดเพียงหลักเดียว"],"options":[{"text":"ทั้งทีมให้กำลังใจกัน แต่ไม่ขึ้นรับเหรียญเพื่อประท้วงที่ถูกล้อ","ok":false,"why":"ผิดกติกา ทั้งสองทีมต้องเข้าร่วมพิธีมอบเหรียญ"},{"text":"ขึ้นรับเหรียญพร้อมกัน แสดงความยินดีกับทีมชนะ แต่ให้มะปรางยืนหลังสุดเพราะทีมคิดว่าเธอพลาดลูกสุดท้าย","ok":false,"why":"ไม่ยุติธรรม ทีมแพ้ด้วยกัน ไม่ควรโทษมะปรางคนเดียว"},{"text":"ขึ้นรับเหรียญตามกติกา ธามไทแจ้งครูเรื่องคำพูด แต่ต่างคนต่างยืน ไม่มีใครปลอบหรือชวนมะปราง","ok":false,"why":"ขาดการร่วมมือ ทีมไม่ช่วยกันดูแลเพื่อนที่กำลังเสียใจ"},{"text":"ปลอบมะปรางแล้วขึ้นรับเหรียญพร้อมกันทั้งทีม แสดงความยินดีกับทีมชนะ และให้ธามไทแจ้งครูเรื่องคำพูดอย่างสุภาพ","ok":true}],"solution":["แผนที่ถูกทำตามกติกา ไม่โทษใคร ดูแลเพื่อนในทีม และแก้เรื่องคำพูดผ่านครูอย่างปลอดภัย"],"answer":3},{"kind":"multi","prompt":"การไม่ตอบโต้ด้วยความรุนแรงตรงกับหลักใดบ้าง (เลือกทุกข้อที่ใช่)","skill":"reason","points":10,"hints":["คิดว่าผลดีเกิดกับใครบ้าง และอะไรที่ไม่ได้เปลี่ยนไป"],"options":[{"text":"ปลอดภัย ไม่มีใครบาดเจ็บ","ok":true},{"text":"ทำตามกติกา ทีมไม่ถูกตัดสิทธิ์รับเหรียญ","ok":true},{"text":"ทำให้ทีมชนะต้องคืนถ้วยรางวัล","ok":false,"why":"ผลการแข่งขันยังเป็นไปตามสกอร์ การตักเตือนเรื่องคำพูดไม่ได้เปลี่ยนผล"},{"text":"มีน้ำใจนักกีฬา ยอมรับผลการแข่งขัน","ok":true},{"text":"แสดงว่าทีมเรากลัวและยอมแพ้","ok":false,"why":"การควบคุมอารมณ์คือความเข้มแข็ง ไม่ใช่ความกลัว"}],"solution":["การไม่ใช้ความรุนแรงทำให้ปลอดภัย ทำตามกติกา และแสดงน้ำใจนักกีฬา","คนที่ควบคุมอารมณ์ได้ตอนโกรธคือคนที่เข้มแข็ง"]}]}', 'hard', 23),
('health_teamwork', 'บัตรแสตมป์หายไปหนึ่งดวง', '{"icon":"🔍","story":["คาบพละวันนี้แข่งวิ่งเก็บแสตมป์ 3 จุดรอบสนาม ใครครบและถึงเส้นชัยก่อนชนะ","ธามไทจากสีเหลือง ทีมเดียวกับใบเฟิร์น เข้าเส้นชัยเป็นคนแรก แต่มีเพื่อนสงสัยว่าเขาวิ่งลัด","มะปรางบอกใบเฟิร์นว่าเห็นธามไทวิ่งตัดกลางลาน ตรงที่ภารโรงกำลังใช้เครื่องตัดหญ้า"],"context":[{"type":"table","title":"บัตรเก็บแสตมป์","head":["ผู้แข่ง","จุด A","จุด B","จุด C","เวลา"],"rows":[["ธามไท","✓","–","✓","3 นาที 10 วินาที"],["ภูผา","✓","✓","✓","3 นาที 40 วินาที"],["มะปราง","✓","✓","✓","3 นาที 55 วินาที"]]},{"type":"note","text":"กติกา: ต้องประทับแสตมป์ครบทั้ง 3 จุด จุด B อยู่ฝั่งไกลสุดของสนาม ทางลัดไปจุด C คือวิ่งตัดกลางลานที่กำลังตัดหญ้า"}],"steps":[{"kind":"multi","prompt":"ข้อมูลใดบ้างที่เป็นเบาะแสว่าธามไทอาจไม่ได้ทำตามกติกา (เลือกทุกข้อที่ใช่)","skill":"analysis","points":10,"hints":["เบาะแสต้องมาจากข้อมูลในตาราง โน้ต หรือสิ่งที่มีคนเห็น ไม่ใช่ความรู้สึก"],"options":[{"text":"บัตรของธามไทไม่มีแสตมป์จุด B","ok":true},{"text":"ธามไทเป็นคนวิ่งเร็วอยู่แล้ว","ok":false,"why":"การวิ่งเร็วไม่ใช่หลักฐานว่าโกง"},{"text":"มะปรางเห็นธามไทวิ่งตัดกลางลาน","ok":true},{"text":"เวลาของธามไทเร็วกว่าคนอื่นอย่างน้อย 30 วินาที","ok":true},{"text":"ธามไทอยู่สีเดียวกับใบเฟิร์น","ok":false,"why":"อยู่สีไหนไม่เกี่ยวกับการทำผิดกติกา"}],"solution":["แสตมป์ที่ขาด คำบอกของคนที่เห็น และเวลาที่เร็วผิดปกติ รวมกันเป็นเบาะแส","ความเร็วหรือสีทีมของคนคนหนึ่งไม่ใช่หลักฐาน"]},{"kind":"scene","prompt":"สีเหลืองจะได้คะแนนจากการชนะครั้งนี้ ใบเฟิร์นควรทำอย่างไร","skill":"decision","points":10,"hints":["ใครมีหน้าที่ตัดสินผล","คิดถึงสีอื่นที่วิ่งครบทุกจุด"],"options":[{"text":"เงียบไว้ เพราะสีเหลืองจะได้คะแนน","score":0,"result":"สีอื่นรู้ทีหลังและไม่พอใจ ไม่มีใครเชื่อใจผลการแข่ง และธามไทยังวิ่งผ่านเครื่องตัดหญ้าในรอบต่อไป"},{"text":"บอกธามไทเองว่ารอบหน้าอย่าลัดอีก แต่ไม่บอกครู","score":0.5,"result":"ธามไทรับปากว่าจะไม่ทำอีก แต่ผลรอบนี้ยังไม่ยุติธรรมกับสีอื่น และครูไม่รู้ว่าทางลัดนั้นอันตราย"},{"text":"นำบัตรแสตมป์ไปให้ครูกรรมการดู เล่าสิ่งที่มะปรางเห็นตามจริง และให้ครูเป็นคนตัดสิน","score":1,"result":"ครูคุยกับธามไท เขายอมรับว่าวิ่งลัด ครูตัดสินตามกติกา และรีบไปกั้นลานที่ตัดหญ้า ครูชมใบเฟิร์นที่ซื่อสัตย์แม้สีตัวเองจะเสียคะแนน"}],"solution":["ความซื่อสัตย์ต่อกติกาสำคัญกว่าคะแนนของสีตัวเอง","การบอกครูยังช่วยให้ครูรู้จุดอันตรายและแก้ไขได้"]},{"kind":"choice","prompt":"ครูให้ช่วยวางแผนการแข่งรอบหน้า แผนใดคำนึงถึงความยุติธรรม การร่วมมือ กติกา และความปลอดภัยครบทุกข้อ","skill":"decision","points":10,"hints":["ตรวจทีละแผน: ใครได้เปรียบไหม มีจุดอันตรายไหม ตรวจกติกาได้จริงไหม","แผนที่ผิดแต่ละแผนพลาดเพียงหลักเดียว"],"options":[{"text":"มีคนประจำทุกจุดแสตมป์ อธิบายเส้นทางให้ทุกคนพร้อมกัน แต่ไม่ต้องกั้นลานที่ตัดหญ้า เพราะวิ่งผ่านเร็ว ๆ ได้","ok":false,"why":"ไม่ปลอดภัย การวิ่งผ่านเครื่องตัดหญ้าเสี่ยงบาดเจ็บ"},{"text":"มีครูหรือเพื่อนอาสาประจำทุกจุดแสตมป์ กั้นเชือกรอบลานที่ตัดหญ้า และอธิบายเส้นทางให้ทุกสีฟังพร้อมกันก่อนเริ่ม","ok":true},{"text":"มีคนประจำทุกจุดแสตมป์ กั้นเชือกรอบลานที่ตัดหญ้า แต่บอกเส้นทางที่ใกล้ที่สุดให้สีเหลืองรู้ก่อน","ok":false,"why":"ไม่ยุติธรรม ทุกสีต้องได้รู้ข้อมูลเท่ากัน"},{"text":"กั้นเชือกรอบลานที่ตัดหญ้า อธิบายเส้นทางพร้อมกัน แต่ยกเลิกบัตรแสตมป์ ให้ทุกคนบอกเองว่าวิ่งครบ","ok":false,"why":"ไม่มีการตรวจตามกติกา การบอกเองตรวจไม่ได้ว่าวิ่งครบจริง"}],"solution":["แผนที่ถูกตรวจกติกาได้จริง ปลอดภัยจากจุดอันตราย ทุกสีได้ข้อมูลเท่ากัน และมีเพื่อนอาสาช่วยกันดูแล"],"answer":1}]}', 'hard', 24),
('health_teamwork', 'ทุกคนได้เล่นโยนบอลลงตะกร้า', '{"icon":"♿","story":["คาบพละวันนี้เล่นเกมโยนบอลลงตะกร้า ทีมละ 4 คน","เก่งนั่งรถเข็นและอยากเล่นด้วย มีเพื่อนพูดว่า \"เก่งเล่นไม่ได้หรอก\"","ใบเฟิร์นอยากจัดทีมที่ทุกคนได้เล่นจริง"],"context":[{"type":"table","title":"สมาชิกในทีม","head":["สมาชิก","จุดเด่น"],"rows":[["เก่ง","นั่งรถเข็น แขนแข็งแรง โยนแม่นที่สุดในห้อง"],["ภูผา","วิ่งเร็ว เก็บบอลไว"],["มะปราง","รับบอลมั่นคง ส่งบอลแม่นระยะกลาง"],["ใบเฟิร์น","ว่องไว ขยับซ้ายขวาเร็ว"]]},{"type":"note","text":"กติกาที่ครูดัดแปลง: ผู้โยนต้องอยู่ในวงกลมหน้าตะกร้า ห้ามแย่งบอลจากมือ ห้ามชนตัวผู้เล่นหรือรถเข็น หน้าที่ในทีม: ผู้โยนลงตะกร้า, ผู้เก็บบอลจากปลายสนาม, ผู้ส่งบอลกลางสนาม, ผู้คอยบังบอลของคู่แข่ง"}],"steps":[{"kind":"choice","prompt":"เหตุผลใดตอบเพื่อนที่บอกว่า \"เก่งเล่นไม่ได้หรอก\" ได้ดีที่สุด","skill":"reason","points":10,"hints":["ดูจุดเด่นของเก่งในตาราง"],"options":[{"text":"เพราะครูสั่งให้ทุกคนเล่น","ok":false,"why":"ไม่ได้อธิบายว่าเก่งเล่นได้อย่างไร เพื่อนจะยังไม่เข้าใจ"},{"text":"เพราะสงสารเก่ง","ok":false,"why":"เก่งควรได้เล่นเพราะเป็นสิทธิ์และมีความสามารถ ไม่ใช่เพราะความสงสาร"},{"text":"เพราะทุกคนมีสิทธิ์ร่วมเล่น และถ้าจัดหน้าที่ให้เหมาะ เก่งโยนแม่นที่สุด ช่วยทีมได้มาก","ok":true},{"text":"เพราะเก่งจะได้ไม่ไปฟ้องครู","ok":false,"why":"เราชวนเพื่อนเล่นเพราะเคารพเพื่อน ไม่ใช่เพราะกลัวถูกฟ้อง"}],"solution":["ทุกคนมีสิทธิ์ร่วมกิจกรรม","การจัดหน้าที่ให้เหมาะกับความสามารถทำให้ทุกคนได้เล่นและช่วยทีมได้จริง"],"answer":2},{"kind":"plan","prompt":"จัดหน้าที่ในทีมให้เหมาะกับจุดเด่นของแต่ละคน","skill":"planning","points":10,"hints":["หน้าที่ไหนไม่ต้องวิ่ง แต่ต้องโยนแม่น"],"fields":[{"id":"f1","label":"เก่ง","options":[{"text":"ผู้โยนลงตะกร้า","ok":true},{"text":"ผู้เก็บบอลจากปลายสนาม","ok":false,"why":"ภูผาวิ่งเร็วกว่า และเก่งโยนแม่นที่สุดในห้อง"},{"text":"ผู้ส่งบอลกลางสนาม","ok":false,"why":"มะปรางส่งบอลระยะกลางแม่นกว่า"},{"text":"ผู้คอยบังบอลคู่แข่ง","ok":false,"why":"ใบเฟิร์นขยับซ้ายขวาได้เร็วกว่า"}],"answer":0},{"id":"f2","label":"ภูผา","options":[{"text":"ผู้โยนลงตะกร้า","ok":false,"why":"เก่งโยนแม่นที่สุดในห้อง"},{"text":"ผู้เก็บบอลจากปลายสนาม","ok":true},{"text":"ผู้ส่งบอลกลางสนาม","ok":false,"why":"มะปรางส่งบอลระยะกลางแม่นกว่า"},{"text":"ผู้คอยบังบอลคู่แข่ง","ok":false,"why":"ใบเฟิร์นขยับซ้ายขวาได้เร็วกว่า"}],"answer":1},{"id":"f3","label":"มะปราง","options":[{"text":"ผู้โยนลงตะกร้า","ok":false,"why":"เก่งโยนแม่นที่สุดในห้อง"},{"text":"ผู้เก็บบอลจากปลายสนาม","ok":false,"why":"ภูผาวิ่งเร็วและเก็บบอลไวกว่า"},{"text":"ผู้ส่งบอลกลางสนาม","ok":true},{"text":"ผู้คอยบังบอลคู่แข่ง","ok":false,"why":"ใบเฟิร์นขยับซ้ายขวาได้เร็วกว่า"}],"answer":2},{"id":"f4","label":"ใบเฟิร์น","options":[{"text":"ผู้โยนลงตะกร้า","ok":false,"why":"เก่งโยนแม่นที่สุดในห้อง"},{"text":"ผู้เก็บบอลจากปลายสนาม","ok":false,"why":"ภูผาวิ่งเร็วและเก็บบอลไวกว่า"},{"text":"ผู้ส่งบอลกลางสนาม","ok":false,"why":"มะปรางส่งบอลระยะกลางแม่นกว่า"},{"text":"ผู้คอยบังบอลคู่แข่ง","ok":true}],"answer":3}],"solution":["เก่งโยน ภูผาเก็บบอล มะปรางส่งบอล ใบเฟิร์นคอยบัง","ทุกหน้าที่ต่อกันเป็นทีม บอลต้องผ่านทุกคนจึงจะได้คะแนน"]},{"kind":"choice","prompt":"แผนการเล่นใดคำนึงถึงความยุติธรรม การร่วมมือ กติกา และความปลอดภัยครบทุกข้อ","skill":"decision","points":10,"hints":["อ่านกติกาที่ครูดัดแปลงอีกครั้ง","แผนที่ผิดแต่ละแผนพลาดเพียงหลักเดียว"],"options":[{"text":"จัดหน้าที่ตามจุดเด่น ซ้อมส่งบอลกับเก่งก่อนแข่ง แต่ให้ภูผาเข็นรถเข็นพาเก่งวิ่งเร็ว ๆ ไปทุกจุดในสนาม","ok":false,"why":"ไม่ปลอดภัย การเข็นรถเข็นวิ่งเร็วเสี่ยงล้มและชนคนอื่น"},{"text":"จัดหน้าที่ตามจุดเด่น ซ้อมส่งบอลกับเก่งก่อนแข่ง แต่ให้เก่งออกมาโยนนอกวงกลมใกล้ตะกร้าเพื่อให้ลงง่ายขึ้น","ok":false,"why":"ผิดกติกา ผู้โยนต้องอยู่ในวงกลม"},{"text":"จัดหน้าที่ตามจุดเด่น เล่นตามกติกาที่ครูดัดแปลง แต่ไม่ซ้อมส่งบอลกับเก่งก่อนแข่ง เพราะคิดว่าเดี๋ยวก็เข้าใจกันเอง","ok":false,"why":"ขาดการร่วมมือ ทีมยังไม่ได้ตกลงจังหวะส่งบอลกับเก่ง"},{"text":"จัดหน้าที่ตามจุดเด่น ซ้อมส่งบอลกับเก่งก่อนแข่ง เล่นตามกติกาที่ครูดัดแปลง และระวังไม่ชนรถเข็น","ok":true}],"solution":["แผนที่ถูกทำให้เก่งได้เล่นเต็มที่ ทำตามกติกา ซ้อมสื่อสารกันก่อน และระวังความปลอดภัย"],"a